insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 66, "Segons l’article 165 de la Constitució espanyola, quina norma regula el funcionament del Tribunal Constitucional?", "Un reglament del Tribunal Constitucional.", "Una llei ordinària del Govern.", "Una llei orgànica.", "Un reglament del Consell General del Poder Judicial."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 67, "Segons l’article 164 de la Constitució espanyola, és possible interposar un recurs contra una sentència del Tribunal Constitucional?", "No.", "Sí, davant el Tribunal Suprem.", "No, amb alguna excepció.", "Sí, un recurs d’empara."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 68, "Segons l’article 166 de la Constitució espanyola, a qui correspon la iniciativa de reforma constitucional?", "Al Govern.", "Al Congrés i al Senat.", "A les assemblees legislatives autonòmiques.", "Les respostes a), b) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 69, "Segons l’article 167 de la Constitució espanyola, quina majoria de cada una de les cambres es requereix per aprovar un projecte de reforma constitucional no essencial?", "Majoria absoluta.", "Majoria de les tres cinquenes parts.", "Majoria de les dues terceres parts.", "Majoria simple."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 70, "Segons l’article 168 de la Constitució espanyola, és obligatori un referèndum per ratificar una reforma total constitucional una vegada que hagi estat aprovada per les Corts Generals?", "No.", "No, excepte excepcions.", "Sí.", "Sí, tret d’excepcions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 71, "Segons l’article 169 de la Constitució espanyola, quan no es pot iniciar una reforma constitucional?", "Durant els estats d’alarma, d’excepció o de setge vigents.", "Durant un procés electoral.", "En temps de guerra.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 72, "Segons l’article 168 de la Constitució espanyola, si es proposa la revisió total de la Constitució, s’ha de procedir:", "A l’aprovació per majoria dels dos terços de cada cambra.", "A l’aprovació per majoria absoluta de cada cambra.", "A la dissolució immediata de les Corts.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 73, "Segons l’article 168 de la Constitució espanyola, si es proposa una revisió parcial de la Constitució que afecta el títol II, es procedeix:", "A l’aprovació per majoria dels dos terços de cada cambra.", "A l’aprovació per majoria absoluta de cada cambra.", "A la dissolució immediata de les Corts.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 74, "Segons l’article 167 de la Constitució espanyola, la reforma de parts no essencials de la Constitució s’ha de sotmetre a referèndum?", "No, mai.", "SÍ, sempre que ho demani una desena part dels membres de qualsevol de les cambres.", "SÍ, sempre que ho demani una tercera part dels membres de qualsevol de les cambres.", "SÍ, sempre que ho demani una cinquena part dels membres de qualsevol de les cambres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 75, "Segons l’article 168 de la Constitució espanyola, sobre la reforma constitucional, no se’n considera una part essencial:", "El títol preliminar.", "El capítol II, secció primera del títol I.", "El títol II.", "El títol III."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 1, "Indiqui la normativa en la que s’estableixen las premisses fonamentals de la normativa pressupostària local", "Orde EHA/3565/2008, de 3 de desembre, por la que s’aprova l’estructura dels pressupostos de les Entitats Locals.", "Llei 7/1985, de 2 de abril, Reguladora de las Bases del Règim Local.", "RD 500/1990, de 20 d’abril, pel qual es desenvolupa el Capítol Primer del Títol Sisè de la Llei 39/1988, de 26 de desembre, reguladora de les Hisendes Locals en matèria de pressupostos.", "Reial Decret Legislatiu 2/2004, de 5 de maig, pel qual s’aprova el text refós de la Llei Reguladora de les Hisendes Locals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 2, "S’estableix com una de las premisses fonamentals", "L’aprovació d’un pressupost anual per part del Ple de la Corporació.", "La inclusió en el projecte de pressupost anual de totes les previsions d’ingressos i despeses de l’exercici.", "La aprovació d’unes Bases d’Execució per les quals es regirà el Pressupost General de la Corporació, quant a l’aprovació, execució i liquidació del pressupost.", "L’existència d’un pressupost únic integrat pel de la pròpia entitat i els dels seus organismes autònoms dependents i empreses municipals participades íntegrament per l’entitat local."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 3, "El Pressupost General d’una Entitat Local constitueix l’expressió xifrada, conjunta i sistemàtica de:", "El total de despeses i  ingressos que es preveu liquidar durant l’exercici pressupostari, a partir de l’experiència d’exercicis pressupostaris anteriors.", "Les operacions d’endeutament a curt termini (pòlisses de crèdit) i a llarg termini (préstecs) que es preveu subscriure durant l’exercici pressupostari per part de l’entitat local, dels organismes autònoms dependents i de les empreses municipals participades íntegrament per l’entitat local.", "Les obligacions que com a màxim es podran reconèixer i els drets que es preveu liquidar per l’Entitat Local i els seus Organismes Autònoms i les previsions d’ingressos i despeses de les Societats Mercantils el capital social de les quals pertany íntegrament a l’Entitat Local.", "Les obligacions que com a màxim es podran reconèixer i els drets que es preveu liquidar per l’Entitat Local i els seus Organismes Autònoms i les previsions d’ingressos i despeses de les Societats Mercantils participades per l’entitat local en més d’un 50% del seu capital social."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 4, "El principio d’anualitat suposa:", "Que el pressupost coincideixi amb l’any natural i que se li imputin els drets liquidats de qualsevol període i les obligacions reconegudes durant el mateix període de l’exercici pressupostari.", "Que el pressupost coincideixi amb l’any natural i que se li imputin els drets liquidats i les obligacions reconegudes del propi exercici pressupostari.", "Que la vigència del pressupost sigui d’un any a comptar des de l’endemà de la inserció en el BOIB del pressupost definitivament aprovat pel Ple de la Corporació.", "Que el pressupost tingui una durada de dotze mesos i que se li imputin els drets liquidats i les obligacions reconegudes derivats del propi exercici pressupostari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 5, "Què implica el principi d’universalitat?", "Que el Pressupost de la Corporació recull totes les obligacions que com a màxim pot reconèixer i els drets que preveu liquidar durant l’exercici pressupostari.", "Que el Pressupost General integra el pressupost de la pròpia Entitat Local i el dels Organismes Autònoms de caràcter administratiu, comercial, industrial i financer, dependents d’aquesta.", "Que el Pressupost General integra el pressupost de la pròpia Entitat Local i el dels Organismes Autònoms i els estats de previsió d’ingressos i despeses de les societats mercantils participades íntegrament per l’entitat local.", "Que el Pressupost General integra el pressupost de la pròpia Entitat Local i el dels Organismes Autònoms i els estats de previsió d’ingressos i despeses de les societats mercantils amb capital social participat en més del 50% per l’Entitat Local."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 6, "El principi d’unitat de una caixa suposa que", "Els drets liquidats per operacions corrents es destinaran a finançar les obligacions reconegudes per operacions corrents.", "Els recursos de les Entitats Locals, dels Organismes Autònoms i de les Societats Municipals es destinaran a satisfer, sense excepció, el conjunt de les obligacions que com a màxim es podran reconèixer.", "Els drets liquidats de les partides de finançament afectat es destinaran a satisfer el conjunt de les obligacions reconegudes..", "Els recursos de les Entitats Locals, dels Organismes Autònoms i de les Societats Municipals es destinaran a satisfer  el conjunt de les obligacions que com a màxim es podran reconèixer, excepte en el cas d’ingressos específics afectats a fins determinats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 7, "El principio d’equilibri pressupostari suposa que", "Tots els pressupostos que integren el Pressupost General hauran d’aprovar-se sense dèficit inicial.", "El Pressupost General de l’Entitat Local, en el seu conjunt, ha d’estar equilibrat.", "L’equilibri pressupostari obliga al fet que, en atenció al que es disposa en la Llei orgànica 2/2017, d’Estabilitat Pressupostària, la liquidació del Pressupost General aprovat, presenti superàvit.", "Els pressupostos de les societats mercantils el capital social de les quals estigui participat al 100% per l’Entitat Local, presentin un benefici inicial."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 8, "El principi de publicitat del pressupost implica que", "El Pressupost General definitivament aprovat serà inserit en el Butlletí Oficial de la Comunitat Autònoma amb antelació al 31 de desembre.", "El Pressupost General inicialment aprovat s’exposarà al públic, previ anunci en el Butlletí Oficial de la Comunitat Autònoma, durant el termini d’un mes perquè els interessats puguin examinar-lo i presentar al·legacions a aquest.", "El Pressupost General definitivament aprovat entrarà en vigor, en l’exercici corresponent, una vegada publicat en el Butlletí Oficial de la Comunitat Autònoma.", "En atenció al que es disposa en la Llei 19/2013, de 9 de desembre, de Transparència, accés a la informació pública i bon govern, la Corporació municipal podrà substituir la publicació de l’aprovació inicial del Pressupost General en el Butlletí Oficial de la Comunitat Autònoma, per la publicació d’aquesta aprovació inicial en el Portal de Transparència de la pàgina web municipal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 9, "Una modificació del pressupost mitjançant la generació de crèdit per un ingrés de naturalesa no tributària pot finançar-se mitjançant", "El reemborsament de préstecs concedits per l'Entitat Local.", "La subscripció d'una operació de préstec a llarg termini destinada a finançar una inversió no prevista.", "La liquidació complementària d'una Taxa de recollida de residus d'un habitatge destinat al turisme vacacional.", "La subscripció d'una pòlissa de crèdit a curt termini per a cobrir un dèficit transitori de tresoreria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 10, "Per a realitzar una ampliació de crèdit del pressupost  es requerirà", "L'aprovació de l'expedient d'ampliació de crèdit mitjançant l'adopció d'un acord per part del Ple municipal.", "Que els recursos afectats procedeixin d'una operació d'endeutament a llarg termini.", "Que l'aplicació pressupostària ampliable i l’ ingrés afectat es relacionin expressament en les Bases d'Execució del pressupost definitivament aprovat.", "Que l' import efectivament recaptat en concepte de l' ingrés afectat sigui igual a l' import previst en el pressupost definitivament aprovat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 11, "En la tramitació d’un expedient d’Incorporació de Romanents de Crèdit, es podran incorporar", "Les obligacions reconegudes aprovades pels òrgans competents de la Corporació amb antelació al 31 de desembre de cada exercici pressupostari.", "Les transferències de crèdit aprovades en l'últim trimestre de l'exercici pressupostari.", "Els crèdits per operacions corrents disponibles al 31 de desembre.", "Tots els suplements de crèdit aprovats durant l'exercici pressupostari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 12, "La competència per a la disposició i l'autorització de despeses de caràcter pluriennal correspondrà", "Al Ple municipal quan la seva durada sigui superior a quatre anys i l'import acumulat de totes les anualitats superi el 10% dels recursos ordinaris del pressupost del primer exercici de la plurianualitat", "A l'Alcalde quan la seva durada sigui superior a quatre anys i l'import acumulat de totes les anualitats no superi el 10% dels recursos ordinaris del pressupost del primer exercici de la plurianualitat.", "A l'Alcalde quan la seva durada sigui inferior a quatre anys i l'import acumulat de totes les anualitats superi el 10% dels recursos ordinaris del pressupost del primer exercici de la plurianualitat.", "Al Ple municipal quan la seva durada sigui inferior a quatre anys i l'import acumulat de totes les anualitats superi el 10% dels recursos ordinaris del pressupost del primer exercici de la plurianualitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 13, "La competència per a la concertació d'operacions d'endeutament a curt termini competeix al Batle  quan", "L'import acumulat de les operacions vives, inclosa la nova operació d'endeutament, no supera el 15% dels recursos corrents del pressupost actual.", "L'import acumulat de les operacions vives, inclosa la nova operació d'endeutament, no supera el 15% dels recursos corrents liquidats en l'exercici pressupostari anterior.", "L'import acumulat de les operacions vives, inclosa la nova operació d'endeutament, no supera el 25% dels recursos corrents liquidats en l'exercici pressupostari anterior.", "L'import acumulat de les operacions vives, inclosa la nova operació d'endeutament, en cap cas suposa un límit a l'autorització per part de l'Alcalde de la nova operació d'endeutament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 14, "La competència per a la concertació d'operacions d'endeutament a llarg termini previstes en el pressupost competeix al Ple de la Corporació quan", "L'import acumulat de les operacions d'endeutament a llarg termini dins de cada exercici econòmic no supera el 15% dels recursos corrents liquidats en l'exercici pressupostari anterior.", "L'import acumulat de les operacions d'endeutament a llarg termini dins de cada exercici econòmic no supera el 10% dels recursos de caràcter ordinari previstos en el pressupost aprovat.", "L'import acumulat de les operacions d'endeutament a llarg termini dins de cada exercici econòmic no podrà superar l'import previst per al capítol d'inversions del pressupost actual.", "L'import acumulat de les operacions d'endeutament a llarg termini dins de cada exercici econòmic supera el 10% dels recursos de caràcter ordinari previstos en el pressupost aprovat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 15, "Dels següents pressupostos, quin d'ells no s'integrarà en el Pressupost General de l'Entitat Local?", "El pressupost d'un organisme autònom per a la gestió i recaptació dels tributs municipals.", "El pressupost d'una societat mercantil el capital social de la qual està participat en un 75% per l'Entitat Local.", "El pressupost d'un Consorci adscrit a la Entitat Local per al foment de l'ocupació local.", "El pressupost d'una societat mercantil el capital social de la qual estigui íntegrament participat per l'Entitat Local."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 16, "Indiqui quin límit opera per als crèdits de les partides del pressupost de despeses.", "El límit quantitatiu; import que com a màxim es pot gastar.", "El límit qualitatiu; destí o finalitat del crèdit pressupostari .", "El límit temporal; determinat pel propi principi d'anualitat del pressupost .", "Els límits quantitatiu, qualitatiu i temporal en el seu conjunt."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 17, "L'elaboració del Pressupost General d'una Entitat Local es realitza sota un criteri", "Jurídic, en atenció als compromisos legals-contractuals adquirits o que es preveu adquirir (contractes, préstecs, pactes, …), normativa tributària d'aplicació, concessions administratives.", "De caixa, a partir del corrent real de cobraments i pagaments que es preveu liquidar i reconèixer.", "De la meritació econòmica, d'acord amb el que disposa la comptabilitat econòmic-patrimonial.", "Tributari, d'acord amb el que disposen les ordenances fiscals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 18, "El pressupost d'ingressos de l'Entitat Local té caràcter estimatiu, això implica que", "L'estimació de l'ingrés previst es realitza a partir de la informació històrica disponible.", "La xifra d'ingrés pressupostada suposa un topall en l'import d'ingrés anual.", "Els drets que es reconeguin en l'exercici poden ser superiors als continguts en el pressupost definitivament aprovat.", "En cas que els drets liquidats en l'exercici siguin superiors als continguts en el pressupost aprovat, haurà d'incorporar-se el preceptiu informe de l'Interventor municipal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 19, "De la següent documentació referida a l'Entitat local, indiqui quina d'elles no es requereix la seva incorporació al Pressupost General.", "Estat de consolidació del pressupost.", "Bases d'execució del pressupost.", "Document amb la projecció de l'estat d'ingressos i despeses del Pressupost General per als pròxims anys.", "Document Annex amb les inversions previstes en l'exercici."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 20, "Com es classifica el pressupost de despeses?", "Mitjançant una classificació Orgànica, per Programes i Econòmica.", "Mitjançant una classificació Econòmica.", "Mitjançant una classificació conjunta per Programes i Econòmica.", "Mitjançant una classificació Orgànica i Econòmica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 21, "Com es classifica el pressupost d'ingressos?", "D'idèntica manera que el pressupost de despeses.", "Mitjançant una classificació Orgànica.", "Mitjançant una classificació Econòmica.", "Mitjançant una classificació Orgànica i Econòmica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 22, "A quin òrgan o departament municipal li correspon la formació del Pressupost General?", "A la Junta de Govern Local.", "Al Director dels Serveis Econòmics municipals.", "Al President de la Corporació Local.", "Al Ple de la Corporació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 23, "Contra l'acord d'aprovació definitiva del Pressupost General, podrà interposar-se?", "Recurs Contenciós Administratiu.", "Recurs davant el Tribunal Economicoadministratiu Regional de les Illes Balears.", "Recurs davant el Tribunal de Comptes.", "Recurs de Reposició previ al Recurs Contenciós Administratiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 24, "Podrà adquirir-se un compromís de despesa de caràcter pluriennal en el següent cas:", "Per a atendre els acords recollits en el Pacte de Funcionaris relatius a increments de remuneracions al cos de funcionaris municipals.", "Per a atendre les càrregues financeres dels deutes de l'entitat local i dels seus organismes autònoms.", "Per a atendre els compromisos econòmics adquirits amb els acords de la carrera professional.", "Per a atendre el contracte per a la compra d'un vehicle moto-bomba per al parc de bombers municipal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 25, "Podran donar-se baixes per anul·lació de crèdits en els següents casos:", "Mitjançant informe previ motivat subscrit per la Direcció dels Serveis Econòmics municipals.", "A petició del responsable de l'Àrea gestora del crèdit pressupostari.", "Per no estar al 31 de desembre afecte al compliment d'obligacions ja reconegudes.", "Per incloure’ls en l'expedient d'incorporació de crèdits a l'exercici pressupostari següent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 26, "Sempre que existeixin recursos financers disponibles, podran incorporar-se als corresponents crèdits del pressupost de despeses de l'exercici immediat següent", "Els crèdits pressupostaris per operacions de capital.", "Les retencions de crèdit dels crèdits pressupostaris per operacions corrents.", "Les modificacions de crèdit que hagin estat concedides o autoritzades al llarg de l'exercici pressupostari.", "Tots els crèdits disponibles a la finalització de l'exercici pressupostari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 27, "El Compte General format per la Intervenció Municipal serà sotmesa a informe per part de:", "La Junta de Govern Local.", "La Comissió Informativa d'Assumptes Generals.", "El Tresorer municipal, d'acord amb el que disposa l'RD 128/2018, de 16 de març, pel qual es regula el règim jurídic dels funcionaris d'Administració Local amb habilitació de caràcter nacional.", "La Comissió Especial de Comptes de l'Entitat Local."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 28, "En quin moment deurà el Compte General ser sotmesa a Informe:", "L'endemà de la seva formació per la Intervenció municipal.", "En el termini de 15 dies hàbils a comptar des de l'endemà de la seva formació per la Intervenció municipal.", "Abans del dia 1 de juny de cada any.", "No existeix un termini determinat per a ser sotmesa a informe."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 29, "De les següents polítiques de despesa, quina d'elles s'inclou en l'Àrea de Producció de Béns i Serveis de Caràcter Preferent?", "Transport públic.", "Esports.", "Comerç i turisme.", "Serveis socials i promoció social."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 30, "La política de despesa de Benestar Comunitari es troba inclosa dins de l'Àrea de despesa de:", "Serveis públics bàsics", "Actuacions de protecció i promoció social.", "Actuacions de caràcter general", "Actuacions de caràcter econòmic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 31, "S'entén per incorporació de crèdit l'operació mitjançant la qual", "S'autoritzen crèdits ordinaris.", "S'aproven suplements de crèdit.", "S'agreguen romanents de crèdit al pressupost ordinari.", "S'autoritzen crèdits extraordinaris."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 32, "L'acumulació de les diferents fases d'execució del pressupost de despeses obeeix a criteris", "D'oportunitat.", "Racionalitat en el pagament de les obligacions.", "Economia i agilitat administrativa.", "No es poden acumular les diferents fases d'execució del pressupost de despeses."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 33, "El principi d'universalitat aplicat al pressupost general d'una Entitat Local implica que:", "Només existeix un pressupost.", "Tots els ingressos i despeses han de figurar en el pressupost.", "És un pressupost general.", "Únicament contempla el pressupost de la Corporació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 34, "Les estimacions dels diferents recursos econòmics a liquidar durant l'exercici pressupostari es contenen en", "L'estat de previsió d'ingressos i despeses.", "La previsió d'ingressos.", "L'estat d'ingressos.", "L'estat de despeses."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 35, "El romanent líquid de tresoreria amb el qual es finança un crèdit extraordinari o un suplement de crèdit està integrat per", "Els majors ingressos efectivament recaptats respecte dels previstos.", "El saldo de les retencions de crèdit pendents d'aplicar.", "Les anul·lacions o baixes de crèdits.", "Els drets pendents de cobrament, les obligacions pendents de pagament i els fons líquids."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 36, "Una vegada aprovat inicialment el Pressupost General de l'Entitat Local, aquest s'exposarà al públic per un termini de", "Deu dies naturals.", "Quinze dies.", "Un mes hàbil.", "Un mes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 37, "Segons l'Orde EHA/3565/2008, per la qual s'aprova l'estructura de pressupostos de les Entitats Locals, en la classificació econòmica de les despeses, el capitulo 3 es refereix a", "Transferències corrents.", "Actius financers.", "Passius Financers.", "Despeses financeres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 38, "El cicle pressupostari de les Entitats Locals, tenen una durada de", "Un any.", "Des del moment de l'entrada en vigor fins a la finalització de l'exercici pressupostari.", "Fins al final del període de legislatura.", "Des del moment d'incorporació de romanents fins a la liquidació del pressupost."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 39, "Quin és el quòrum requerit per a l'aprovació del Pressupost General de l'Entitat Local", "Una majoria qualificada.", "Per majoria absoluta del nombre legal de membres de la Corporació.", "Per majoria simple.", "Per una majoria de dos terços del nombre legal de membres de la Corporació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 40, "A la fase d'execució pressupostària amb la qual es procedeix a l'Ordenació del Pagament es denomina", "Fase OR.", "Fase P.", "Fase OP.", "Fase RP."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 41, "Dins del procés d'execució pressupostària, la fase corresponent al Reconeixement de l'Obligació és", "Anterior a l'ordenació del pagament i posterior al compromís de la despesa.", "Posterior a l'ordenació del pagament i anterior a la liquidació de la despesa.", "Anterior a l'autorització de la despesa i posterior a la disposició d'aquest.", "Posterior a la retenció del crèdit i anterior a la disposició de la despesa ."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 42, "Les regles que han de seguir-se en l'execució del pressupost estan contingudes en", "La Memòria explicativa del contingut del Pressupost General de l'Entitat Local.", "Les delegacions de despeses amb l'assignació de competències al Ple, al Batle o als Tinents de Batle, segons sigui la quantia de la despesa a incórrer.", "Les Bases d'Execució del pressupost, adaptant les disposicions legals en matèria pressupostària a l'organització i circumstàncies de la pròpia Entitat Local.", "L'Informe Econòmic-financer on es recullen les bases utilitzades per a l'elaboració i execució del pressupost"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 43, "Dins de la classificació econòmica de l'estat de despeses, les partides pressupostàries es desenvolupen per", "Els subprogrames.", "Les subfunciones.", "Els programes.", "Els subconceptes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 44, "En el procés d'execució del pressupost no es podran acumular les fases de", "Autorització i disposició de crèdits.", "Autorització i disposició de crèdits i reconeixement de l'obligació.", "Retenció i autorització del crèdit.", "Autorització, disposició de crèdits, reconeixement de l'obligació i ordenació del pagament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 45, "La funció fiscalitzadora a càrrec de la Intervenció Municipal es produirà en la fase de.", "Autorització de la despesa", "Reconeixement de l'obligació.", "Ordenació del pagament", "La funció fiscalitzadora es produirà en totes les fases de l'execució del pressupost."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 46, "En el cas que el Ple de la Corporació no resolgui les reclamacions presentades en el període d'exposició al públic del pressupost inicialment aprovat,", "S'entendran desestimades les reclamacions presentades.", "Es relegarà l'aprovació definitiva del pressupost fins a la seva resolució.", "S'incorporaran les mateixes al pressupost.", "S'entendran estimades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 47, "Una vegada aprovat definitivament el Pressupost General de l'Entitat Local, haurà d'existir una còpia a la disposició del públic", "Durant el termini de dos mesos a comptar des de la seva publicació.", "Durant el termini de quinze dies a comptar des de la seva aprovació definitiva.", "Pel termini d'un any.", "Fins a la finalització de l'exercici pressupostari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 48, "Finalitzat el termini d'exposició al públic del pressupost inicialment aprovat, no es requerirà acord exprés d'aprovació definitiva quan", "Existeixi un informe favorable de l'Interventor Municipal i així ho proposi al President de la Corporació.", "Al final del període d'exposició s'haurien presentat al·legacions i/o reclamacions a aquest.", "Existeixi el ple consens entre els diferents grups polítics que conformen el Consistori.", "Al final del període d'exposició no s'haurien presentat al·legacions i/o reclamacions a aquest."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 49, "L'aprovació dels pressupostos que integren el Pressupost General d'una Entitat Local amb dèficit inicial", "S'admet de manera excepcional.", "Es permet quan al llarg de l'exercici al qual es refereixin pugui produir-se l'anivellament de tots els pressupostos.", "No es permet l'aprovació inicial dels pressupostos amb dèficit inicial.", "Obliga a una immediata compensació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 50, "Una vegada emès l'informe del pressupost per la Intervenció Municipal, el President de l'Entitat Local el remetrà al Ple de la Corporació", "Abans del 15 de novembre per a la seva aprovació, esmena o devolució.", "Abans del 31 d'octubre per a la seva aprovació, esmena o devolució.", "Podrà remetre-ho en qualsevol moment, sempre que sigui abans del 31 de desembre, per a la seva aprovació, esmena o devolució", "Abans del 15 d'octubre per a la seva aprovació, esmena o devolució."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 51, "El control intern de la despesa pública de l'Entitat Local serà exercit", "Per la Comissió Especial de Comptes.", "Pel Tribunal de Comptes.", "Per la Intervenció local.", "Pel Ple de la Corporació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 52, "L'informe del Tribunal de Comptes està previst per al supòsit en què:", "Li ho requereixi un òrgan jurisdiccional competent quan la impugnació es refereixi a l'anivellament pressupostari.", "El pressupost s'aprovi fora del termini assenyalat per a això.", "S'hagi prescindit del període d'exposició al públic del pressupost inicialment aprovat.", "Es cometi qualsevol irregularitat en el procés d'elaboració i aprovació del pressupost."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 53, "En la classificació econòmica dels ingressos, l'Alienació d'Inversions Reals té la consideració de:", "Una operació econòmica.", "Una operació de capital.", "Una operació financera.", "Una operació corrent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 54, "D'entre les següents opcions, indiqui quina d'elles no constitueix un dels objectius del Control Intern", "Corregir les deficiències detectades.", "Exigir les corresponents responsabilitats.", "Prendre decisions per a l'elaboració i aprovació del Pressupost General de l'Entitat Local.", "Reforçar la necessària transparència en la gestió pública."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 55, "El control intern es concreta en la vigilància dels aspectes formals i materials de", "Totes les operacions i les fases d'execució dels crèdits del pressupost de despeses.", "La subscripció de les operacions d'endeutament a llarg termini previstes en l'estat d'ingressos del Pressupost General.", "Totes les operacions que puguin generar una despesa o bé el reconeixement d'un dret per a l'Entitat Local.", "Únicament es realitzarà un control intern sobre la recaptació dels tributs municipals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 56, "El control que es realitza sobre l'activitat econòmico-financera d'una Entitat Local contempla", "Un control intern realitzat per un òrgan de la pròpia Administració Local.", "Un control intern realitzat per un òrgan de la pròpia Administració Local i un control extern realitzat per una institució pública aliena a l'Entitat Local", "Un control extern realitzat pel Tribunal de Comptes.", "Un control extern realitzat per un auditor de comptes contractat per l'Entitat Local a aquest efecte."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 57, "Constitueix un òrgan de control extern de les Comunitats Autònomes", "Les Sindicatures de Comptes.", "La Intervenció General de la Comunitat Autònoma.", "Els Consells Consultius.", "El Tribunal Econòmic-administratiu Regional."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 58, "El control realitzat per la Intervenció local es realitza a través de", "La funció interventora i el control d'eficàcia.", "El control financer i el control d'eficiència.", "La fiscalització de totes les operacions de Pagament del pressupost de despesa –Fase P de l'execució pressupostària", "La funció interventora, el control financer i el control d'eficàcia i eficiència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 59, "El control al qual es refereix el títol VI del RDL 2/2004 del TRLRHL serà exercit sobre totes les entitats que conformen el sector públic local, amb excepció de:", "Els organismes autònoms dependents de l'Entitat Local.", "Els consorcis dotats de personalitat jurídica pròpia adscrits a l'Entitat Local.", "Les entitats amb o sense personalitat jurídica amb participació minoritària de l'Entitat Local.", "Les societats mercantils dependents íntegrament de l'Entitat Local."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 60, "En l'exercici de la funció interventora, es comprovarà:", "Que l'expedient s'ajusta a la legalitat aplicable en cada cas.", "Que l'expedient s'ajusta a la legalitat aplicable en cada cas i als principis de bona gestió econòmica.", "La conveniència o oportunitat de dur a terme una actuació municipal amb contingut econòmic.", "L'adequació de l'actuació prevista als principis d'economia, eficàcia i eficiència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 61, "Quina fase de la funció interventora correspon realitzar en el moment previ a l'adjudicació d'un contracte de serveis?", "La intervenció prèvia.", "La presa de raó en la comptabilitat pressupostària.", "El compromís de la despesa –Fase D de l'execució pressupostària.", "La fiscalització prèvia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 62, "El control financer de l'activitat econòmico-financera del sector públic local s'exercirà a través de les seves dues modalitats, a saber:", "El control permanent i l'auditoria pública.", "La funció interventora i l'auditoria de comptes.", "L'auditoria de compliment i l'auditoria operativa.", "El control intern planificat i el control permanent no planificat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 63, "En l'exercici de la funció interventora, la fiscalització prèvia de despeses pròpiament dita es realitzarà sobre els actes que donin lloc a:.", "Al reconeixement d'una obligació –Fase O de l'execució pressupostària", "A l'ordenació del pagament contra els recursos disponibles en la Tresoreria de l'Entitat Local –Fase O de l'execució pressupostària.", "A l'autorització de la despesa i compromís del mateix –Fase A i D de l'execució pressupostària.", "A la disposició de la despesa –Fase D de l'execució pressupostària."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 64, "Les Administracions Públiques que proposin l'establiment de subvencions hauran de concretar amb caràcter previ.", "Un pla estratègic de subvencions", "El crèdit pressupostari necessari i suficient per a atendre les subvencions previstes.", "Les bases d'execució del pressupost contenint el detall de les subvencions previstes.", "L'expedient administratiu de concessió de la subvenció."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 65, "Quina de les següents opcions no reuneix els requisits per a ser considerada una subvenció?", "Que el lliurament es realitzi sense contraprestació directa dels beneficiaris.", "Que el lliurament estigui subjecte al compliment d'un determinat objectiu, l'execució d'un projecte, la realització d'una activitat, l'adopció d'un comportament singular, ja realitzats o per desenvolupar, o la concurrència d'una situació, devent el beneficiari complir les obligacions materials i formals que s'haguessin establert.", "Les aportacions dineràries a un Organisme Autònom dependent de l'Entitat Local.", "Que el projecte, l'acció, conducta o situació finançada tingui per objecte el foment d'una activitat d'utilitat pública o interès social o de promoció d'una finalitat pública."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 66, "Quin és l'òrgan competent per a iniciar el procediment sancionador en matèria de subvencions?", "L'òrgan que hagués formulat la proposta de concessió de la subvenció.", "El Ple de la Corporació.", "Els Serveis Jurídics de la Corporació.", "L'Interventor municipal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 67, "D'acord amb la Llei General de Subvencions, quin dels següents principis no és un principi general de les subvencions públiques?", "Publicitat, transparència, concurrència, objectivitat, igualtat, no discriminació.", "Eficàcia en el compliment dels objectius marcats per l'Administració atorgant.", "Agilitat dels procediments administratius i de les activitats materials de gestió.", "Eficiència en l'assignació i utilització dels recursos públics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 68, "D'acord amb la Llei General de Subvencions, s'estableix com a procediment ordinari de concessió el de:", "Procediment negociat.", "Concurrència competitiva.", "Subhasta pública.", "Adjudicació directa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 69, "Poden realitzar-se pagaments a compte de subvencions encara que no s'hagin justificat els pagaments anticipats?", "Sí, quan així estigui previst en les bases de la corresponent convocatòria.", "No, en cap cas.", "Sí, sempre que es garanteixi el pagament a compte per part del beneficiari mitjançant un aval bancari.", "No, excepte autorització expressa de l'òrgan concedent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 70, "En un expedient de concessió de subvenció, quin tràmit segueix immediatament a la proposta de resolució definitiva?", "L'acceptació de la subvenció.", "El tràmit d'audiència a l'interessat.", "La resolució de la concessió.", "La justificació de la subvenció."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 71, "Quina és la normativa general mitjançant la qual es regulen les subvencions?", "La Llei 28/2013, de 17 de desembre, de Subvencions Generals.", "La Llei 38/2006, de 17 d'octubre, General de Subvencions Públiques.", "La Llei 38/2003, de 17 de novembre, General de Subvencions.", "La Llei 38/2006, de 17 de novembre, de Subvencions Generals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 72, "En l'àmbit de les subvencions públiques, en quin cas podran imposar-se sancions no pecuniàries?", "En el cas d'infraccions lleus o greus.", "En el cas d'infraccions molt greus.", "En el cas d'infraccions lleus, greus i molt greus.", "En el cas d'infraccions greus o molt greus."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 73, "Què és la Base de dades Nacional de Subvencions –BDNS?", "És el sistema que regula la concessió de subvencions.", "És el sistema nacional de publicitat de subvencions.", "És el sistema de control pressupostari de les subvencions.", "És el sistema de control financer de les subvencions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 74, "Quines subvencions tenen la consideració de nominatives?", "Les previstes com a tals en les Bases d'Execució del Pressupost General de l'Entitat Local", "Les que resulten d'una convocatòria pública.", "Les que no requereixen d'una acceptació per part de beneficiari.", "Les que així es determinin pel President de la Corporació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 14, 75, "En un expedient de concessió de subvenció, quin tràmit segueix immediatament a la proposta de resolució provisional?", "La proposta de resolució definitiva.", "La resolució de la concessió de la subvenció.", "L'acceptació de la subvenció.", "El tràmit d'audiència a l'interessat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 1, "La normativa sobre prevenció de riscs laborals queda constituïda:", "Per la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals.", "Per la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals, i les disposicions de desenvolupament o complementàries.", "Per la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals, les disposicions de desenvolupament o complementàries i les normes internacionals.", "Per la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals, les disposicions de desenvolupament o complementàries, i totes aquelles altres normes legals o convencionals que contenguin prescripcions relatives a l’adopció de mesures preventives en l’àmbit laboral."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 2, "La Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals, té com a objecte:", "Millorar les condicions laborals de les persones treballadores.", "Promoure la seguretat i la salut de les persones treballadores.", "Disposar les mesures preventives adequades als llocs de feina.", "Establir la forma d’avaluació dels riscs als llocs de feina."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 3, "Les disposicions de caràcter laboral que conté la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals tenen el caràcter:", "De dret necessari mínim indisponible, i poden ser millorades i desenvolupades en els convenis col·lectius.", "De dret mínim indisponible, però no es poden desenvolupar amb els convenis col·lectius.", "No tenen caràcter de dret mínim.", "Tenen caràcter de màxim de dret."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 4, "La Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals, és aplicable en l’àmbit de:", "Policia, seguretat i resguard duaner.", "Les relacions laborals regulades per la Llei de l’Estatut dels treballadors i en les relacions de caràcter administratiu o estatutari del personal al servei de les administracions públiques.", "Serveis operatius de protecció civil i peritatge forense en els casos de risc greu, catàstrofe i calamitat pública.", "Forces armades i activitats militars de la Guàrdia Civil."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 5, "D’acord amb l’article 4 de la Llei de prevenció de riscs laborals, el risc laboral és:", "Les malalties, patologies o lesions sofertes amb motiu o ocasió del treball.", "El conjunt d’activitats o mesures adoptades o previstes en totes les fases d’activitat de l’empresa.", "La possibilitat que un treballador pateixi un determinat dany derivat del treball.", "Qualsevol màquina, aparell, instrument o instal·lació que s’utilitza en el treball."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 6, "La Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals, no és aplicable en les activitats les particularitats de les quals ho impedeixin en l’àmbit de les funcions públiques de:", "Policia, seguretat i resguard duaner.", "Serveis operatius de protecció civil, peritatge forense en els casos de risc greu, catàstrofe i calamitat pública.", "Forces armades i activitats militars de la Guàrdia Civil.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 7, "Quina és la definició de danys derivats del treball segons la Llei de prevenció de riscs laborals?", "Els problemes de salut relacionats per una causa amb les condicions de treball.", "Les malalties, patologies o lesions sofertes amb motiu o ocasió del treball.", "Qualsevol alteració de la salut relacionada, causada o agreujada per les condicions de treball.", "Les lesions corporals i psíquiques que el treballador pateixi amb ocasió o per conseqüència del treball."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 8, "Quina és la definició de prevenció segons la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals?", "El conjunt d’activitats o mesures adoptades o previstes en totes les fases de l’activitat de l’empresa amb la finalitat d’evitar o disminuir els riscs derivats del treball.", "El conjunt de mitjans disponibles per ajudar en el desenvolupament de la tasca laboral.", "El conjunt de mitjans auxiliars i equips de protecció individual.", "Els procediments de feina i les normatives derivades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 9, "Quina és la definició de risc laboral segons la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals?", "És el focus d’emissió de gasos i vapors.", "És la casualitat que una persona treballadora pateixi un accident.", "És la gravetat d’un dany a la salut.", "És la possibilitat que un treballador pateixi un determinat dany derivat del treball."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 10, "Per qualificar un risc laboral des del punt de vista de la gravetat s’ha de valorar conjuntament:", "El grau d’afectació a la persona treballadora.", "La probabilitat que es produeixi el dany i la seva severitat.", "Només es valora la severitat.", "La probabilitat que hi hagi patiment físic i no psicològic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 11, "Quina és la definició de risc laboral greu i imminent segons la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals?", "És aquell en el qual les conseqüències i el dany tenen lloc a curt termini.", "És el fet en el qual la gravetat fa que el risc sigui impossible de prevenir.", "És aquell que racionalment es materialitza en un futur immediat i pugui suposar un dany greu per a la salut de la persona treballadora.", "És la situació inesperada que té conseqüències greus per a la seguretat i la salut dels treballadors."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 12, "Quina és la definició d’equip de treball segons la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals?", "És qualsevol màquina, aparell, instrument o instal·lació utilitzada en el treball.", "És tot aparell amb el qual es desenvolupa el treball diari.", "És tot sistema amb el qual es desenvolupa el treball.", "Són les instal·lacions dels centres de treball."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 13, "Quina és la definició de condició de treball segons la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals?", "Són totes les circumstàncies derivades del treball.", "És la situació més habitual a l’entorn laboral.", "Són les característiques inherents al desenvolupament de la tasca diària.", "És qualsevol característica del treball que pugui tenir una influència significativa en la generació de riscs per a la seguretat i la salut del treballador o treballadora."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 14, "Quina és la definició d’equip de protecció individual segons la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals?", "És tot aquell equipament destinat a protegir la seguretat i la salut del personal.", "És qualsevol equip destinat a ser portat o subjectat pel treballador o treballadora perquè el protegeixi d’un o de diversos riscs que en puguin amenaçar la seguretat o la salut en el treball, com també qualsevol complement o accessori destinat a aquesta finalitat.", "És qualsevol element que protegeix d’un risc laboral a diversos treballadors.", "És tot sistema de subjecció individual amb la finalitat d’evitar les caigudes a nivell."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 15, "La política en matèria de prevenció de riscs laborals té l’objectiu de:", "Promoure la millora de les condicions de treball a fi d’elevar el nivell de protecció de la seguretat i la salut dels treballadors en el treball.", "Millorar les condicions salarials i socials dels treballadors afiliats a la seguretat social.", "Aconseguir unes condicions dignes de treball.", "Respectar la salut dels treballadors en el treball amb l’adopció de mesures preventives."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 16, "Les administracions públiques competents en matèria laboral han de dur a terme les funcions de:", "Promoció de la seguretat i assessorament jurídic en el seu àmbit d’aplicació.", "Prevenció dels accidents laborals i les malalties professionals.", "Promoció de la prevenció, assessorament tècnic, vigilància i control del compliment pels subjectes compresos en el seu àmbit d’aplicació de la normativa de prevenció de riscs laborals, i sanció de les infraccions en cas necessari.", "Sanció de les infraccions administratives."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 17, "Amb relació a l’Institut Nacional de Seguretat i Salut en el Treball (anteriorment, Institut Nacional de Seguretat i Higiene en el Treball), quina no és una funció d’aquest organisme:", "Suport tècnic i col·laboració amb la Inspecció de Treball i Seguretat Social.", "Promoció i, si escau, realització d’activitats de formació, informació, investigació, estudi i divulgació en matèria de prevenció de riscs laborals.", "Assessorament tècnic en l’elaboració de la normativa legal i en el desenvolupament de la normalització, tant en l’àmbit nacional com internacional.", "Vigilància del compliment de la normativa sobre prevenció de riscs laborals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 18, "D’acord amb la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals, la funció de la Inspecció de Treball i Seguretat Social és:", "Desenvolupar la normativa que incideix en les condicions de treball.", "En cap cas pot ordenar la paralització immediata de treballs quan hi hagi risc greu i imminent per a la seguretat i salut del personal.", "Vigilar i controlar el compliment de la normativa en prevenció de riscs laborals.", "Només té funcions en concepte de sancions en temes relatius a la seguretat social."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 19, "És un principi bàsic de la política de prevenció de riscs laborals", "La participació d’empresaris i de treballadors, mitjançant les organitzacions empresarials i sindicals més representatives, en la planificació, la programació, l’organització i el control de la gestió relacionades amb la millora de les condicions de treball i la protecció  de la seguretat i la salut dels treballadors.", "L’elaboració de normativa laboral.", "La conciliació de la vida familiar i laboral.", "Només la millora de les condicions de treball."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 20, "L’article 14 de la Llei de prevenció de riscs laborals estableix:", "Que quan s’hagi produït un dany per a la salut (física o psíquica) s’ha d’investigar.", "Que l’empresari ha de garantir la seguretat i la salut dels treballadors en tots els aspectes relacionats amb el treball.", "Que com a acció preventiva s’ha de promocionar la salut.", "Que s’ha d’atenuar el treball monòton i repetitiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 21, "Senyalau la resposta correcta amb relació al pla de prevenció de riscs laborals:", "L’han de dur a terme les empreses de més de cinquanta treballadors.", "Les empreses, segons el nombre de treballadors i la naturalesa i perillositat de les activitats realitzades, poden dur a terme el pla de prevenció de riscs laborals de forma simplificada.", "L’han de dur a terme aquelles empreses de més de cent treballadors.", "Les empreses, segons el nombre de treballadors i la naturalesa i perillositat de les activitats realitzades, poden dur a terme el pla de prevenció de riscs laborals de forma extensa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 22, "L’article 15 de la Llei 31/1995,  de 8 de novembre,  de prevenció de riscs laborals, estableix que:", "L’empresari no ha de tenir en compte la capacitació professional dels treballadors.", "Les empreses de més de 150 empleats han de disposar de pla d’emergències.", "El disseny del lloc de treball no es té en compte en la prevenció de riscs laborals.", "L’empresari ha d’aplicar els principis de l’acció preventiva."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 23, "El principi de substituir el que sigui perillós pel que comporti poc perill o no en comporti cap és:", "Un principi de l’acció preventiva.", "Una acció de l’estudi inicial.", "Un cas aplicable als productes químics.", "No és un principi de l’acció preventiva."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 24, "D’acord amb l’article 16 de la Llei de prevenció de riscs laborals, quan s’hagi produït un dany per a la salut dels treballadors, l’empresari:", "Ha de fer un nou pla de prevenció que inclogui els danys dels treballadors.", "Ha de portar a terme una investigació sobre el cas, a fi de detectar les causes dels fets.", "Ha de comunicar els fets a la Fiscalia.", "Ha de portar a terme el seguiment de l’activitat preventiva a fi de perfeccionar de manera contínua les activitats d’identificació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 25, "L’article 17 de la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals diu que:", "L’empresari ha de proporcionar als empleats només equips de protecció individual.", "L’empresari ha de vetlar perquè es faci un ús efectiu dels equips de protecció individual.", "L’empresari ha de proporcionar als empleats equips de protecció individual adequats per a l’exercici de les seves funcions i vetlar perquè se’n faci un ús efectiu quan sigui necessari.", "Són necessaris els equips de treball i els equips de protecció individual."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 26, "D’acord amb l’article 18 de la Llei de prevenció de riscs laborals, l’empresari ha d’adoptar les mesures adequades perquè els treballadors rebin totes les informacions necessàries en relació amb:", "Els drets laborals que els corresponen.", "Les obligacions en referència a la prevenció de riscs laborals.", "Els riscs, les mesures i les activitats de protecció i prevenció i les mesures adoptades.", "L’empresari no té cap obligació d’informar els treballadors."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 27, "La informació a la qual es refereix l’article 18 de la Llei de prevenció de riscs laborals estableix que:", "Si hi ha representants dels treballadors, l’ha de proporcionar l’empresari als treballadors a través dels representants; no obstant això, s’ha d’informar directament cada treballador dels riscs específics que afecten el seu lloc de treball o funció i de les mesures de protecció i prevenció aplicables als riscs.", "L’empresari únicament l’ha de donar als representants dels treballadors, els quals la faran arribar als treballadors.", "L’empresari sempre l’ha de donar als treballadors sense tenir haver de passar pels representants dels treballadors.", "La informació s’estableix en l’article 23 de la Llei de prevenció de riscs laborals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 28, "La formació en l’àmbit de la prevenció de riscs laborals ha de ser:", "Voluntària per a l’empresari, però obligatòria per al personal.", "Voluntària per a l’empresari i voluntària per al personal.", "L’empresari ha de garantir per a tot el personal la formació teòrica i pràctica en matèria preventiva.", "La formació no s’ha de centrar específicament en el lloc de treball o la funció del personal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 29, "La formació en matèria preventiva de riscs laborals s’ha d’impartir:", "Dins la jornada laboral, sempre que sigui possible, o si no fos possible en altres hores, descomptant-les de la jornada laboral.", "Fora de la jornada laboral.", "Un pla de formació no específic.", "El cost anirà sempre a càrrec del personal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 30, "Indicau l’afirmació correcta en relació amb les situacions d’emergència:", "Sobre les mesures d’emergència, l’empresari no n’ha de fer res perquè és competència exclusiva dels serveis d’emergència de la comunitat autònoma.", "L’empresari encarregarà sempre a una empresa l’avaluació de les situacions d’emergència, independentment de les dimensions i l’activitat de l’empresa i de la presència de persones alienes a aquesta.", "Les situacions d’emergència queden fora de les obligacions de l’empresari que estableix la Llei de prevenció de riscs laborals.", "L’empresari, tenint en compte les dimensions i l’activitat de l’empresa, així com la possible presència de persones alienes, ha d’analitzar les possibles situacions d’emergència i adoptar les mesures necessàries en matèria de primers auxilis, lluita contra incendis i evacuació dels treballadors."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 31, "Quan el personal estigui o pugui estar exposat a un risc greu i imminent a causa de la seva feina, l’empresari està obligat a:", "Donar avís a la inspecció de treball i a la Seguretat Social.", "Informar d’aquesta situació a tot el personal afectat al més aviat possible, adoptar les mesures perquè es pugui interrompre l’activitat laboral immediatament i disposar del que sigui necessari per adoptar les mesures necessàries per evitar les conseqüències de l’esmentat perill.", "Precintar el centre de treball.", "Donar avís amb el temps suficient per aplicar les mesures preventives necessàries."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 32, "En referència al que estableix l’article 22 de la Llei de prevenció de riscs laborals quant a la vigilància de la salut, senyalau la resposta incorrecta:", "Les dades relatives a la vigilància de la salut dels treballadors no es poden fer servir amb fins discriminatoris ni en perjudici del treballador.", "L’empresari ha de garantir als treballadors al seu servei la vigilància periòdica del seu estat de salut en funció dels riscs inherents al treball.", "Els resultats de la vigilància s’han de comunicar als treballadors afectats, a l’empresari i als representants dels treballadors.", "Les mesures de vigilància i control de la salut s’han de portar a terme respectant sempre el dret a la intimitat i a la dignitat de la persona i la confidencialitat de tota la informació relacionada amb el seu estat de salut."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 33, "Amb relació al dret a la vigilància de la salut:", "Sempre s’ha de prolongar més enllà de la finalització de la relació laboral.", "S’ha de prolongar més enllà de la finalització de la relació laboral només quan el treballador ho sol·liciti expressament.", "En cap cas s’ha de prolongar més enllà de la finalització de la relació laboral.", "S’ha de prolongar en els supòsits en què la naturalesa dels riscs inherents al treball ho faci necessari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 34, "Quina documentació ha d’elaborar i conservar l’empresari d’acord amb la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals?", "L’avaluació de riscs laborals de cada lloc de treball específic i la documentació relativa a l’estat de salut del personal.", "El pla de prevenció i la relació d’accidents laborals, però no la de malalties professionals.", "El pla de prevenció i la relació d’accidents laborals i la de malalties professionals.", "El pla de prevenció, l’avaluació de riscs per a la seguretat i la salut del personal, la planificació preventiva, la pràctica dels controls de l’estat de salut del personal i la relació d’accidents de treball i malalties professionals que hagin causat al treballador una incapacitat laboral superior a un dia de feina."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 35, "D’acord amb l’article 26 de la Llei de prevenció de riscs laborals, les dones embarassades tenen dret:", "A absentar-se de la feina, amb dret a remuneració, per fer exàmens prenatals i tècniques de preparació al part, amb avís previ a l’empresari i amb la justificació de la necessitat de fer-ho dins de la jornada de treball.", "A absentar-se de la feina, sense dret a remuneració, per fer exàmens prenatals i tècniques de preparació al part, amb avís previ a l’empresari i amb la justificació de la necessitat de fer-ho dins de la jornada de treball.", "A absentar-se de la feina, amb dret a remuneració, per fer exàmens prenatals i tècniques de preparació al part, sense l’obligació d’avisar prèviament l’empresari.", "No tenen dret a absentar-se de la feina per fer exàmens prenatals i tècniques de preparació al part."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 36, "La coordinació d’activitats empresarials implica que:", "En un o més centres de treball hi ha més de dues empreses implicades en el desenvolupament laboral.", "En un centre de treball hi ha més de tres empreses treballant alhora però no implica cap responsabilitat al titular del centre.", "Quan en un mateix centre de treball hi duguin a terme activitats el personal de dues o més empreses, aquestes han de cooperar en l’aplicació de la normativa sobre prevenció de riscs laborals.", "Només és necessari la cooperació documental del pla de prevenció."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 37, "L’article 25 de la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals, estableix que:", "El pla de prevenció s’ha de revisar anualment.", "L’avaluació de riscs laborals s’ha de revisar anualment.", "El pla de prevenció i l’avaluació de riscs laborals caduquen als tres anys.", "L’empresari ha de garantir específicament la protecció del personal que per les seves característiques personals o el seu estat biològic conegut siguin especialment sensibles als riscs derivats del treball."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 38, "Quines actuacions preventives cal fer abans de la incorporació a la feina de joves menors de devuit anys?", "S’ha de fer una avaluació del lloc de treball que hagin d’ocupar amb la finalitat de determinar la naturalesa, el grau i la durada de la seva exposició als riscs específics, a agents, processos o condicions de treball que puguin posar en perill la seguretat o la salut d’aquest treballador.", "S’han d’incloure en el pla de prevenció i establir formació específica.", "S’ha de fer una avaluació global del lloc de treball.", "S’han de tenir només en compte les condicions de seguretat del lloc de treball."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 39, "Quan és necessària la presència dels recursos preventius?", "Quan es duguin a terme activitats o processos que per reglament siguin considerats com a perillosos o amb riscs especials.", "Quan els riscs es puguin veure agreujats o modificats en el desenvolupament del procés o l’activitat, per la concurrència d’operacions diverses que es duen a terme successivament o simultàniament i que facin necessari el control de l’aplicació correcta dels mètodes de treball.", "Quan la necessitat d’aquesta presència sigui requerida per la Inspecció de Treball i Seguretat Social, si les circumstàncies del cas així ho exigeixen a causa de les condicions de treball detectades.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 40, "Les obligacions del personal en matèria de prevenció de riscs laborals són:", "Vetlar per la seguretat i salut d’un mateix.", "Vetlar per la seva pròpia seguretat i salut en el treball i per la d’aquelles altres persones a les quals la seva activitat professional pugui afectar, a causa dels actes i les omissions en el treball.", "Adoptar les mesures preventives necessàries del pla de prevenció.", "Implantar les instruccions de seguretat i salut en el lloc de treball."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 41, "El dret de participació que es regula en el capítol V de la Llei de prevenció de riscs laborals:", "S’exerceix en l’àmbit de les administracions públiques amb les adaptacions que siguin procedents atesa la diversitat de les activitats que duen a terme i les diferents condicions en què aquestes es duen a terme, la complexitat i la dispersió de l’estructura organitzativa i les seves peculiaritats en matèria de representació col·lectiva.", "S’exerceix de la mateixa manera en l’àmbit de l’empresa privada i en l’àmbit de les administracions públiques sense adaptacions particulars en cap dels dos àmbits.", "S’exerceix sempre i únicament a través dels representants dels treballadors, tant en l’àmbit de l’empresa privada com en l’àmbit de les administracions públiques.", "S’exerceix sempre i únicament a través dels treballadors, tant en l’àmbit de l’empresa privada com en l’àmbit de les administracions públiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 42, "Quina de les següents no és una competència dels delegats de prevenció?", "Exercir una tasca de vigilància i control sobre el compliment de la normativa de prevenció de riscs laborals.", "Promoure i fomentar la cooperació dels treballadors en l’execució de la normativa sobre prevenció de riscs laborals.", "Informar l’autoritat laboral sobre els accidents de treball.", "Col·laborar amb la direcció de l’empresa en la millora de l’acció preventiva."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 43, "Els delegats de prevenció estan facultats per:", "Dur a terme visites als llocs de treball per exercir una tasca de vigilància i control de l’estat de les condicions de treball.", "Ser informats per les autoritats laborals sobre els danys produïts en la salut dels treballadors.", "Paralitzar l’activitat laboral quan es detectin riscs molt greus per a la salut dels treballadors.", "Tenir accés, sense cap limitació, a la informació i la documentació relativa a les condicions de treball i dels treballadors."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 44, "El comitè de seguretat i salut:", "És l’òrgan científic i tècnic especialitzat que té com a missió l’anàlisi i l’estudi de les condicions de seguretat i salut en el treball.", "És l’òrgan paritari i col·legiat de participació destinat a la consulta regular i periòdica de les actuacions de l’empresa en matèria de prevenció de riscs.", "És l’òrgan a qui correspon la funció de la vigilància i el control de la normativa sobre prevenció de riscs laborals.", "És l’òrgan col·legiat assessor de les administracions públiques en la formulació de les polítiques de prevenció."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 45, "Indicau la resposta incorrecta en referència al comitè de seguretat i salut:", "S’ha de constituir un comitè de seguretat i salut a totes les empreses o centres de treball que disposin de cinquanta treballadors o més.", "El comitè està format pels delegats de prevenció, d’una banda, i per l’empresari i/o els seus representants en un nombre igual al dels delegats de prevenció, de l’altra.", "El comitè de seguretat i salut s’ha de reunir trimestralment i sempre que ho sol·liciti alguna de les representacions en el mateix comitè.", "Les normes de funcionament del comitè de seguretat i salut les adopta l’empresari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 46, "L’incompliment per part dels empresaris de les obligacions en matèria de prevenció de riscs laborals, a quin tipus de responsabilitats pot donar lloc?", "Administratives, penals i civils.", "Només penals i civils.", "Només penals i administratives.", "Només civils i administratives."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 47, "Què és un servei de prevenció d’acord amb l’article 31 de la Llei de prevenció de riscs laborals?", "És el conjunt de mitjans humans i materials necessaris per dur a terme les activitats preventives a fi de garantir la protecció adequada de la seguretat i la salut del personal.", "És una empresa que es contracta per gestionar els reconeixements mèdics i l’assistència en els accidents de treball i les malalties professionals.", "És un conjunt de mitjans auxiliars per establir el pla de prevenció.", "És l’empresa que s’encarrega de la gestió dels accidents i malalties professionals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 48, "D’acord amb l’article 32 de la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals, les mútues d’accidents de treball i malalties professionals:", "Tenen prohibida la participació en activitats mercantils de prevenció.", "Poden exercir activitats preventives només en casos concrets.", "Exerceixen les seves funcions d’acord amb el que estableix la llei.", "Les mútues i els serveis de prevenció són la mateixa cosa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 49, "L’empresari ha de consultar els treballadors d’acord amb:", "L’article 1 de la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals.", "L’article 33, consulta dels treballadors, de la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals.", "L’article 55 de la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals.", "L’article 2 de la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 50, "Què són els delegats de prevenció?", "Són elegits en les eleccions sindicals.", "Són els representants dels treballadors amb funcions específiques en matèria de prevenció de riscs en el treball.", "Són les persones que duen a terme les avaluacions de riscs laborals.", "Els elegeix l’empresari entre els representants sindicals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 51, "Quants delegats de prevenció són necessaris a l’Administració autonòmica de les Illes Balears amb més de 5.000 treballadors?", "Com a mínim un delegat de prevenció.", "D’entre quatre a cinc delegats de prevenció.", "Vuit delegats de prevenció.", "Només és necessari un delegat de personal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 52, "A què estan obligats els delegats de prevenció d’acord amb l’article 37 de la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals?", "A complir el deure d’execució de les mesures preventives.", "A complir amb secret professional respecte de les informacions a què tenguin accés  a conseqüència de la seva actuació en l’empresa.", "Estan obligats a formar-se per compte propi.", "A seguir les indicacions i les instruccions de l’empresari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 53, "Quines són les competències i les facultats del Comitè de Seguretat i Salut?", "Elaborar el pla de prevenció i avaluar les conseqüències a l’aplicació.", "Avaluar els riscs inherents als llocs de treball.", "Promoure l’aplicació de mesures correctores.", "Participar en l’elaboració, la posada en pràctica i l’avaluació dels plans i els programes de prevenció de riscs de l’empresa, i promoure iniciatives sobre mètodes i procediments per a la prevenció dels riscs en l’empresa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 54, "Quan podrà el personal i els seus representants recórrer a la inspecció de treball i seguretat social?", "Quan considerin que amb les mesures adoptades i els mitjans utilitzats per l’empresari no n’hi ha prou per garantir la seguretat i la salut en el treball.", "No hi poden recórrer perquè no és funció de la inspecció de treball i seguretat social.", "Quan hagin passat tres dies des del darrer dia sotmesos a un risc greu i imminent.", "Sempre que aportin el pla de prevenció implementat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 55, "Què estableix l’article 41 de la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals?", "Els fabricants, però no els importadors, han de complir la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals.", "Els fabricants, els importadors i els subministradors de maquinària, equips, productes i estris de treball estan obligats a assegurar que aquests no constitueixin un font de perill per al treballador.", "Els fabricants i els subministradors han de complir les disposicions reglamentaries.", "L’empresari ha de fer complir la llei als fabricants, importadors i subministradors d’eines i serveis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 56, "El Reial decret 486/1997, de 14 d’abril, pel qual s’estableixen les disposicions mínimes de seguretat i salut als llocs de treball no és aplicable:", "Als mitjans de transport, les obres de construcció, temporals o mòbils, les indústries d’extracció, els vaixells de pesca ni camps de conreu, boscs o altres terrenys que estiguin fora de la zona edificada d’aquests terrenys.", "Als centres de treball de l’Administració pública.", "Als centres de treball de l’àmbit hospitalari.", "Als centres de treball d’hostaleria i restauració."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 57, "Què s’entén per lloc de treball?", "L’espai que hi ha de 2 metres quadrats lliures d’objectes al voltant del treballador.", "S’entén per lloc de treball les àrees del centre de treball, edificades o no, en què els treballadors han de romandre o a les quals poden accedir per raó del seu treball.", "Només és l’espai al voltant de la maquinària mòbil.", "S’entén per lloc de treball l’espai mínim per treballar amb una taula i un ordinador."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 58, "Com han de ser les portes d’emergència d’un centre de treball?", "Les portes d’emergència s’han d’obrir cap a l’interior i han d’estar tancades amb pany.", "El Reial decret 486/1997 no regula com són les portes d’emergència.", "Les portes d’emergència s’han d’obrir cap a l’exterior i no han d’estar tancades, de manera que qualsevol persona que necessiti usar-les en cas d’urgència pugui obrir-les fàcilment i immediatament.", "Han de ser de color vermell i poden ser corredisses o giratòries."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 59, "Pel que fa a l’ordre, la neteja i el manteniment d’un centre de treball cal tenir en compte que:", "El manteniment preventiu l’ha de dur a terme el personal no especialitzat.", "Les zones de pas, sortides i vies de circulació dels llocs de treball i, en especial, les sortides i vies de circulació previstes per a l’evacuació en casos d’emergència, han de romandre lliures d’obstacles de manera que sigui possible utilitzar-les en tot moment sense dificultats.", "La instal·lació elèctrica no cal que es revisi periòdicament.", "La neteja dels centres de feina no és àmbit d’aplicació de la Llei de prevenció de riscs laborals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 60, "A quins riscs laborals es veu sotmès el personal que utilitza pantalles de visualització de dades?", "Només fatiga visual.", "Fatiga física i visual.", "Somnolència i sordesa.", "Les alteracions principals de la salut són degudes, bàsicament, a riscs per a la vista i als problemes físics i de càrrega mental, així com al possible efecte combinat d’ambdós."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 61, "La il·luminació dels llocs de treball ha de complir les condicions següents:", "La distribució dels nivells d’il·luminació ha de ser al més uniforme possible i adequada a l’exigència visual.", "No hi ha condicions mínimes d’il·luminació.", "Amb 500 lux és insuficient per a llocs administratius.", "No cal tenir en compte la il·luminació en els llocs de treball."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 62, "Com ha de ser el material de primers auxilis d’un centre de treball?", "No és necessari el material perquè el treballador accidentat s’ha de dirigir a la mútua de treball.", "Si l’accés al centre d’assistència mèdica és proper no cal disposar de material de primers auxilis.", "Ha ser adequat, pel que fa a la quantitat i les característiques, al nombre de treballadors, als riscs a què estiguin exposats i a les facilitats d’accés al centre d’assistència mèdica més proper.", "La mútua de treball no proporciona el material necessari per actuar en cas de primers auxilis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 63, "En la manipulació manual de càrregues, quines característiques del medi laboral poden augmentar el risc dorsolumbar?", "L’estat de salut del personal.", "L’espai de treball és insuficient, el terreny és irregular i la il·luminació és escassa.", "La càrrega que s’ha de traslladar.", "La manca d’informació i formació al personal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 64, "Quines condicions han de complir els equips de protecció individual?", "Han d’adequar-se al portador, després dels ajustaments necessaris.", "Han de tenir en compte les condicions anatòmiques i fisiològiques i l'estat de salut del treballador.", "Han de complir la normativa vigent.", "Han de respondre a les condicions existents al lloc de treball, tenir en compte les condicions anatòmiques i fisiològiques i l'estat de salut del treballador i adequar-se al portador, després dels ajustaments necessaris."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 65, "Quines disposicions mínimes han de complir els llocs de treball?", "Les d’ordre i neteja.", "Les condicions constructives, ordre, neteja i manteniment, senyalització, instal·lacions de servei o protecció, condicions ambientals, il·luminació, serveis higiènics i locals de descans, i material i locals de primers auxilis.", "La il·luminació i les portes d’emergència.", "Les condicions ambientals i sonores."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 66, "El disseny i les característiques constructives dels llocs de treball han d’oferir seguretat davant dels riscs:", "Només per als riscs higiènics.", "De fatiga visual i postural.", "De trauma auditiu.", "De relliscades o caigudes, xocs o cops contra objectes i ensorraments o caiguda de materials sobre els treballadors."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 67, "L’exposició als agents físics, químics i biològics de l’ambient de treball es regeix:", "Mitjançant normativa específica.", "Només mitjançant normativa internacional.", "Mitjançant normativa autonòmica.", "Mitjançant la Llei 31/1995, de prevenció de riscs laborals estableix criteris per l’exposició a agents físics, químics i biològics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 68, "Les condicions ambientals i termohigromètriques dels llocs de treball:", "Són valors mínims i màxims només d’humitat.", "No poden cap risc per a la seguretat i salut del personal.", "Són la temperatura absoluta.", "Són la humitat relativa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 69, "Quins aspectes dels llocs de treball s’han de tenir en compte perquè el personal amb diversitat funcional s’incorpori als llocs de treball tenint en compte la seguretat i salut?", "Només es tenen en compte les rampes d’accés.", "Els serveis higiènics han d’estar adaptats.", "Les portes, les vies de circulació, les escales, els serveis higiènics i els llocs de treball, utilitzats o ocupats per personal amb diversitat funcional, han d’estar condicionats perquè aquests treballadors puguin utilitzar-los.", "No cal fer adaptacions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 70, "La instal·lació de ventilació d’un centre de treball s’ha de:", "No cal fer cap actuació.", "Només s’ha d’actuar després d’una avaria.", "Mantenir en bon estat de funcionament i un sistema de control ha d’indicar qualsevol avaria, sempre que calgui per a la salut dels treballadors.", "Canviar anualment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 71, "Els llocs de treball han de disposar de vestuaris quan els treballadors hagin de dur roba especial de treball?", "No", "Sí.", "Mai, perquè no és necessari.", "La roba especial de treball no és àmbit de la prevenció de riscs laborals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 72, "Quin article de la Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals estableix la informació, la consulta i la participació del personal?", "L’article 118.", "Els articles 5 i 8.", "Els articles 1 i 3.", "L’article 18."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 73, "L’article 17 de la Llei de prevenció de riscs laborals fa referència:", "Als equips de treball i als mitjans de protecció.", "A la promoció de la salut.", "Al personal sensible.", "A la formació i informació als treballadors."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 74, "Cal disposar de serveis externs a l’empresa per aplicar les mesures d’emergència?", "Sí; en particular en matèria de primer auxilis, assistència mèdica d’urgència, salvament i lluita contra incendis per garantir-ne la rapidesa i l’eficàcia.", "No és necessari.", "S’estableix en l’article 22 de la Llei de prevenció de riscs laborals.", "Sí; però no cal tenir en compte cap particularitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 75, "La vigilància i el control de la salut del personal s’ha de dur a terme:", "En finalitzar la relació laboral amb l’empresa.", "Respectant sempre el dret a la intimitat, a la dignitat de la persona i la confidencialitat de la informació relacionada amb el seu estat de salut.", "La Llei 31/1995, de 8 de novembre, de prevenció de riscs laborals, no estableix cap criteri.", "A criteri tècnic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 1, "D’acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quina de les respostes següents no està inclosa en l’àmbit d’aplicació d’aquesta Llei?", "L’Administració General de l’Estat.", "L’Administració de la Comunitat Autònoma de les Illes Balears.", "Les societats mercantils quan, com a mínim, un 25 % del capital estigui en mans d'administracions públiques.", "El Congrés dels Diputats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 2, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, el dret d'accés a la informació pública quan la informació contingui dades especialment protegides:", "El dret d’accés s’ha d’exercir sota declaració responsable de deure de sigil.", "La publicitat només s’ha de dur a terme amb la dissociació prèvia d’aquestes dades.", "La publicitat s’ha de dur a terme després del transcurs de quatre anys.", "La publicitat s’ha de dur a terme, atès que el dret d'accés és preferent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 3, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, les administracions públiques han de publicar:", "Els plans i els programes anuals i plurianuals en què es fixin objectius concrets, encara que no les activitats i els mitjans per a la seva consecució.", "Els plans i els programes anuals i plurianuals en què es fixin objectius genèrics, encara que no les activitats i els mitjans per a la seva consecució.", "Els plans i els programes anuals i plurianuals en què es fixin objectius concrets, així com les activitats i mitjans per a la seva consecució.", "Els plans i els programes anuals i plurianuals en què es fixin objectius genèrics, així com les activitats i els mitjans per a la seva consecució."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 4, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, senyalau quina informació pública correspon a informació de rellevància jurídica que han de publicar les administracions públiques:", "La relació dels convenis subscrits.", "La informació estadística necessària per valorar el grau de compliment i la qualitat dels serveis públics que siguin de la seva competència.", "Les retribucions percebudes anualment pels alts càrrecs.", "Les directrius, les instruccions, els acords o les circulars en la mesura que suposin una interpretació del dret o tenguin efectes jurídics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 5, "D'acord amb la Constitució espanyola, la llei ha de regular l'accés dels ciutadans als arxius i registres administratius excepte:", "Pel que fa a la seguretat i la defensa de l'Estat, la indagació dels delictes i la intimitat de les persones.", "Pel que fa als secrets d'Estat, la indagació dels delictes i la intimitat de les persones.", "Pel que fa a la seguretat i la defensa de l'Estat, la indagació dels delictes i l'honor de les persones.", "Pel que fa als secrets d'estat, la indagació dels delictes i l'honor de les persones."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 6, "D'acord amb la Llei 39/2015, d'1 d'octubre, del procediment administratiu comú de les administracions públiques, entre els drets de les persones en les seves relacions amb les administracions públiques hi ha:", "L'accés a la informació pública, els fitxers i els registres.", "El dret a la sol·licitud i l’accés als expedients i els registres.", "L'accés a la informació pública, els expedients i les circulars.", "El dret a la sol·licitud i l’accés als arxius i les circulars."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 7, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, si la informació sol·licitada conté dades personals que revelin la ideologia, l’afiliació sindical, la religió o creences, i l’afectat no hagués fet manifestament públiques les dades amb anterioritat:", "L'accés només es pot autoritzar en cas de tenir el consentiment exprés i per escrit de l'afectat.", "L'accés només es pot autoritzar en cas de tenir el consentiment exprés per qualsevol mitjà de l'afectat.", "L'accés només es pot autoritzar en cas de tenir el consentiment exprés i en escriptura pública de l'afectat.", "L'accés únicament es pot autoritzar en cas de tenir el consentiment exprés i per escrit de l'afectat o per compareixença apud acta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 8, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, si la informació sol·licitada inclou dades personals que incloguin dades genètiques o biomètriques:", "L'accés únicament es podrà autoritzar en cas de tenir el consentiment exprés i per escrit de l'afectat, o que aquest afectat hagués fet manifestament públiques les dades anteriorment.", "L'accés només es pot autoritzar en cas que es compti amb el consentiment exprés de l'afectat o si l’accés estigués emparat per una norma amb rang de llei.", "L'accés només es pot autoritzar en cas que es compti amb el consentiment exprés i per escrit de l'afectat.", "L'accés només es pot autoritzar en cas que es compti amb el consentiment exprés, per escrit o per compareixença apud acta de l'afectat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 9, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quines entitats estan obligades a publicar de forma periòdica i actualitzada la informació rellevant per garantir la transparència de la seva activitat?", "Quan almenys el 50 % del total dels seus ingressos anuals tenguin caràcter d’ajuda o subvenció pública, sempre que arribin com a mínim a la quantitat de 10.000 euros.", "Quan almenys el 40 % del total dels seus ingressos anuals tenguin caràcter d’ajuda o subvenció pública, sempre que arribin com a mínim a la quantitat de 10.000 euros.", "Quan almenys el 50 % del total dels seus ingressos anuals tenguin caràcter d’ajuda o subvenció pública, sempre que arribin com a mínim a la quantitat de 5.000 euros.", "Quan almenys el 40 % del total dels seus ingressos anuals tenguin caràcter d’ajuda o subvenció pública, sempre que arribin com a mínim a la quantitat de 5.000 euros."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 10, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern senyalau quina informació pública  correspon a informació institucional, organitzativa i de planificació que han de publicar les administracions públiques:", "Els comptes anuals que s'hagin de rendir.", "Informació relativa a les funcions que desenvolupen i la normativa que els sigui aplicable.", "La informació estadística necessària per valorar el grau de compliment i la qualitat dels serveis públics que siguin de la seva competència.", "La relació dels convenis subscrits."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 11, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, indicau quina de les respostes següents no suposarà una limitació per exercir el dret d'     accés:", "Els interessos econòmics i comercials.", "La política d'aliances militars.", "Les relacions exteriors.", "La seguretat pública."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 12, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, l'aplicació dels límits al dret d'accés:", "Sempre ha de ser justificada i s'ha d’aplicar igual en tots els casos, d’acord amb el principi constitucional d’igualtat.", "No sempre necessita justificació i ha d’atendre les circumstàncies del cas concret.", "Sempre ha de ser justificada i ha d’atendre les circumstàncies del cas concret.", "No sempre necessita justificació i s'ha d’aplicar igual en tots els casos, d’acord amb el principi constitucional d’igualtat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 13, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quan la informació sol·licitada contingui dades personals però aquestes dades no estiguin especialment protegides, l'òrgan al qual es dirigeixi la sol·licitud:", "Ha de concedir l'accés immediatament sense possibilitat de recurs administratiu per part dels afectats.", "Ha de concedir l'accés si s'efectua la dissociació prèvia de les dades de caràcter personal de manera que s'impedeixi la identificació de les persones afectades.", "Ha de concedir l'accés immediatament amb possibilitat de recurs administratiu per part dels afectats.", "No ha de concedir l'accés."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 14, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, el procediment per a l'exercici del dret d'accés s'iniciarà amb la presentació de la sol·licitud corresponent, que s'haurà de dirigir:", "Al Portal de Transparència de cada administració.", "Al Portal de Transparència de l’Estat.", "Al Consell de Transparència i Bon Govern.", "Al titular de l’òrgan administratiu o entitat que posseeixi la informació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 15, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, cal motivar la sol·licitud d'accés a la informació?", "Haurà d'estar motivada.", "No s'ha de motivar en cap cas.", "No és obligatori a motivar la sol·licitud, però es pot motivar.", "L'absència de motivació pot ser per si mateixa causa de rebuig de la sol·licitud."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 16, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, si la sol·licitud d'informació no identifica de forma suficient la informació sol·licitada:", "Es demanarà al sol·licitant que la concreti en un termini de quinze dies, amb indicació que, si no ho fa, se'l tendrà per desistit, i que no se suspèn el termini per dictar resolució.", "Es demanarà al sol·licitant que la concreti en un termini de deu dies, amb indicació que, si no ho fa, se'l tendrà per desistit, i que no se suspèn el termini per dictar resolució.", "Es demanarà al sol·licitant que la concreti en un termini de quinze dies, amb indicació que, si no ho fa, se'l tendrà per desistit, així com la suspensió del termini per dictar resolució.", "Es demanarà al sol·licitant que la concreti en un termini de deu dies, amb indicació que, si no ho fa, se'l tendrà per desistit, així com la suspensió del termini per dictar resolució."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 17, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, el dret d'accés pot ser limitat quan accedir a la informació suposi un perjudici:", "Per a la seguretat internacional.", "Per als interessos econòmics i comercials.", "Per als interessos polítics del govern.", "Per a la igualtat de gènere."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 18, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, si la informació sol·licitada pot afectar drets o interessos de tercers:", "Si estan degudament identificats, se'ls ha de concedir un termini de quinze dies perquè puguin realitzar les al·legacions que estimin oportunes.", "En tot cas, fins i tot sense estar identificats, se'ls ha de concedir un termini de quinze dies perquè puguin fer les al·legacions que estimin oportunes.", "Si estan degudament identificats, se'ls ha de concedir un termini de deu dies perquè puguin fer les al·legacions que estimin oportunes.", "En tot cas, fins i tot sense estar identificats, se'ls ha de concedir un termini de deu dies perquè puguin fer les al·legacions que estimin oportunes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 19, "D'acord amb la Llei 19/ 2013, transcorregut el termini màxim per resoldre les sol·licituds d'informació pública sense que s'hagi dictat i notificat resolució expressa:", "S'entén que la sol·licitud ha estat estimada.", "S'entén que la sol·licitud ha caducat.", "S'entén que la sol·licitud ha estat desestimada.", "S'entén que el sol·licitant ha renunciat a la sol·licitud."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 20, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, la reclamació davant el Consell de Transparència i Bon Govern:", "Té la consideració de substitutiva de la rectificació d’errors.", "Té la consideració de substitutiva del recurs de reposició.", "Té la consideració de substitutiva del recurs d’alçada.", "Té la consideració de substitutiva del recurs extraordinari de revisió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 21, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quina de les sol·licituds d'informació següents s'inadmeten a tràmit?", "Les dirigides a un òrgan que no disposi de la informació quan es conegui el competent.", "Les relatives a informació per a la divulgació de la qual sigui necessària una acció prèvia de reelaboració.", "Les que continguin dades personals que incloguin dades genètiques o biomètriques.", "Les que continguin dades personals relatives a la comissió d'infraccions penals o administratives que no comporten l'amonestació pública a l'infractor."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 22, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, la formalització de l'accés a la informació pública:", "S’ha de fer preferentment per via electrònica. Quan no es pugui donar l'accés en el moment de la notificació de la resolució, s'ha d'atorgar, en qualsevol cas, en un termini no superior a deu dies.", "S’ha de fer preferentment per via electrònica. Quan no es pugui donar l'accés en el moment de la notificació de la resolució, s'ha d'atorgar, en qualsevol cas, en un termini no superior a un mes.", "S’ha de fer preferentment per escrit en paper. Quan no es pugui donar l'accés en el moment de la notificació de la resolució s'haurà d'atorgar, en qualsevol cas, en un termini no superior a deu dies.", "S’ha de fer preferentment per escrit en paper. Quan no es pugui donar l'accés en el moment de la notificació de la resolució, s'ha d'atorgar, en qualsevol cas, en un termini no superior a un mes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 23, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, a l'efecte d’aplicar als seus responsables el règim disciplinari, l'incompliment de l'obligació de resoldre dins termini les resolucions dictades en matèria d'accés a la informació pública:", "Té en tot cas la consideració d'infracció molt greu.", "Té en tot cas la consideració d'infracció greu.", "Només l' incompliment reiterat s'estableix com a infracció, que té la consideració de greu.", "Té la consideració d'infracció greu però si l'incompliment és reiterat tindrà la consideració d'infracció molt greu ."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 24, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, la reclamació davant el Consell de Transparència i Bon Govern s’ha d’interposar:", "En el termini d’un mes a comptar de l’endemà de la notificació de l’acte impugnat o des de l’endemà a aquell en què es produeixin els efectes del silenci administratiu.", "En el termini d'un mes a comptar de l'endemà de la notificació de l'acte impugnat o de tres mesos de l'endemà del dia en què es produeixin els efectes del silenci administratiu.", "En el termini d'un mes a comptar de l'endemà de la notificació de l'acte impugnat o de sis mesos des de l'endemà del dia en què es produeixin els efectes del silenci administratiu.", "En el termini d'un mes a comptar de l'endemà de la notificació de l'acte impugnat o de dos mesos des de l'endemà del dia en què es produeixin els efectes del silenci administratiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 25, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, el termini màxim per resoldre i notificar la resolució de la reclamació davant el Consell de Transparència i Bon Govern:", "És de dos mesos, transcorregut el qual la reclamació s'entén estimada.", "És de dos mesos, transcorregut el qual la reclamació s’entén desestimada.", "És de tres mesos, transcorregut el qual la reclamació s'entén estimada.", "És de tres mesos, transcorregut el qual la reclamació s'entén desestimada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 26, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, les resolucions del Consell de Transparència i Bon Govern s’han de publicar:", "Per mitjans electrònics i en els termes en què s’estableixi reglamentàriament.", "Per mitjans electrònics i en els termes en què s'estableixi legalment.", "Al diari oficial corresponent i en els termes en què s'estableixi reglamentàriament.", "Al diari oficial corresponent i en els termes en què s'estableixi legalment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 27, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, les resolucions de les reclamacions davant del Consell de Transparència i Bon Govern s’han de comunicar:", "Pel president del Consell de Transparència i Bon Govern al Defensor del Poble.", "Pel secretari del Consell de Transparència i Bon Govern al Govern.", "Pel president del Consell de Transparència i Bon Govern al Govern.", "Pel secretari del Consell de Transparència i Bon Govern al Defensor del Poble."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 28, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, les comunitats autònomes, per a la resolució de la reclamació prevista amb relació al dret d'accés a la informació pública:", "Han de crear un òrgan propi per resoldre-la.", "Poden no ajustar la seva actuació al que estableix aquesta Llei.", "Han d’atribuir aquesta competència al Consell de Transparència i Bon Govern.", "Poden atribuir aquesta competència al Consell de Transparència i Bon Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 29, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quan es pot limitar el dret d'accés a la informació pública relacionada amb les relacions exteriors?", "En cap cas, sempre preval el dret a la informació.", "En tot cas, atès el caràcter de les relacions exteriors.", "Quan l'ambaixada del país afectat s'oposi a aquest dret d'accés.", "Quan accedir a la informació suposi un perjudici per a les mateixes relacions exteriors."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 30, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, el dret d'accés a la informació pública s’ha d’exercir:", "Sense límit, atès que és un dret constitucional.", "Té només els límits que regula la Constitució Espanyola, ja que qualsevol altra limitació vulneraria la Constitució.", "Té el límit derivat de la protecció de dades de caràcter personal.", "Té el límit temporal de quatre anys des que es resol l’expedient al qual es pretén accedir."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 31, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, si la informació sol·licitada pot afectar drets o interessos de tercers, degudament identificats, i se'ls ha concedit un termini per presentar al·legacions:", "Se suspèn el termini per dictar resolució fins que s'hagin rebut les al·legacions o hagi transcorregut el termini de vint dies per presentar-les.", "Se suspèn el termini per dictar resolució fins que s'hagin rebut les al·legacions o hagi transcorregut el termini de quinze dies per presentar-les", "No és obligatori suspendre el termini per dictar resolució fins que s'hagin rebut les al·legacions o hagi transcorregut el termini de vint dies per presentar-les.", "No és obligatori suspendre el termini per dictar resolució fins que s'hagin rebut les al·legacions o hagi transcorregut el termini de quinze dies presentar-les."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 32, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, la resolució en la qual es concedeixi o denegui l'accés a la informació pública haurà de notificar-se:", "Al sol·licitant i als tercers afectats quan així ho hagin sol·licitat en el termini màxim de tres mesos des de la recepció de la sol·licitud.", "Únicament al sol·licitant en el termini màxim de tres mesos des de la recepció de la sol·licitud.", "Únicament al sol·licitant en el termini màxim d'un mes des de la recepció de la sol·licitud.", "Al sol·licitant i als tercers afectats quan així ho hagin sol·licitat en el termini màxim d'un mes des de la recepció de la sol·licitud."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 33, "D’acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, les comunitats autònomes, per atribuir la competència per a la resolució de la reclamació prevista en relació amb el dret d’accés al Consell de Transparència i Bon Govern:", "Hauran de subscriure el conveni corresponent amb l'Administració General de l'Estat.", "Hauran de fer el corresponent contracte amb l'Administració General de l'Estat.", "Hauran de dur a terme la comanda de gestió corresponent amb l'Administració General de l'Estat.", "No poden atribuir aquesta competència al Consell de Transparència i Bon Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 34, "Segons la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, amb relació a la protecció de les dades de caràcter personal, cal el consentiment exprés i per escrit de l'afectat per a dades relatives a:", "Origen racial.", "Salut.", "Ideologia.", "Vida sexual."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 35, "Segons la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quina de les respostes següents no indica un membre de la Comissió de Transparència i Bon Govern?", "Un representant de l’Autoritat Independent de Responsabilitat Fiscal.", "Un representant de l’Agència Espanyola de Protecció de Dades.", "Un representant de l'Institut de les Dones.", "Un senador."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 36, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, indicau la resposta falsa:", "La publicitat activa i el dret d’accés fomenten la transparència i la participació en l’activitat pública.", "En la publicitat activa l’Administració posa les dades a disposició de la ciutadania, en portals i pàgines web, sempre que els ciutadans les demanin proactivament.", "En el dret d'accés a la informació pública, l'Administració respon a les demandes d'informació dels ciutadans.", "El dret d'accés a la informació pública pot ser limitat de manera justificada i proporcionada a l'objecte i la finalitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 37, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, el Consell de Transparència i Bon Govern, es configura com a:", "Òrgan incardinat a l'estructura del ministeri competent en funció pública.", "Organisme públic adscrit a l'actual Ministeri d'Hisenda i Funció Pública.", "Òrgan previst en el títol IV de la Constitució espanyola.", "Consell interterritorial en què estan representats l'Estat i les comunitats autònomes i les entitats locals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 38, "D'acord amb la Llei 39/2015, d'1 d'octubre, del procediment administratiu comú de les administracions públiques, entre els principis de bona regulació hi ha:", "Els de transparència i eficiència.", "El d’eficiència, però no el de transparència.", "El de transparència, però no el d'eficiència.", "Cap dels dos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 39, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, indicau quina de les respostes següents no suposarà una limitació per exercir el dret d'accés.", "La política econòmica i monetària.", "Les funcions administratives de vigilància, inspecció i control.", "La protecció del medi ambient.", "La garantia de la confidencialitat en els processos penals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 40, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quina de les dades personals següents es poden revelar sense autorització de l'afectat si una norma amb rang de llei ho empara?", "Dades personals que facin referència a la salut.", "Dades personals que revelin la ideologia.", "Dades personals que revelin l’afiliació sindical.", "Dades personals que revelin la religió o les creences."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 41, "Senyalau la resposta correcta respecte de la sol·licitud d'accés a la informació pública segons la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern:", "La resolució en què es concedeixi o denegui l'accés s'ha de notificar al sol·licitant i als tercers afectats quan així ho hagin sol·licitat en el termini màxim d'un mes des de la recepció de la sol·licitud per l'òrgan competent per resoldre.", "Transcorregut el termini màxim per resoldre sense que s'hagi dictat i notificat una resolució expressa s'entén que la sol·licitud ha estat estimada.", "Les resolucions dictades en matèria d'accés a la informació pública no són recurribles directament davant de la Jurisdicció Contenciosa Administrativa.", "L'incompliment reiterat de l'obligació de resoldre dins termini té la consideració d'infracció molt greu a l'efecte de l'aplicació als responsables del règim disciplinari que preveu la normativa reguladora corresponent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 42, "Si un ciutadà sol·licita informació a l'Administració i hi són aplicables els límits de dret d'accés que preveu l'article 14 de la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, però aquests límits no afecten la totalitat de la informació:", "Se n’ha d’oferir un accés parcial sense indicar al sol·licitant quina part de la informació ha estat omesa.", "No s’ha de concedir mai l'accés parcial a la informació.", "S’ha de concedir l'accés parcial amb l’omissió prèvia de la informació afectada pel límit d'accés, llevat que en resulti una informació distorsionada o que no tengui sentit.", "Sempre es concedirà l’accés parcial a la informació a la qual no l'afecti la limitació prevista en l'article 14."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 43, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, el Consell de Transparència i Bon Govern:", "No té personalitat pròpia perquè és un òrgan dependent del ministeri competent en funció pública.", "Té personalitat jurídica pròpia, però no plena capacitat d'obrar.", "Té personalitat jurídica pròpia i plena capacitat dobrar.", "No té personalitat jurídica pròpia, però sí independència funcional."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 44, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, indicau quina de les respostes següents no suposa una limitació per exercir el dret d'accés:", "La política econòmica i monetària.", "Els interessos econòmics i comercials.", "Les funcions administratives de vigilància, inspecció i control.", "La protecció de l'agricultura."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 45, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, si la informació sol·licitada inclou dades personals que facin referència a dades relatives a la comissió d'infraccions penals o administratives que no comportin l'amonestació pública a l'infractor:", "L'accés només es pot autoritzar en cas que es compti amb el consentiment exprés de l'afectat o si l’accés està emparat per una norma amb rang de llei.", "L'accés només es pot autoritzar en cas que es compti amb el consentiment exprés i per escrit de l'afectat.", "L'accés només es pot autoritzar en cas que estigui emparat per una norma amb rang de llei.", "L'accés no es pot autoritzar."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 46, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quina de les sol·licituds d'informació següents s'inadmetran a tràmit?", "Les que continguin dades personals relatives a la comissió d'infraccions penals o administratives que no comporten l'amonestació pública a l'infractor.", "Les que siguin manifestament repetitives.", "Les que continguin dades personals que incloguin dades genètiques o biomètriques.", "Les que continguin dades personals que facin referència a la vida sexual."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 47, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quin és el termini màxim per notificar la resolució en què es concedeixi o denegui l'accés a la informació pública?", "Un mes des de la recepció de la sol·licitud per part de l’òrgan competent per resoldre, sense possibilitat d'ampliació de termini.", "Tres mesos des de la recepció de la sol·licitud per part de l’òrgan competent per resoldre, sense possibilitat d'ampliació de termini.", "Un mes des de la recepció de la sol·licitud per l’òrgan competent per resoldre, amb possibilitat d’ampliar-se en un mes més d’acord amb la llei.", "Tres mesos des de la recepció de la sol·licitud per l’òrgan competent per resoldre, amb possibilitat d’ampliar-se en tres mesos més d’acord amb la llei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 48, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quin dels següents és un motiu per ampliar el termini màxim per notificar la resolució en què es concedeixi o denegui l'accés a la informació pública?", "Falta de mitjans materials per resoldre dins el termini.", "Tenir acumulació d’expedients.", "Falta de mitjans personals.", "La complexitat de la informació que se sol·licita."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 49, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, la reclamació davant el Consell de Transparència i Bon Govern:", "Pot interposar-se amb caràcter obligatori i previ a la impugnació en via contenciosa administrativa.", "Pot interposar-se amb caràcter obligatori i previ al recurs d’alçada o de reposició que correspongui.", "Es pot interposar amb caràcter potestatiu i previ al recurs d’alçada o de reposició que correspongui.", "Pot interposar-se amb caràcter potestatiu i previ a la impugnació en via contenciosa administrativa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 50, "La Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, estableix que l'incompliment reiterat de les obligacions de publicitat activa que es regulen en el capítol II del títol I de la Llei té la consideració:", "D’infracció molt greu a l’efecte d'aplicació, als seus responsables, del règim disciplinari que preveu la normativa reguladora corresponent.", "D’infracció greu a l’efecte d’aplicació, als seus responsables, del règim disciplinari  que preveu la normativa reguladora corresponent.", "D’infracció lleu a l’efecte d'aplicació, als seus responsables, del règim disciplinari que preveu la normativa reguladora corresponent.", "D’amonestació als seus responsables, a l’efecte d’aplicació del règim disciplinari que preveu la normativa reguladora corresponent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 51, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, senyalau quina informació pública correspon a informació econòmica, pressupostària i estadística que han de publicar les administracions públiques:", "Les resolucions d’autorització o de reconeixement de compatibilitat que afectin els empleats públics.", "La informació relativa a les funcions que desenvolupen.", "Els plans i els programes anuals i plurianuals en què es fixin objectius concrets.", "Els avantprojectes de llei i els projectes de decrets legislatius la iniciativa dels quals els correspongui."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 52, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, indicau la resposta correcta:", "La publicitat activa respon a les demandes d’informació per part dels ciutadans.", "La transparència pública pot ser per publicitat activa i publicitat passiva.", "La transparència pública pot ser per publicitat activa i per dret d’accés a la informació pública.", "La publicitat passiva no respon a demandes d’informació, ja que la ciutadania pren un paper passiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 53, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, l'aplicació dels límits al dret d'accés:", "S'han d'aplicar de la mateixa manera en totes les sol·licituds pel principi d'interdicció de l'arbitrarietat dels poders públics.", "Han d’atendre les circumstàncies del cas concret, especialment la concurrència d'interès exclusivament públic.", "Han d’atendre les circumstàncies del cas concret, especialment la concurrència d'un interès públic o privat.", "Han d’atendre les circumstàncies del cas concret, sense atendre altres possibles interessos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 54, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, la sol·licitud d'accés a la informació haurà de permetre tenir constància en tot cas de la informació següent:", "La identitat del sol·licitant i la informació que se sol·licita.", "La identitat del sol·licitant, la informació que se sol·licita i una adreça de contacte.", "La identitat del sol·licitant, la informació que se sol·licita, la motivació de la consulta i una adreça de contacte.", "La identitat del sol·licitant, la informació que se sol·licita, els afectats per la revelació de les dades i una adreça de contacte."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 55, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quina de les dades personals següents es poden revelar sense autorització de l'afectat si una norma amb rang de llei ho empara?", "Dades personals que revelin l’origen racial.", "Dades personals que revelin l’afiliació sindical.", "Dades personals que revelin la religió o creences.", "Dades personals que revelin la ideologia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 56, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, el dret d'accés a la informació pública significa:", "Que tots els ciutadans de la Unió Europea tenen dret a accedir a la informació pública.", "Que tots els espanyols tenen dret a accedir a la informació pública.", "Que totes les persones tenen dret a accedir a la informació pública.", "Que tots els ciutadans de la Unió Europea i dels països, que hagin subscrit un conveni, tenen dret a accedir a la informació pública."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 57, "El dret d'accés a la informació pública que regula la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, suposa per a les administracions públiques l'obligació:", "De fer públiques determinades informacions de manera proactiva i gratuïta.", "D'atendre les sol·licituds d'informació que facin els ciutadans de manera gratuïta.", "De fer públiques determinades informacions de forma proactiva, tot i poder establir una taxa.", "D'atendre les sol·licituds d'informació que facin els ciutadans, tot i poder establir una taxa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 58, "La Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern,en l'article 36 indica que en la composició de la Comissió de Transparència i Bon Govern s'inclou:", "Un representant de la Intervenció General de l’Administració de l’Estat.", "Un representant de l’Agència Espanyola de Protecció de Dades.", "Un representant de la Secretaria d’Estat de Polítiques Públiques.", "Un representant de l’Autoritat Independent de Responsabilitat Fiscal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 59, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, senyalau quina informació pública correspon a informació econòmica, pressupostària i estadística que han de publicar les administracions públiques:", "Les subvencions i ajudes públiques concedides.", "Els projectes de reglaments la iniciativa dels quals els correspongui.", "Les memòries i els informes que conformen els expedients d'elaboració dels textos normatius.", "Els avantprojectes de llei i els projectes de decrets legislatius la iniciativa dels quals els correspongui."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 60, "Segons la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, en relació amb la protecció de les dades de caràcter personal, s’hi pot accedir quan aquest accés estigui emparat per una norma amb rang de llei per a dades relatives a:", "Afiliació sindical.", "Religió.", "Ideologia.", "Vida sexual."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 61, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, si la sol·licitud d'informació no identifica de forma suficient la informació sol·licitada:", "S’ha de demanar al sol·licitant que la concreti en un termini de deu dies.", "S’ha de demanar al sol·licitant que la concreti en un termini de quinze dies.", "S’ha de demanar que el sol·licitant la concreti en un termini d'un mes.", "S'ha d’inadmetre la sol·licitud, sens perjudici de poder tornar-la a presentar."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 62, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quines de les dades personals següents es poden revelar si l'afectat les ha fet manifestament públiques amb anterioritat?", "Dades personals que incloguin dades genètiques o biomètriques.", "Dades personals que facin referència a la vida sexual.", "Dades personals relatives a la comissió d'infraccions penals o administratives que no comporten l'amonestació pública a l'infractor.", "Dades personals que revelin la religió o creences."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 63, "D'acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, senyalau quina informació pública correspon a informació de rellevància jurídica que han de publicar les administracions públiques:", "Les memòries i els informes que conformen els expedients d'elaboració dels textos normatius.", "Informació relativa a la seva estructura organitzativa.", "Els comptes anuals que s'hagin de retre.", "Informació relativa a les funcions que desenvolupen."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 64, "D’acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quina de les respostes següents no està inclosa dins l’àmbit d’aplicació d’aquesta Llei?", "Les entitats gestores i els serveis comuns de la Seguretat Social.", "La Casa de Sa Majestat el Rei.", "El Senat.", "Les fundacions l’activitat de les quals es realitza en territori espanyol."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 65, "D’acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, el dret d’accés a la informació pública s’exerceix:", "Sense límit, atès que és un dret constitucionalment garantit.", "Té el límit derivat dels secrets polítics.", "Té el límit derivat de la protecció de dades de caràcter personal.", "Té el límit temporal de deu anys des que es resol l’expedient al qual es pretén accedir."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 66, "D’acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, tota la informació ha d’estar a disposició de les persones amb discapacitat en una modalitat subministrada per mitjans o en formats adequats:", "De manera que resultin accessibles i comprensibles, d’acord amb el principi d’accessibilitat universal i disseny per a tothom.", "De manera que resultin accessibles i comprensibles, sempre que la tecnologia ho permeti.", "De manera que siguin accessibles i comprensibles, en el termini de dos anys des de la publicació d’aquesta Llei.", "De manera que siguin accessibles i comprensibles, d’acord amb el principi d’accessibilitat per a la majoria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 67, "D’acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, quines entitats privades estan obligades a publicar de forma periòdica i actualitzada la informació, el coneixement de la qual sigui rellevant per garantir la transparència de la seva activitat?", "Les que percebin durant el període d’un any ajudes o subvencions públiques en una quantia superior a 100.000 euros.", "Les que percebin durant el període d’un any ajudes o subvencions públiques en una quantia superior a 10.000 euros.", "Les que percebin durant el període de tres anys ajudes o subvencions públiques en una quantia superior a 100.000 euros.", "Les que percebin durant el període de tres anys ajudes o subvencions públiques en una quantia superior a 10.000 euros."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 68, "La Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, com anomena els dos tipus de transparència que regula?", "Publicitat activa i dret de sol·licitud de la informació pública.", "Publicitat informativa i dret d’accés a la informació pública.", "Publicitat informativa i dret de sol·licitud de la informació pública.", "Publicitat activa i dret d’accés a la informació pública."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 69, "D’acord amb la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, en aplicació del principi de transparència entre els principis de bona regulació, les administracions públiques:", "Possibilitaran l’accés a la normativa en vigor i els documents propis del seu procés d’elaboració, però no es preveu que els destinataris potencials puguin tenir una participació activa en l’elaboració de les normes.", "Possibilitaran l’accés exclusivament als processos d’elaboració de les lleis, ja que l’accés a la normativa vigent s’obliga pel principi de seguretat jurídica.", "Possibilitaran l’accés a la normativa en vigor a través de les pàgines web però no estan obligades a fer-ho en els processos d’elaboració de les lleis.", "Possibilitaran l’accés a la normativa en vigor i els documents propis del seu procés d’elaboració i possibilitaran que els destinataris potencials tenguin una participació activa en l’elaboració de les normes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 70, "D’acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, senyalau quina informació pública es correspon a informació institucional, organitzativa i de planificació que han de publicar les administracions públiques:", "La informació relativa a la seva estructura organitzativa.", "Les directrius, instruccions, acords o circulars que tenguin efectes jurídics.", "Els projectes de reglaments la iniciativa dels quals els correspongui.", "La informació estadística necessària per valorar el grau de compliment i la qualitat dels serveis públics que siguin de la seva competència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 71, "D’acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, què s’entén per informació pública?", "Els continguts, però no els documents, que estiguin en poder d’algun dels subjectes inclosos en l’àmbit d’aplicació d’aquesta Llei, elaborats o adquirits en l’exercici de les seves funcions.", "Els continguts, però no els documents, que estiguin en poder d’algun dels subjectes inclosos a l’àmbit d’aplicació d’aquesta Llei, sempre que hagin estat elaborats per aquests subjectes.", "Els continguts o documents que estiguin en poder d’algun dels subjectes inclosos a l’àmbit d’aplicació d’aquesta Llei, sempre que hagin estat elaborats per aquests subjectes.", "Els continguts o documents que estiguin en poder d’algun dels subjectes inclosos en l’àmbit d’aplicació d’aquesta Llei, elaborats o adquirits en l’exercici de les seves funcions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 72, "D’acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, el dret d’accés podrà ser limitat quan accedir a la informació suposi un perjudici:", "Per a les relacions interiors.", "Per a la igualtat de les parts en els processos judicials i la tutela judicial efectiva.", "Per a la seguretat internacional.", "Per a la geopolítica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 73, "D’acord amb la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern, l’aplicació dels límits al dret d’accés:", "Ha d’atendre les circumstàncies del cas concret, especialment a la concurrència d’un interès públic o privat.", "Ha d’atendre les circumstàncies del cas concret, especialment la concurrència d’interès exclusivament públic.", "Ha d’atendre les circumstàncies del cas concret, especialment la concurrència d’interès exclusivament privat.", "Ha d’atendre les circumstàncies del cas concret, sense atendre altres possibles interessos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 1, "Segons l’article 16 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quines són les funcions del secretari d’un òrgan col·legiat?", "Únicament garantir que les regles de constitució dels òrgans es compleixen adequadament.", "Vetlar per la legalitat formal i material de les actuacions de l’òrgan col·legiat, certificar les actuacions d’aquest i garantir que els procediments i regles de constitució i adopció d’acords són respectades.", "Establir els procediments que s’han de seguir per adoptar acords.", "Només assistir a les sessions dels òrgans col·legiats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 2, "Qui pot sol·licitar al secretari d’un òrgan col·legiat l’expedició de la certificació dels acords?", "Els qui acreditin la titularitat d’un interès legítim.", "Qualsevol persona.", "Ningú.", "Només els membres de l’òrgan."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 3, "Senyalau la resposta correcta. Segons el que disposa l’article 18 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, a l’acta de la sessió d’un òrgan col·legiat s’ha d’incloure:", "Només els assistents i el contingut dels acords adoptats.", "Els assistents, l’ordre del dia de la reunió, les circumstàncies del lloc i temps en què s’ha celebrat, els punts principals de les deliberacions, així com el contingut dels acords adoptats.", "Únicament l’ordre del dia i el contingut dels acords adoptats.", "Només els assistents i les circumstàncies del lloc i temps en què s’ha celebrat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 4, "Senyalau la resposta correcta respecte de l’acta de cada sessió:", "S’ha d’aprovar a la mateixa reunió.", "Només es pot aprovar a la reunió següent.", "Pot aprovar-se a la mateixa reunió o a la següent immediata", "S’ha d’aprovar a la darrera reunió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 5, "Quina de les funcions següents no correspon al president dels òrgans col·legiats de l’Administració general de l’Estat i de les entitats de dret públic vinculades o que en depenen?", "Visar les actes i les certificacions dels acords de l’òrgan.", "Assegurar el compliment de les lleis.", "Acordar la convocatòria de les sessions ordinàries i extraordinàries i la fixació de l’ordre del dia, tenint en compte, si escau, les peticions dels altres membres, sempre que hagin estat formulades amb la suficient antelació.", "Expedir certificacions de les consultes, dels dictàmens i dels acords aprovats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 6, "Quina de les funcions següents no correspon al secretari dels òrgans col·legiats de l’Administració general de l’Estat i de les entitats de dret públic vinculades o que en depenen?", "Exercir la representació de l’òrgan.", "Expedir certificacions de les consultes, dels dictàmens i dels acords aprovats.", "Preparar el despatx dels afers, i redactar i autoritzar les actes de les sessions.", "Rebre els actes de comunicació dels membres amb l’òrgan, siguin notificacions, peticions de dades, rectificacions o qualsevol altra classe d’escrits dels quals hagi de tenir coneixement."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 7, "Senyalau la resposta incorrecta. Segons l’article 19 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, els membres dels òrgans col·legiats de l’Administració general de l’Estat i de les entitats de dret públic vinculades o que en depenen:", "Han de rebre, amb una antelació mínima de dos dies, la convocatòria que contengui l’ordre del dia de les reunions.", "Han d’obtenir la informació necessària per complir les funcions assignades.", "Han de participar als debats de les sessions.", "Han de rebre, amb una antelació mínima d’una setmana, la convocatòria que contengui l’ordre del dia de les reunions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 8, "En quins casos els membres titulars de l’òrgan col·legiat de l’Administració general de l’Estat i de les entitats de dret públic vinculades o dependents han de ser substituïts pels seus suplents, si n’hi ha?", "En casos d’absència o de malaltia.", "Sempre que ho sol·licitin.", "Quan ho sol·licitin les organitzacions representatives.", "En general, encara que no hi hagi causa justificada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 9, "Si alguna disposició atribueix la competència a una administració, sense especificar l’òrgan que l’ha d’exercir, s’entén que la facultat d’instruir i de resoldre els expedients correspon:", "Als òrgans superiors competents per raó de la matèria.", "Als òrgans inferiors competents per raó de la matèria i el territori.", "Als òrgans inferiors que tenguin competència únicament per raó del territori.", "Als òrgans superiors competents per raó del territori i la matèria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 10, "A qui poden delegar els òrgans de les diferents administracions públiques l’exercici de les competències que tenguin atribuïdes?", "En altres òrgans de la mateixa administració, encara que no siguin jeràrquicament dependents, o en els organismes públics o entitats de dret públic vinculats o dependents d’aquelles.", "En altres òrgans de la mateixa administració, sempre que siguin jeràrquicament dependents.", "Sempre en òrgans d’una altra administració.", "Només en els organismes públics o entitats de dret públic vinculats o dependents d’aquelles."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 11, "On s’ha de publicar la delegació de competències i la revocació d’aquestes?", "Únicament en el Butlletí Oficial de l’Estat.", "Únicament en el butlletí de la comunitat autònoma o al de la província.", "En el Butlletí Oficial de l’Estat, en el de la comunitat autònoma o en el de la província, segons l’administració a què pertanyi l’òrgan delegant, i l’àmbit territorial de competència d’aquest.", "No cal publicar-la."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 12, "Senyalau la resposta incorrecta en relació amb la delegació de competències:", "Les resolucions administratives que s’adoptin per delegació han d’indicar expressament aquesta circumstància i es consideren dictades per l’òrgan delegant.", "Llevat d’autorització expressa d’una llei, no es poden delegar les competències que s’exerceixin per delegació.", "La delegació no és revocable en cap cas per l’òrgan que l’hagi conferida.", "L’acord de delegació d’aquelles competències atribuïdes a òrgans col·legiats, per a l’exercici de les quals es requereixi un quòrum o majoria especial, s’ha d’adoptar observant, en qualsevol cas, aquest quòrum o majoria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 13, "En quins casos la realització d’activitats de caràcter material o tècnic de la competència dels òrgans administratius o de les entitats de dret públic es pot encarregar a altres òrgans o entitats de dret públic de la mateixa administració o d’una altra?", "Sempre que entre les seves competències estiguin aquestes activitats, per raons d’eficàcia o quan no es posseeixin els mitjans tècnics idonis per exercir-les.", "Sempre que entre les seves competències estiguin aquestes activitats, per raons d’eficàcia, encara que es posseeixin els mitjans tècnics idonis per exercir-les.", "Per raons tècniques i sempre que no es posseeixin els mitjans per exercir-les.", "Sempre per raons d’eficiència i d’eficàcia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 14, "On s’ha de publicar l’encàrrec de gestió entre òrgans i entitats de dret públic de diferents administracions?", "Únicament en el Butlletí Oficial de l’Estat.", "Únicament en el butlletí de la comunitat autònoma o en el de la província.", "En el Butlletí Oficial de l’Estat, en el de la comunitat autònoma o en el de la província, segons l’administració a què pertanyi l’òrgan que efectua l’encàrrec, excepte en el cas de la gestió ordinària dels serveis de les comunitats autònomes per part de les diputacions provincials o, si s’escau, cabildos o consells insulars, que es regeix per la legislació de règim local.", "No cal publicar-la."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 15, "Senyalau la resposta incorrecta en relació amb la suplència que preveu l’article 13 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic:", "Si no es designa cap suplent, la competència de l’òrgan administratiu l’ha d’exercir qui designi l’òrgan administratiu immediat superior de qui depengui.", "La suplència no implica l’alteració de la competència.", "Els titulars dels òrgans administratius poden ser suplents temporalment en els casos de vacant, absència o malaltia, així com en els casos en què hagi estat declarada la seva abstenció o recusació.", "Perquè sigui vàlida, és necessari publicar-la."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 16, "Què ha de fer l’òrgan administratiu que es consideri incompetent per resoldre un afer?", "Ha de remetre directament les actuacions a l’òrgan que consideri competent i ha de notificar aquesta circumstància als interessats.", "Ha de remetre, a través d’un jeràrquic superior, les actuacions a l’òrgan que consideri competent.", "Ha de remetre directament les actuacions a l’òrgan que consideri competent, sense necessitat de notificar aquesta circumstància als interessats.", "Ha de dictar una resolució en què es declari incompetent i l’ha de notificar als interessats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 17, "Senyalau la resposta correcta en relació amb la competència:", "Els interessats, tant si són part en el procediment com si no, poden adreçar-se a l’òrgan que estigui coneixent d’un afer perquè declini la seva competència i remeti les actuacions a l’òrgan competent.", "Els conflictes d’atribucions només es poden suscitar entre òrgans d’una mateixa administració no relacionats jeràrquicament, i pel que fa a afers sobre els quals no hagi finalitzat el procediment administratiu.", "Els interessats no es poden adreçar a l’òrgan que considerin competent perquè requereixi la inhibició al que conegui de l’afer.", "Els conflictes d’atribucions només es poden suscitar entre òrgans d’una mateixa administració que estiguin relacionats jeràrquicament, i respecte a afers sobre els quals hagi finalitzat el procediment administratiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 18, "Senyalau la resposta incorrecta. Els convenis que subscriguin les administracions públiques, els organismes públics i les entitats de dret públic vinculats o dependents i les universitats públiques han d’incloure:", "El règim de recursos.", "Els subjectes que subscriuen el conveni i la capacitat jurídica amb què actua cadascuna de les parts.", "El règim de modificació del conveni.", "L’objecte del conveni i les actuacions que ha de dur a terme cada subjecte per al seu compliment, amb indicació, si s’escau, la titularitat dels resultats obtinguts."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 19, "Senyalau la resposta correcta en relació amb el termini de vigència d’un conveni d’acord amb la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic:", "No pot ser superior a quatre anys, llevat que normativament es prevegi un termini superior.", "En cap cas no pot ser superior a quatre anys.", "No pot ser superior a 5 anys, llevat que es prevegi normativament un termini superior.", "No pot ser superior a 3 anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 20, "Quina de les causes següents no preveu l’article 51 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, com una causa de resolució d’un conveni?", "El transcurs del termini de vigència del conveni sense que s’hagi acordat la pròrroga del conveni.", "L’acord unànime de tots els signants.", "L’incompliment de les obligacions i els compromisos assumits per part d’algun dels signants.", "La renúncia verbal per part d’algun dels signants."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 21, "En l’àmbit de l’Administració general de l’Estat, la designació de suplent es pot efectuar:", "En els reials decrets d’estructura orgànica bàsica dels departaments ministerials o en els estatuts dels seus organismes públics i entitats vinculats o dependents segons correspongui.", "Únicament en els estatuts dels seus organismes públics i entitats vinculats o dependents segons correspongui.", "En les resolucions del Govern.", "Mitjançant una llei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 22, "Segons l’article 6 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, els òrgans administratius poden dirigir les activitats dels seus òrgans jeràrquicament dependents mitjançant:", "Instruccions i circulars.", "Circulars.", "Instruccions i ordres de servei.", "Reglaments."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 23, "Quan s’han de publicar en el butlletí oficial que correspongui les instruccions i les ordres de servei, de conformitat amb l’article 6 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic?", "Quan una disposició específica ho estableixi així, o quan es consideri convenient per raó dels destinataris o dels efectes que es puguin produir, sense perjudici de la seva difusió d’acord amb el que preveu la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern.", "Sempre.", "Mai.", "Només quan una disposició específica ho estableixi així."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 24, "Segons l’article 7 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, l’administració consultiva es pot articular mitjançant òrgans específics dotats d’autonomia orgànica i funcional respecte a l’administració activa, o a través dels serveis d’aquesta última que presten assistència jurídica. Senyalau la resposta correcta en relació amb aquests serveis:", "No poden estar subjectes a dependència jeràrquica, ja sigui orgànica o funcional.", "Poden estar subjectes a dependència jeràrquica.", "Només poden estar subjectes a dependència jeràrquica funcional.", "Només poden estar subjectes a dependència jeràrquica orgànica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 25, "Senyalau la resposta correcta. L’article 47.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, estableix que:", "Són convenis els acords amb efectes jurídics adoptats per les administracions públiques, els organismes públics i les entitats de dret públic vinculats o dependents o les universitats públiques entre si o amb subjectes de dret privat per a una finalitat comuna.", "No tenen la consideració de convenis, els protocols generals d’actuació o instruments similars que comportin meres declaracions d’intenció de contingut general o que expressin la voluntat de les administracions i parts subscriptores per actuar amb un objectiu comú, sempre que no suposin la formalització de compromisos jurídics concrets i exigibles.", "Els convenis no poden tenir per objecte prestacions pròpies dels contractes. En aquest cas, la seva naturalesa i règim jurídic s’han d’ajustar al que preveu la legislació de contractes del sector públic.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 26, "Quins requisits es requereixen per crear un òrgan administratiu d’acord amb la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic?", "Delimitar les seves funcions i competències.", "Determinar la forma d’integració en l’Administració pública de què es tracti i la seva dependència jeràrquica.", "Dotar dels crèdits necessaris per posar-lo en marxa i en funcionament.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 27, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, en els casos prevists com a motius d’abstenció, els interessats poden promoure la recusació:", "En qualsevol moment de la tramitació del procediment.", "En qualsevol moment anterior al tràmit d’audiència.", "En qualsevol moment anterior a la proposta de resolució.", "En qualsevol moment anterior a l’inici del procediment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 28, "Segons la Llei 40/2015 , d’1 d’octubre, de règim jurídic del sector públic, les administracions públiques han de respectar en la seva actuació i relacions els principis següents (senyalau la resposta incorrecta):", "Eficiència en l’assignació i la utilització dels recursos públics.", "Servei efectiu als ciutadans.", "Participació, discrecionalitat i transparència de l’actuació administrativa.", "Responsabilitat per la gestió pública."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 29, "En relació amb els òrgans col·legiats i d’acord amb la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, no pot ser objecte de deliberació o acord cap assumpte que no figuri inclòs en l’ordre del dia:", "Llevat que hi assisteixi la majoria dels membres de l’òrgan col·legiat i es declari la urgència de l’assumpte pel vot favorable de tots els presents.", "Llevat que hi assisteixin tots els membres de l’òrgan col·legiat i es declari la urgència de l’assumpte pel vot favorable de tots ells.", "Llevat que hi assisteixi la majoria dels membres de l’òrgan col·legiat i es declari la urgència de l’assumpte pel vot favorable de la majoria dels presents.", "Llevat que hi assisteixin tots els membres de l’òrgan col·legiat i sigui declarada la urgència de l’assumpte pel vot favorable de la majoria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 30, "D’acord amb l’article 9.5 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, si la norma reguladora d’un procediment preveu, com a tràmit preceptiu, l’emissió d’un dictamen o informe (senyalau l’opció correcta):", "No es pot delegar la competència per resoldre aquest procediment en cap cas.", "Només es pot delegar després d’haver-se emès l’informe o el dictamen preceptiu si no és vinculant.", "No es pot delegar la competència per resoldre aquest procediment una vegada que s’hagi emès el dictamen o informe preceptiu.", "Només es pot delegar la competència per resoldre aquest procediment una vegada que s’hagi emès el dictamen o informe preceptiu si és vinculant."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 31, "Indicau la resposta incorrecta en relació amb el règim previst per als encàrrecs de gestió que regular l’article 11 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic:", "Les encàrrecs de de gestió no poden tenir per objecte les prestacions pròpies dels contractes regulats en la legislació de contractes del sector públic.", "L’encàrrec de gestió no suposa cessió de la titularitat de la competència de l’òrgan o de l’entitat que l’encarrega.", "L’encàrrec de gestió suposa la cessió dels elements essencials de l’exercici de la competència de l’òrgan o de l’entitat que l’encarrega.", "Per assolir eficàcia, l’instrument de formalització de l’encàrrec de gestió entre òrgans administratius pertanyents a la mateixa administració i la seva resolució s’ha de publicar en el diari oficial a què correspongui l’òrgan que l’encarrega."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 32, "Senyalau l'opció; correcta en matèria d'òrgans col.legiats de les diferents administracions públiques d'acord amb la Llei 40/2015, d'1 d'octubre, de règim jurídic del sector públic:", "El secretari sempre té la condició de membre de l’òrgan col·legiat.", "Correspon al president vetlar per la legalitat formal i material de les actuacions de l’òrgan col·legiat.", "Perquè la constitució de l’òrgan col·legiat sigui vàlida, a l’efecte d’adoptar d’acords, es requereix l’assistència de la meitat més un dels seus membres.", "No pot ser objecte de deliberació o acord cap assumpte que no figuri inclòs en l’ordre del dia, llevat que hi assisteixin tots els membres de l’òrgan col·legiat i es declari la urgència de l’assumpte pel vot favorable de la majoria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 33, "D’acord amb l’article 5 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, tenen la consideració d’òrgans administratius:", "Les unitats administratives a les quals s’atribueixin funcions que tenguin efectes jurídics davant tercers, o l’actuació de les quals tengui caràcter preceptiu.", "Qualsevol unitat administrativa independentment de si té atribuïdes funcions que tengui efectes jurídics davant tercers o l’actuació de la qual tengui caràcter preceptiu.", "Les unitats administratives a les quals s’atribueixin funcions que tenguin efectes jurídics davant tercers i l’actuació de les quals tengui caràcter preceptiu, i han de complir ambdues condicions.", "Cap resposta anterior no és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 34, "De conformitat amb la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, senyalau l’afirmació correcta en relació amb els convenis:", "Són convenis els acords amb efectes jurídics adoptats per les administracions públiques, els organismes públics i les entitats de dret públic vinculats o dependents o les universitats públiques entre si o amb subjectes de dret privat per a un fi comú.", "És causa de resolució dels convenis el compliment de les actuacions que en constitueixen l’objecte.", "Els convenis poden tenir per objecte prestacions pròpies dels contractes.", "Tota la regulació sobre convenis és aplicable als encàrrecs de gestió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 35, "La Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, estableix i regula el següent:", "Les bases del règim jurídic de les administracions públiques.", "Els principis de la potestat sancionadora.", "L’organització i el funcionament del sector públic institucional per al desenvolupament de les seves activitats.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 36, "La Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, s’aplica als ens següents:", "Únicament a l’Administració general de l’Estat.", "Exclusivament a les administracions de les comunitats autònomes.", "A l’Administració general de l’Estat, a les administracions de les comunitats autònomes, a les entitats que integren l’Administració local i al sector públic institucional.", "Exclusivament a l’Administració general de l’Estat i a les administracions de les comunitats autònomes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 37, "D’acord amb l’article 9 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quina de les competències següents podria ser objecte de delegació?", "Els assumptes que facin referència a relacions amb la prefectura de l’Estat o la presidència del Govern.", "L’adopció de disposicions de caràcter general.", "La resolució d’un recurs d’alçada en l’òrgan administratiu que hagi dictat l’acte objecte de recurs.", "Cap de les respostes anteriors no és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 38, "Senyalau l’opció correcta en relació amb el règim que preveu l’article 8 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, sobre la irrenunciabilitat de la competència:", "La competència és irrenunciable llevat dels casos de delegació o advocació, quan s’efectuïn en els termes que preveu aquesta llei o d’altres.", "La competència és irrenunciable sense cap excepció.", "La competència és irrenunciable llevat dels casos d’absència del titular, quan s’efectuï en els termes que preveu aquesta llei o d’altres.", "La competència és irrenunciable llevat dels casos de vacant, quan s’efectuï en els termes que preveu aquesta llei o d’altres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 39, "Indicau la resposta correcta en relació amb el que disposa la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, sobre la delegació de signatura:", "Cap titular d’òrgan administratiu no pot delegar la signatura.", "Només pot delegar la signatura un director general.", "La delegació de signatura no altera la competència de l’òrgan delegant, i perquè sigui vàlida no cal publicar-la.", "Un director general només pot delegar la seva signatura al titular de la conselleria a què pertanyi."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 40, "Quins ens tenen la consideració d’administracions públiques d’acord amb l’article 2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic?", "Les entitats que integren l’Administració local.", "Les administracions de les comunitats autònomes.", "Els organismes públics i les entitats de dret públic vinculats o dependents de les administracions públiques.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 41, "Senyalau l’opció correcta en relació amb la suplència, d’acord amb la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic:", "La suplència implica l’alteració de la competència, i perquè sigui vàlida no cal publicar-la.", "Els titulars dels òrgans administratius poden ser suplerts temporalment en els supòsits de vacant, absència o malaltia, així com quan se n’hagi declarat l’abstenció o la recusació.", "La suplència implica l’alteració de la competència, perquè sigui vàlida cal publicar-la.", "Cap de les respostes anteriors no és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 42, "D’acord amb la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, la realització d’una activitat de caràcter tècnic de la competència d’un òrgan administratiu que, per no posseir els mitjans tècnics idonis per exercir-la, hagi estat encarregada a un altre òrgan de la mateixa administració entre les competències del qual també estiguin aquestes activitats, es denomina:", "Advocació.", "Desconcentració.", "Delegació de competències.", "Encàrrec de gestió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 43, "D’acord amb la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, tenen la consideració de convenis els acords amb efectes jurídics següents:", "Els que s’adoptin entre organismes públics i entitats de dret públic o privat.", "Els protocols generals d’actuació.", "Els que s’adoptin entre universitats públiques i subjectes de dret privat per a un fi comú.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 44, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quina de les afirmacions següents no és correcta:", "Les administracions públiques serveixen amb objectivitat els interessos generals.", "Les administracions públiques han de respectar en la seva actuació i relacions el principi de participació, objectivitat i transparència de l’actuació administrativa.", "Les universitats públiques tenen la consideració d’administració pública.", "Correspon a cada administració pública delimitar, en l’àmbit competencial respectiu, les unitats administratives que configuren els òrgans administratius propis de les especialitats derivades de la seva organització."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 45, "Senyalau l’afirmació correcta respecte als òrgans consultius que regula la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic:", "Estan subjectes a la dependència jeràrquica, orgànica o funcional, dels òrgans que hagin elaborat les disposicions objecte de consulta.", "Poden rebre les directrius i les indicacions dels òrgans que hagin produït els actes objecte de consulta.", "No tenen autonomia orgànica i funcional.", "Actuen de forma col·legiada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 46, "De conformitat amb el que disposa l’article 17 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, estan exempts de la responsabilitat que, si s’escau, es pugui derivar dels acords adoptats pels òrgans col·legiats:", "Els membres de l’òrgan que emetin el seu vot per mitjans electrònics o per correu.", "Els membres de l’òrgan que hi votin a favor.", "Els membres de l’òrgan que hi votin en contra o que se n’abstinguin.", "Cap de les respostes anteriors no és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 47, "De conformitat amb el que disposa l’article 6 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quina és la conseqüència de l’incompliment d’instruccions o d’ordres de servei?", "La nul·litat jurídica plena dels actes emesos pels òrgans administratius.", "La nul·litat dels actes emesos pels òrgans administratius.", "No afecta per si mateix la validesa dels actes emesos pels òrgans administratius.", "L’anul·labilitat dels actes emesos pels òrgans administratius."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 48, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quan ha d’exigir l’Administració, d’ofici, de les seves autoritats i la resta de personal al seu servei la responsabilitat patrimonial en què hagin pogut incórrer?", "Sempre.", "Quan hi hagin incorregut per dol, culpa o negligència molt greus.", "Quan hi hagin incorregut per dol, culpa o negligència greus.", "Quan hi hagin incorregut, no per culpa o negligència greus, sinó per dol."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 49, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, les administracions públiques han de respectar en la seva actuació i relacions els principis següents (senyalau la resposta incorrecta):", "Eficiència en l’assignació i la utilització dels recursos públics.", "Servei efectiu als ciutadans.", "Participació i discrecionalitat.", "Responsabilitat per la gestió pública."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 50, "Segons el principi de proporcionalitat de la potestat sancionadora que regula la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic (senyalau la resposta correcta):", "És sancionable, com a infracció continuada, la realització d’una pluralitat d’accions o omissions que infringeixin el mateix precepte administratiu, en execució d’un pla preconcebut o aprofitant una ocasió diferent.", "És sancionable, com a infracció continuada, la realització d’una pluralitat d’accions o omissions que infringeixin el mateix precepte administratiu o preceptes administratius semblants, en execució d’un pla preconcebut o aprofitant una ocasió idèntica.", "No és sancionable, com a infracció continuada, la realització d’una pluralitat d’accions o omissions que infringeixin el mateix precepte administratiu, en execució d’un pla preconcebut o aprofitant una ocasió idèntica.", "És sancionable, com a infracció intermitent, la realització d’una pluralitat d’accions o omissions que infringeixin el mateix precepte administratiu o preceptes administratius semblants, en execució d’un pla preconcebut o aprofitant una ocasió diferent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 51, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, senyalau la resposta correcta respecte de les dades de caràcter personal a les quals es pot tenir accés en execució de l’encàrrec de gestió:", "L’entitat o l’òrgan encomanat no té la condició de responsable del fitxer o tractament.", "L’entitat o l’òrgan encomanat té la condició d’encarregat del tractament.", "L’entitat o l’òrgan que encomana l’encàrrec té la condició d’encarregat del tractament.", "L’entitat o l’òrgan que encomana l’encàrrec ha de dictar una resolució per a determinar quin òrgan serà el responsable del tractament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 52, "D’acord amb la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, s’han de remetre electrònicament al Tribunal de Comptes o òrgan extern de fiscalització de la Comunitat Autònoma, segons correspongui, els convenis els compromisos econòmics dels quals superin:", "Els 600.000 euros dins els tres mesos següents a la subscripció.", "Els 600.000 euros dins els tres mesos següents a comptar de la finalització de la vigència del conveni.", "Els 300.000 euros dins els tres mesos següents a la subscripció.", "Els 300.000 euros dins els tres mesos següents a comptar de la finalització de la vigència del conveni."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 53, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, en els casos prevists com a motius d’abstenció, els interessats poden promoure la recusació en els casos següents (senyalau la resposta correcta):", "En qualsevol moment de la tramitació del procediment.", "En qualsevol moment anterior al tràmit d’audiència.", "En qualsevol moment anterior a la proposta de resolució.", "En qualsevol moment anterior a l’inici del procediment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 54, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, a fi de contribuir a la identificació més correcta de les conductes o a la determinació més precisa de les sancions corresponents, les disposicions reglamentàries de desenvolupament poden introduir especificacions o graduacions en el quadre de les infraccions o sancions establertes legalment:", "Que constitueixin noves infraccions o sancions, o que alterin la naturalesa o els límits de les que la llei preveu.", "Que no constitueixin noves infraccions o sancions, però que alterin la naturalesa o els límits de les que la llei preveu.", "Que no constitueixin noves infraccions o sancions, ni alterin la naturalesa o els límits de les que la llei preveu.", "Que constitueixin noves infraccions o sancions, però no alterin la naturalesa o els límits de les que la llei preveu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 55, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, les lleis reguladores dels diferents règims sancionadors (senyalau la resposta correcta):", "Poden preveure els supòsits en què determinades persones han de respondre del pagament de les sancions no pecuniàries imposades als qui en depenguin o hi estiguin vinculades.", "Poden preveure els supòsits en què determinades persones han de respondre del pagament de les sancions pecuniàries imposades als qui en depenguin o hi estiguin vinculades.", "No poden preveure els supòsits en què determinades persones han de respondre del pagament de les sancions no pecuniàries imposades als qui en depenguin o hi estiguin vinculades.", "No poden preveure els supòsits en què determinades persones han de respondre del pagament de les sancions pecuniàries imposades als qui en depenguin o hi estiguin vinculades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 56, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, la graduació de la sanció ha de considerar especialment els criteris següents (senyalau la resposta incorrecta):", "El grau de culpabilitat o l’existència d’intencionalitat.", "La continuïtat o persistència en la conducta infractora.", "La naturalesa dels perjudicis causats.", "La reincidència, per comissió en el termini de dos anys de més d’una infracció de la mateixa naturalesa quan així hagi estat declarat per resolució ferma en via administrativa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 57, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, la responsabilitat patrimonial de l’Estat pel funcionament de l’Administració de justícia s’ha de regir per:", "La Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques.", "La mateixa Llei 40/2015.", "Les lleis 39/2015 i 40/2015.", "La Llei orgànica 6/1985, d’1 de juliol, del poder judicial."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 58, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, l’Administració corresponent, quan hagi indemnitzat els lesionats, ha d’exigir a les seves autoritats i a la resta de personal al seu servei la responsabilitat en què hagin incorregut per dol, o culpa o negligència greus. L’Administració, com ha de dur a terme aquest requeriment?", "D’ofici, en via penal.", "D’ofici, en via administrativa, amb la instrucció prèvia del procediment corresponent.", "D’ofici, en via administrativa.", "D’ofici, en via penal, amb la instrucció prèvia del procediment corresponent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 59, "De conformitat amb la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, senyalau la resposta incorrecta respecte a les seus electròniques:", "L’establiment d’una seu electrònica comporta la responsabilitat del titular respecte de la integritat, la veracitat i l’actualització de la informació i els serveis als quals es pugui accedir a través d’aquella.", "Han de disposar de sistemes que permetin establir comunicacions segures sempre que siguin necessàries.", "La publicació a les seus electròniques d’informacions, serveis i transaccions ha de respectar els principis d’accessibilitat i ús d’acord amb les normes establertes en aquest respecte, estàndards oberts i, si s’escau, els altres que siguin d’ús generalitzat pels part dels ciutadans.", "L’Administració general de l’Estat ha de determinar les condicions i els instruments de creació de totes les seus electròniques, d’acord amb els principis de transparència, publicitat, responsabilitat, qualitat, seguretat, disponibilitat, accessibilitat, neutralitat i interoperabilitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 60, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quan els participants en les comunicacions a què fa referència l’article 44 pertanyin a diferents administracions, com s’estableixen les condicions i les garanties per les quals es regeixen?", "Les estableix l’Administració que iniciï l’enviament de les comunicacions.", "S’estableixen mitjançant un conveni subscrit entre aquelles.", "Les estableix l’Administració jeràrquicament superior.", "Són les que estableix la Llei 40/2015."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 61, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, com s’han d’emmagatzemar tots els documents utilitzats en les actuacions administratives?", "Per mitjans electrònics o mitjans no electrònics de manera discrecional.", "Sempre per mitjans electrònics.", "Per mitjans electrònics, excepte quan no sigui possible.", "En paper amb còpia digitalitzada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 62, "Senyalau la resposta incorrecta respecte dels requisits de validesa i eficàcia dels convenis segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic:", "Cal que els convenis que incloguin compromisos financers siguin financerament sostenibles.", "Les aportacions financeres que es comprometin a efectuar els signants poden ser superiors a les despeses derivades de l’execució del conveni.", "La subscripció de convenis ha de complir la legislació d’estabilitat pressupostària i de sostenibilitat financera.", "Els convenis es perfeccionen per la prestació del consentiment de les parts."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 63, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, la subscripció de convenis (senyalau la resposta incorrecta):", "Ha de millorar l’eficiència de la gestió pública.", "Ha de facilitar la utilització conjunta de mitjans i serveis públics.", "Ha de contribuir a l’exercici d’activitats d’utilitat pública i privada.", "Ha de complir la legislació d’estabilitat pressupostària i sostenibilitat financera."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 64, "Senyalau la resposta correcta respecte de les normes del capítol VI del títol preliminar de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic:", "Són aplicables als encàrrecs de gestió, però no als acords de terminació convencional dels procediments administratius.", "No són aplicables als encàrrecs de gestió ni als acords de terminació convencional dels procediments administratius.", "Són aplicables als encàrrecs de gestió i als acords de terminació convencional dels procediments administratius.", "Són aplicables als acords de terminació convencional dels procediments administratius, però no als encàrrecs de gestió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 65, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, sens perjudici de les especialitats que la legislació autonòmica pugui preveure, cal que el conveni s’acompanyi d’una memòria justificativa en què s’analitzi el següent (senyalau la resposta incorrecta):", "L’impacte econòmic.", "La necessitat i l’oportunitat.", "El caràcter contractual de l’activitat en qüestió.", "El compliment del que preveu la Llei 40/2015 esmentada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 66, "El títol preliminar de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, s’anomena:", "Títol preliminar.", "Dels ens del sector públic.", "Disposicions generals, principis d’actuació i funcionament del sector públic.", "Sector públic institucional."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 67, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, senyalau la resposta correcta en relació amb la competència per a la resolució dels recursos administratius:", "Es pot delegar en òrgans superiors.", "Es pot delegar en òrgans inferiors, en qualsevol cas.", "En cap cas no pot ser objecte de delegació.", "No es pot delegar en els òrgans administratius que hagin dictat els actes objecte de recurs."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 68, "Segons la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, senyalau la resposta incorrecta en relació amb els supòsits en què no es pot delegar la competència:", "Els assumptes que es refereixin a relacions amb la prefectura de l’Estat, la presidència del Govern de la nació, les Corts Generals, les presidències dels consells de govern de les comunitats autònomes i les assemblees legislatives de les comunitats autònomes.", "La resolució de recursos als òrgans administratius que hagin dictat els actes objecte de recurs.", "L’adopció de disposicions de caràcter especial.", "Les matèries en què així es determini per norma amb rang de llei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 69, "D’acord amb el que preveu la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, l’advocació s’ha de dur a terme mitjançant un acord motivat. En quin moment s’ha de notificar als interessats, si n’hi ha?", "Amb anterioritat o simultàniament a la resolució final que es dicti.", "Simultàniament a la resolució final que es dicti.", "Amb posterioritat a la resolució final que es dicti.", "Simultàniament o amb posterioritat a la resolució final que es dicti."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 70, "En quants de capítols es divideix el títol preliminar de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic?", "En tres capítols.", "En dos capítols.", "En cinc capítols.", "En sis capítols."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 71, "D’acord amb l’article 157 de la Llei 40/2015, de règim jurídic del sector públic, senyalau la resposta correcta en relació amb el directori general d’aplicacions:", "Hi han de constar tant les aplicacions disponibles de l’Administració General de l’Estat com les disponibles en els directoris integrats d’aplicacions de la resta d’administracions.", "Hi han de constar únicament les aplicacions disponibles de les administracions de les comunitats autònomes.", "Hi han de constar les aplicacions no disponibles de totes les administracions públiques.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 72, "Segons l’article 93 de la Llei 40/2015 d’1 d’octubre, de règim jurídic del sector públic, què han de regular els estatuts dels organismes públics estatals?", "Les funcions i les competències de l’organisme, amb indicació de les potestats administratives que pugui tenir.", "El règim relatiu a recursos humans, patrimoni, pressupost i contractació.", "La facultat de participació en societats mercantils quan això sigui imprescindible per a la consecució dels fins assignats.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 73, "Segons l’article 11 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quan l’encàrrec de gestió es dugui a terme entre òrgans administratius o entitats de dret públic pertanyents a la mateixa administració, s’ha de formalitzar en els termes que estableixi la seva normativa pròpia i, si no n’hi ha, per acord exprés dels òrgans o entitats de dret públic intervinents. En aquest sentit (senyalau la resposta correcta):", "Cada administració pot regular els requisits necessaris per a la validesa de tals acords que han d’incloure, almenys, una menció expressa de l’activitat o activitats que afectin, però no la justificació de la necessitat de l’encàrrec ni el termini de vigència.", "Cada administració pot regular, els requisits necessaris per a la validesa d’aquests acords que han d’incloure, almenys, una menció expressa de l’activitat o activitats que afectin, el termini de vigència i la naturalesa i l’abast de la gestió encomanada.", "Cada administració ha de dictar una disposició reglamentària que reguli els requisits necessaris per a la validesa d’aquests acords que han d’incloure, únicament, una menció expressa de l’activitat o activitats que afectin.", "Les administracions no poden regular els requisits necessaris per a la validesa d’aquests acords."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 74, "D’acord amb la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, senyalau la resposta correcta en relació amb l’estructura de l’Administració general de l’Estat:", "A l’organització territorial de l’Administració general de l’Estat són òrgans directius tant els delegats del Govern a les comunitats autònomes, que tenen rang de secretari d’Estat, com els subdelegats del Govern a les províncies, els quals tenen el nivell de subdirector general.", "A l’Administració general de l’Estat a l’exterior són òrgans directius els ambaixadors i representants permanents davant organitzacions internacionals.", "A l’organització central de l’Administració general de l’Estat són òrgans directius els secretaris d’Estat i subsecretaris, els secretaris generals tècnics, els directors generals i els subdirectors generals.", "Correspon als òrgans directius establir els plans d’actuació de l’organització, així com el seu desplegament i execució."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 75, "De conformitat amb l’article 16 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, senyalau la resposta incorrecta en relació amb el secretari d’un òrgan col·legiat:", "El secretari pot ser un membre del mateix òrgan.", "El secretari pot ser una persona al servei de l’Administració pública corresponent.", "En cas que el secretari no membre sigui suplert per un membre de l’òrgan col·legiat, aquest conserva tots els seus drets com a tal.", "En cas que el secretari no membre sigui suplert per un membre de l’òrgan col·legiat, aquest perd tots els seus drets com a tal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 1, "D'acord amb el Codi civil, les normes jurídiques contingudes en els tractats internacionals:", "No tenen aplicació directa a Espanya.", "Encara que no poden arribar a tenir aplicació directa a Espanya, tenen caràcter informador de l'ordenament jurídic intern.", "Són d'aplicació directa a Espanya des de la signatura del tractat internacional corresponent.", "No són d'aplicació directa a Espanya mentre no hagin passat a formar part de l'ordenament intern mitjançant la publicació íntegra en el Butlletí Oficial de l'Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 2, "Quina de les matèries següents és regulable per mitjà d’un decret llei?", "El règim de les comunitats autònomes.", "El dret electoral general.", "Els drets, els deures i les llibertats dels ciutadans que es regulen en el títol I de la Constitució.", "Cap de les matèries anteriors és regulable mitjançant un decret llei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 3, "Quan s'aplica el costum com a font de dret?", "A falta de llei aplicable, sempre que no sigui contrària a la moral o a l'ordre públic, i que resulti provada.", "Quan sigui d'aplicació per raó de la matèria.", "En qualsevol cas, encara que hi hagi una llei aplicable.", "Quan no hi hagi principis generals del dret aplicables al cas."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 4, "Les disposicions administratives que contradiguin el que estableix una norma de caràcter superior:", "Són nul·les de ple dret.", "Han de ser adaptades.", "Han de ser recorregudes davant el Tribunal Suprem.", "Són anul·lades per les Corts Generals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 5, "Quin article del Codi civil estableix les fonts del dret?", "Cap.", "L'article 1.", "L'article 18.", "L'article 35."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 6, "De conformitat amb la Constitució espanyola, els estatuts d'autonomia són:", "La norma institucional bàsica de cada comunitat autònoma.", "Una llei orgànica estatal.", "Part integrant de l'ordenament jurídic de l'Estat.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 7, "La Constitució espanyola estableix que la reforma dels estatuts s'ajustarà al procediment que s’hi estableixi i requerirà, en tot cas:", "L’aprovació del Congrés, mitjançant una llei ordinària.", "L’aprovació de les Corts Generals per majoria simple, amb un dictamen previ favorable del Consell d'Estat.", "L’aprovació de les Corts Generals, mitjançant una llei orgànica.", "L’aprovació de les Corts Generals, mitjançant una llei ordinària."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 8, "El principi de legalitat s’estableix en la Constitució en:", "L'article 2.", "L'article 9.", "L'article 104.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 9, "En cas de necessitat extraordinària i urgent, el Govern pot dictar disposicions legislatives provisionals que adopten la forma de:", "Decret legislatiu.", "Llei de bases.", "Decret llei.", "Llei marc."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 10, "Les disposicions dictades pels ministres es publiquen amb la denominació:", "D’ordre.", "D’ordre ministerial.", "De decret.", "De decret ministerial."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 11, "El principi de jerarquia de les fonts del dret administratiu:", "Determina la invalidesa de la norma inferior que contradigui el que disposa la superior.", "Es regula en l'article 9.3 de la Constitució.", "No s'aplica en les relacions entre les lleis ordinàries i les orgàniques.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 12, "El principi de reserva de llei significa:", "Que la llei se situa en la posició més elevada de la piràmide normativa.", "Que no és possible negar-se a l'aplicació o el compliment de la llei.", "Que l'enjudiciament de la llei competeix en exclusiva als tribunals o hi està reservat.", "Que determinades matèries establertes per la Constitució només poden ser regulades per una norma amb rang legal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 13, "Els principis generals del dret:", "Són font indirecta.", "Tenen un valor normatiu superior al costum.", "Són font d'aplicació a falta de llei i costum, sense perjudici del seu caràcter informador de l'ordenament jurídic.", "Tenen un valor normatiu superior al costum, sense perjudici del seu caràcter informador de l'ordenament jurídic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 14, "En relació amb els decrets llei:", "Són aprovats pel Consell de Ministres.", "Són aprovats pel Consell de Ministres, amb l’autorització prèvia del Congrés.", "Són aprovats pel Consell de Ministres, amb l’autorització prèvia de les Corts Generals.", "Són aprovats pel president del Govern, amb la deliberació prèvia del Consell de Ministres i la consulta al Congrés."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 15, "En la llei marc:", "Es fixen els principis per harmonitzar les disposicions normatives de les comunitats autònomes quan ho exigeixi l'interès general.", "Es transfereixen facultats de titularitat estatal a les comunitats autònomes, mitjançant una llei orgànica.", "S'estableix la modalitat de control de les Corts Generals sobre determinades normes legislatives de les comunitats autònomes.", "Pot atorgar-se una delegació legislativa al Govern perquè harmonitzi actuacions autonòmiques quan així ho exigeixi l'interès general."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 16, "L'aprovació, modificació o derogació d'una llei orgànica exigeix:", "La majoria absoluta del Congrés.", "La majoria absoluta del Senat.", "La majoria absoluta de les Corts.", "La majoria simple del Congrés, en votació final sobre el conjunt del projecte."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 17, "La delegació legislativa efectuada per les Corts Generals en favor del Govern, amb la finalitat de formar un text articulat, haurà de fer-se:", "A través d'una llei marc.", "A través d'una llei bàsica.", "A través d'una llei ordinària.", "A través d'una llei de bases."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 18, "L'Estatut d'autonomia ha de contenir:", "La delimitació del territori de la comunitat autònoma.", "La denominació, l’organització i la seu de les institucions autonòmiques pròpies.", "La denominació de la comunitat autònoma.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 19, "D'acord amb l'article 149.3 de la Constitució, quines normes prevalen en cas de conflicte entre les d'una comunitat i les de l'Estat?", "Sempre les de l'Estat.", "Sempre les de la comunitat.", "Les de l'Estat, tret que la matèria estigui atribuïda exclusivament a la comunitat.", "Les de la comunitat, tret que la matèria estigui atribuïda exclusivament a l'Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 20, "D'acord amb la Constitució, són lleis orgàniques les relatives:", "Al règim de les comunitats autònomes.", "Al desenvolupament dels drets fonamentals i de les llibertats públiques.", "Al règim electoral general.", "Les respostes b) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 21, "D'acord amb la Constitució, els decrets llei:", "Hauran de ser sotmesos immediatament a debat i votació de la totalitat al Congrés en el termini de quinze dies des de la promulgació.", "Podran afectar els drets fonamentals i les llibertats públiques.", "Hauran de ser sotmesos immediatament a debat i votació de la totalitat al Congrés en el termini dels vint dies següents a la promulgació.", "Durant el termini per a la convalidació o derogació, les Corts podran tramitar-los com a projecte de llei pel procediment d'urgència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 22, "En relació amb la supletorietat del dret estatal respecte de l'autonòmic, l'article 149.3 de la Constitució estableix que:", "El dret estatal serà, en tot cas, supletori del de les comunitats autònomes.", "Només serà supletori del dret de les comunitats autònomes en el cas que aquestes no hagin legislat sobre les seves competències assumides.", "El dret estatal només serà supletori quan així ho estableixi una norma amb rang de llei.", "Serà supletori del dret de les comunitats autònomes excepte en les matèries de competència exclusiva d'aquestes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 23, "Segons la Constitució espanyola:", "El Congrés podrà delegar al Govern la potestat de dictar normes amb rang de llei sobre matèries determinades, excepte les que s'hagin d'aprovar amb una llei orgànica.", "El Senat, com a cambra de representació territorial, podrà delegar al Govern la potestat de dictar normes amb rang de llei sobre la distribució territorial de l'Estat.", "Les Corts Generals podran delegar al Govern la potestat de dictar normes amb rang de llei sobre el desenvolupament dels drets fonamentals i les llibertats publiques, sobre el règim electoral general i sobre les altres matèries previstes en la Constitució.", "Les Corts Generals podran delegar al Govern la potestat de dictar normes amb rang de llei sobre matèries determinades no incloses en l'article 81."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 24, "D'acord amb la Llei 50/1997, de 27 de novembre, del Govern, els reglaments dictats pel president del Govern es publiquen amb la denominació de:", "Reials decrets del president del Govern.", "Decrets del president.", "Decrets de Presidència.", "Reials decrets."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 25, "D'acord amb el Codi civil, amb relació a les fonts del dret:", "El costum només regirà a falta d’una llei aplicable, sempre que no sigui contrària a la moral o a l'interès social i que resulti provada.", "La jurisprudència complementarà l'ordenament jurídic amb la doctrina que, de manera reiterada, estableixi el Tribunal Suprem en interpretar i aplicar la llei i el costum.", "Els principis generals del dret s'apliquen a falta de llei, sense perjudici del seu caràcter informador de l'ordenament jurídic.", "La jurisprudència complementarà l'ordenament jurídic amb la doctrina que, de manera reiterada, estableixi el Tribunal Suprem en interpretar i aplicar la llei, el costum i els principis generals del dret."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 26, "Les matèries que han de ser desenvolupades per mitjà d’una llei orgànica es contenen en la Constitució en:", "L'article 9.", "L'article 82.", "L'article 81.", "L'article 84."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 27, "Els decrets llei són convalidats:", "Pel Congrés dels Diputats.", "Pel Senat.", "Per les Corts Generals.", "Pel Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 28, "El termini per convalidar un decret llei és de:", "Vint dies.", "Quinze dies.", "Un mes.", "Trenta dies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 29, "Les disposicions del Govern que contenen legislació delegada es denominen:", "Decrets lleis.", "Lleis de delegació.", "Decrets legislatius.", "Decrets."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 30, "Una llei estatal que conté els principis necessaris per harmonitzar les disposicions normatives de les comunitats autònomes en una matèria és:", "Una llei orgànica.", "Una llei d'harmonització.", "Una llei de bases.", "Una llei de delegació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 31, "En relació amb el procediment de l'elaboració de les lleis que es preveu en la Constitució:", "El rei sancionarà en el termini de quinze dies les lleis aprovades per les Corts Generals, i les promulgarà i n’ordenarà la publicació immediata.", "El rei sancionarà en el termini de vint dies les lleis aprovades per les Corts Generals, i les promulgarà i n’ordenarà la publicació immediata.", "El rei sancionarà en el termini de trenta dies les lleis aprovades per les Corts Generals, i les promulgarà i n’ordenarà la publicació immediata.", "El president del Govern, en nom del rei, sancionarà en el termini de quinze dies les lleis aprovades per les Corts Generals, i les promulgarà i n’ordenarà la publicació immediata."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 32, "Pel que fa a la regulació disposada en la Constitució respecte dels decrets legislatius:", "La delegació legislativa haurà d'atorgar-se mitjançant una llei ordinària quan l’objecte sigui la formació de texts articulats o mitjançant una llei de bases quan es tracti de refondre diversos texts legals en un de sol.", "Les Corts Generals podran delegar al Govern la potestat de dictar normes amb rang de llei, inclosa la regulació de les possibles formes de col·laboració financera entre les comunitats autònomes i l'Estat.", "La delegació legislativa haurà d'atorgar-se al Govern de forma expressa per a una matèria concreta i amb fixació del termini d’exercici. La delegació s'esgota per l'ús que en faci el Govern mitjançant la publicació de la norma corresponent.", "La delegació legislativa haurà d'atorgar-se mitjançant una llei orgànica quan l’objecte sigui la formació de texts articulats o per una llei de bases quan es tracti de refondre diversos texts legals en un de sol."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 33, "Indicau la resposta correcta:", "Les Corts Generals, en matèria de competència estatal, podran atribuir a totes o a alguna de les comunitats autònomes la facultat de dictar, per a si mateixes, normes legislatives en el marc dels principis, les bases i les directrius que fixi una llei estatal.", "Les Corts Generals, en matèria de competència estatal, podran atribuir a totes o a alguna de les comunitats autònomes la facultat de dictar, per a si mateixes, normes legislatives en el marc dels principis, les bases i les directrius que fixi una llei de bases.", "El Govern, en matèria de competència estatal, podrà atribuir a totes o a alguna de les comunitats autònomes la facultat de dictar, per a si mateixes, normes legislatives en el marc dels principis, les bases i les directrius que fixi una llei estatal.", "El Congrés, en matèria de competència estatal, podrà atribuir a totes o a alguna de les comunitats autònomes la facultat de dictar, per a si mateixes, normes legislatives en el marc dels principis, les bases i les directrius que fixi una llei estatal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 34, "Segons el que disposa la Constitució, les lleis de bases podran:", "Autoritzar la modificació de la llei de bases.", "Facultar per dictar normes amb caràcter retroactiu.", "Facultar per refondre diversos texts legals en un de sol.", "Facultar per a la formació de texts articulats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 35, "Les resolucions dels ministres es denominen:", "Resolucions ministerials.", "Ordres ministerials.", "Decrets ministerials.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 36, "Senyalau la resposta incorrecta:", "La iniciativa legislativa l'exerciran els òrgans de govern de les comunitats autònomes en els termes que estableixen la Constitució i els seus corresponents estatuts d'autonomia.", "El Govern de la nació podrà aprovar reials decrets llei i reials decrets legislatius en els termes que preveu la Constitució.", "Els òrgans de govern de les comunitats autònomes no podran aprovar normes equivalents a reials decrets lleis i reials decrets legislatius en el seu àmbit territorial.", "La iniciativa popular no és procedent en matèries pròpies de llei orgànica, tributàries o de caràcter internacional, ni quant a la prerrogativa de gràcia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 37, "Els reglaments independents es caracteritzen per ser:", "Els que regulin matèries sobre les quals la Constitució ha previst expressament una reserva reglamentària.", "Aquells que regulin matèries en què no s’ha produït una regulació prèvia per llei i que no estan protegides per reserva material de llei.", "Els que regulin matèries sobre les quals la Constitució ha previst expressament una reserva reglamentària, així com aquells que regulin matèries en què no s’ha produït una regulació prèvia per llei i que no estan protegides per reserva material de llei.", "A Espanya no poden haver-hi reglaments independents, atès que la Constitució no ha previst expressament una reserva reglamentària."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 38, "Els reglaments executius són els que:", "Regulen matèries en les quals no s’ha produït una regulació prèvia per llei i que no estan protegides per reserva material de llei.", "Desenvolupen i complementen una llei.", "Dicta l’Administració per fer front a riscs extraordinaris, suspenent la vigència dels lleis als que contradiuen mentre duri la situació d’emergència.", "Els que regulen matèries sobre les quals la Constitució espanyola ha previst una reserva reglamentària."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 39, "L'autorització al Govern de la nació per dictar un text refós ha d'efectuar-se a través:", "D’una llei ordinària.", "D’una decret legislatiu.", "D’una llei orgànica.", "D’un decret llei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 40, "Un decret llei del Govern de la nació no pot afectar:", "El sistema tributari.", "Els pressuposts generals de l'Estat.", "El règim de drets, deures i llibertats del títol I de la Constitució espanyola.", "Cap de les respostes anteriors és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 41, "Per aplicar un costum a falta d'un principi general del dret:", "No pot atemptar contra la moral.", "Ha de ser provat.", "No pot anar en contra de l'ordre públic.", "Cap de les respostes anteriors són correctes, perquè s'aplica sempre abans que el principi general del dret."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 42, "De conformitat amb la Constitució espanyola, les administracions públiques no actuen d'acord amb el principi de:", "Coordinació.", "Jerarquia.", "Desconcentració.", "Delegació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 43, "Els reglaments són disposicions normatives:", "De caràcter general.", "De rang inferior a la Llei.", "Que emanen del poder executiu en virtut de la seva potestat reglamentària.", "Totes els respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 44, "Indicau quina de les respostes següents és la incorrecta amb relació als reglaments:", "El control de les normes reglamentàries dictades per l’Administració de la Comunitat Autònoma dels Illes Balears correspon a la jurisdicció contenciosa administrativa.", "L’entrada en vigor dels reglaments aprovats pel Govern de la nació requereix la publicació íntegra en el Butlletí Oficial de l’Estat.", "D’acord amb la Llei 1/2019, de 31 de gener, del Govern de les Illes Balears, en casos d’urgència i de forma excepcional, l’entrada en vigor de determinats reglaments aprovats pel Consell de Govern requereix únicament la publicació d’un extracte en el Butlletí Oficial de les Illes Balears.", "Els reglaments dictats per les entitats locals s’han de publicar en el butlletí oficial que correspongui."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 45, "Els reglaments es poden definir com a:", "Qualsevol disposició jurídica de caràcter singular dictada per l’Administració pública i subordinada a la llei.", "Qualsevol disposició jurídica dictada pel Govern i l’Administració en virtut de la delegació normativa efectuada al seu favor per les Corts Generals.", "Qualsevol disposició jurídica de caràcter general dictada pel Govern i l’Administració pública, subordinada a la llei.", "Qualsevol disposició administrativa dictada en el si d’un procediment, amb efecte erga omnes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 46, "D’acord amb la Llei 1/2019, de 31 de gener, del Govern de les Illes Balears, senyalau l’ordre jeràrquic correcte:", "Primer els decrets aprovats pel Consell de Govern, i segon les ordres dels consellers.", "Primer els decrets dels consellers, i segon les resolucions dels consellers.", "Primer els decrets aprovats pel Consell de Govern o pel president, i segon les ordres dels consellers.", "Cap de les respostes anteriors és la correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 47, "Les normes es poden ordenar jeràrquicament de la forma següent:", "Constitució, lleis i normes amb rang de llei, reglaments, principis generals del dret i costums.", "Constitució, lleis i normes amb rang de llei, reglaments, costums i principis generals del dret.", "Constitució, reglaments, lleis i normes amb rang de llei i costums.", "Constitució, lleis, reglaments, normes amb rang de llei i costums."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 48, "Senyalau quina de les següents frases és la incorrecta:", "La supremacia formal implica que la Constitució no pot ser modificada ni derogada per cap altra norma.", "Quant a la norma, la Constitució gaudeix d'una posició de supremacia normativa en un doble pla, material i formal.", "La Constitució es sobreposa als ciutadans, a tots els poders públics i, per tant, a totes les normes de qualsevol naturalesa que d'aquests dimanen.", "La Constitució és un poder constituït, els altres poders són mers poders constituents."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 49, "Quin article de la Constitució està dedicat a la irretroactivitat de les disposicions sancionadores desfavorables o restrictives de drets individuals?", "L'article 9.3.", "L'article 9.2.", "L'article 9.4.", "L'article 10."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 50, "Quants components ha de tenir la delegació autonòmica encarregada de la defensa d'una proposició de llei autonòmica en el Congrés?", "Mínim dos.", "Tres.", "Quatre.", "Màxim tres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 51, "Quin és el nombre de signatures necessari per a l'exercici de la iniciativa legislativa popular?", "No menys de 500.000 signatures acreditades.", "500.000 signatures acreditades.", "Més de 600.000 signatures acreditades.", "600.000 signatures acreditades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 52, "En quina de les següents matèries és procedent la iniciativa legislativa popular?", "En matèries tributàries.", "En matèries de caràcter internacional.", "En matèries relatives a la prerrogativa de gràcia.", "Cap de les matèries anteriors poden ser objecte d'una iniciativa legislativa popular."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 53, "Pot el Govern subdelegar la facultat de dictar legislació delegada?", "En cap cas.", "Sí, sempre que ho autoritzi la llei de delegació.", "Sí, sempre que delegui en autoritats administratives.", "No, tret que delegui en òrgans administratius."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 54, "Un estatut d'autonomia ha de ser aprovat:", "Per llei ordinària.", "Per llei orgànica.", "Per reial decret.", "Per decret llei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 55, "Indicau la resposta incorrecta relativa al reglament de necessitat:", "El reglament de necessitat implica la suspensió de la legalitat establerta.", "El reglament de necessitat té caràcter transitori en l’ordenament jurídic.", "El reglament de necessitat només es pot dictar per raó de la concurrència de circumstàncies extraordinàries.", "El reglament de necessitat té caràcter de permanència en l’ordenament jurídic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 56, "Quin altre principi, a més del de jerarquia normativa, hem de tenir en compte per explicar la relació entre les diferents fonts de l'ordenament?", "Principi de cooperació.", "Principi de col·laboració.", "Principi de coordinació.", "Principi de competència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 57, "No ha de ser regulat per llei orgànica:", "El dret de propietat.", "El dret de reunió.", "El règim electoral general.", "El dret de vaga."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 58, "Jeràrquicament, la llei orgànica:", "És superior a la llei ordinària.", "Té el mateix rang que la llei ordinària.", "Té el mateix rang que la Constitució.", "Té rang inferior al decret llei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 59, "Poden les assemblees de les comunitats autònomes remetre a les Corts Generals proposicions de llei?", "No, en cap cas.", "Sí, al Congrés i al Senat.", "Sí, però només a la Mesa del Senat, que és la cambra de representació territorial.", "Sí, però només a la Mesa del Congrés."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 60, "D’acord amb la Constitució espanyola, l'apreciació de la necessitat de dictar lleis que estableixin els principis necessaris per harmonitzar les disposicions normatives de les comunitats autònomes correspon:", "Al Congrés, per majoria de tres cinquenes parts dels seus membres.", "Al Consell de Ministres.", "Al Senat, en qualitat de cambra de representació territorial.", "A les Corts Generals, per majoria absoluta de cada cambra."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 61, "Quina majoria es necessita en el Senat per interposar un veto a una proposició de llei aprovada en el Congrés dels Diputats?", "Majoria simple.", "Majoria absoluta.", "Majoria de dos terços.", "El Senat no pot vetar matèries aprovades pel Congrés."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 62, "Quin altre nom reben els decrets legislatius?", "Legislació executiva.", "Legislació delegada.", "Legislació delegant.", "Legislació secundària."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 63, "D’acord amb les classificacions doctrinals clàssiques dels reglaments, com es denomina el reglament que es dicta sense una habilitació o una remissió específica d’una llei?", "Reglament executiu.", "Reglament independent.", "Reglament de necessitat.", "Cap de les respostes és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 64, "Quina d'aquestes normes té un procediment especial d'aprovació?", "Les lleis orgàniques.", "Les lleis harmonitzadores.", "Els decrets llei.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 65, "Què s’entén per inderogabilitat singular dels reglaments?", "Que les resolucions administratives de caràcter particular poden vulnerar els reglaments quan procedeixin d’un òrgan d’igual o superior jerarquia al que dictà la disposició general.", "Que les resolucions administratives de caràcter particular poden vulnerar els reglaments únicament quan procedeixin del Govern en casos d’extraordinària i urgent necessitat.", "Que les resolucions administratives de caràcter particular no poden vulnerar les disposicions reglamentàries malgrat procedeixin d’un òrgan d’igual o superior jerarquia al que dictà la disposició general.", "Que la vulneració d’una disposició d’abast general per una de caràcter particular requereix l’acord del Consell de Ministres o del Consell de Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 66, "La possibilitat del Govern de regularitzar, aclarir i harmonitzar els textos legals és possible quan dicti:", "Texts articulats.", "Texts refosos.", "Reials decrets.", "Reglaments."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 67, "Indicau quina de les matèries següents no es regula mitjançant una llei orgànica:", "Les condicions i el procediment de les diferents modalitats de referèndum previstes en la Constitució.", "Les funcions, els principis bàsics d'actuació i els estatuts de les forces i els cossos de seguretat.", "La composició i les competències del Consell d'Estat.", "Els col·legis professionals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 68, "El dret administratiu:", "És un dret públic.", "És un dret comú.", "És un dret limitatiu.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 69, "En parlar dels límits formals dels reglaments es pot afirmar:", "Que el reglament només està subjecte a la Constitució i a les lleis orgàniques pel principi de jerarquia.", "Que les relacions entre la llei i el reglament són de competència i no de jerarquia.", "Que el reglament està jeràrquicament subordinat a la Constitució i a la llei, d’acord amb l’article 97 de la Constitució i l’article 128 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques.", "Que no hi ha jerarquia normativa entre reglaments."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 70, "Els principis generals del dret operen com a límit material dels reglaments?", "Només els principis que recull l’article 103 de la Constitució.", "Sí.", "No; els límits materials dels reglaments són la Constitució, els estatuts d’autonomia i les normes amb rang de llei.", "Només opera com a límit el principi de no arbitrarietat dels poders públics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 71, "Un reglament que vulneri un altre reglament de rang superior:", "Pot ser convalidat.", "És anul·lable.", "És nul de ple dret.", "És nul de ple dret; això no obstant, el termini per declarar la nul·litat o impugnar-lo és d’un any, d’acord amb el que preveu la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 72, "Què han de fer els jutges i els magistrats davant un reglament il·legal?", "Aplicar-lo fins que el Tribunal Constitucional en declari la nul·litat.", "No aplicar-lo, atesa l’obligació que estableix la Llei orgànica del poder judicial de no aplicar els reglaments o qualsevol altra disposició contraris a la Constitució, a la llei o al principi de jerarquia normativa.", "Pot no aplicar-lo, atesa la independència del poder judicial.", "No aplicar-lo sempre que ho hagi al·legat la part recurrent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 73, "Què ha de fer un funcionari davant un reglament il·legal?", "Aplicar-lo fins que el Tribunal Constitucional en declari la nul·litat.", "No aplicar-lo, atès que els funcionaris estan subjectes a la Constitució i a la llei.", "Aplicar-lo si així ho imposa una instrucció o una ordre de servei.", "Les respostes b) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 74, "Davant un reglament il·legal, l’Administració pot:", "Convalidar-lo, reparant els vicis que presenti.", "Revisar-lo d’ofici, amb un dictamen previ del Consell Consultiu.", "Revisar-lo d’ofici, amb audiència prèvia i informació pública.", "Revocar-lo, sempre que siguin normes desfavorables."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 75, "Les disposicions reglamentàries s’han d’encapçalar:", "Amb una exposició de motius, que expressi la finalitat de les mesures adoptades en la regulació i el marc normatiu en què s’insereix.", "Amb un preàmbul, que expressi la finalitat de les mesures adoptades en la regulació i el marc normatiu en què s’insereix.", "Amb una exposició motivada, que expressi la finalitat de les mesures adoptades en la regulació i el marc normatiu en què s’insereix.", "Amb uns antecedents, que expressin la finalitat de les mesures adoptades en la regulació i el marc normatiu en què s’insereix."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 1, "Segons l’article 137 de la Constitució espanyola, l’Estat s’organitza territorialment:", "En municipis, en províncies i en les comunitats autònomes que se constitueixin.", "En municipis, en comarques, en províncies i en les comunitats autònomes que se constitueixin.", "En Àrees metropolitanes, en municipis, en províncies i en les comunitats autònomes que se constitueixin.", "En municipis, en illes, en províncies i en les comunitats autònomes que se constitueixin."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 2, "L’article 140 de la Constitució espanyola garanteix:", "L’autonomia de la província.", "L’autonomia dels municipis.", "La suficiència de recursos per a les entitats locals.", "El dret a crear agrupacions de municipis diferents de la província."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 3, "Quin article de la Constitució espanyola regula el municipi?", "L’article 137.", "L’article 138.", "L’article 139.", "L’article 140."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 4, "Quin article de la Constitució espanyola consagra el principi de suficiència financera de les hisendes locals?", "L’article 140.", "L’’article 142.", "L’article 156.", "L’article 158."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 5, "Segons l’article 141 de la Constitució espanyola, qualsevol alteració dels límits provincials s’ha d’aprovar mitjançant:", "Un reial decret.", "Una llei de l’assemblea legislativa autonòmica corresponent.", "Una llei orgànica.", "Un decret del consell de govern autonòmic corresponent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 6, "D’acord amb la Constitució espanyola, el finançament de les hisendes locals ha de provenir fonamentalment:", "Dels pressuposts generals de l’Estat.", "De les subvencions de la Unió Europea, de l’Estat i de les comunitats autònomes.", "De  l’import de les sancions que imposin.", "Dels tributs propis i de la participació en els tributs de l’Estat i de les comunitats autònomes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 7, "Preveu la Constitució espanyola la forma d’administració pròpia de les illes?", "Sí, preveu que als arxipèlags, les illes tindran a més la seva administració pròpia en forma de cabildos.", "No, preveu que la forma d’administració pròpia de les illes la determinarà, en el seu cas, una llei orgànica.", "Sí, preveu que als arxipèlags, les illes tindran a més la seva administració pròpia en forma de consells.", "Sí, preveu que als arxipèlags, les illes tindran a més la seva administració pròpia en forma de cabildos o consells."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 8, "D’acord amb l’article 141 de la Constitució espanyola, la província és una entitat local amb personalitat jurídica pròpia, determinada per l’agrupació de:", "Municipis.", "Comarques.", "Àrees metropolitanes.", "Mancomunitats de municipis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 9, "On s’ubica la regulació de l’Administració local a la Constitució espanyola?", "Al capítol III del Títol VIII.", "Al Títol VII.", "Al capítol II del Títol VIII.", "Al capítol II del Títol III."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 10, "Quina norma aprova el Text refós de les disposicions legals vigents en matèria de règim local?", "La Llei 7/1985, de 2 de abril.", "El Reial decret legislatiu 2/2004, de 5 de març.", "El Reial decret legislatiu 781/1986, de 18 de abril.", "La Llei 20/2006, de 15 de desembre."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 11, "L’article 140 de la Constitució Espanyola disposa que els batles s’han d’elegir:", "Per consens entre els regidors i els veïnats.", "Pels regidors.", "Directament pels veïnats mitjançant sufragi universal, igual, lliure, directe i secret.", "Pels regidors o pels veïnats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 12, "Quina és la norma reguladora de las bases del règim local?", "La Llei 7/1985, de 2 de abril.", "El Reial decret legislatiu 2/2004, de 5 de març.", "La Llei 20/2006, de 15 de desembre.", "El Reial decret llei 7/1985, de 2 d’abril."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 13, "Quina de les normes següents aprova el Text refós de la Llei reguladora de les hisendes locals?", "El Reial decret legislatiu 2/2004, de 5 de març.", "El Reial decret llei 2/2004, de 5 de març.", "El Decret llei 2/2004, de 5 de març.", "La Llei 7/1985, de 2 d’abril."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 14, "Les entitats locals territorials resten exemptes dels imposts de l’Estat i de les comunitats autònomes:", "En tot cas.", "En els termes que estableixi el reglament de l’impost corresponent.", "Només resten exemptes dels imposts de l’Estat.", "En els termes que estableixi la llei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 15, "Les competències de les entitats locals poden ser:", "Només pròpies.", "Només atribuïdes per delegació.", "Pròpies o atribuïdes per delegació.", "Les entitats locals manquen de competències."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 16, "Poden les entitats locals exercir competències distintes de les pròpies i de les atribuïdes per delegació?", "Sí, en qualsevol cas.", "Només quan no se posi en risc la sostenibilitat financera del conjunt de la Hisenda municipal, d’acord amb els requeriments de la legislació d’estabilitat pressupostària i sostenibilitat financera i no s’incorri en un supòsit d'execució simultània del mateix servei públic amb una altra Administració.", "No, en cap cas, atès que se posa en risc la sostenibilitat financera del conjunt de la Hisenda municipal.", "Només quan així ho decideixi, per motius d’oportunitat, l’òrgan o entitat delegant i l’accepti l’entitat local interessada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 17, "Quina norma du a terme el desplegament legislatiu en matèria de règim local a la comunitat autònoma de les Illes Balears?", "La Llei 3/2003, de 26 de març, de règim jurídic de l’Administració de la Comunitat Autònoma de les Illes Balears.", "La Llei 7/2010, de 21 de juliol, del sector públic instrumental de la Comunitat Autònoma de les Illes Balears.", "La Llei 20/2006, de 15 de desembre, municipal i de règim local de les Illes Balears.", "La Llei 4/2022, de 28 de juny, de consells insulars."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 18, "D’acord amb l’Estatut d’autonomia de les Illes Balears, a més de les competències derivades de la legislació bàsica de l’Estat i de la legislació sectorial, correspon als municipis:", "L’exercici de les competències que puguin ser delegades per l’Estat, per la Comunitat Autònoma, pels consells insulars i per altres administracions, sempre que vagin acompanyades dels mitjans econòmics, personals i materials adequats i suficients.", "L’exercici de les competències que el Ple de l’ajuntament consideri oportunes.", "L’exercici de les competències que, malgrat siguin competència d’altres administracions, afectin directament els interessos del municipi.", "L’exercici de les competències que puguin ser delegades per l’Estat, per la Comunitat Autònoma, pels consells insulars i per altres administracions, amb independència de la suficiència i adequació dels mitjans econòmics, personals i materials."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 19, "Segons la Carta Europea d’Autonomia Local, s’entén per autonomia local:", "El dret i la capacitat efectiva de les entitats locals de dictar normes amb rang de llei.", "El dret i la capacitat efectiva de les entitats locals d’ordenar i gestionar una part important dels assumptes públics en el marc de la llei, sota la seva pròpia responsabilitat i en benefici dels seus habitants.", "El dret i la capacitat efectiva de les entitats locals per convocar referèndums.", "El dret i la capacitat efectiva de les entitats locals per a l’autodeterminació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 20, "Quin precepte de la Constitució espanyola garanteix l’autonomia dels municipis?", "L’article 141.", "L’article 139.", "L’article 142.", "L’article 140."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 21, "Quin precepte de la Constitució espanyola consagra l’autonomia dels municipis i de les províncies?", "L’article 141.", "L’article 137.", "L’article 142.", "L’article 140."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 22, "L’article 137 de la Constitució espanyola se refereix a:", "L’autonomia dels ens territorials per a la gestió dels interessos respectius.", "L’autonomia financera de les entitats locals.", "El dret a l’autodeterminació.", "La garantia de la realització efectiva del principi de solidaritat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 23, "A quin òrgan correspon resoldre els conflictes en defensa de l’autonomia local?", "Als jutjats i tribunals de la jurisdicció contenciosa administrativa.", "Al Tribunal Constitucional.", "A la Comissió Bilateral de Cooperació entre la Administració General de l’Estat i la respectiva entitat local.", "Al Consell de Ministres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 24, "Qui pot plantejar un conflicte en defensa de l’autonomia local?", "L’Estat.", "Les comunitats autònomes.", "Els municipis, les províncies i les comunitats autònomes.", "Els municipis i les províncies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 25, "Poden donar lloc al plantejament dels conflictes en defensa de l’autonomia local:", "Els actes administratius i les normes reglamentàries de l’Estat o de les comunitats autònomes que lesionin l’autonomia local constitucionalment garantida.", "Les normes reglamentàries de l’Estat o de les comunitats autònomes que lesionin l’autonomia local constitucionalment garantida.", "Les normes de l’Estat amb rang de llei o les disposicions amb rang de llei de les comunitats autònomes que lesionin l’autonomia local constitucionalment garantida.", "Els actes administratius de l’Estat o de les comunitats autònomes que lesionin l’autonomia local constitucionalment garantida."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 26, "L'autonomia local reconeguda per la Constitució espanyola, implica potestat legislativa?", "Si, en tot cas.", "Només en determinades matèries.", "Només en virtut d’una delegació.", "No, en cap cas."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 27, "Quina norma autonòmica garanteix als municipis i a les altres entitats locals que puguin existir a les Illes Balears la plena autonomia per a la gestió dels seus respectius interessos, així com per a l’exercici de les seves competències?", "L’article 3 de l’Estatut d’autonomia de les Illes Balears.", "L’article 3 de la Llei 20/2006, de 15 de desembre, municipal i de règim local de les Illes Balears.", "L’article 3 de la Llei 3/2003, de 26 de març, de règim jurídic de l’Administració de la Comunitat Autònoma de les Illes Balears.", "L’article 3 de la Llei 7/2010, de 21 de juliol, del sector públic instrumental de la Comunitat Autònoma de les Illes Balears."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 28, "L'autonomia dels municipis:", "Està garantida pel Govern de l’Estat.", "No existeix.", "Està garantida per la Constitució espanyola.", "Està garantida per l’Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 29, "Quin article de la Constitució espanyola garanteix l’autonomia financera dels ens locals?", "L’article 142.", "L’article 140.", "L’article 1.", "L’article 141."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 30, "L’autonomia financera dels ens locals implica:", "Disposar de tributs propis i participar en els tributs en els de l’Estat i en els de les comunitats autònomes.", "Disposar de tributs propis.", "Participar en els tribus de l’Estat.", "Participar en els tributs de les comunitats autònomes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 31, "Segons l’instrument de Ratificació, per quin precepte de la Carta Europea de l’Autonomia Local no s’hi considera vinculat el Regne d’Espanya?", "Per l’article 1.", "Per l’apartat 2 de l’article 4.", "Per l’apartat 2 de l’article 3.", "Per l’apartat 3 de l’article 7."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 32, "L’Estat espanyol firmà la Carta Europea de l’Autonomia Local l’any:", "1978.", "1986.", "1989.", "1985."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 33, "Segons la doctrina del Tribunal Constitucional, el concepte d’autonomia local fa referència a:", "Un poder il·limitat.", "Un poder limitat.", "La sobirania.", "L’autodeterminació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 34, "Segons la doctrina del Tribunal Constitucional, l’autonomia local constitucionalment reconeguda no permet:", "L’existència d’un control de legalitat sobre l’exercici de les competències de les entitats locals.", "La configuració del règim competencial de les entitats locals per la legislació estatal i autonòmica.", "L’existència d’una dependència jeràrquica de les entitats locals a altres entitats territorials d’àmbit superior.", "La protecció de l’autonomia local davant el Tribunal Constitucional."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 35, "Pot el Consell de Ministres dissoldre els òrgans de les corporacions locals?", "No, això és contrari al principi d’autonomia local.", "Sí, mitjançant un reial decret, a iniciativa pròpia i amb coneixement del consell de govern de la comunitat autònoma corresponent o a sol·licitud d’aquest i, en tot cas, previ acord favorable del Senat, en el supòsit de gestió greument danyosa per als interessos generals que suposi incompliment de les obligacions constitucionals.", "Sí, mitjançant un reial decret llei, a iniciativa pròpia i amb coneixement del consell de govern de la comunitat autònoma corresponent o a sol·licitud d’aquest, en el supòsit de gestió greument danyosa per als interessos generals que suposi incompliment de les obligacions constitucionals.", "Sí, mitjançant un reial decret, a iniciativa pròpia i amb coneixement del consell de govern de la comunitat autònoma corresponent o a sol·licitud d’aquest i, en tot cas, previ acord favorable del Senat, per raons d’oportunitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 36, "En els conflictes en defensa de l’autonomia local regulats a la Llei orgànica 2/1979, de 3 de octubre, del Tribunal Constitucional:", "La sentència se limitarà, segons escaigui, a anul·lar la disposició legislativa objecte del conflicte o a declarar la vigència d’aquesta..", "La sentència se limitarà a declarar si existeix o no vulneració de l'autonomia local constitucionalment garantida.", "La sentència se limitarà a determinar la titularitat o atribució de la competència controvertida.", "La sentència declararà si existeix o no vulneració de l'autonomia local constitucionalment garantida, determinant, segons escaigui, la titularitat o atribució de la competència controvertida, i resoldrà, si escau, el que sigui procedent sobre les situacions de fet o de dret creades en lesió de l'autonomia local."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 37, "Són entitats locals territorials:", "El municipi i la província.", "L’ajuntament i la diputació provincial.", "El municipi, la província i l'Illa als arxipèlags balear i canari.", "El municipi, la comarca, la província i l'Illa als arxipèlags balear i canari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 38, "D’acord amb l’article 2 de la Llei 20/2006, de 15 de desembre, municipal i de règim local de les Illes Balears, també tenen la condició d’ens locals:", "Els llogarets, les mancomunitats de municipis, les entitats locals menors, les àrees metropolitanes i els consorcis locals constituïts per ens locals entre si o amb altres administracions públiques que tenguin per objecte essencial la prestació de serveis i d’obres que siguin competència dels ens locals.", "Les entitats locals menors, les àrees metropolitanes i els consorcis locals constituïts per ens locals entre sí o amb altres administracions públiques que tenguin per objecte essencial la prestació de serveis i d’obres que siguin competència dels ens locals.", "Les mancomunitats de municipis, les àrees metropolitanes i els consorcis locals constituïts per ens locals entre sí o amb altres administracions públiques que tenguin per objecte essencial la prestació de serveis i d’obres que siguin competència dels ens locals.", "Les mancomunitats de municipis, les entitats locals menors, les àrees metropolitanes i els consorcis locals constituïts per ens locals entre sí o amb altres administracions públiques que tenguin per objecte essencial la prestació de serveis i d’obres que siguin competència dels ens locals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 39, "D’acord amb l’article 3 de la Llei 7/1985, de 2 de abril, reguladora de les bases del règim local, no se considera ens local territorial:", "L’illa als arxipèlags balear i canari.", "El municipi.", "Les mancomunitats de municipis.", "La província."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 40, "Quina de les següents afirmacions és la correcta?", "La província és una entitat local, determinada per l'agrupació de municipis i la divisió territorial per al compliment de les activitats dels veïns.", "La província és una entitat local, determinada per l'agrupació de municipis i la divisió territorial per al compliment de les activitats de l'Estat.", "La província és una entitat local, determinada per l'agrupació de municipis i la divisió territorial per al compliment de les activitats del Govern.", "La província és una entitat local, determinada per l'agrupació de municipis i la divisió territorial per al compliment de les activitats de la Comunitat Autònoma."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 41, "Segons la Llei 20/2006, de 15 de desembre, municipal i de règim local de les Illes Balears, els ens locals menors estan dotats de totes les potestats a què es refereix la legislació bàsica de règim local per als municipis?", "Si.", "No.", "Sí, excepte la potestat d’expropiació.", "Sí, excepte la potestat d’expropiació i la d’aprovació de plans d'urbanisme."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 42, "D’acord amb la Llei 7/1985, de 2 de abril, reguladora de les bases del règim local, les comarques:", "Són entitats locals territorials.", "Son entitats locals que agrupen varis municipis, que poden ser creades per les comunitats autònomes en el seu territori, d’acord amb el que disposin els respectius estatuts d’autonomia.", "Son entitats locals que agrupen varis municipis, que poden ser creades per les províncies o les illes en el seu territori, d’acord amb el que disposin els respectius estatuts d’autonomia.", "No són entitats locals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 43, "Quina de les afirmacions següents és la correcta?", "El municipi és l’entitat local bàsica de l’organització territorial de l’Estat.", "La província és l’entitat local bàsica de l’organització territorial de l’Estat.", "La comarca és l’entitat local bàsica de l’organització territorial de l’Estat.", "L’àrea metropolitana és l’entitat local bàsica de l’organització territorial de l’Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 44, "Les mancomunitats de municipis:", "No tenen personalitat jurídica independent de la dels municipis que la formen", "Tenen personalitat i capacitat jurídiques per al compliment dels seus fins específics i se regeixen pels seus Estatuts.", "Tenen personalitat jurídica, però no capacitat jurídica.", "Només tenen capacitat jurídica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 45, "Es poden crear agrupacions de municipis diferents de la província?", "Sí, amb autorització prèvia del Senat.", "Sí.", "No, en cap cas.", "Només a iniciativa del Consell de Ministres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 46, "D’acord amb la Llei 20/2006, de 15 de desembre, municipal i de règim local de les Illes Balears:", "La creació d’entitats locals menors és subsidiària respecte de les àrees metropolitanes, dels ens autònoms locals, i dels districtes i delegacions territorials.", "No és possible, en cap cas, la creació d’entitats locals menors.", "La creació d’entitats locals menors s’ha de dur a terme a iniciativa dels consells insulars.", "La creació d’entitats locals menors s’ha de dur a terme a iniciativa del Govern de les Illes Balears."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 47, "Què són les àrees metropolitanes?", "Son entitats locals territorials.", "Són entitats locals integrades per les mancomunitats de municipis de grans aglomeracions urbanes entre els nuclis de població de les quals hi hagi vinculacions econòmiques i socials que facin necessària la planificació conjunta i la coordinació de determinats serveis i obres.", "Són entitats locals integrades pels municipis de grans aglomeracions urbanes entre els nuclis de població de les quals hi hagi vinculacions econòmiques i socials que facin necessària la planificació conjunta i la coordinació de determinats serveis i obres.", "Són entitats locals integrades pels municipis, les característiques dels quals determinin interessos comuns necessaris d'una gestió pròpia o demanin la prestació de serveis del dit àmbit."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 48, "D’acord amb l’article 54 de la Llei 20/2006, de 15 de desembre, municipal i de règim local de les Illes Balears, les entitats locals menors tenen competència, en coordinació amb el municipi, sobre les matèries següents:", "L’administració i la conservació del seu patrimoni i la regulació i l’ordenació del seu aprofitament i de la seva utilització.", "Gestió del padró municipal d’habitants", "Policia local.", "Normalització lingüística."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 49, "Poden integrar-se a la mateixa mancomunitat municipis pertanyents a diferents comunitats autònomes?", "Sí, en tot cas.", "Sí, sempre que ho permetin les normatives de les comunitats autònomes afectades.", "No, en cap cas.", "Si, amb autorització prèvia del Senat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 50, "La Llei 20/2006, de 15 de desembre, municipal i de règim local de les Illes Balears:", "Regula les comarques a l’article 51.", "Preveu la seva creació a iniciativa dels municipis interessats.", "Preveu la seva creació a iniciativa dels consells insulars.", "No regula les comarques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 51, "D’acord amb l’article 3.2 de la Llei 7/1985, de 2 de abril, reguladora de les bases del règim local, gaudeixen, així mateix, de la condició d’entitats locals:", "Les mancomunitats de municipis.", "Les entitats públiques empresarials locals.", "Els organismes autònoms locals.", "Les societats mercantils locals"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 52, "Quines entitats poden crear una àrea metropolitana?", "Els municipis interessats, amb audiència prèvia de l’Administració de l’Estat i de les diputacions provincials afectades.", "Les comunitats autònomes, amb audiència prèvia de l'Administració de l'Estat i dels ajuntaments i les diputacions afectats, mitjançant una llei, d'acord amb el que disposen els Estatuts respectius.", "Les províncies, amb audiència prèvia de l'Administració de l'Estat i dels ajuntaments afectats.", "A la comunitat autònoma de les Illes Balears, els consells insulars amb audiència prèvia de l'Administració de l'Estat i dels ajuntaments afectats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 53, "D’acord amb la Llei 20/2006, de 15 de desembre, municipal i de règim local de les Illes Balears, els ens locals autònoms, els districtes i les delegacions territorials:", "Tenen la condició d’entitats locals.", "Sense tenir la condició d’entitats locals, són formes d’organització descentralitzada o desconcentrada del municipi.", "Sense tenir la condició d’entitats locals, són formes d’organització descentralitzada o desconcentrada de l’illa.", "Son formes d’organització descentralitzada o desconcentrada de les mancomunitats de municipis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 54, "La creació de nous municipis només podrà realitzar-se:", "Sobre la base de nuclis de població territorialment diferenciats, d’almenys 50.000 habitants.", "Sobre la base de nuclis de població territorialment diferenciats, d’almenys 500 habitants.", "Amb independència el nombre d’habitants, sempre que els municipis resultants siguin financerament sostenibles.", "Sobre la base de nuclis de població territorialment diferenciats, d’almenys 5.000 habitants."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 55, "D’acord amb l’article 4 de la Llei 7/1985, de 2 de abril, reguladora de les bases del règim local, no correspon als municipis, les províncies i les illes:", "La potestat legislativa.", "La potestat reglamentària.", "Les potestats tributària i financera.", "La potestat de programació o planificació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 56, "Segons la Llei 7/1985, de 2 de abril, reguladora de les bases del règim local, quina és l’entitat bàsica de l’organització territorial de l’Estat?", "La província.", "L’illa.", "El municipi.", "La comarca."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 57, "Quina norma pot determinar les competències pròpies de les entitats locals territorials?", "Només una llei orgànica.", "Només una llei.", "Només un reial decret.", "Només un reial decret o un decret del consell de govern autonòmic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 58, "Corresponen a las mancomunitats de municipis, per a la prestació dels serveis o l’execució de les obres de la seva competència:", "Les mateixes potestats que corresponen a les entitats locals territorials.", "Les potestats que determinin els seus estatuts i, en defecte de previsió estatutària, les  mateixes potestats que corresponen a les entitats locals territorials.", "Les potestats que determinin els seus estatuts i, en defecte de previsió estatutària, les  mateixes potestats que corresponen a les entitats locals territorials, sempre que siguin necessàries per al compliment de la seva finalitat, i d’acord amb la legislació aplicable a cadascuna de les dites potestats, en ambdós casos.", "Les potestats que determinin els seus estatuts i, en defecte de previsió estatutària, les potestats tributària i financera."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 59, "L’exercici del control de legalitat dels acords i actes de les entitats locals correspon:", "Als Tribunals.", "Al Consell de Ministres.", "Al consell de govern autonòmic corresponent.", "Al Tribunal Constitucional."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 60, "Amb caràcter general, el govern i administració de les entitats locals territorials correspon:", "En el municipi, a l’ajuntament, integrat pel batle i els regidors; en la província, a la diputació o altra corporació de caràcter representatiu; i en l’illa, als cabildos i consells insulars.", "En el municipi, a una assemblea integrada por tots els electors existents en el municipi i pel batle elegit directament per ells; en la província, a la diputació o altra corporació de caràcter representatiu; i en l’illa, als cabildos i consells insulars.", "En el municipi, a l’ajuntament, integrat pel batle i els regidors; en la província, només a la diputació; i en l’illa, als consells insulars.", "En el municipi, a l’ajuntament, integrat pel batle i els regidors; en la província i en l’illa, a la diputació o altra corporació de caràcter representatiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 61, "Les províncies i les illes poden realitzar la gestió ordinària de serveis propis de l’Administració autonòmica:", "En tot cas.", "Només quan així ho decideixi el consell de govern autonòmic corresponent.", "Només quan així estigui previst a l’estatut d’autonomia i a la legislació autonòmica corresponent.", "Només de forma subsidiària, per garantir el desenvolupament de les funcions públiques necessàries."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 62, "D’acord amb l’article 4 de la  Llei 7/1985 de 2 d'abril, reguladora de les bases del règim local, la potestat reglamentària s’atribueix en tot cas a:", "Municipis, províncies i illes, en la seva qualitat d’Administracions públiques territorials.", "Municipis, províncies i illes, entitats territorials d’àmbit inferior al municipi, com també a les mancomunitats.", "Municipis, províncies i illes i demés entitats territorials d’àmbit inferior al municipi, com també a les comarques i àrees metropolitanes.", "Municipis, províncies i illes i demés entitats territorials d’àmbit inferior al municipi, comarques, àrees metropolitanes i mancomunitats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 63, "Perquè les entitats locals puguin exercir competències diferents de les pròpies i de les atribuïdes per delegació són necessaris:", "Els informes facultatius de l’Administració competent per raó de matèria, en què s’assenyali la inexistència de duplicitats, i de l’Administració que tingui atribuïda la tutela financera sobre la sostenibilitat financera de les noves competències.", "Els informes previs i vinculants del secretari i de l’interventor de la corporació en què s’assenyali la inexistència de duplicitats, i de l’Administració que tingui atribuïda la tutela financera sobre la sostenibilitat financera de les noves competències.", "Els informes previs i vinculants de l’Administració competent per raó de matèria, en què s’assenyali la inexistència de duplicitats, i de l’Administració que tingui atribuïda la tutela financera sobre la sostenibilitat financera de les noves competències.", "Els informes previs i vinculants de l’interventor de la corporació i de l’Administració que tingui atribuïda la tutela financera sobre la sostenibilitat financera de les noves competències."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 64, "D’acord amb l’article 4 de la Llei 7/1985, de 2 de abril, reguladora de les bases del règim local, correspon a les comarques:", "La potestat de revisió d’ofici dels seus actes i acords.", "Les potestats que concretin les lleis de les comunitats autònomes.", "Les potestats tributària i financera.", "La potestat de programació o planificació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 65, "Segons l’article 9 de la Llei 7/1985, de 2 de abril, reguladora de les bases del règim local:", "Les normes de desplegament de la Llei reguladora de les bases del règim local  que afectin els municipis, les províncies, les illes o altres entitats locals territorials poden limitar el seu àmbit d'aplicació a una o diverses d'aquestes entitats amb caràcter singular.", "Les normes de desplegament de la Llei reguladora de les bases del règim local  que afectin els municipis, les províncies, les illes o altres entitats locals territorials no poden limitar el seu àmbit d'aplicació a una o diverses d'aquestes entitats amb caràcter singular en cap cas.", "Les normes de desplegament de la Llei reguladora de les bases del règim local  que afectin les entitats locals territorial no poden limitar el seu àmbit d'aplicació a una o diverses d'aquestes entitats amb caràcter singular, sens perjudici del que disposa aquesta Llei per als municipis.", "Les normes de desplegament de la Llei reguladora de les bases del règim local  que afectin els municipis, les províncies, les illes o altres entitats locals territorials no poden limitar el seu àmbit d'aplicació a una o diverses d'aquestes entitats amb caràcter singular, sens perjudici del que disposa aquesta Llei per als règims municipals o provincials especials."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 66, "D’acord amb l’article 10 de la Llei 7/1985, de 2 de abril, reguladora de les bases del règim local, què té per objecte, especialment, la coordinació de les entitats locals?", "Assegurar el compliment de la legislació d'estabilitat pressupostària i de sostenibilitat financera.", "Assegurar l’exercici de la potestat de programació o planificació.", "Assegurar el compliment de la legislació en matèria urbanística.", "Assegurar el compliment de la legislació en matèria de subvencions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 67, "Les funcions de coordinació de les entitats locals:", "Limiten l’autonomia de les entitats locals.", "Només procedeixen respecte de l’exercici de les competències de les entitats locals entre sí.", "Només procedeixen respecte de l’exercici de les competències de les entitats locals amb les de la resta d’Administracions públiques.", "Han de ser compatibles amb l’autonomia de les entitats locals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 68, "D’acord amb l’article 6 de la Llei 7/1985, de 2 de abril, reguladora de les bases del règim local, les entitats locals serveixen amb objectivitat els interessos públics que els estan encomanats i actuen:", "D'acord amb els principis d’eficàcia i descentralització.", "D'acord amb els principis de descentralització, desconcentració i coordinació, amb plena submissió a la llei i al dret.", "D'acord amb els principis d'eficàcia, descentralització, desconcentració i coordinació, amb plena submissió a la llei i al dret.", "D'acord amb el principi d’eficiència, amb plena submissió a la llei i al dret."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 69, "L'Administració local i les altres administracions públiques:", "Han d’ajustar les relacions recíproques als deures d'informació mútua, col·laboració, coordinació i respecte als àmbits competencials respectius.", "S’han de limitar a exercir les seves competències.", "No s’hi troben sotmeses a cap deure d’informació.", "Només han d’ajustar les relacions recíproques al deure d’informació mútua."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 70, "D’acord amb l’article 4 de la Llei 7/1985, de 2 de abril, reguladora de les bases del règim local, correspon a les àrees metropolitanes:", "Les potestats reglamentària i d’autoorganització.", "Les potestats d’execució forçosa i sancionadora.", "La potestat de revisió d’ofici dels seus actes i acords.", "Les potestats que concretin les lleis de les comunitats autònomes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 71, "La disposició o l’acord de delegació de competències a les entitats locals, pot preveure tècniques de direcció i control d’oportunitat i d’eficiència?", "No, això seria contrari al principi d’autonomia local.", "Sí, en tot cas.", "Només pot preveure tècniques de direcció.", "Només pot preveure tècniques de control d’oportunitat i d’eficiència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 72, "Les potestats tributària i financera corresponen en tot cas:", "Exclusivament als municipis.", "Exclusivament a les províncies.", "Als municipis, a les províncies i a les illes.", "Als municipis i a les comarques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 1, "Segons l’article 25.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, les entitats locals exerceixen la potestat sancionadora de conformitat amb el que disposa:", "El títol XI de la Llei 39/2015, d’1 d’octubre.", "El títol IX de la Llei 7/1985, de 2 d’abril.", "El títol IX de la Llei 39/2015, d’1 d’octubre.", "El títol XI de la Llei 7/1985, de 2 d’abril."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 2, "L’article 25.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, disposa que l’exercici de la potestat sancionadora correspon als òrgans administratius que la tinguin atribuïda expressament:", "Per la Constitució.", "Per una norma amb rang de llei.", "Per disposició de rang legal o reglamentari.", "Per les normes específiques de cada òrgan."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 3, "Segons l’article 26.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, les disposicions sancionadores:", "Poden produir efecte retroactiu quan afavoreixin el presumpte infractor.", "Produeixen efecte irretroactiu quan afavoreixin el presumpte infractor.", "No produeixen efecte retroactiu quan afavoreixin el presumpte infractor.", "Produeixen efecte retroactiu quan afavoreixin el presumpte infractor."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 4, "Segons l’article 27.3 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, les disposicions reglamentàries:", "Poden introduir especificacions o graduacions al quadre de les infraccions o sancions establertes legalment.", "Poden introduir infraccions i sancions de caràcter lleu.", "Poden regular infraccions i sancions administratives si no hi ha llei.", "Únicament poden regular el procediment sancionador."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 5, "Segons l’article 28.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, els grups d’afectats:", "Poden ser sancionats per fets constitutius d’infracció administrativa.", "Poden ser sancionats per fets constitutius d’infracció administrativa quan una llei els reconegui capacitat d’obrar.", "No poden ser sancionats per fets constitutius d’infracció administrativa.", "No poden ser sancionats per fets constitutius d’infracció administrativa quan una llei els reconegui capacitat d’obrar."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 6, "Segons l’article 28.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quan poden ser sancionats els patrimonis independents o autònoms?", "Quan una llei els reconegui capacitat d’obrar.", "Quan el seu estatut els reconegui capacitat d’obrar.", "Quan una llei o un reglament els reconegui capacitat d’obrar.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 7, "Segons l’article 28.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, les persones jurídiques poden ser sancionades:", "Per fets constitutius d’infracció administrativa.", "Per fets constitutius d’infracció administrativa, quan una llei els reconegui capacitat d’obrar.", "Per fets constitutius de sanció administrativa.", "Per fets constitutius d’infracció administrativa, llevat que una llei limiti la seva capacitat d’obrar."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 8, "Segons l’article 28.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, els infractors són responsables a títol de:", "Dol o culpa.", "Dol.", "Culpa.", "Dol, culpa o imprudència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 9, "Segons l’article 28.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, les responsabilitats administratives que es derivin de la comissió d’una infracció:", "Són compatibles amb l’exigència a l’infractor de la reposició de la situació alterada per aquest infractor al seu estat originari.", "Són compatibles amb la indemnització pels danys i perjudicis causats.", "Són incompatibles amb la indemnització pels danys i perjudicis causats.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 10, "Segons l’article 28.3 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quan el compliment d’una obligació establerta per una norma amb rang de llei correspongui a diverses persones conjuntament:", "Responen de manera solidària de les infraccions que, si s’escau, es cometin i de les sancions que s’imposin.", "Responen de manera mancomunada de les infraccions que, si s’escau, es cometin i de les sancions que s’imposin.", "Responen de manera subsidiària de les infraccions que, si s’escau, es cometin i de les sancions que s’imposin.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 11, "Segons l’article 28.3 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quan s’imposi una sanció pecuniària a diverses persones conjuntament, si és possible:", "S’ha de tenir en compte la capacitat econòmica dels responsables.", "S’ha d’individualitzar en la resolució en funció de la capacitat econòmica de cada responsable.", "No s’ha de valorar el grau de participació de cada responsable.", "S’ha d’individualitzar en la resolució en funció del grau de participació de cada responsable."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 12, "Segons l’article 28.4 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, les lleis reguladores dels diferents règims sancionadors:", "Han de preveure els supòsits en què determinades persones han de respondre del pagament de les sancions pecuniàries imposades als qui depenguin d’elles o hi estiguin vinculades.", "Poden preveure els supòsits en què determinades persones han de respondre del pagament de les sancions pecuniàries imposades als qui depenguin d’elles o hi estiguin vinculades.", "Han de preveure els supòsits en què determinades persones han de respondre de les sancions imposades als qui depenguin d’elles o hi estiguin vinculades.", "Poden preveure els supòsits en què determinades persones han de respondre de les sancions imposades als qui depenguin d’elles o hi estiguin vinculades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 13, "Segons l’article 29.3 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, és un criteri de graduació de la sanció:", "La reincidència, per comissió en el terme d’un any de més d’una infracció de la mateixa naturalesa quan hagi estat declarat així per una resolució ferma en via administrativa.", "La reiteració, per comissió en el terme d’un any de més d’una infracció de la mateixa naturalesa quan hagi estat declarat així per una resolució ferma en via administrativa.", "La reincidència, per comissió en el terme d’un any de més d’una infracció quan hagi estat declarat així per una resolució ferma en via administrativa.", "La reiteració, per comissió en el terme d’un any de més d’una infracció quan hagi estat declarat així per una resolució ferma en via administrativa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 14, "Quina de les regles següents no figura entre els criteris de graduació de la sanció de l’article 29.3 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic?", "El grau de culpabilitat.", "L’existència d’intencionalitat.", "La capacitat econòmica.", "La continuïtat o persistència en la conducta infractora."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 15, "Segons l’article 29.4 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, es pot imposar la sanció en el grau inferior:", "Quan les circumstàncies ho aconsellin i ho sol·liciti l’interessat.", "Quan hi hagi raons d’interès públic.", "Quan ho justifiqui l’adequació deguda entre la sanció que s’hagi d’aplicar amb la gravetat del fet constitutiu de la infracció i les circumstàncies concurrents.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 16, "Segons l’article 29.5 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quan de la comissió d’una infracció en derivi necessàriament la comissió d’una altra o altres:", "Es pot qualificar únicament la infracció més greu comesa.", "S’ha d’imposar únicament la sanció corresponent a la infracció més greu comesa.", "S’ha de qualificar únicament la infracció més greu comesa.", "Es pot imposar únicament la sanció corresponent a la infracció més lleu comesa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 17, "Segons l’article 30.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, si no hi ha una llei específica les infraccions molt greus prescriuen:", "Al cap de sis mesos.", "Al cap d'un any.", "Al cap de dos anys.", "Al cap de tres anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 18, "Segons l’article 30.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, les sancions imposades per faltes lleus prescriuen:", "Segons el que disposen les lleis que les estableixen o, si no n’hi ha, al cap d'un any.", "Al cap d'un any.", "Segons el que disposen les lleis que les estableixen o,  si no n’hi ha, al cap de sis mesos.", "Al cap de sis mesos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 19, "Segons l’article 30.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, si no hi ha una llei específica les sancions imposades per faltes greus prescriuen:", "Al cap de sis mesos.", "Al cap d'un any.", "Al cap de dos anys.", "Al cap de tres anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 20, "Segons l’article 30.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, és possible augmentar el termini de prescripció de les infraccions greus fins als tres anys?", "Sí, mitjançant una llei.", "No, únicament es poden reduir els terminis de prescripció.", "Sí, mitjançant una llei específica o un reglament sectorial.", "No, els terminis de prescripció no poden ser modificats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 21, "Segons l’article 30.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, el termini de prescripció de les infraccions comença a comptar:", "Des del dia en què s’hagi comès la infracció.", "Des de l’endemà del dia en què la resolució sigui executable.", "Des de l’endemà del dia en què s’hagi comès la infracció.", "Des del dia en què la resolució sigui executable."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 22, "Segons l’article 30.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, la iniciació, amb coneixement de l’interessat, d’un procediment administratiu de naturalesa sancionadora:", "Interromp el termini de prescripció de la sanció.", "Interromp el termini de prescripció de la infracció.", "Interromp el termini de prescripció de la infracció i de la sanció.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 23, "Segons l’article 30.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, el termini de prescripció de la infracció es reinicia si l’expedient sancionador:", "Està paralitzat durant menys d’un mes.", "Està paralitzat durant menys d’un mes per causa no imputable al presumpte responsable.", "Està paralitzat durant més d’un mes.", "Està paralitzat durant més d’un mes per causa no imputable al presumpte responsable."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 24, "Segons l’article 30.3 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, el termini de prescripció de les sancions comença a comptar:", "Des del dia en què sigui executable la resolució per la qual s’imposa la sanció o hagi transcorregut el termini per recórrer-la.", "Des del dia en què s’hagi comès la infracció.", "Des de l’endemà del dia en què sigui executable la resolució per la qual s’imposa la sanció o hagi transcorregut el termini per recórrer-la.", "Des de l’endemà del dia en què s’hagi comès la infracció."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 25, "Segons l’article 30.3 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, el termini de prescripció de les sancions torna a transcórrer quan el procediment estigui paralitzat:", "Durant menys d’un mes per causa no imputable a l’infractor.", "Durant més d’un mes.", "Durant més d’un mes per causa imputable a l’infractor.", "Durant més d’un mes per causa no imputable a l’infractor."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 26, "Segons l’article 30.3 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, en el cas de desestimació presumpta del recurs d’alçada interposat contra la resolució per la qual s’imposa la sanció, el termini de prescripció de la sanció comença a comptar:", "Des de l’endemà del dia en què finalitzi el termini previst legalment per a la resolució del recurs esmentat.", "Des de l’endemà del dia en què sigui executable la resolució per la qual s’imposa la sanció o hagi transcorregut el termini per recórrer-la.", "Des del dia en què finalitzi el termini previst legalment per a la resolució del recurs esmentat.", "Des del dia en què sigui executable la resolució per la qual s’imposa la sanció o hagi transcorregut el termini per recórrer-la."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 27, "L’article 31.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, disposa que:", "No es poden sancionar els fets que ho hagin estat penalment, en els casos en què s’apreciï identitat del subjecte, fet i fonament.", "No es poden sancionar els fets que ho hagin estat penalment.", "No es poden sancionar els fets que ho hagin estat penalment o administrativament, en els casos en què s’apreciï identitat del subjecte, fet i fonament.", "No es poden sancionar els fets que ho hagin estat penalment o administrativament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 28, "Segons l’article 31.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quan un òrgan de la Unió Europea hagi imposat una sanció pels mateixos fets, i sempre que no concorri la identitat de subjecte i fonament, l’òrgan competent per resoldre:", "La pot tenir en compte als efectes de graduar la que, si s’escau, hagi d’imposar, i la pot minorar, sense perjudici de declarar la comissió de la infracció.", "Ha d’arxivar el procediment.", "L’ha de tenir en compte als efectes de graduar la que, si s’escau, hagi d’imposar, i la pot minorar, sense perjudici de declarar la comissió de la infracció.", "Pot arxivar el procediment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 29, "Segons l’article 32.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, no hi ha responsabilitat patrimonial de les administracions públiques per danys que el particular:", "Tengui el deure jurídic de suportar d’acord amb la llei.", "Tengui el deure jurídic de suportar d’acord amb les normes.", "No tengui el deure jurídic de suportar d’acord amb la llei.", "No tengui el deure jurídic de suportar d’acord amb les normes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 30, "Segons l’article 32.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, l’anul·lació en via administrativa o per l’ordre jurisdiccional contenciós administratiu dels actes o disposicions administratives:", "No pressuposa, per si mateixa, dret a la indemnització.", "Pressuposa el dret a la indemnització.", "No pressuposa, per si mateixa, dret a la sanció.", "Pressuposa el dret al reconeixement de la situació jurídica individualitzada del particular afectat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 31, "Segons l’article 32.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, en els supòsits de responsabilitat patrimonial el dany al·legat ha de ser:", "Efectiu.", "Avaluable econòmicament.", "Individualitzat en relació amb una persona o un grup de persones.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 32, "Segons l’article 32.3 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, en quin dels supòsits següents pot sorgir la responsabilitat patrimonial de l’Estat legislador?", "Quan els danys derivin de l’aplicació d’una norma contrària al dret de la Unió Europea.", "Quan els danys derivin de l’aplicació d’una norma comunitària contrària al dret intern.", "Quan els danys derivin de l’aplicació d’una llei o una disposició general contrària a l’ordenament jurídic.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 33, "Segons l’article 32.4 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quins requisits s’han de complir per obtenir una indemnització per una lesió que sigui conseqüència de l’aplicació d’una norma amb rang de llei declarada inconstitucional?", "Que el particular hagi obtingut, en qualsevol instància, una sentència ferma desestimatòria d’un recurs contra l’actuació administrativa que va ocasionar el dany.", "Que s’hagi al·legat la inconstitucionalitat declarada posteriorment.", "Que l’incompliment estigui prou caracteritzat.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 34, "Segons l’article 32.6 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, des de quan produeix efectes la sentència que declari la inconstitucionalitat d’una norma amb rang de llei?", "Des de la data de la notificació als interessats.", "Des de la data de publicació en el Butlletí Oficial de l’Estat, llevat que en la sentència s’estableixi una altra cosa.", "Des de la data de publicació en el Butlletí Oficial de l’Estat o al butlletí oficial corresponent, llevat que en aquesta s’hi estableixi una altra cosa.", "Des de la data de publicació en el Butlletí Oficial de l’Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 35, "Segons l’article 32.8 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quan el Tribunal Constitucional hagi declarat, a instància de part interessada, l’existència d’un funcionament anormal en la tramitació dels recursos d’empara o de les qüestions d’inconstitucionalitat, quin òrgan ha de fixar l’import de les indemnitzacions que sigui procedent abonar?", "El Consell de Ministres.", "El Consell de Ministres o l’òrgan de govern de la comunitat autònoma.", "El Tribunal Constitucional.", "El Ministeri de Justícia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 36, "Segons l’article 32.8 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quan el Tribunal Constitucional hagi declarat, a instància de part interessada, l’existència d’un funcionament anormal en la tramitació dels recursos d’empara o de les qüestions d’inconstitucionalitat, el procediment per fixar l’import de les indemnitzacions l’ha de tramitar:", "El Consell d‘Estat, amb audiència al Consell de Ministres.", "El Ministeri de Justícia, amb audiència al Consell d’Estat.", "El Consell General del Poder Judicial, amb audiència al Consell d’Estat.", "El Consell de Ministres o l’òrgan de govern de la comunitat autònoma, amb audiència al Consell d’Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 37, "Segons l’article 32.9 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, hi ha responsabilitat de les administracions públiques pels danys i perjudicis causats a tercers durant l’execució de contractes quan siguin conseqüència:", "D’una ordre immediata i directa de l’Administració.", "Dels vicis del projecte elaborat pel contractista.", "Dels vicis del projecte elaborat per l’Administració.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 38, "Segons l’article 33.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, l’instrument jurídic regulador de l’actuació conjunta de diverses administracions públiques:", "Ha de determinar la distribució de la responsabilitat entre les diferents administracions públiques.", "Pot determinar la distribució de la responsabilitat entre les diferents administracions públiques.", "Ha de determinar la distribució de la responsabilitat en funció de la capacitat econòmica de les diferents administracions públiques.", "Pot determinar l’exempció de la responsabilitat de les diferents administracions públiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 39, "Segons l’article 33.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quins criteris s’han de tenir en compte per fixar la responsabilitat patrimonial en cas de concurrència de diverses administracions públiques?", "Competència.", "Interès públic tutelat.", "Intensitat de la intervenció.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 40, "Segons l’article 34.1 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, no són indemnitzables els danys que es derivin de fets o circumstàncies:", "Que no s’hagin pogut preveure o evitar segons l’estat dels coneixements de la ciència o de la tècnica existents en el moment de produir-se aquells danys.", "Que s’hagin pogut preveure o evitar segons l’estat dels coneixements de la ciència o de la tècnica existents en el moment de produir-se aquells danys.", "Que no s’hagin pogut preveure o evitar segons l’estat dels coneixements de la ciència o de la tècnica existents en el moment de la taxació d'aquells danys.", "Que s’hagin pogut preveure o evitar segons l’estat dels coneixements de la ciència o de la tècnica existents en el moment de la taxació d'aquells danys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 41, "Segons l’article 34.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, en els casos de responsabilitat patrimonial la indemnització es calcula d’acord amb els criteris de valoració establerts en la legislació fiscal, d’expropiació forçosa i altres normes aplicables:", "I subsidiàriament s’han d’aplicar les valoracions predominants en el mercat.", "Amb ponderació, si s’escau, de les valoracions predominants en el mercat.", "Amb ponderació, si s’escau, de les valoracions realitzades per un perit judicial.", "I subsidiàriament s’ha de realitzar una taxació judicial."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 42, "Segons l’article 34.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quina valoració es pot prendre com a referència per calcular la indemnització en els casos de mort o lesions corporals?", "La inclosa en els barems de l’annex 2 de la Llei 40/2015.", "La inclosa en els barems de la normativa vigent en matèria d’assegurances obligatòries i de la Seguretat Social.", "La inclosa en els barems de la Llei sobre responsabilitat civil i assegurança en la circulació de vehicles de motor.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 43, "Segons l’article 34.4 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, en els casos de responsabilitat patrimonial, quan es pot abonar la indemnització mitjançant pagaments periòdics?", "Quan no hi hagi disponibilitat pressupostària per abonar la indemnització durant l’any en curs.", "Quan es prevegi en les normes sectorials específiques.", "Quan sigui més adequat per aconseguir la reparació deguda i convingui a l’interès públic.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 44, "Segons l’article 35 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quan les administracions públiques actuïn, directament o a través d’una entitat de dret privat, en relacions d’aquesta naturalesa, la seva responsabilitat s’ha d’exigir de conformitat amb el que preveuen els articles 32 i següents:", "Fins i tot quan la responsabilitat s’exigeixi directament a l’entitat de dret privat a través de la qual actuï l’Administració.", "Llevat quan la responsabilitat s’exigeixi directament a l’entitat de dret privat a través de la qual actuï l’Administració.", "Llevat quan la responsabilitat s’exigeixi directament a l’entitat que cobreixi la responsabilitat.", "Fins i tot quan la responsabilitat s’exigeixi indirectament i subsidiàriament a l’entitat de dret privat a través de la qual actuï l’Administració."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 45, "Segons l’article 36.2 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quins criteris s’han de ponderar per quantificar la indemnització que han d’abonar els empleats de l’Administració en els casos de responsabilitat patrimonial?", "El resultat danyós produït.", "El grau de culpabilitat.", "La responsabilitat professional del personal al servei de les administracions públiques, i la seva relació amb la producció del resultat danyós.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 46, "Segons l’article 36.3 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, en quins casos s’ha d’exigir responsabilitat als empleats públics pels danys i perjudicis causats en els béns o drets de l’Administració?", "Quan concorri dol, o culpa o negligència greus.", "Quan concorri dol o negligència greus.", "Quan concorri dol o culpa greus.", "Quan concorri dol, culpa o imprudència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 47, "Segons l’article 36.4 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, el termini d’al·legacions i el termini d’audiència en els procediments de responsabilitat patrimonial a les autoritats i personal al servei de les administracions públiques és de:", "Deu dies en ambdós casos.", "Deu dies per presentar al·legacions i quinze dies per dur a terme l’audiència.", "Quinze dies per presentar al·legacions i deu dies per dur a terme l’audiència.", "Quinze dies en ambdós casos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 48, "Segons l’article 36.4 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, el termini per practicar proves en els procediments de responsabilitat patrimonial a les autoritats i personal al servei de les administracions públiques és:", "De deu dies.", "No inferior a deu dies ni superior a trenta.", "De quinze dies.", "No inferior a quinze dies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 49, "Segons l’article 36.4 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, el termini d’audiència en els procediments de responsabilitat patrimonial a les autoritats i personal al servei de les administracions públiques és:", "De deu dies.", "No inferior a deu dies.", "De quinze dies.", "No inferior a quinze dies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 50, "Segons l’article 36.4 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, en els procediments de responsabilitat patrimonial a les autoritats i personal al servei de les administracions públiques, en quin termini s’ha de formular la proposta de resolució?", "Deu dies comptadors des de la conclusió de la fase de prova.", "Cinc dies comptadors des de la finalització del tràmit d’audiència.", "Deu dies comptadors des de la finalització del tràmit d’audiència.", "No hi ha cap termini específic per formular la proposta de resolució."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 51, "Segons l’article 36.4 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, quin és el termini per dictar resolució en els procediments de responsabilitat patrimonial a les autoritats i personal al servei de les administracions públiques?", "Cinc dies comptadors des de la finalització del tràmit d’audiència.", "Deu dies.", "Deu dies comptadors des de la finalització del tràmit d’audiència.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 52, "Segons l’article 36.5 de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic, la resolució declaratòria de responsabilitat en els procediments de responsabilitat patrimonial a les autoritats i personal al servei de les administracions públiques:", "No posa fi a la via administrativa.", "Posa fi a la via administrativa.", "Posa o no fi a la via administrativa en funció de l’òrgan que la dicta.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 53, "Segons l’article 64.2. c) de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, l’acord d’iniciació dels procediments de naturalesa sancionadora ha de contenir:", "Identificació de l’instructor i, si s’escau, del secretari del procediment, amb indicació expressa del règim de recusació d’aquests dos.", "Identificació de l’instructor i, si s’escau, del secretari del procediment.", "Identificació de l’instructor i del secretari del procediment, amb indicació expressa del règim de recusació d’aquests.", "Identificació de l’instructor, amb indicació expressa del règim de recusació d’aquest."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 54, "Indicau quina de les afirmacions següents és correcta segons l’article 65.1 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, relatiu a l’inici d’ofici dels procediments de responsabilitat patrimonial:", "El procediment iniciat s’ha d’arxivar si els particulars presumptament lesionats no s’hi personen en el termini establert.", "El termini d’al·legacions no ha de ser inferior a deu dies.", "Per iniciar el procediment és necessari que no hagi prescrit el dret a la reclamació de l’interessat a què es refereix l’article 67.", "L’acord d’iniciació s’ha de notificar a l’instructor i al secretari del procediment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 55, "Segons l’article 65.2 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, el termini per presentar al·legacions en els procediments de responsabilitat patrimonial és de:", "Cinc dies.", "Deu dies.", "Quinze dies.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 56, "Segons l’article 67.1 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, els interessats només poden sol·licitar l’inici d’un procediment de responsabilitat patrimonial:", "Quan no hagi prescrit el seu dret a reclamar.", "Quan no hagi caducat el seu dret a reclamar.", "Quan no hagi prescrit o caducat el seu dret a reclamar.", "Quan hagi prescrit o caducat el seu dret a reclamar."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 57, "Segons l’article 67.1 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, en cas de danys de caràcter físic o psíquic a les persones, el termini per reclamar responsabilitat patrimonial comença a computar:", "Des de la cura o la determinació de l’abast de les seqüeles.", "Des de la data de producció dels danys.", "Des que es manifesti l’efecte lesiu.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 58, "Segons l’article 67.1 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, en els casos en què és procedent reconèixer el dret a indemnització per anul·lació en via administrativa o contenciosa administrativa d’un acte o disposició de caràcter general, el dret a reclamar:", "Caduca al cap d’un any que s’hagi notificat la resolució administrativa o la sentència definitiva.", "Prescriu al cap d’un any que s’hagi dictat la resolució administrativa o la sentència definitiva.", "Caduca al cap d’un any que s’hagi dictat la resolució administrativa o la sentència definitiva.", "Prescriu al cap d’un any que s’hagi notificat la resolució administrativa o la sentència definitiva."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 59, "Segons l’article 67.1 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, quin és el termini de prescripció del dret per reclamar responsabilitat patrimonial?", "Un mes.", "Sis mesos.", "Un any.", "Tres anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 60, "Segons l’article 67.2 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, les sol·licituds de responsabilitat patrimonial han d’especificar:", "Les lesions produïdes.", "La presumpta relació de causalitat entre les lesions i el funcionament del servei públic.", "El moment en què la lesió efectivament es va produir.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 61, "Segons l’article 81.2 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, el termini per emetre el dictamen del Consell d’Estat en els procediments de responsabilitat patrimonial:", "No pot ser inferior a dos mesos.", "És de dos meses.", "És d’un mes.", "No pot ser inferior a un mes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 62, "Segons l’article 81.2 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, en quins casos és preceptiu sol·licitar un dictamen del Consell d’Estat o, si s’escau, de l’òrgan consultiu de la comunitat autònoma en els procediments de responsabilitat patrimonial?", "Quan les indemnitzacions reclamades siguin d’una quantia igual o superior a 50.000 euros o a la que estableixi la legislació autonòmica corresponent.", "En aquells casos que disposi la Llei orgànica 3/1980, de 22 d’abril, del Consell d’Estat.", "Quan les indemnitzacions reclamades siguin d’una quantia igual o superior a 30.000 euros o a la que estableixi la legislació autonòmica corresponent.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 63, "Segons l’article 81.2 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, en els procediments de responsabilitat patrimonial l’òrgan instructor ha de remetre a l’òrgan competent per sol·licitar el dictamen una proposta de resolució:", "En el termini de deu dies comptador des de la finalització del tràmit d’audiència.", "En un termini no superior a deu dies.", "En el termini de deu dies comptador des de l’emissió de la proposta de resolució.", "En un termini no inferior a deu dies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 64, "Segons l’article 81.2 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, ¿sobre quin dels aspectes següents s’ha de pronunciar el dictamen del Consell d’Estat emès en els procediments de responsabilitat patrimonial?", "La continuïtat o persistència en la conducta infractora.", "La valoració del dany causat i la quantia i mode de la indemnització.", "El grau de culpabilitat o l’existència d’intencionalitat.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 65, "Segons l’article 81.3 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, en els procediments de responsabilitat patrimonial de l’Estat pel funcionament anormal de l’Administració de justícia, el termini per dictar resolució:", "Pot quedar suspès pel temps que transcorri entre la sol·licitud de l’informe del Consell General del Poder Judicial i la seva recepció.", "Queda suspès pel temps que transcorri entre la sol·licitud de l’informe del Consell General del Poder Judicial i la seva recepció.", "Pot quedar suspès pel temps que transcorri entre la sol·licitud de l’informe del Consell d’Estat i la seva recepció.", "Queda suspès pel temps que transcorri entre la sol·licitud de l’informe del Consell d’Estat i la seva recepció."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 66, "Segons l’article 81.3 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, en el cas de reclamacions en matèria de responsabilitat patrimonial de l’Estat pel funcionament anormal de l’Administració de justícia, l’informe del Consell General del Poder Judicial s’ha d’emetre:", "En el termini màxim de dos mesos.", "En un termini no inferior a dos mesos.", "En el termini màxim d’un mes.", "En un termini no inferior a un mes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 67, "Segons l’article 85.3 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, les reduccions de l’import de la sanció per reconeixement de la responsabilitat i per pagament voluntari anterior a la resolució:", "Són acumulables entre sí.", "Són acumulables entre sí quan l’interessat desisteixi d’exercir qualsevol recurs en via administrativa o judicial contra la sanció.", "No són acumulables entre sí.", "Són acumulables entre sí quan l’interessat desisteixi d’exercir qualsevol recurs en via judicial contra la sanció."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 68, "Segons l’article 85.3 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, és possible modificar els percentatges de reducció de la sanció prevists en aquesta Llei?", "No, atès que la Llei té caràcter bàsic.", "Sí, es poden incrementar reglamentàriament.", "Sí, però únicament es poden incrementar mitjançant una llei específica.", "No, atès que la Llei ho prohibeix expressament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 69, "Segons l’article 90.2 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, relatiu a les especialitats de la resolució en els procediments sancionadors:", "En la resolució es poden acceptar fets diferents dels determinats en el curs del procediment, amb un tràmit d’audiència als interessats no inferior a set dies.", "En la resolució es poden acceptar fets diferents dels determinats en el curs del procediment.", "En la resolució no es poden acceptar fets diferents dels determinats en el curs del procediment.", "En la resolució es poden acceptar fets diferents dels determinats en el curs del procediment, amb un tràmit d’audiència als interessats no inferior a deu dies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 70, "Segons l’article 90.3 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, es pot suspendre l’execució de la sanció si l’interessat manifesta a l’Administració la seva intenció d’interposar:", "Un recurs contenciós administratiu contra la resolució ferma en via administrativa.", "Un recurs administratiu contra la sanció definitiva.", "Un recurs administratiu contra la sanció ferma en via administrativa.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 71, "Segons l’article 90.4 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, la resolució del procediment complementari per fixar la quantia dels danys o perjudicis causats a l’Administració:", "No posa fi a la via administrativa.", "No posa fi a la via administrativa, llevat que per llei específica es disposi una altra cosa.", "Posa fi a la via administrativa.", "Posa fi a la via administrativa, llevat que per llei específica es disposi una altra cosa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 72, "Segons l’article 91.1 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, relatiu a la resolució dels procediments de responsabilitat patrimonial, quan s’ha de sotmetre la proposta d’acord per a la seva formalització per part de l’interessat i de l’òrgan administratiu competent per subscriure’l?", "Una vegada finalitzat el tràmit d’audiència.", "Una vegada rebut, si s’escau, el dictamen a què es refereix l’article 81.2 o, quan aquest no sigui preceptiu, una vegada finalitzat el tràmit d’audiència.", "Una vegada notificada la proposta de resolució.", "Una vegada iniciat el tràmit d’audiència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 73, "Segons l’article 91.2 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, en els procediments de responsabilitat patrimonial és necessari que la resolució es pronunciï sobre:", "La quantia i el mode de la indemnització, quan escaigui.", "L’existència o no de la relació de causalitat entre el funcionament del servei públic i la lesió produïda.", "La continuïtat o persistència en la conducta infractora.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 74, "Segons l’article 91.3 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, quin és el termini per resoldre els procediments de responsabilitat patrimonial?", "Un mes.", "Tres mesos.", "Sis mesos.", "Un any."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 75, "Segons l’article 91.3 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, transcorreguts sis mesos des que es va iniciar el procediment de responsabilitat patrimonial i no s’ha dictat i s’ha notificat una resolució expressa o, si s’escau, s’ha formalitzat l’acord:", "Es produeix la prescripció del procediment.", "Es pot entendre que la resolució és favorable a la indemnització del particular.", "El procediment queda arxivat.", "Es pot entendre que la resolució és contrària a la indemnització del particular."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 1, "La Constitució espanyola de 1978 garanteix el dret a l’autonomia de les nacionalitats i regions que integren la Nació espanyola en:", "L’article 148.", "L’article 2.", "L’article 146.", "L’article 12."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 2, "D’acord amb la Constitució espanyola, poden accedir a l’autogovern i constituir-se en comunitat autònoma:", "Les províncies limítrofes amb característiques històriques, culturals i econòmiques comunes, els territoris insulars i les províncies amb entitat regional històrica.", "Les províncies amb característiques històriques comunes, els territoris insulars i les províncies amb entitat regional històrica, cultural o econòmica.", "Les províncies limítrofes amb característiques històriques, culturals o econòmiques comunes, els territoris insulars i les províncies amb entitat cultural històrica.", "Les províncies, els territoris insulars i les províncies amb característiques històriques, culturals i econòmiques comunes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 3, "En quin títol de la Constitució es regula l’accés a l’autonomia de les províncies i regions d’Espanya i la distribució competencial entre l’Estat i les comunitats autònomes?", "En el títol VII.", "En el títol VI.", "En el títol VIII.", "En el títol III."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 4, "L’organització institucional de les comunitats autònomes constituïdes d’acord amb l’article 152 de la Constitució es basa en:", "Un parlament, un consell de govern, un president i un tribunal de justícia.", "Una assemblea legislativa, un consell de govern presidit per un president i un tribunal superior de justícia.", "Una assemblea legislativa, un consell de govern i un president.", "Un parlament, un consell de Govern i un president."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 5, "La Constitució espanyola de 1978, respecte de les comunitats autònomes, prohibeix:", "El desplegament de competències atribuïdes a l’Estat.", "La federació entre comunitats autònomes.", "La regulació de les institucions pròpies.", "Els convenis entre comunitats autònomes per a la gestió i la prestació de serveis propis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 6, "Pel que fa als convenis entre comunitats autònomes, la Constitució estableix:", "Que és imprescindible l’autorització de les Corts Generals quan es tracti de convenis per a la gestió i prestació de serveis propis de les comunitats que duen a terme el conveni.", "Que només es comuniquen al Congrés dels Diputats si es tracta de convenis distints dels de gestió i prestació de serveis propis.", "Que els ha d’autoritzar el Congrés dels Diputats amb independència de l’objecte del conveni.", "Que s’han de comunicar a les Corts Generals quan  es tracti de convenis per a la gestió i prestació de serveis propis de les comunitats que duen a terme el conveni."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 7, "La delimitació del territori de les comunitats autònomes es regula:", "En la Constitució espanyola de 1978.", "En una llei aprovada pel Senat.", "En una llei aprovada per l’assemblea legislativa corresponent.", "En l’Estatut d’autonomia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 8, "La Constitució espanyola defineix els estatuts d’autonomia:", "Com la norma fundacional bàsica de cada comunitat autònoma.", "Com la norma orgànica bàsica de cada comunitat autònoma.", "Com la norma institucional bàsica de cada comunitat autònoma.", "Com la norma institucional bàsica de les regions i nacionalitats que han accedit a l’autonomia per la via de l’article 151 de la Constitució."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 9, "D’acord amb la Constitució espanyola de 1978, les competències que assumeix cada comunitat autònoma s’estableixen:", "En les lleis de transferències de competències.", "En les lleis de traspàs de competències.", "En els estatuts d’autonomia.", "En la Constitució espanyola."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 10, "La distribució de competències entre l’Estat i les comunitats autònomes s’estableix:", "En els articles 149 i 150 de la Constitució espanyola, respectivament.", "En els articles 148 i 149 de la Constitució espanyola, respectivament.", "En els articles 149 i 148 de la Constitució espanyola, respectivament.", "En els articles 150 i 149 de la Constitució espanyola, respectivament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 11, "D’acord amb el sistema de distribució competencial entre l’Estat i les comunitats autònomes, podem distingir les matèries següents:", "Matèries que corresponen exclusivament a l’Estat; matèries en què l’Estat legisla i les comunitats autònomes executen aquesta legislació;  i matèries que corresponen exclusivament a les comunitats autònomes.", "Matèries que corresponen exclusivament a l’Estat; matèries en què l’Estat legisla i les comunitats autònomes executen aquesta legislació; matèries en què l’Estat aprova la legislació bàsica, mentre que el desenvolupament legislatiu i l’execució correspon a les comunitats autònomes, i matèries que corresponen exclusivament a les comunitats autònomes.", "Hi ha matèries en què l’Estat i les comunitats autònomes tenen indistintament competències legislatives i executives.", "Les respostes b) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 12, "S’entén que una competència és concurrent:", "Quan l’Estat ostenta la facultat de dictar les bases sobre una matèria i la comunitat autònoma pot assumir la legislació de desenvolupament.", "Quan l’Estat i la comunitat autònoma tenen la possibilitat de concórrer amb idèntiques facultats en la regulació d’una matèria.", "Quan l’Estat ostenta totes les facultats sobre una matèria, excepte la d’execució, que correspon a les comunitats autònomes.", "Quan els estatuts d’autonomia els atribueix aquest caràcter."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 13, "Respecte de les competències exclusives de l’Estat que estableix l’article 149:", "Les comunitats autònomes no poden ostentar cap facultat.", "Les comunitats autònomes poden dictar normes legislatives, per a si mateixes, en el marc dels principis, bases i directrius fixades per una llei estatal, sempre que les Corts Generals els atribueixin aquesta facultat.", "Les comunitats autònomes tenen competències de desplegament normatiu, si la competència estatal exclusiva és sobre les bases.", "Els estatuts d’autonomia poden assumir-ne algunes en virtut del principi dispositiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 14, "Pel que fa al sistema de distribució de competències entre l’Estat i les comunitats autònomes trobam:", "Les competències exclusives de l’Estat, d’acord amb l’article 148 de la Constitució.", "Les competències que poden ser assumides per les comunitats autònomes, segons l’article 149 de la Constitució.", "La resta de competències, de les quals la facultat o la matèria no s’esmenta expressament com a exclusiva de l’Estat, que poden ser assumides per les comunitats autònomes, segons l’apartat 3 de l’article 149 de la Constitució.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 15, "Digues quina de les competències següents és concurrent entre l’Estat i les comunitats autònomes:", "Defensa.", "Medi ambient.", "Cultura.", "Legislació sobre productes farmacèutics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 16, "En els Estatuts aprovats pel procediment de l'article 151, l'organització institucional autonòmica es basa, entre d’altres, en una assemblea legislativa elegida per sufragi:", "Universal, conformement a un sistema de representació proporcional que asseguri, a més, la representació de les diverses zones del territori.", "Universal, conformement a un sistema de representació proporcional que asseguri, a més, la representació de les diverses cultures del territori.", "Proporcional, conformement a un sistema de representació universal que asseguri, a més, la representació de les diverses zones del territori.", "Cap de les respostes anteriors és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 17, "Per què una comunitat autònoma pot tenir competència exclusiva en matèries que no estan incloses en la llista de l’article 148 de la Constitució espanyola?", "Les comunitats autònomes no poden tenir competència exclusiva en matèries que no estan incloses en l’article 148.", "Perquè el sistema de distribució de competències en la Constitució no és un sistema tancat, per la qual cosa les comunitats autònomes poden assumir competències en aquelles matèries no atribuïdes a l’Estat.", "Perquè la Constitució preveu que el Senat, per majoria absoluta, pugui atribuir a les comunitats autònomes competències no incloses en l’article 148.", "Perquè la Constitució preveu que el Congrés dels Diputats, en matèries de competència estatal, atribueixi a les Comunitats Autònomes la facultat de dictar, per a si mateixes, normes legislatives dins del marc dels principis, les bases i les directrius fixats per una llei estatal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 18, "Son competències compartides:", "Aquelles en què les facultats d’Estat i comunitats autònomes són coincidents.", "Aquelles en què els estatuts d’autonomia els atribueixi aquest caràcter.", "Aquelles en què la Constitució atribueix a l’Estat la funció legislativa i a les comunitats autònomes únicament la funció executiva.", "Aquelles en què determinades facultats corresponen a l’Estat i d’altres corresponen a les comunitats autònomes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 19, "Segons la doctrina, una competència és exclusiva:", "Quan un ens aglutina totes les facultats possibles sobre una matèria determinada.", "Quan un ens s’atribueix amb exclusivitat una facultat sobre una matèria.", "Quan un ens conserva totes les facultats de la mateixa qualitat sobre una matèria.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 20, "La tinença i l’ús d’armes i explosius:", "És competència exclusiva de les comunitats autònomes pel que fa al seu territori.", "Es tracta d’una competència compartida entre l’Estat i les comunitats autònomes.", "És competència de l’Administració local.", "És competència exclusiva de l’Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 21, "Quina d’aquestes competències és exclusiva de l’Estat:", "L’assistència social.", "La determinació de les fonts del dret, amb respecte a les normes de dret foral o especial.", "La determinació de les fonts del dret, excepte les normes autonòmiques, cas en el qual la competència correspon a la comunitat autònoma.", "Els ports i aeroports esportius."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 22, "Quina de les següents competències correspon a l'Estat, segons la Constitució espanyola?", "Les alteracions dels termes municipals compresos en el territori de les comunitats autònomes.", "El foment i la coordinació general de la recerca científica i tècnica.", "L’ordenació del territori, l’urbanisme i l’habitatge.", "L'agricultura i la ramaderia, d'acord amb l'ordenació general de l'economia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 23, "Quina de les següents competències poden assumir les comunitats autònomes:", "Les bases i la coordinació de la planificació general de l'activitat econòmica.", "La il·luminació de costes i senyals marítims.", "Les obres públiques d'interès general.", "Els aprofitaments forestals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 24, "És possible que les comunitats autònomes legislin sobre les relacions laborals de treballadors i empresaris radicats en el territori respectiu?", "Sí, perquè es tracta d’una competència compartida entre l’Estat i les comunitats autònomes.", "Sí, perquè les comunitats autònomes tenen competències de desenvolupament en matèria laboral.", "No, es tracta d’una competència exclusiva de l’Estat; les comunitats autònomes només tenen competències d’execució.", "No, llevat que ho hagin assumit en els estatuts d’autonomia corresponents."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 25, "A qui correspon la competència en matèria de legislació processal?", "A l'Estat, com a competència exclusiva, inclosa l’execució en el territori de les comunitats autònomes.", "A l'Estat, com a competència exclusiva.", "A les comunitats autònomes en cas d'haver-se recollit en els respectius estatuts d'autonomia.", "A les comunitats autònomes pel que fa a la normativa de desenvolupament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 26, "Mitjançant quin instrument de l’Estat pot una comunitat autònoma  assumir competències en matèria de justícia?", "Mitjançant una llei marc.", "Mitjançant una llei ordinària.", "Mitjançant una llei d’harmonització.", "Mitjançant una llei orgànica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 27, "En el cas que una comunitat autònoma no compleixi les obligacions que la Constitució o altres lleis li imposen, o bé actuï de forma que atempti greument contra l’interès general d’Espanya:", "El Govern, amb un requeriment previ al president de la comunitat autònoma, pot adoptar les mesures necessàries per obligar-la al compliment forçós de dites obligacions o per a la protecció de l’interès general esmentat.", "El Govern, amb un requeriment previ al president de l’assemblea legislativa de la comunitat autònoma, amb la majoria absoluta del Senat, pot adoptar les mesures necessàries per obligar la comunitat autònoma al compliment de les dites obligacions o per a la protecció de l’interès general esmentat.", "El Govern, amb un requeriment previ al president de la comunitat autònoma i, en el cas de no ser atès, amb l’aprovació per majoria absoluta del Senat, pot adoptar les mesures necessàries per obligar-la al compliment forçós de dites obligacions o per a la protecció de l’esmentat interès general.", "El Govern, amb un requeriment previ al president de la comunitat autònoma i, en el cas de no ser atès, amb l’aprovació per majoria absoluta del Congrés dels Diputats, pot adoptar les mesures necessàries per obligar-la al compliment forçós de dites obligacions o per a la protecció de l’esmentat interès general."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 28, "Senyalau la resposta correcta:", "Les comunitats autònomes poden convocar referèndums en el seu territori.", "Les comunitats autònomes poden convocar referèndums sempre que la consulta no afecti les institucions d’autogovern.", "La competència per autoritzar convocatòries de consultes populars per via d’un referèndum correspon sempre a l’Estat.", "La Constitució no preveu aquesta competència en el títol VIII."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 29, "D’acord amb l’article 155 de la Constitució, quan el Govern adopti les mesures que correspongui:", "Pot donar instruccions exclusivament a l’administració de la comunitat autònoma afectada.", "Pot donar instruccions exclusivament al personal de la Delegació del Govern a la comunitat autònoma afectada.", "Només pot donar instruccions al govern de la comunitat autònoma afectada.", "Pot donar instruccions a totes les autoritats de la comunitat autònoma afectada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 30, "La finalitat del Fons de Compensació que preveu el títol VIII de la Constitució és:", "Garantir un nivell mínim en la prestació de serveis públics.", "Compensar serveis estatals assumits per les comunitats autònomes.", "Corregir desequilibris econòmics interterritorials i fer efectiu el principi de solidaritat.", "Cap de les respostes és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 31, "Quina llei regula el Fons de Compensació que preveu l’article 158 de la Constitució?", "La Llei 22/2003, de 26 de desembre, reguladora dels Fons de Compensació Interterritorial.", "La Llei 21/2004, de 27 de desembre, reguladora dels Fons de Compensació Constitucional.", "La Llei 22/2001, de 27 de desembre, reguladora dels Fons de Compensació Interterritorial.", "No hi ha cap llei que reguli el Fons de Compensació previst en la Constitució."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 32, "L'article 147 de la Constitució indica que els estatuts d'autonomia hauran de contenir:", "La denominació de la comunitat que acordin les entitats que hagin iniciat el procediment d'autonomia.", "La denominació de la comunitat que millor correspongui a la seva identitat històrica.", "La denominació, organització i seu de les institucions estatals en el seu territori.", "Les competències assumides i assumibles dins del marc establert en la Constitució."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 33, "Indicau quina de les respostes següents no forma part del contingut que l’article 147 de la Constitució estableix per als estatuts d’autonomia?", "Les competències assumides dins del marc que estableix la Constitució.", "Les competències assumides per l'Estat dins del marc que estableix la Constitució.", "Les bases per al traspàs dels serveis corresponents a aquestes competències.", "La delimitació del territori de la comunitat autònoma."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 34, "D'acord amb la Constitució espanyola, els recursos de les comunitats autònomes estan constituïts:", "Pels seus propis impostos, taxes i contribucions especials.", "Per les transferències d'un fons de compensació interterritorial i altres assignacions amb càrrec als Pressupostos Generals de l'Estat.", "El producte de les operacions de crèdit.", "Totes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 35, "Amb la finalitat de corregir desequilibris econòmics interterritorials i fer efectiu el principi de solidaritat, la Constitució preveu un Fons de Compensació amb destinació a despeses d'inversió, els recursos del qual seran distribuïts:", "Per les Corts Generals entre les comunitats autònomes i províncies, en el seu cas.", "Pel Govern entre les comunitats autònomes.", "Pel Govern entre les comunitats autònomes i províncies, en el seu cas.", "Per les Corts Generals entre les comunitats autònomes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 36, "D’acord amb la Constitució, l'Estat pot dictar lleis que estableixin els principis necessaris per a harmonitzar les disposicions normatives de les comunitats autònomes:", "En matèries atribuïdes a la competència de l'Estat, quan així ho exigeixi l'interès general.", "Fins i tot en el cas de matèries atribuïdes a la competència de les comunitats autònomes, quan així ho exigeixi l'interès general.", "En matèries atribuïdes a la competència de l'Estat, quan així ho exigeixi la seguretat de l'Estat.", "Fins i tot en el cas de matèries atribuïdes a la competència de les comunitats autònomes, quan així ho exigeixi la seguretat de l'Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 37, "L’article 150 de la Constitució disposa que l’Estat pot dictar lleis que estableixin els principis necessaris per harmonitzar les disposicions normatives de les comunitats autònomes quan així ho exigeixi l’interès general. A qui correspon apreciar aquesta necessitat?", "Al Congrés dels Diputats, per majoria absoluta.", "A les Corts Generals, per majoria absoluta de cada Cambra.", "A les Corts Generals, per majoria de dos terços dels membres de cada Cambra.", "Al Congrés dels Diputats, per majoria de dos terços dels seus membres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 38, "Senyalau la resposta incorrecta:", "Les diferències entre els estatuts de les diferents comunitats autònomes no poden implicar privilegis econòmics o socials.", "Tots els espanyols tenen els mateixos drets i obligacions en qualsevol part del territori de l'Estat.", "Cap autoritat, excepte el Govern de la nació, pot adoptar mesures que directament o indirectament obstaculitzin la llibertat de circulació i l’establiment de les persones i la lliure circulació de béns en tot el territori espanyol.", "Els municipis gaudeixen d'autonomia per gestionar els seus respectius interessos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 39, "D’acord amb la Constitució espanyola, qui pot adoptar mesures que obstaculitzin la llibertat de circulació i d’establiment de les persones i la lliure circulació de béns en tot el territori nacional?", "Les Corts Generals, en qualsevol cas.", "El Govern, mitjançant la corresponent delegació legislativa.", "Cap autoritat pot adoptar mesures que directament o indirectament ho obstaculitzin.", "Les assemblees legislatives o òrgans col·legiats superiors de les diferents comunitats autònomes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 40, "Quina de les següents competències correspon a l'Estat, segons la Constitució espanyola?", "Les alteracions dels termes municipals compresos en el territori de les comunitats autònomes.", "El foment i la coordinació general de la recerca científica i tècnica.", "L’ordenació del territori, l’urbanisme i l’habitatge.", "L'agricultura i la ramaderia, d'acord amb l'ordenació general de l'economia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 41, "La Constitució atribueix a l’Estat la competència exclusiva sobre contractes. Això implica:", "Que les comunitats autònomes no poden regular la contractació pública que duguin a terme les seves institucions.", "Que les comunitats autònomes hauran de regular mitjançant un reglament aquells aspectes no considerats bàsics per la normativa estatal.", "Que les comunitats autònomes poden regular mitjançant una llei aquells aspectes no considerats bàsics per la normativa estatal.", "Cap de les respostes és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 42, "Quina de les següents competències poden assumir les comunitats autònomes?", "Bases i coordinació de la planificació general de l'activitat econòmica.", "Il·luminació de costes i senyals marítims.", "Obres públiques d'interès general.", "Sanitat i higiene."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 43, "Una de les següents fonts no constitueix un recurs econòmic de les comunitats autònomes:", "Els ingressos de dret privat.", "Els rendiments procedents del seu patrimoni.", "El producte de les operacions borsàries.", "El producte de les operacions de crèdit."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 44, "Indicau quina de les següents competències no és exclusiva de l’Estat:", "La legislació laboral, en totes les seves manifestacions, fins i tot les d'execució.", "Les bases i la coordinació de la planificació general de l'activitat econòmica.", "La defensa i les forces armades.", "La hisenda general i el deute de l'Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 45, "Com denomina la Constitució l'òrgan de govern de la comunitat autònoma?", "Consell col·legiat.", "Consell.", "Consell executiu.", "Consell de govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 46, "D’acord amb la Constitució, els Estatuts poden establir circumscripcions territorials pròpies:", "Mitjançant l'agrupació de municipis encara que no siguin limítrofs.", "Sense personalitat jurídica pròpia.", "Mitjançant l'agrupació de municipis limítrofs.", "En cap cas."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 47, "Segons la Constitució espanyola, les comunitats autònomes no poden en cap cas adoptar mesures tributàries:", "Sobre béns situats a l'interior del seu territori de propietat privada.", "Sobre béns situats fora del seu territori, o que suposin un obstacle per a la lliure circulació de mercaderies i serveis.", "Que suposin un obstacle per a la competència regulada.", "Que impedeixin la creació de multinacionals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 48, "Quines facultats poden assumir les comunitats autònomes en matèria de dret d’asil?", "Cap.", "Legislació de desenvolupament.", "D’execució.", "Cap de les respostes és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 49, "L'organització judicial en l'àmbit de les comunitats autònomes la culminen:", "Les audiències provincials corresponents, sense perjudici de la jurisdicció que correspon al Tribunal Suprem.", "Un Tribunal Superior de Justícia, sense perjudici de la jurisdicció que correspon al Tribunal Suprem.", "Un Tribunal Superior de Justícia, que assumirà en l'àmbit territorial de la Comunitat Autònoma la jurisdicció que sobre aquest mateix tribunal exercia el Tribunal Suprem.", "Per una audiència territorial, sense perjudici de la jurisdicció que correspon al Tribunal Suprem."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 50, "Quina de les matèries següents no poden assumir inicialment les comunitats autònomes?", "L’artesania.", "L’administració de justícia.", "L’ordenament del territori, l’urbanisme i l’habitatge.", "L’organització de les institucions bàsiques d'autogovern de les comunitats autònomes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 51, "Les comunitats autònomes, respecte dels recursos tributaris de l'Estat:", "No poden assumir-ne cap mena de competències.", "Poden actuar com a delegats de l'Estat pel que fa a la recaptació i la gestió, però no la liquidació.", "Poden actuar com a delegats o col·laboradors de l'Estat pel que fa a la recaptació, la gestió i la liquidació.", "Poden actuar com a delegats o col·laboradors de l'Estat exclusivament per a la recaptació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 52, "Per a garantir, entre d’altres, un nivell mínim en la prestació de serveis públics fonamentals en tot el territori espanyol:", "L'Estat i les comunitats autònomes poden establir tributs especials.", "Una llei orgànica establirà el nivell mínim i la forma de finançament per aconseguir-lo.", "Es pot establir una assignació a les comunitats autònomes en els pressuposts generals de l'Estat.", "L'Estat pot assumir directament l'exercici de competències autonòmiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 53, "Quant a l’organització territorial del poder judicial, les comunitats autònomes:", "Poden participar en l'organització de les demarcacions judicials del seu territori al marge del que disposa la Llei orgànica del poder judicial, en aquelles instàncies processals que s'esgotin en l'àmbit territorial de les comunitats autònomes.", "No poden proposar al Govern la fixació dels partits judicials del seu àmbit territorial, d'acord amb la independència del poder judicial.", "No poden participar en l'organització de les demarcacions judicials del seu territori perquè és una competència reservada a l'Estat.", "Poden participar en l'organització de les demarcacions judicials del seu territori, d’acord amb els supòsits i amb les formes que indiquen en els seus estatuts."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 54, "En matèria de propietat intel·lectual i industrial correspon a les comunitats autònomes:", "El desenvolupament legislatiu i l’execució.", "La legislació i l’execució.", "L’execució.", "Les bases."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 55, "Les lleis marc que atribueixen a les comunitats autònomes la facultat de dictar, per a si mateixes, normes legislatives en matèries de competència estatal:", "Estableixen la modalitat de control que els tribunals han d’exercir sobre les normes que dictin les comunitats.", "Estableixen la modalitat de control que les Corts Generals han d’exercir sobre les normes que dictin les comunitats autònomes, sens perjudici de la competència dels tribunals.", "Fixen els principis, les bases i les directrius als quals s’han de sotmetre les normes que dictin les comunitats autònomes.", "Les respostes b) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 56, "Les comunitats autònomes gaudiran d'autonomia financera per al desenvolupament i l’execució de les seves competències d’acord amb els principis de:", "Solidaritat entre totes les comunitats autònomes.", "Progressivitat, repartiment equitatiu de la riquesa i justícia distributiva.", "Coordinació amb les hisendes locals.", "Coordinació amb la hisenda estatal i solidaritat entre tots els espanyols."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 57, "L’harmonització de les disposicions normatives de les comunitats autònomes:", "S'efectuarà només en el cas de matèries atribuïdes a l'Estat que hagin estat transferides o delegades a les comunitats autònomes.", "Aquesta harmonització no afectarà les normes dictades per al desenvolupament de les matèries atribuïdes a la competència de les comunitats autònomes.", "Correspondrà a l'Estat, que dictarà lleis en les quals s'establiran els principis necessaris per a aconseguir aquesta harmonia.", "L'harmonització s'efectuarà quan així ho exigeixi l'interès de la seguretat nacional."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 58, "D’acord amb l’article 149.1.27 de la Constitució, l’Estat té competència exclusiva sobre normes bàsiques del règim de premsa, ràdio i televisió. Això implica:", "Que correspon a l’Estat l’establiment dels criteris generals de regulació d’aquesta matèria, que han de ser comuns a tot l’Estat.", "Un límit dins el qual s’han de moure els òrgans de les comunitats autònomes en l’exercici de les seves competències.", "La possibilitat que l’Estat atribueixi aquesta competència a la comunitat autònoma mitjançant una llei de transferència.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 60, "És possible que l’Estat transfereixi o delegui en les comunitats autònomes funcions corresponents a matèries de titularitat estatal?", "Sí, mitjançant un reial decret llei, l’Estat pot transferir matèries de la seva competència.", "No; si una matèria és competència de l’Estat, aquest n’exerceix totes les funcions.", "No; la Constitució ho prohibeix.", "Sí, però només en aquelles matèries la naturalesa de les quals les faci susceptibles de transferència o delegació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 61, "Què ocorre amb les matèries no atribuïdes expressament a l’Estat per la Constitució espanyola?", "Corresponen en tot cas a les comunitats autònomes.", "Corresponen en tot cas a l’Estat.", "Podran correspondre a les comunitats autònomes en virtut dels estatuts respectius.", "Correspondran a l’Estat o a les comunitats autònomes segons que la matèria tengui interès general o no."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 62, "A qui correspon la competència sobre les matèries que no hagin assumit els estatuts d’autonomia?", "Correspon a l'Estat o a les comunitats autònomes segons si la matèria té interès general o no.", "Correspon a l'Estat.", "Correspon a les comunitats autònomes en cas de tractar-se de matèries d'àmbit autonòmic.", "Cap de les respostes anteriors és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 63, "La clàusula residual que estableix l’article 149.3 de la Constitució:", "Opera a favor de les comunitats autònomes només en el cas que l’Estat no assumeixi expressament les competències.", "Opera a favor de l’Estat només en el cas de que les comunitats autònomes no assumeixin expressament les competències.", "Atribueix a les comunitats autònomes les funcions legislatives i executives.", "Atribueix a l’Estat únicament la funció legislativa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 64, "En cas de conflicte entre les normes estatals i les de les comunitats autònomes, l’article 149.3 de la Constitució estableix que:", "Les normes estatals prevalen sobre les de les comunitats autònomes.", "Les normes estatals prevalen sobre les de les comunitats autònomes sempre que no es tracti de competències atribuïdes en exclusiva a les comunitats autònomes.", "És una manifestació de la supremacia del dret estatal sobre l’autonòmic.", "S’ha d’atendre al sistema competencial."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 65, "La clàusula de supletorietat que estableix l’article 149.3 de la Constitució disposa expressament que:", "En qualsevol cas, el dret estatal serà supletori del dret de les comunitats autònomes.", "El dret estatal serà supletori del dret de les comunitats autònomes només en les matèries que aquestes no hagin regulat.", "Les respostes a) i b) són correctes.", "Cap de les respostes és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 66, "El principi de prevalença que estableix l’article 149.3 de la Constitució espanyola:", "No atribueix superioritat natural del dret estatal sobre el de les comunitats autònomes.", "No suposa que, en tots els conflictes entre una norma estatal i una norma autonòmica s’hagi d’aplicar sempre el dret estatal per ser prevalent.", "Opera juntament al principi de competència tot respectant-lo.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 67, "Pot una comunitat autònoma atribuir-se funcions legislatives sobre les institucions de crèdit cooperatiu públic i territorial:", "No, perquè es tracta d’una competència exclusiva de l’Estat, d’acord amb l’article 149 de la Constitució.", "No, només pot tenir competències d’execució.", "Sí, perquè l’exclusivitat de l’Estat només està referida a les bases de l’ordenació del crèdit.", "Sí; és una matèria sobre la qual la Constitució no atribueix cap competència a l’Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 69, "L’Estat i les comunitats autònomes poden compartir funcions legislatives sobre una determinada matèria de la competència exclusiva de l’Estat?", "No, es tracta d’una competència exclusiva; si la té l’Estat, ja no poden tenir-la les comunitats autònomes.", "Sí, quan les comunitats autònomes tenen competències de desenvolupament en el marc de la legislació bàsica de l’Estat.", "No, quan l’Estat té la competència legislativa, les comunitats autònomes només poden tenir la potestat reglamentària.", "No, aquesta possibilitat resultaria contradictòria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 70, "En el cas que una comunitat autònoma no hagi assumit com a pròpia la competència sobre una de les matèries que preveu l’article 148 de la Constitució:", "L’assumpció de les competències de l’article 148 per part de les comunitats autònomes és obligatòria.", "No té competència sobre la matèria de què es tracti, atès que regeix el principi dispositiu.", "La competència correspondrà a l’Estat.", "Les respostes b) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 71, "Indicau quina de les respostes és la correcta amb relació a la clàusula de supletorietat:", "La clàusula de supletorietat permet a l’Estat dictar normes sobre matèries competència de les comunitats autònomes a l’efecte de ser aplicades per aquelles comunitats que no hagin regulat la matèria de la seva competència o estiguin pendents de regular-la.", "La supletorietat només és predicable de les normes dictades per l’Estat en matèries de la seva competència.", "La supletorietat permet al legislador estatal, en matèries en les quals té atribuïdes competències sobre allò bàsic, elaborar ex profeso una regulació sobre el desenvolupament que, si s’escau, pugui completar supletòriament les llacunes provocades per una inactivitat autonòmica en l’exercici d’aquestes competències.", "Cap de les respostes és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 72, "L’Estat pot transferir o delegar en les comunitats autònomes, mitjançant una llei orgànica, facultats corresponents a matèries de titularitat estatal que per la seva pròpia naturalesa siguin susceptibles de transferència o delegació. En aquest cas:", "La llei preveurà en cada cas la corresponent transferència de mitjans financers i de personal, així com les formes de control que reservi als tribunals.", "La llei preveurà en cada cas la corresponent transferència de mitjans financers, així com les formes de control que es reservi l'Estat.", "L'Estat no podrà reservar-se mesures de control, i haurà de preveure en cada cas la corresponent transferència de mitjans financers i de personal.", "L'Estat haurà de dictar les lleis que estableixin els principis necessaris per harmonitzar les disposicions normatives de les comunitats autònomes amb les estatals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 73, "Indicau la resposta incorrecta:", "Les comunitats autònomes tenen funcions legislatives en aquelles matèries en què l’article 149 de la Constitució atribueix la competència exclusiva a l’Estat.", "Les comunitats autònomes tenen funcions legislatives si la competència exclusiva de l’Estat és sobre les bases d’una matèria determinada.", "Les comunitats autònomes no poden dictar lleis orgàniques.", "La competència exclusiva de l’Estat sobre el procediment administratiu comú  permet a les comunitats autònomes legislar sobre les especialitats derivades de l’organització pròpia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 74, "Senyalau la resposta incorrecta. El control de l’activitat dels òrgans de les comunitats autònomes l’exerceix:", "El Tribunal Constitucional.", "El Govern de la nació.", "La jurisdicció contenciosa administrativa.", "Les Corts Generals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 75, "Quin òrgan és el competent per conèixer els conflictes de competències entre l’Estat i les comunitats autònomes:", "El Tribunal Suprem.", "El Consell d’Estat.", "El Tribunal Constitucional,", "La Comissió Constitucional."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 1, "El Decret 12/2014, de 28 de febrer, de la Comunitat Autònoma de les Illes Balears (modificat pel Decret 12/2017 de 31 de març), va crear:", "La Comissió Tècnica de Seguiment del Pla d’Igualtat i la Comissió d’Igualtat.", "La Comissió Tècnica d’Avaluació del Pla d’Igualtat i la Comissió d’Igualtat.", "La Comissió de Seguiment de les Polítiques d’Igualtat.", "La Comissió d’Avaluació de les Polítiques d’Igualtat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 2, "De conformitat amb l’article 3 de la Llei orgànica 3/2007, de 22 de març, per a la igualtat efectiva de dones i homes:", "El principi d’igualtat de tracte entre dones i homes suposa l’absència de tota discriminació, directa o indirecta, per raó de sexe.", "El principi d’igualtat de tracte entre dones i homes suposa un tracte no igualitari i no discriminatori entre dones i homes.", "El principi d’igualtat de tracte entre dones i homes suposa un retrocés en la convivència en la nostra societat.", "El principi d’igualtat de tracte entre dones i homes suposa un repte important per la nostra societat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 3, "Indicau la resposta correcta en relació amb les accions positives que estableix la Llei Orgànica 3/2007, de 22 de març, per a la igualtat efectiva de dones i homes:", "Els poders públics adoptaran mesures específiques en favor de les dones per corregir situacions paleses de desigualtat de fet respecte dels homes.", "Les mesures han de ser aplicables en tant que subsisteixin les situacions de desigualtat.", "Les mesures han de ser raonables i proporcionades en relació amb l’objectiu perseguit en cada cas.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 4, "Indicau la resposta incorrecta en relació amb el foment de la igualtat, que regula l’article 6 de la Llei orgànica 1/2004, de 28 de desembre, de mesures de protecció integral contra la violència de gènere:", "Les administracions educatives vetlaran perquè en tots els materials educatius s’eliminin els estereotips sexistes.", "Les administracions educatives vetlaran perquè tots els materials educatius fomentin l’igual valor d’homes i de dones.", "Les administracions educatives fomentaran l’educació desagregada per sexes.", "Les administracions educatives vetlaran perquè en tots els materials educatius s’eliminin els estereotips discriminatoris."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 5, "Les acreditacions de víctimes de violència de gènere, que regula la Llei Orgànica 1/2004, de 28 de desembre, de mesures de protecció integral contra la violència de gènere:", "Es podran realitzar mitjançant documents sanitaris oficials de comunicació a la Fiscalia o a l’òrgan judicial.", "Es podran realitzar mitjançant declaracions d’altres menors d’edat davant les forces i cossos de seguretat de l’Estat.", "Es podran realitzar mitjançant declaracions de familiars davant les forces i cossos de seguretat de l’Estat.", "Les persones menors d’edat no poden ser víctimes de violència de gènere."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 6, "Dissenyar els procediments bàsics que permeten posar en marxa els sistemes d’acreditació de les situacions de violència de gènere regulats per la Llei Orgànica 1/2004, de 28 de desembre, de mesures de protecció integral contra la violència de gènere, és una competència que correspon:", "Al Govern central.", "A les administracions autonòmiques.", "A les comissions d’igualtat de cada administració autonòmica.", "Al Govern central i a les comunitats autònomes, de comú acord, en el marc de la conferència sectorial d’igualtat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 7, "D’acord amb la Llei orgànica 3/2007, de 22 de març, per a la igualtat efectiva de dones i homes:", "Constitueix discriminació directa per raó de sexe qualsevol tracte desfavorable relacionat amb l’embaràs o la maternitat.", "Constitueix discriminació indirecta per raó de sexe qualsevol tracte desfavorable relacionat amb l’embaràs o la maternitat.", "Constitueix acció directa qualsevol tracte favorable relacionat amb l’embaràs o la maternitat.", "L’embaràs i la maternitat no tenen res a veure amb la discriminació per raó de sexe."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 8, "Segons la Llei 11/2016, de 28 de juliol, d’igualtat de dones i homes:", "Les dones víctimes de violència de gènere seran considerades col·lectius prioritaris en l’accés a habitatges protegits.", "Les dones víctimes de violència de gènere seran considerades col·lectius prioritaris en l’accés a residències públiques per gent gran.", "Les dones víctimes de violència de gènere només tindran prioritat per accedir a residències privades.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 9, "D’acord amb la Llei 11/2016, de 28 de juliol, d’igualtat de dones i homes:", "Les administracions públiques de les Illes Balears han de prendre mesures a fi de fomentar la corresponsabilitat en la vida laboral, la familiar i la personal de les dones i els homes.", "Les administracions públiques de les Illes Balears han de prendre mesures a fi de fomentar la corresponsabilitat en la vida laboral, la familiar i la personal de les dones i els homes, tenint en compte els nous models de família.", "Les administracions públiques han de prendre mesures de conciliació només en casos de famílies nombroses.", "Les administracions públiques han de prendre mesures de conciliació només en casos de famílies monoparentals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 10, "Segons la Llei 11/2016, de 28 de juliol, d’igualtat de dones i homes:", "També es consideren víctimes de violència les persones que convisquin amb la víctima.", "També es consideren víctimes de violència les persones que tenguin parentiu amb la víctima.", "També es consideren víctimes les filles i els fills de la mare víctima de la violència.", "Només es consideren víctimes les dones."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 11, "Segons la Llei 11/2016, de 28 de juliol, d’igualtat de dones i homes, quin és el màxim òrgan de participació de caràcter autonòmic que té la finalitat d’afavorir l’associacionisme i la participació de les dones en els temes que les puguin afectar?", "El Consell de Participació de la Dona Treballadora.", "El Consell de Participació de la Dona.", "L’Observatori de Participació de les Dones.", "La Comissió de Participació de la Dona."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 12, "Indicau la resposta correcta en relació amb el V Pla Estratègic d’Igualtat entre Dones i Homes de les Illes Balears (2021-2023):", "L’Institut Balear de la Dona és l’òrgan encarregat d’elaborar-lo, amb la col·laboració de les conselleries corresponents.", "Hi han de participar els consells insulars i les entitats socials.", "Hi han de participar els agents socials i econòmics i les associacions en defensa dels drets de les dones de les Illes Balears.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 13, "D’acord amb la Llei 11/2016, de 28 de juliol, d’igualtat de dones i homes:", "Les administracions públiques de les Illes Balears han de garantir un ús no sexista del llenguatge.", "Les administracions públiques de les Illes Balears podran garantir un ús no sexista del llenguatge.", "Les administracions públiques de les Illes Balears podran fomentar l’ús del llenguatge sexista.", "Les administracions públiques de les Illes Balears no poden interferir en l’ús del llenguatge sexista."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 14, "Segons la Llei orgànica 3/2007, de 22 de març, per a la igualtat efectiva de dones i homes:", "El principi d’igualtat de tracte i d’oportunitats entre dones i homes informarà l’actuació de tots els poders públics.", "El principi d’igualtat de tracte i d’oportunitats entre dones i homes informarà, amb caràcter transversal, l’actuació de tots els poders públics.", "El principi d’igualtat de tracte i d’oportunitats entre dones i homes no cal que s’integri, de forma activa, en l’adopció i l’execució de disposicions normatives.", "El principi d’igualtat de tracte i d’oportunitats entre dones i homes no està regulat en aquesta normativa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 15, "Indicau la resposta correcta en relació amb la definició de plans d’igualtat de les empreses de conformitat amb la Llei orgànica 3/2007, de 22 de març, per a la igualtat efectiva de dones i homes:", "Són un conjunt ordenat de mesures, adoptades després de realitzar un diagnòstic de situació, amb la intenció d’assolir la igualtat de tracte i d’oportunitats entre dones i homes.", "Són un conjunt ordenat de mesures, adoptades després de realitzar un diagnòstic de situació, amb la intenció d’eliminar la discriminació per raó de sexe.", "Són un conjunt ordenat de mesures amb la intenció de fer una avaluació de les conductes sexistes de les empreses.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 16, "Indicau la resposta correcta en relació amb l’obligatorietat de les empreses de disposar d’un pla d’igualtat segons la normativa en vigor:", "Estan obligades a disposar de plans d’igualtat les empreses de cinquanta o més persones treballadores.", "Estan obligades a disposar de plans d’igualtat les empreses entre cent i cent cinquanta persones treballadores.", "Estan obligades a disposar de plans d’igualtat les empreses de més de cent cinquanta persones treballadores.", "No existeix cap tram relacionat amb el nombre de persones treballadores."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 17, "Senyalau la resposta incorrecta en relació amb els drets de les dones víctimes de violència de gènere, que regula la Llei orgànica 1/2004, de 28 de desembre, de mesures de protecció integral contra la violència de gènere:", "Les dones víctimes de violència de gènere tenen dret a serveis socials d’atenció.", "Les dones víctimes de violència de gènere tenen dret a serveis de suport, d’acollida i de recuperació integral.", "Les dones víctimes de violència de gènere no tenen dret a serveis d’emergència.", "Les dones víctimes de violència de gènere tenen dret a rebre informació plena i assessorament adequat a la seva situació personal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 18, "El Conveni del Consell d’Europa sobre prevenció i lluita contra la violència contra la dona i la violència domèstica:", "Es va signar a Istanbul l’11 de maig de 2011.", "Va ser ratificat per Espanya el març del 2014.", "Encara no està ratificat per Espanya.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 19, "La Carta dels Drets Fonamentals de la Unió Europea:", "Conté un article sobre no-discriminació.", "Conté un article sobre no estigmatització.", "Conté un article sobre bon tracte.", "No conté cap dels articles anteriors."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 20, "La Directiva 2004/113/CE del Consell d’Europa, de 13 de desembre de 2004, per la qual s'aplica el principi d’igualtat de tracte entre homes i dones en l’accés als béns i serveis i al seu subministrament:", "Estableix la distinció entre discriminació directa i discriminació indirecta.", "Estableix la distinció entre discriminació múltiple i ordre de discriminar.", "Estableix la distinció entre assetjament i assetjament sexual.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 21, "Indicau la resposta incorrecta d’acord amb l’Estatut d’autonomia de les Illes Balears, quan estableix que les administracions públiques de les Illes Balears s’han de centrar, primordialment, en els àmbits següents:", "La igualtat de drets de dones i homes en tots els àmbits.", "La protecció social contra la violència, especialment contra la violència de gènere.", "El desenvolupament sostenible del turisme.", "La protecció específica i la tutela social del menor."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 22, "Segons disposa l’Estatut d’autonomia de les Illes Balears en l’article 17 «no-discriminació per raó de sexe»:", "Totes les dones i homes tenen dret al lliure desenvolupament de la seva personalitat i capacitat personal.", "Totes les dones i homes tenen dret a viure amb dignitat, seguretat i autonomia.", "Totes les persones tenen dret a no ser discriminades per raó de la seva orientació sexual.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 23, "Indicau la resposta correcta en relació amb la definició de perspectiva de gènere que estableix la Llei 11/2016, de 28 de juliol, d’igualtat de dones i homes:", "És la presa en consideració de les diferències entre dones i homes en un a?mbit o una activitat per a l'anàlisi, la planificació, el disseny i l'execució de poli?tiques.", "És la presa en consideració de les similituds entre homes i dones per a l’execució de les polítiques.", "És tenir en compte la manera en que? les diverses actuacions, situacions i necessitats afecten els homes.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 24, "Indicau la resposta incorrecta d’acord amb el que la Llei 11/2016, de 28 de juliol, d’igualtat de dones i homes estableix com a violència masclista:", "La violència econòmica, que inclou la privació intencionada, i no justificada legalment, de recursos per al benestar físic o psicolo?gic.", "La violència simbòlica, que inclou les icones, representacions, narratives, imatges, etc., que reprodueixen o transmeten relacions de dominació dels homes respecte de les dones, aixi? com desigualtats de poder entre sexes i de segregació.", "La violència institucional, produïda des dels serveis públics i que revictimitza les víctimes.", "El feminicidi, assassinat de dones pel fet de ser dones, al marge que hi hagi o hi hagi hagut relacio? de parella."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 25, "Senyalau la resposta correcta en relació amb l’informe d’avaluació d’impacte de gènere, regulat per la Llei 11/2016, de 28 de juliol, d’igualtat de dones i homes:", "L’Administració de la Comunitat Autònoma de les Illes Balears ha d’aprovar les directrius en què s’estableixin les pautes que s’han de seguir per dur a terme l’informe d’avaluació d’impacte de gènere.", "L’Administració de la Comunitat Autònoma de les Illes Balears, a proposta de l’Institut Balear de la Dona, ha d’aprovar les directrius en què s’estableixin les pautes que s’han de seguir per dur a terme l’informe d’avaluació d’impacte de gènere.", "La Comissió de Paritat ha d’aprovar les pautes que s’han de seguir per dur a terme l’informe d’avaluació d’impacte de gènere.", "L’Observatori per a l’Equitat ha d’aprovar les directrius que s’han de seguir per dur a terme l’informe d’avaluació d’impacte de gènere."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 26, "L’òrgan col·legiat encarregat de coordinar les poli?tiques i els programes que duen a terme les administracions autonòmica, insular i local en mate?ria d’igualtat de dones i homes, és:", "La Comissió d’Igualtat.", "L’Observatori per a la Igualtat.", "La Comissió per a la Igualtat de Gèneres.", "La Comissió per a la Igualtat de Sexes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 27, "L’Observatori per a la Igualtat, regulat pel Decret 1/2018, de 2 de febrer, té, entre d’altres, les funcions següents:", "Proposar un sistema d’indicadors per prendre coneixement de manera actualitzada de l'evolució de les desigualtats entre homes i dones i la violència masclista, i per fer-ne el seguiment i l’avaluació.", "Analitzar l’evolució i els motius de la persistència de les desigualtats entre sexes i sexualitats i la violència masclista.", "Promoure l’elaboració d’estudis, informes te?cnics i avaluacions comparables.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 28, "Senyalau la resposta incorrecta en relació amb quines són les àrees d’intervenció de l’Observatori per a la Igualtat, regulat pel Decret 1/2018, de 2 de febrer:", "La violència masclista.", "El sostre de vidre en l’accés al mercat de treball.", "La imatge pública de les dones.", "La sexualitat i la salut de les dones."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 29, "Senyalau la resposta correcta en relació amb el Decret de traspàs de competències en matèria de polítiques de gènere i dona:", "És el Decret 26/2004, de 21 de desembre, de traspàs als consells insulars de les funcions i els serveis inherents a les competències pròpies d’aquests consells insulars que actualment exerceix l’Administració de la Comunitat Autònoma de les Illes Balears en matèria de polítiques de gènere i dona.", "És el Decret 46/2018, de 21 de desembre, de traspàs als consells insulars de les funcions i els serveis inherents a les competències pròpies d’aquests consells insulars que actualment exerceix l’Administració de la Comunitat Autònoma de les Illes Balears en matèria de polítiques de gènere i dona.", "És el Decret 46/2018, de 21de desembre, de traspàs als consells insulars de les funcions i els serveis inherents a les competències pròpies d’aquests consells insulars que actualment exerceix l’Administració de la Comunitat Autònoma de les Illes Balears en matèria de polítiques de coresponsabilitat.", "No s’han transferit encara aquestes competències als consells insulars."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 30, "Senyalau quina de les normes d’àmbit estatal següents s’ha aprovat recentment en matèria de no-discriminació:", "La Llei 15/2022, de 12 de juliol, integral per a la igualtat de tracte i la no-discriminació.", "La Llei 15/2022, de 12 de juliol, per a la discriminació i la igualtat de tracte.", "La Llei 16/2022, de 18 de novembre, per combatre la desigualtat de gènere i la no-discriminació.", "La Llei 17/2021, de 20 de desembre, per atendre les desigualtats i les discriminacions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 31, "Indicau la resposta correcta en relació amb la Llei 6/2022, de 31 de març, de modificació del Text refós de la Llei general de drets de les persones amb discapacitat i de la seva inclusió social:", "Introdueix un nou article per establir les condicions bàsiques d’accessibilitat cognitiva, així com per preveure’n el desenvolupament normatiu posterior mitjançant un reglament específic.", "Estableix les condicions bàsiques d’accessibilitat cognitiva sense preveure cap desenvolupament normatiu posterior.", "La modificació no preveu establir cap condició bàsica d’accessibilitat cognitiva.", "La modificació només afecta l’apartat de la inclusió social."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 32, "L’article 14 de la Constitució espanyola proclama el dret a la igualtat i a la no-discriminació per motius de:", "Naixement, raça, sexe, nacionalitat i opinió.", "Naixement raça, sexe, religió i opinió.", "Naixement, raça, sexe, religió, opinió i qualsevol altra circumstància personal o social.", "Lloc d’origen, ètnia, espiritualitat, opinió i qualsevol altra circumstància personal o social."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 33, "Indicau la resposta correcta en relació amb els drets de les funcionàries públiques víctimes de violència de gènere segons el que estableix la Llei orgànica 1/2004, de 28 de desembre, de mesures de protecció integral contra la violència de gènere:", "La funcionària víctima de violència de gènere tindrà dret a la reducció o a la reordenació del seu temps de treball.", "La funcionària víctima de violència de gènere tindrà dret a la mobilitat geogràfica del centre de treball.", "La funcionària víctima de violència de gènere tindrà accés a serveis específics d’atenció.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 34, "L’Estratègia per a la igualtat de les persones Lesbianes, Gais, Bisexuals, Trans, Intersexuals i Queer (LGTBIQ) de la Unió Europea:", "Té previst integrar la lluita contra la discriminació que afecta les persones LGTBIQ en totes les polítiques que es duguin a terme a la Unió Europea.", "Està pensada per al període 2020-2025.", "Està basada, entre altres fonts, en l’informe sobre els drets fonamentals de l’Agència Europea de Drets Fonamentals (FRA) del 2020.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 35, "Indicau la resposta correcta en relació amb l’objecte de la Llei 8/2016, de 30 de maig, per garantir els drets de lesbianes, gais, trans, bisexuals i intersexuals i per erradicar l’LGTBI-fòbia:", "Establir i regular els principis, els mitjans i les mesures per garantir plenament la igualtat real i efectiva en l’exercici dels drets de les persones lesbianes, gais, trans (transsexuals i transgèneres), bisexuals i intersexuals (LGTBI).", "Establir i regular els principis per garantir els drets de les persones no heterosexuals.", "Establir i regular els principis per fomentar els drets de les persones gais i lesbianes.", "Establir i regular els principis per promoure els drets de les persones trans i intersexuals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 36, "Indicau la resposta correcta en relació amb l’avaluació d’impacte sobre orientació sexual i identitat de gènere que estableix la Llei 8/2016, de 30 de maig, per garantir els drets de lesbianes, gais, trans, bisexuals i intersexuals i per erradicar l’LGTBI-fòbia:", "Aquesta avaluació s’ha d’incorporar sobre totes les disposicions legals o reglamentàries que s’impulsin dins del territori de la comunitat autònoma.", "Aquesta avaluació s’ha d’incorporar sobre algunes disposicions legals o reglamentàries concretes que s’impulsin dins del territori de la comunitat autònoma.", "Aquesta avaluació ha de garantir la integració del principi d’igualtat i no-discriminació de les persones LGTBI.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 37, "D’acord amb la Llei 8/2016, de 30 de maig, per garantir els drets de lesbianes, gais, trans, bisexuals i intersexuals i per erradicar l’LGTBI-fòbia i la discriminació per associació és:", "La situacio? en que? una persona o un grup de persones son objecte de discriminació per orientació sexual, identitat de gènere o expressió de gènere com a conseqüència d’una apreciació erro?nia.", "La situació en què una persona és objecte de discriminació per orientació sexual, identitat de gènere o expressió de gènere com a conseqüència de la seva relacio? amb una persona o un grup LGTBI.", "La situació en què una persona activista pels drets de les persones gais és discriminada.", "La situació en què un grup de persones activistes pels drets de les persones lesbianes són discriminades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 38, "Quin Tractat va marcar una fita en la lluita contra la discriminació en la Unió Europea quan va començar a vigir l’1 de maig de 1999?", "El Tractat de Maastricht.", "El Tractat d'Amsterdam.", "El Tractat d’Oslo.", "El Tractat de Milà."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 39, "Quina directiva del Consell d’Europa prohibeix la discriminació per origen racial o ètnic en qualsevol àmbit?", "La Directiva 1998/53/CE, de 18 de maig de 1996.", "La Directiva 2000/43/CE, de 29 de juny de 2000.", "La Directiva 2020/32/CE, de 29 d’abril de 2019.", "No hi ha cap directiva que prohibeixi aquesta discriminació a la Unió Europea."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 40, "En quina Llei es va transposar a Espanya la Directiva del Consell d’Europa que prohibeix la discriminació per origen racial o ètnic?", "Mitjançant la Llei 62/2003, de 30 de desembre, de mesures fiscals, administratives i d’ordre social.", "Mitjançant la Llei 62/2011, de 30 de desembre, de mesures fiscals, administratives i d’ordre social.", "Mitjançant la Llei 17/2014, de 30 de desembre, de mesures fiscals, administratives i d’ordre social.", "Mitjançant la Llei 19/2015, de 30 de desembre, de mesures fiscals, administratives i d’ordre social."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 41, "L’entrada en vigor del Tractat de Lisboa l’1 de desembre de 2009 ha reforçat en la Unió Europea:", "La protecció dels drets fonamentals.", "La protecció dels drets socials.", "La protecció dels drets civils.", "La protecció dels drets a la infància."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 42, "El Consell de la Unió Europea, per unanimitat, i prèvia aprovació del Parlament Europeu, podrà adoptar accions adequades per lluitar:", "Contra la discriminació per motius de gènere, lloc de naixement, nacionalitat o discapacitat.", "Contra la discriminació per motius de sexe, país d’origen, color de pell o capacitat.", "Contra la discriminació per motius de sexe, d’origen racial o ètnic, religió o conviccions, discapacitat, edat o orientació sexual.", "Contra la discriminació per motius de raça, religió, ideologia i condició sexual."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 43, "Indicau la resposta correcta en relació amb el que disposa la Recomanació CM/Rec (2019) del Comitè de Ministres als Estats membre per prevenir i combatre el sexisme, adoptada el 27 de març de 2019:", "Afirma que el sexisme es reforça pels estereotips de gènere que afecten dones i homes, nines i nins, i impedeix la consecució de la igualtat de gènere i l’establiment de societats inclusives.", "Recorda que el sexisme és una manifestació de les relacions de poder històricament desiguals entre dones i homes, que provoca discriminació i que impedeix el ple avenç de les dones en la societat.", "Observa que dones i nines poden ser objecte de discriminació múltiple i interseccional i que poden enfrontar-se a un sexisme combinat amb altres normes o comportaments discriminatoris, d’odi o nocius.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 44, "En quina llei d’àmbit autonòmic està reconegut el dret a la no-discriminació de les persones menors d’edat?", "En la Llei 9/2019, de 19 de febrer, de l’atenció i els drets de la infància i l’adolescència de les Illes Balears.", "En la Llei 9/2019, de 19 de febrer, de protecció a joves menors d’edat de les Illes Balears.", "En la Llei 6/2018, de 18 de març, de no-discriminació d’infants i d’adolescents a les Illes Balears.", "Aquest dret no està reconegut en cap normativa autonòmica en vigor."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 45, "Quina llei d’àmbit autonòmic té per objecte garantir la igualtat d’oportunitats, la", "La Llei 8/2017, de 3 d’agost, per a l’accessibilitat de les persones amb discapacitats de les Illes Balears.", "La Llei 8/2017, de 3 d’agost, d’accessibilitat universal de les Illes Balears.", "La Llei 4/2020, de 8 de maig, per millorar l’accessibilitat de totes les persones de les Illes Balears.", "La Llei 5/2021, de 10 d’abril, de no-discriminació de les persones amb diversitat funcional de les Illes Balears."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 46, "Quina llei d’àmbit autonòmic té un títol de mesures per garantir la igualtat real i efectiva de les persones atenent a la seva identitat i a l’expressió de gènere?", "La Llei 11/2016, de 28 de juliol, d’igualtat de dones i homes.", "La Llei 5/2003, de 4 d’abril, de salut de les Illes Balears.", "La Llei 8/2016, de 30 de maig, per garantir els drets de lesbianes, gais, trans, bisexuals i intersexuals i per erradicar l’LGTBI-fòbia.", "La Llei 8/2018, de 31 de juliol, de suport a les famílies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 47, "De quin ministeri depèn el Pacte d’Estat contra la Violència de Gènere?", "Del Ministeri d’Igualtat.", "Del Ministeri de Treball i Economia Social.", "Del Ministeri de Sanitat.", "Del Ministeri de Justícia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 48, "El Govern, mitjançant la Delegació del Govern per a la Violència de Gènere, desenvolupa el Pacte d’Estat contra la Violència de Gènere impulsant:", "Mesures de coordinació amb la resta de ministeris i organismes autònoms que en depenen.", "Mesures de coordinació amb les comunitats autònomes.", "Mesures de coordinació amb les entitats locals representades per la Federació Espanyola de Municipis i Províncies.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 49, "El Conveni europeu per a la protecció dels drets humans i de les llibertats fonamentals, més conegut com la Convenció europea de drets humans (CEDH), estableix una prohibició general de discriminació, entre d’altres, per raons de sexe en relació amb:", "El gaudi d’alguns dels drets laborals", "El gaudi de tots els drets reconeguts per llei", "El gaudi de drets de l’àmbit públic", "El gaudi d’alguns drets reconeguts per llei"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 50, "El Conveni del Consell d'Europa sobre prevenció i lluita contra la violència contra les dones i la violència domèstica estableix com a delicte totes les formes de violència contra la dona. Això implica per als estats membres que:", "Poden desenvolupar aquests delictes als seus sistemes jurídics", "Ja no cal que introduexin aquests delictes als seus sistemes jurídics", "Poden introduir aquests delictes als seus sistemes jurídics.", "Han d’introduir aquests delictes als seus sistemes jurídics"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 51, "La Convenció sobre l'eliminació de totes les formes de discriminació contra la dona, aprovada per l'Assemblea General de Nacions Unides el desembre de 1979, proclama el principi d'igualtat de dones i homes. Al seu art. 2 els membres es comprometen a:", "Assegurar per llei o altres mitjans apropiats la realització pràctica d'aquest principi", "Consolidar per llei o altres mitjans apropiats la realització teórica d’aquest principi", "Assegurar per llei o altres mitjans apropiats la valoració pràctica d'aquest principi", "Consolidar pels mitjans que es considerin apropiats la realització teòrica d'aquest principi."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 52, "El Tractat d'Amsterdam formalitza l'objectiu marcat explícitament que totes les activitats de la Unió Europea s'han d'adreçar a:", "Eliminar les desigualtats i promoure la igualtat entre persones diferents.", "Denunciar les desigualtats i promoure la igualtat entre homes i dones", "Eliminar les desigualtats i promoure la igualtat entre homes i dones.", "Avaluar les desigualtats existents entre homes i dones i promoure la igualtat social."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 53, "El Conveni del Consell d'Europa sobre prevenció i lluita contra la violència contra les dones i la violència domèstica estableix que s’entendran per “violència domèstica”:", "Tots els actes de violència física, sexual, psicològica o econòmica que es produeixen a la família o a la llar o entre cònjuges o parelles de fet antics o actuals, independentment que l’autor del delicte comparteixi o hagi compartit el domicili amb la víctima", "Tots els actes de violència física, sexual, psicològica o econòmica que es produeixen a la família o a la llar o entre cònjuges o parelles de fet actuals, independentment que l’autor del delicte comparteixi o hagi compartit el domicili amb la víctima", "Tots els actes de violència física, sexual, psicològica o econòmica que es produeixen a la família o a la llar o entre cònjuges o parelles de fet antics o actuals quan l’autor del delicte comparteixi o hagi compartit el domicili amb la víctima.", "Tots els actes de violència física, sexual, psicològica o econòmica que es produeixen a la família entre cònjuges o parelles de fet actuals, independentment que l’autor del delicte comparteixi o hagi compartit el domicili amb la víctima"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 54, "L’objectiu de la Directiva (UE) 2019/1158 del Parlament Europeu i del Consell, de 20 de juny de 2019, relativa a la conciliació de la vida familiar i la vida professional dels progenitors i cuidadors és:", "Establir requisits mínims destinats a assolir la igualtat entre homes i dones pel que fa a les oportunitats al mercat laboral i al tracte a la feina, facilitant a tots els treballadors la conciliació de la vida personal.", "Establir una sèrie de normes de compliment obligat destinades a assolir la igualtat entre tots els homes pel que fa a les oportunitats al mercat laboral i al tracte a la feina, facilitant als treballadors que siguin progenitors o cuidadors la conciliació de la vida familiar i professional.", "Establir requisits mínims destinats a assolir la igualtat entre homes i dones pel que fa a les oportunitats al mercat laboral i al tracte a la feina, facilitant als treballadors que siguin progenitors o cuidadors la conciliació de la vida familiar i professional.", "Establir una sèrie de normes de compliment obligat destinades a assolir la igualtat entre homes i dones pel que fa a les oportunitats al mercat laboral i al tracte a la feina, facilitant als treballadors que siguin progenitors o cuidadors la conciliació de la vida familiar i professional"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 55, "El Conveni del Consell d'Europa sobre prevenció i lluita contra la violència contra les dones i la violència domèstica estableix que s’entén per “violència contra la dona per raons de gènere”:", "Tota violència contra una dona perquè és una dona i que afecta les dones de manera proporcionada.", "Tota violència contra una dona perquè és una dona i que afecta les dones de manera desproporcionada.", "La violència física i psíquica contra una dona perquè és una dona o que afecta les dones de manera desproporcionada.", "Tota violència contra una dona perquè és una dona o que afecta les dones de manera desproporcionada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 56, "Quin dels següents no és un objectiu del Conveni del Consell d'Europa sobre prevenció i lluita contra la violència contra les dones i la violència domèstica:", "Protegir les dones contra totes les formes de violència i prevenir, i perseguir i eliminar la violència contra la dona i la violència domèstica.", "Contribuir a eliminar tota forma de discriminació contra la dona i promoure la igualtat real entre dones i homes, incloent-hi l'apoderament de les dones.", "Concebre un sistema penal específic, sistemes de detecció i de mesures d’assistència legal a totes les víctimes de violència contra la dona i la violència domèstica.", "Donar suport a les organitzacions i les forces i cossos de seguretat per a cooperar de manera eficaç per a adoptar un enfocament integrat amb vista a eliminar la violència contra la dona i la violència domèstica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 57, "Assenyalau quin dels enunciats següents és fals:", "La Constitució espanyola propugna com a valors superiors del seu ordenament jurídic la llibertat, la justícia, la igualtat i el pluralisme polític.", "La Constitució espanyola estableix que tots els espanyols són iguals davant la llei, sense que pugui prevaler cap discriminació per raó de naixença, raça, sexe, religió, opinió o qualsevol altra condició o circumstància personal o social.", "La Constitució espanyola ordena la successió al tron seguint l’ordre regular de primogenitura i representació, i serà preferida sempre la línia anterior a les posteriors; en la mateixa línia, el grau més pròxim al més remot; en el mateix grau, la persona major, i en la mateixa edat, l’home a la dona.", "La Constitució espanyola dicta que l’home i la dona tenen dret a contreure matrimoni amb plena igualtat jurídica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 58, "La finalitat de les mesures de protecció integral establertes per la Llei orgànica 1/2004, de 28 de desembre, de mesures de protecció integral contra la violència de gènere és", "Prevenir, sancionar i erradicar la violència de gènere i prestar assistència a les dones, als seus fills menors i als menors subjectes a la seva tutela, o guarda i custòdia, que la pateixin.", "Avaluar, sancionar i erradicar les desigualtats esdevingudes per raó de gènere, i prestar assistència a les dones, als seus fills menors i als menors subjectes a la seva tutela, o guarda i custòdia, que la pateixin.", "Prevenir, sancionar i erradicar la violència de gènere i prestar assistència a les dones, als seus fills i als menors subjectes a la seva tutela, o guarda i custòdia, que la pateixin.", "Avaluar, estructurar i erradicar la violència de gènere i prestar assistència a les dones, als seus fills i als menors subjectes a la seva tutela, o guarda i custòdia, que la pateixin."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 59, "D’acord amb la Llei orgànica 3/2007, de 22 de març, per a la igualtat efectiva de dones i homes, la igualtat de tracte i d'oportunitats entre dones i homes és un principi informador de l'ordenament jurídic i com a tal:", "S'ha d’integrar i observar en l'aplicació de les normes jurídiques", "Es pot integrar i observar en la interpretació i l'aplicació de les normes jurídiques.", "S'ha d’integrar i observar en la interpretació i l'aplicació de les normes jurídiques.", "S'ha d’integrar i observar en la interpretació i l'aplicació de les sentències"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 60, "Què es considera discriminació indirecta per raó de sexe?", "La situació en què es troba una persona que sigui, hagi estat o pugui ser tractada, tenint en compte el seu sexe, de manera menys favorable que una altra en situació comparable.", "La situació en què una disposició, un criteri o una pràctica aparentment neutres posa persones d'un sexe en desavantatge particular respecte de persones de l'altre sexe, llevat que aquesta disposició, criteri o pràctica es pugui justificar objectivament en atenció a una finalitat legítima i que els mitjans per a assolir aquesta finalitat siguin necessaris i adequats.", "La situació en què es troba una persona que sigui, hagi estat o pugui ser tractada, sense tenir en compte el seu sexe, de manera menys favorable que una altra en situació comparable.", "La situació en què una disposició, un criteri o una pràctica aparentment neutres posa persones de diferents sexes en desavantatge particular respecte de persones dels altres sexes, tenint en compte que aquesta disposició, criteri o pràctica es pugui justificar objectivament en atenció a una finalitat legítima i que els mitjans per a assolir aquesta finalitat siguin necessaris i adequats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 61, "Quin és l'òrgan responsable d'adoptar plans i programes conjunts d'actuació perquè l'AGE i les administracions de les comunitats autònomes cooperin per a integrar el dret d'igualtat entre dones i homes en l'exercici de les competències respectives?", "La Conferencia Sectorial de la Dona.", "L’Institut de la Dona.", "L’Observatori Estatal d’Igualtat.", "La Conferència Estatal de la Dona."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 62, "Quina d'aquestes accions no es preveu com un deure de les administracions públiques, en l'àmbit de les competències respectives i en aplicació del principi d'igualtat entre dones i homes?", "Remoure els obstacles que impliquen la pervivència de qualsevol tipus de discriminació per tal d'oferir condicions d'igualtat efectiva entre dones i homes a l'accés a l'ocupació pública i en el desenvolupament de la carrera professional.", "Facilitar la conciliació de la vida personal, familiar i laboral, sense detriment de la promoció professional.", "Fomentar la formació en igualtat, tant a l'accés a l'ocupació pública com al llarg de la carrera professional.", "Promoure la presència equilibrada de dones de totes les edats als òrgans de selecció i valoració."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 63, "En quins casos no és necessari que s'adjunti un informe d'impacte de gènere a l'aprovació de convocatòries de proves selectives per a l'accés a l'ocupació pública?", "Si es tracta de professions neutres", "En casos d'urgència i sempre sense perjudici de la prohibició de discriminació per raó de sexe", "En casos en què a convocatòries similars ja hi hagi qualque prohibició de discriminació per raó de sexe.", "En casos d'urgència, si no hi ha una prohibició de discriminació per raó de sexe."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 64, "En quins casos es pot establir a les bases dels concursos per a la provisió de llocs de feina que el temps d’excedència per cura d’un fill es computi a l’efecte de valoració del treball desenvolupat i dels mèrits corresponents?", "En qualsevol cas.", "Quan l’aspirant sigui una dona", "Quan l’aspirant sigui un home", "En qualsevol cas, si es tracta d’una família monoparental."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 65, "Quins d’aquests principis és imperatiu en un protocol d’actuació per a la prevenció de l'assetjament sexual i de l'assetjament per raó de sexe d’una administració pública?", "El compromís polític de prevenir i no tolerar l'assetjament sexual i l'assetjament per raó de sexe.", "La instrucció a tot el personal sobre el seu deure de respectar la dignitat de les persones i el dret a la intimitat, així com la igualtat de tracte entre dones i homes.", "El tractament públic de les denúncies de fets que puguin constituir assetjament sexual o assetjament per raó de sexe, sens perjudici del que estableix la normativa de règim disciplinari.", "L’anonimat de les persones responsables d'atendre els qui formulen una queixa o denúncia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 66, "Quin és l’objectiu de les accions de responsabilitat social en matèria d’igualtat que poden realitzar les empreses?", "Promoure condicions d'igualtat entre les dones i els homes al si de l'empresa o al seu entorn social.", "Vetlar perquè es compleixin les condicions d'igualtat entre les dones i els homes implantades per l’administració de cada comunitat autònoma al si de l'empresa o al seu entorn social.", "Promoure condicions d'igualtat per a les dones al si de l'empresa o al seu entorn social.", "Concertar amb la comunitat autònoma condicions d'igualtat entre les dones i els homes al si de l'empresa o al seu entorn social."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 67, "Què és el Consell de Participació de la Dona?", "És una secretaria general de consulta, vigilància i assessorament, amb la finalitat essencial de participar mitjançant diferents vies en la consecució efectiva del principi d’igualtat de tracte.", "És una secretaria general de consulta i assessorament, amb la finalitat essencial de servir de via per a la participació de les dones en la consecució efectiva del principi d’igualtat de tracte i d‘oportunitats entre dones i homes, i de lluitar contra la discriminació per raó de sexe.", "És un òrgan col·legiat de consulta, assessorament i vigilància, amb la finalitat essencial de servir de via per a la participació de les dones en la consecució efectiva del principi d’igualtat de tracte i d‘oportunitats entre dones i homes, i de lluitar contra la discriminació per raó de sexe.", "És un òrgan col·legiat de consulta i assessorament, amb la finalitat essencial de servir de via per a la participació de les dones en la consecució efectiva del principi d’igualtat de tracte i d‘oportunitats entre dones i homes, i de lluitar contra la discriminació per raó de sexe."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 68, "D'acord amb la Llei 11/2016, del 28 de juliol, d'igualtat de dones i homes, quin requisit han de tenir les empreses per a obtenir els beneficis derivats de l'elaboració d'un pla d'igualtat?", "El visat previ del Govern de les Illes Balears, en els termes establerts reglamentàriament.", "El visat previ de la Inspecció de Treball, en els termes establerts reglamentàriament.", "El visat previ de l’Institut Balear de la Dona, en els termes establerts reglamentàriament.", "El visat previ de l’Observatori per a la Igualtat de les Illes Balears, en els termes establerts reglamentàriament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 69, "Quines d’aquestes mesures han d’incloure les normes que regulen els processos selectius d'accés, provisió i promoció a l'ocupació pública, sens perjudici d'altres que es considerin oportunes?", "Una clàusula per la qual, si hi ha igualtat de capacitació, es doni prioritat a les dones en els cossos, les escales, els nivells i les categories de l’Administració en què la seva representació sigui inferior al 40%, llevat que es donin en un altre candidat circumstàncies que no siguin discriminatòries per raó de sexe i que justifiquin la no aplicació de la mesura.", "Una clàusula per la qual, si hi ha igualtat de capacitació, es doni prioritat a les dones en els cossos, les escales, els nivells i les categories de l’Administració en què la seva representació sigui inferior al 60%, llevat que es donin en un altre candidat circumstàncies que no siguin discriminatòries per raó de sexe i que justifiquin la no aplicació de la mesura.", "Una clàusula per la qual, si hi ha igualtat de capacitació, es doni prioritat a les dones en els cossos, les escales, els nivells i les categories de l’Administració en què la seva representació sigui inferior al 40%, tot i que es donin en un altre candidat circumstàncies discriminatòries diferents a les que siguin per raó de sexe.", "Una clàusula per la qual, si hi ha igualtat de capacitació, es doni prioritat a les dones en els cossos, les escales, els nivells i les categories de l’Administració en què la seva representació sigui inferior al 60%, tot i que es donin en un altre candidat circumstàncies discriminatòries diferents a les que siguin per raó de sexe."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 70, "Quines d’aquestes característiques han de tenir els plans d’igualtat del personal al servei de les administracions públiques de les Illes Balears", "Han de tenir una vigència mínima de quatre anys, s’han d’avaluar cada dos anys i, si escau, han d’establir mesures correctores.", "Han de tenir una vigència màxima de quatre anys, s’han d’avaluar cada dos anys i, si escau, han d’establir mesures correctores.", "Han de tenir una vigència màxima de quatre anys, s’han d’avaluar cada dos anys i s’han d’establir mesures correctores", "Han de tenir una vigencia mínima de quatre anys, s’han d’avaluar cada dos anys i s’han d’establir mesures correctores."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 71, "De quins instruments disposen les administracions públiques per a evitar l'assetjament sexual i l'assetjament per raó de sexe?", "Protocols d’actuació que contenen les mesures de prevenció i protecció necessàries davant les conseqüències derivades d’aquestes modalitats d’assetjament.", "Protocols de detecció que contenen les mesures per a obtenir la informació i la protecció necessàries davant les conseqüències derivades d'aquestes modalitats d'assetjament.", "Protocols d’actuació que contenen les mesures de prevenció i protecció necessàries davant les conseqüències derivades de l’assetjament laboral.", "Protocols de detecció que contenen les mesures per a obtenir la informació i la protecció necessàries davant les conseqüències derivades de l'assetjament laboral."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 72, "Quina d'aquestes opcions no concorda amb les definicions de violència masclista recollides a la Llei 11/2016, del 28 de juliol, d'igualtat de dones i homes?", "Violència simbòlica: violència que inclou icones, representacions, narratives, imatges, etc. que reprodueixen o transmeten relacions de dominació dels homes respecte de les dones, així com desigualtats de poder entre sexes i de segregació.", "Mutilació genital femenina: qualsevol procediment que implica o pot implicar una eliminació total o parcial dels genitals femenins o hi produeix lesions, encara que hi hagi consentiment exprés o tàcit de la dona o de la nina.", "Feminicidi: assassinat de dones pel fet de ser dones, sempre que hi hagi hagut relació de parella.", "Violència econòmica: violència que inclou la privació intencionada, i no justificada legalment, de recursos per al benestar físic o psicològic de les dones i de les filles i els fills o la discriminació en la disposició dels recursos compartits en l'àmbit de la convivència de parella."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 73, "Quina de les següents informacions s’ha de tenir en compte per a dur a terme un estudi quantitatiu de la situació en matèria d'igualtat de gènere a l’hora d’elaborar un pla d’igualtat?", "Moviments del personal dels darrers tres anys: incorporacions d'excedències i baixes, incorporacions de personal temporal, incorporacions del darrer any per tipus de contracte, incorporacions per categories i baixes definitives.", "Característiques de l’ordenació del temps de treball i conciliació de la representació legal dels treballadors i treballadores.", "Promoció i carrera: quins temps s’ha trigat a promocionar depenent del gènere.", "Formació: nombre de cursos fets pel personal els darrers tres anys i de quin tipus."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 74, "Quina d’aquestes accions no es preveu com a eina de capacitació en matèria d’igualtat del personal al servei de les administracions públiques?", "Establir requisits específics de coneixement en matèria d’igualtat per a accedir a llocs que tenguin, entre altres, les funcions d’impulsar i dissenyar programes d’igualtat d’oportunitats i de donar assessorament tècnic en matèria d’igualtat entre dones i homes.", "Establir programes específics d’actualització i reciclatge del personal adscrit als organismes responsables en matèria d’igualtat, que s’han de dur a terme preferentment en horari laboral i que en aquest cas són obligatoris.", "Incloure continguts relatius a la legislació d’igualtat de dones i homes i la seva aplicació a l’activitat administrativa en els temaris dels processos de selecció per a l’accés a la funció pública.", "Incentivar membres dels diferents equips de treball amb coneixements demostrats en matèria d’igualtat perquè actuïn des del seu lloc de feina com a suport per a supervisar la implantació de les diferents mesures."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 75, "Com les administracions públiques han d’impulsar la transversalització de gènere en el marc de les seves competències?", "Com a instrument per a integrar la perspectiva de gènere en el disseny, l'execució, el seguiment i l'avaluació de les polítiques d'ocupació que es desenvolupin a les Illes Balears, incloent-hi, si escau, les mesures específiques i necessàries.", "Com a instrument per a integrar la perspectiva de gènere en el disseny, l'execució, el seguiment i l'avaluació de les polítiques d'ocupació que es desenvolupin a les Illes Balears, incloent hi, si escau, les mesures específiques i necessàries", "Com a obligació per a integrar la perspectiva de gènere en el disseny, l'execució, el seguiment i l'avaluació de les polítiques d'ocupació que es desenvolupin a les Illes Balears, incloent hi, si escau, les mesures específiques i necessàries", "Com a instrument per a valorar la perspectiva de gènere en el disseny, l'execució, el seguiment i l'avaluació de les polítiques d'ocupació que es desenvolupin a les Illes Balears, incloent hi, si escau, les mesures específiques i necessàries"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 1, "Qui dirigeix l’acció del Govern i coordina les funcions dels altres membres del Govern?", "El ministre de la Presidència.", "El president del Govern.", "El Consell de ministres.", "La Comissió General de Secretaris d’Estat i Subsecretaris."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 2, "El Govern exerceix:", "La funció legislativa i la potestat reglamentària d’acord amb la Constitució i les lleis.", "La funció executiva i la potestat legislativa d’acord amb la Constitució i les lleis.", "La funció executiva i la potestat reglamentària d’acord amb la Constitució i les lleis.", "La funció executiva i la potestat reglamentària i administrativa d’acord amb la Constitució i les lleis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 3, "El candidat a la Presidència del Govern el proposa:", "El president del Congrés, prèvia consulta al rei i als representants designats pels grups polítics amb representació parlamentària.", "El president del Congrés, prèvia consulta amb els representants designats pels grups polítics amb representació parlamentària.", "El rei, prèvia consulta als portaveus dels grups polítics que varen concórrer a les eleccions.", "El rei, prèvia consulta amb els representants designats pels grups polítics amb representació parlamentària."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 4, "El candidat a la Presidència del Govern que s’ha proposat d’acord amb el que preveu l’article 99.1 de la Constitució:", "Exposarà al rei el programa polític del Govern que vulgui formar.", "Exposarà davant les Corts Generals el programa polític del Govern que vulgui formar.", "Exposarà al Congrés del Diputats el programa polític del Govern que vulgui formar.", "Exposarà davant la Mesa de les cambres el programa polític del Govern que vulgui formar."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 5, "El candidat a la Presidència del Govern que s’ha proposat d’acord amb el que preveu l’article 99.1 de la Constitució:", "Demanarà la confiança del poble espanyol.", "Demanarà la confiança de les Corts Generals.", "Demanarà la confiança del Congrés dels Diputats.", "Demanarà la confiança del seu grup parlamentari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 6, "En segona votació, d’acord amb el que preveu l’article 99 de la Constitució, la confiança al candidat a la Presidència del Govern, s’entén atorgada amb:", "Amb la majoria absoluta dels membres del Congrés dels Diputats.", "Amb la majoria simple dels membres del Congrés dels Diputats.", "Amb la majoria de dos terços dels membres del Congrés dels Diputats.", "Amb la majoria de tres cinquenes parts dels membres del Congrés dels Diputats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 7, "Si en segona votació, el candidat a la Presidència del Govern no obté la confiança del Congrés dels Diputats:", "El rei nomenarà president del Govern al representant del grup parlamentari amb major representació en el Congrés dels Diputats.", "Es dissoldran les cambres i es convocaran noves eleccions.", "Es tramitaran propostes successives en la forma que preveu la Constitució.", "Es durà a terme una tercera i darrera votació i la confiança s’entén atorgada si obté la majoria dels vots dels membres presents en el Congrés dels Diputats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 8, "Els membres del Govern distints del president son nomenats i separats:", "Pel president del Congrés dels Diputats.", "Pel rei.", "Pel president del Govern.", "Pel Consell de Ministres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 9, "D’acord amb l’article 101 de la Constitució, el Govern cessa:", "Per incapacitat del president.", "Després de la convocatòria d’eleccions generals.", "Després de la celebració d’eleccions generals.", "Després de la proclamació dels resultats electorals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 10, "En l’exercici de les seves funcions, l’acusació per traïció o per qualsevol delicte contra la seguretat de l’Estat dels membres del Govern:", "Ha de ser aprovada per la majoria absoluta de les Corts Generals.", "Ha de ser aprovada per la majoria absoluta del Congrés dels Diputats.", "Ha de ser plantejada per la majoria absoluta de les Corts Generals.", "Ha de ser aprovada per la majoria simple del Congrés dels Diputats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 11, "De conformitat amb l’article 103 de la Constitució, l’Administració serveix els interessos generals:", "Amb tolerància.", "Amb eficiència.", "Amb objectivitat.", "Amb eficàcia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 12, "L’Administració pública actua:", "Amb submissió plena a la Constitució, a la llei i al dret.", "Amb submissió plena a la llei i al dret.", "Amb la única submissió a la llei i al dret.", "Amb submissió plena a la Constitució."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 13, "De conformitat amb l’article 103 de la Constitució, es regularan per llei:", "El règim de nomenaments dels funcionaris públics.", "Totes les respostes són correctes.", "Les peculiaritats del sistema sanitari del personal laboral.", "El sistema d’incompatibilitats i les garanties per a la imparcialitat en l’exercici de les seves funcions dels funcionaris públics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 14, "Les forces i cossos de seguretat tenen com a missió:", "Garantir la sobirania i independència de la nació.", "Garantir la seguretat de les institucions.", "Totes les respostes són correctes.", "Protegir el lliure exercici dels drets i de les llibertats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 15, "Senyalau la resposta correcta. D’acord amb l’article 105 de la Constitució, la llei regularà:", "El procediment a través del qual han de fer-se els actes administratius, amb garantia, quan sigui procedent, de l’audiència de l’interessat.", "El procediment a través del qual han de fer-se els actes administratius, amb garantia, en tots els supòsits, de l’audiència de l’interessat.", "El procediment a través del qual han de fer-se els actes legislatius, amb garantia, en tots les supòsits, de l’audiència de l’interessat.", "El procediment a través del qual han de fer-se els actes que afectin als ciutadans, amb garantia, quan sigui procedent, de l’audiència de l’interessat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 16, "Senyalau la resposta correcta. D’acord amb l’article 105 de la Constitució, la llei regularà:", "La audiència dels ciutadans i dels empresaris en el procediment d’elaboració de les disposicions administratives que els afectin.", "L’audiència dels ciutadans directament o a través de les organitzacions i associacions reconegudes per la llei en el procediment d’elaboració de les disposicions administratives que els afectin.", "La audiència dels ciutadans en el procediment d’elaboració de tot tipus de disposicions administratives.", "La audiència dels empresaris en el procediment d’elaboració de les disposicions administratives que els afectin."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 17, "La llei regularà l’accés dels ciutadans als arxius i els registres administratius:", "Llevat del que afecti la seguretat i la defensa de l’Estat.", "Llevat del que afecti la indagació dels delictes.", "Llevat del que afecti la intimitat de les persones.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 18, "Qui té dret a ser indemnitzats per qualsevol lesió que pateixin en qualsevol dels seus béns i drets com a conseqüència del funcionament dels serveis públics?", "Els ciutadans.", "Els particulars.", "Els ciutadans i les empreses.", "Els funcionaris públics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 19, "Els particulars tenen dret a ser indemnitzats per qualsevol lesió que pateixin en qualsevol dels seus béns i drets com a conseqüència del funcionament dels serveis públics:", "En els termes establerts per una llei orgànica.", "Mitjançant la reclamació corresponent.", "Llevat dels casos de força major.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 20, "La Constitució regula l’òrgan consultiu suprem del Govern:", "A l’article 99.", "A l’article 103.", "A l’article 106.", "A l’article 107."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 21, "Correspon establir el programa polític del Govern:", "A les Corts Generals.", "Al president del Govern.", "Al Consell de Ministres.", "Al president del Congrés dels Diputats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 22, "Al president del Govern li correspon plantejar davant el Congrés dels Diputats la qüestió de confiança:", "Prèvia deliberació del Consell d’Estat.", "Prèvia autorització del Consell d’Estat.", "Prèvia deliberació del Consell de Ministres.", "Prèvia autorització del Consell de Ministres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 23, "Correspon dirigir la política de defensa i, respecte de les forces armades, exercir les funcions que preveu la legislació reguladora de la defensa nacional i de l’organització militar:", "Al Consell de Ministres.", "Al president del Govern.", "A les Corts Generals.", "Al rei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 24, "Correspon crear, modificar i suprimir, per reial decret, els departaments ministerials, així com les secretaries d’Estat:", "Al president del Govern.", "Al rei.", "Al Consell de ministres.", "Al Congrés dels Diputats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 25, "Correspon resoldre els conflictes d’atribucions que puguin sorgir entre els diferents ministeris:", "Al ministre de la Presidència.", "A la Comissió General de Secretaris d’Estat i Subsecretaris.", "Al Consell de Ministres.", "Al president del Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 26, "L’aprovació dels projectes de llei correspon:", "Als ministres.", "Al president del Govern.", "Al Consell de Ministres.", "Al ministre de la Presidència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 27, "El Projecte de Llei de pressuposts generals de l’Estat ´és aprovat:", "Pel ministre de la Presidència.", "Pel president del Govern.", "Pel Consell de Ministres.", "Pels ministres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 28, "Emetre deute públic o contreure crèdit, quan hagi estat autoritzat per una llei, és una competència que correspon:", "A cada un dels ministres.", "Al ministre competent en matèria d’hisenda.", "Al Consell de Ministres.", "Al president del Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 29, "Correspon resoldre els assumptes que afecten més d'un ministeri i no requereixen ser elevats al Consell de Ministres:", "Al Consell d’Estat.", "A la Comissió General de Secretaris i Subsecretaris.", "Al ministre de la Presidència.", "A las comissions delegades del Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 30, "La remissió de les convocatòries als diferents membres del Consell de ministres, de les comissions delegades del Govern i de la Comissió; General de Secretaris d'Estat i Subsecretaris, correspon:", "Al ministre de la Presidència.", "Al Secretariat del Govern.", "Al Subsecretari d’Estat de Presidència.", "Al president de la Comissió General de Secretaris d’Estat i Subsecretaris."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 31, "Actua com a secretari del Consell de Ministres:", "El vicepresident del Govern.", "El ministre d’Afers Exteriors.", "El ministre de la Presidència.", "El Secretari d’Estat de la Vicepresidència del Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 32, "La competència de l’arxivament i de la custòdia de les actes de les reunions del Consell de Ministres correspon:", "Al Secretari d’Estat de Presidència.", "Al Secretariat del Govern.", "Al president del Consell de Ministres.", "Al vicepresident del Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 33, "Els tràmits relatius a la sanció i promulgació reial de les lleis aprovades per les Corts Generals i l’expedició dels reials decrets és una funció:", "Del president del Govern.", "Del Secretariat del Govern.", "Del rei.", "Del ministre de la Presidència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 34, "Quin dels següents és o són òrgans de suport polític i tècnic del president del Govern, dels vicepresidents, si és el cas, i dels ministres?", "Els gabinets.", "Els subsecretaris d’Estat.", "Els secretaris d’Estat.", "El secretariat del Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 35, "Qui presideix el Consell de Ministres?", "El ministre de la Presidència.", "El president del Govern.", "El president del Govern, llevat dels supòsits de presència del rei.", "El ministre de la Presidència, en absència del president del Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 36, "El coneixement d&#8217;un assumpte que correspon decidir a les comissions delegades del Govern pot ser advocades:", "Pel Consell de Ministres, a proposta del president del Govern.", "Pel president del Govern, a proposta del Consell de ministres.", "Pel president de la comissió respectiva, a proposta del president del Govern.", "Pel Consell de Ministres, a proposta del president de la comissió respectiva."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 37, "Aprovar, abans del 30 d’abril de cada any, un informe anual en el qual es reflecteixi el grau de compliment del pla anual normatiu de l’any anterior, és una funció:", "Del president del Govern.", "Del Secretariat del Govern.", "Del ministre de la Presidència.", "Del Consell de ministres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 38, "Al Consell de Ministres li correspon, d’acord amb la Llei 50/1997, de 27 de novembre, del Govern:", "Resoldre els conflictes d’atribucions que puguin sorgir entre els diferents ministeris.", "Crear, modificar i suprimir els òrgans directius dels departaments ministerials.", "Crear, modificar i suprimir, per reial decret, els departaments ministerials i les secretaries d’Estat.", "Proposar al rei la convocatòria d’un referèndum consultiu, amb l’autorització prèvia del Congrés dels Diputats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 39, "Els reials decrets llei els aprova:", "El Consell de ministres.", "El Consell de ministres, amb l’autorització prèvia del Congrés dels Diputats.", "El Consell de ministres, amb l’autorització prèvia de les Corts Generals.", "El Consell de ministres, amb la delegació prèvia del Congrés dels Diputats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 40, "D’acord amb el que disposa l’article 26 de la Llei 50/1997, de 27 de novembre, del Govern, la memòria de l’anàlisi d’impacte normatiu, en el procediment d’elaboració de normes amb rang de llei i dels reglaments, ha d’incloure:", "L’impacte per raó de gènere.", "L’impacte sobre els drets de la infància.", "L’anàlisi sobre l’adequació de la norma aprovada a l’ordre establert legalment en base a criteris nacionals i internacionals.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 41, "D’acord amb l’article 26.6 de la Llei 50/1997, de 27 de novembre, del Govern, en el procediment d’elaboració de reglaments, el tràmit d’audiència als ciutadans, no serà inferior:", "Vint dies naturals.", "Quinze dies hàbils.", "Quinze dies naturals.", "Vint dies hàbils."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 42, "En relació amb la Comissió General de Secretaris d’Estat i Subsecretaris:", "Està integrada pels titulars de les secretaries d’Estat i dels òrgans que tenguin el rang de subsecretari.", "La Presidència correspon al Director de Gabinet del president del Govern.", "No pot adoptar decisions proposades per la Delegació del Govern en les comunitats autònomes.", "És un òrgan de govern que té per objecte resoldre els assumptes que afecten més d’un ministeri i no requereixen ser elevats al Consell de ministres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 43, "Quina de les funcions següents correspon als ministres?", "Fixar l’ordre del dia de les reunions del Consell de Ministres.", "Interposar el recurs d’inconstitucionalitat.", "Exercir la potestat reglamentària en les matèries pròpies del departament.", "Crear, modificar i suprimir, mitjançant un reial decret, els departaments ministerials."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 44, "D’acord amb l’article 4 de la Llei 50/1997, de 27 de novembre, del Govern, els ministres sense cartera:", "Se’ls atribuirà la responsabilitat de determinades funcions governamentals.", "Assumiran el càrrec de vicepresident.", "No són membres del govern.", "Depenen orgànicament de la Presidència del Govern i funcionalment del ministeri al qual figuren adscrits."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 45, "Quin dels òrgans següents no és un òrgan de col·laboració i de suport al Govern?", "La Comissió General de Secretaris d’Estat i Subsecretaris.", "Els gabinets.", "Els secretaris d’Estat.", "Els secretaris generals tècnics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 46, "D’acord amb la Llei 50/1997, de 27 de novembre, del Govern, les disposicions d’entrada en vigor de les lleis o els reglaments, l’aprovació o la proposta dels quals correspon al Govern o als seus membres i que imposin noves obligacions a les persones físiques o jurídiques que desenvolupin una activitat econòmica o professional com a conseqüència de l’exercici d’aquesta, preveuran el començament de la seva vigència el 2 de gener o l’1 de juliol següents a la seva aprovació. Això que es preveu anteriorment:", "No serà d’aplicació quan el compliment del termini de transposició de directives europees així ho aconsellin.", "No serà d’aplicació als reials decrets llei.", "Totes les respostes són correctes.", "No serà d'aplicació quan ho aconsellin raons justificades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 47, "Els directors dels Gabinet del President, dels vicepresidents i dels ministres són nomenats:", "Mitjançant un reial decret aprovat en Consell de Ministres.", "Pel president del Govern.", "Mitjançant una ordre ministerial.", "Pel rei, a proposta del president del Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 48, "D’acord amb la Llei 50/1997, de 27 de novembre, del Govern, els membres d’aquest es reuneixen:", "En Consell de Ministres i en Consell d’Estat.", "Sempre en Consell de Ministres.", "En Consell de Ministres i en comissions delegades del Govern.", "En Consell de Ministres i en Comissió Especial de Comptes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 49, "Acordar la negociació i la signatura dels tractats internacionals, així com la seva aplicació provisional, correspon:", "Al Consell de Ministres.", "Al Congrés dels Diputats.", "Al president del Congrés dels Diputats.", "Al rei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 50, "D’acord amb l’article 3 de la Llei 50/1997, del Govern, el vicepresident que assumeix la titularitat d’un departament ministerial:", "No pot tenir la condició de ministre.", "Ha de tenir, a més, la condició de ministre.", "Pot, de forma excepcional, assumir la condició de ministre de la Presidència.", "Pot, de forma excepcional, assumir la condició de ministre d’Administracions Públiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 51, "D'acord amb la Llei 50/1997, de 27 de novembre, del Govern, entre les funcions del Secretariat del Govern no està:", "Vetlar per la publicació correcta de les disposicions i les normes del Govern que s’han d’inserir en el Butlletí Oficial de l’Estat.", "Col·laborar amb les secretaries tècniques de les comissions delegades del Govern.", "Assistir al ministre secretari del Consell de ministres.", "Assistir als Ministeris en el control de la seva eficàcia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 52, "De conformitat amb el que disposa la Llei 50/1997, de 27 de novembre, del Govern:", "Els conflictes d’atribucions entre ministeris es resolen per Acord del Consell de ministres.", "Els secretaris d’Estat són membres del Govern.", "La Comissió General de Secretaris d’Estat i Subsecretaris estarà integrada pels titulars de les secretaries d’Estat i pels subsecretaris dels diferents departaments ministerials.", "Els vicepresidents, quan n’hi hagi, no poden ostentar la condició de ministres, simultàniament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 53, "De la seva gestió política, el Govern respon:", "Individualment davant les cambres.", "Solidàriament davant les Corts Generals.", "Solidàriament davant el Congrés dels Diputats.", "Mancomunadament davant les Corts Generals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 54, "D’acord amb l’article 109 de la Constitució, poden demanar la informació i l’ajut que necessitin del Govern i dels seus departaments:", "El Congrés dels Diputats i les seves comissions, únicament.", "Les cambres i les seves comissions, únicament.", "Les cambres, únicament.", "El Senat i les seves comissions, únicament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 55, "D’acord amb el text de l’article 110 de la Constitució espanyola, en relació amb els membres del Govern:", "Tenen la facultat de fer-se escoltar en les cambres i en les seves comissions.", "Només tenen la facultat de fer-se escoltar en les cambres però no en les seves comissions.", "No poden sol·licitar que informin davant les cambres el personal funcionari dels seus departaments.", "Tenen dret a vot en les cambres i en les seves Comissions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 56, "El Govern està sotmès a les interpel·lacions que es formulin en les cambres. Per a aquesta classe de debat:", "Els reglaments estableixen un temps mínim en cada sessió.", "Els reglaments estableixen un temps mínim mensual.", "Els reglaments estableixen un temps mínim setmanal.", "Els reglaments estableixen un temps mínim per cada període de sessions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 57, "De conformitat amb l’article 112 de la Constitució, qui pot plantejar la qüestió de confiança?", "El president del Govern, amb la deliberació prèvia del Consell d’Estat.", "El president del Govern, amb la deliberació prèvia del Consell de Ministres.", "El Consell de ministres, a través del president del Govern.", "El president del Govern, sota la seva exclusiva responsabilitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 58, "El president del Govern pot plantejar la qüestió de confiança:", "Sobre una situació política especial.", "Sobre una declaració de política especial.", "Sobre una declaració de política general.", "Sobre un assumpte d'interès públic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 59, "D’acord amb l’article 113 de la Constitució, la moció de censura ha d’incloure:", "Els candidats a ocupar tots els ministeris.", "Els candidats a ocupar els llocs de vicepresident o vicepresidents, si n’hi ha.", "Un candidat a la Presidència del Govern.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 60, "D’acord amb la Constitució, la moció de censura ha de ser votada:", "No abans que transcorrin tres dies des de la seva presentació.", "Als cinc dies de la seva presentació.", "No abans que transcorrin cinc dies des de la seva presentació.", "Als tres dies de la seva presentació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 61, "Què passa si una moció de censura no és aprovada pel Congrés?", "Els signataris no en podran presentar cap més durant el mateix període de sessions.", "El signataris no en podran presentar cap més durant tota la legislatura.", "No se’n podrà presentar cap més durant el mateix període de sessions.", "No se’n podrà presentar cap més durant la mateixa legislatura."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 62, "Senyalau la resposta correcta. Si el Congrés dels Diputats adopta una moció de censura:", "El candidat inclòs en la moció de censura s’entendrà investit de la confiança de la cambra als efectes que preveu l’article 99.", "El Govern presentarà la seva dimissió al rei.", "Totes les respostes són correctes.", "El rei nomenarà president del Govern inclòs en la moció de censura."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 63, "Qui pot decretar la dissolució del Congrés, del Senat o de les Corts Generals, d’acord amb l’article 115 de la Constitució?", "El president del Govern, prèvia deliberació del Consell de ministres.", "El rei.", "El president del Govern, sota la seva exclusiva responsabilitat.", "El Consell de Ministres, a proposta del president del Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 64, "Senyalau la resposta correcta. En relació amb la la dissolució del Congrés, del Senat o de les Corts Generals, de l’article 115 de la Constitució:", "No serà procedent una nova dissolució abans que transcorri un any des de l’anterior, llevat del que disposa l’article 99.5 o durant la vigència dels estats d’alarma, excepció o setge.", "En cap cas serà procedent una nova dissolució fins que transcorri un any des de l’anterior.", "No serà procedent una nova dissolució abans que transcorri un any des de l’anterior, llevat del que disposa l’article 99.5.", "En cap cas serà procedent una nova dissolució abans que transcorrin sis mesos des de l’anterior."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 65, "Els estats d’alarma, d’excepció i de setge es regularan mitjançant una llei orgànica, així com:", "La suspensió d’algun dels poders de l’Estat.", "Les competències i limitacions corresponents.", "Les funcions assumides pels òrgans estatals durant la seva vigència.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 66, "L'estat d'alarma serà declarat:", "Per un termini màxim de vint dies.", "Per un termini màxim de quinze dies.", "Per un termini màxim de deu dies.", "Sense termini de finalització"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 67, "El Decret que acordi l’estat d’alarma determinarà:", "Els drets i les llibertats que quedaran suspesos durant el temps de la declaració.", "L’àmbit territorial al qual s’estenen els efectes de la declaració.", "L’autoritat que exerciran els poders de l’Estat en l’àmbit territorial afectat.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 68, "L’autorització i la proclamació de l’estat d’excepció haurà de determinar de manera expressa:", "Els seus efectes.", "Totes les respostes són correctes.", "La seva durada.", "L’àmbit territorial al qual s’estén."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 69, "L’estat de setge serà declarat:", "Per la majoria absoluta del Congrés dels Diputats, a proposta exclusiva del Govern.", "Per la majoria simple del Congrés dels Diputats, a iniciativa pròpia.", "Pel Govern, a proposta del Congrés dels Diputats.", "Per la majoria absoluta del Congrés dels Diputats, a iniciativa pròpia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 70, "Durant la vigència dels estats que defineix l’article 116 de la Constitució:", "El funcionament de tots els poders constitucionals passarà a ser exercit pel Congrés dels Diputats.", "No es podrà interrompre el funcionament d’ambdues cambres ni el dels altres poders constitucionals de l’Estat.", "El funcionament de tots els poders constitucionals passarà a ser exercit pel Senat.", "El funcionament de tots els poders constitucionals passarà a ser exercit per les Corts Generals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 71, "Quin òrgan té competència per mantenir relacions amb les comunitats autònomes i convocar conferències sectorials:", "El Delegat del Govern.", "El ministre.", "El secretari d’Estat.", "El subsecretari d’Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 72, "La prefectura de l’Estat, és un òrgan de l’Administració de l’Estat?", "Sí, és l’òrgan suprem.", "No, ja que és exercida per la Corona.", "Sí, però jeràrquicament depèn de la Presidència del Govern.", "No, ja que és un òrgan inexistent actualment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 73, "La prefectura superior de tot el personal en un departament ministerial és exercida:", "Pel ministre.", "Pel secretari d’Estat.", "Pel subsecretari.", "Pel director general."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 74, "La creació o modificació de les Comissions Delegades del Govern s’acordarà mitjançant:", "Un reial decret acordat en Consell de Ministres.", "Una llei ordinària.", "Una llei orgànica.", "Una ordre de comissions delegades de govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 75, "La representació d’un ministeri, per delegació d’un ministre, correspon:", "Al subsecretari del departament.", "Al secretari d’Estat del departament.", "Al director general del departament que designi el ministre.", "Al secretari general tècnic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 76, "En l’Administració General de l’Estat, poden dictar circulars i instruccions als inferiors al seu departament:", "Els directors generals.", "Els subsecretaris.", "Els secretaris d’Estat.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 77, "Senyalau la resposta correcta. El subdelegat del Govern, on n’hi hagi:", "Assumeix la representació del Govern en el territori de la comunitat autònoma.", "Depèn directament de la Presidència del Govern.", "És nomenat per un període màxim de dos anys entre persones de reconeguda competència professional.", "Totes les respostes anteriors són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 78, "En les comunitats autònomes uniprovincials, supleix el Delegat del Govern, durant la seva absència:", "El subdelegat del Govern més antic.", "El subdelegat del Govern que designi el delegat del Govern.", "El secretari general si no existeix el subdelegat.", "El director insular."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 1, "Segons l’article 35.1 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, han de ser motivats:", "Els actes que se separin del criteri seguit en actuacions precedents o del dictamen d’òrgans consultius.", "Els actes que proposin proves proposades pels interessats.", "Els acords d’aplicació de la tramitació ordinària.", "Els actes que reconeguin drets subjectius o interessos legítims."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 2, "Indicau quina de les afirmacions següents és correcta segons l’article 36.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques:", "Els actes administratius no es poden refondre en un únic acte.", "Els òrgans administratius poden exercir la seva competència de forma verbal.", "Els actes administratius s’han de produir sempre per escrit.", "Els actes administratius de distinta naturalesa es poden refondre en un únic acte."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 3, "Segons l’article 37.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, la inderogabilitat singular implica que les resolucions administratives de caràcter particular:", "No poden vulnerar el que estableix una disposició de caràcter general, encara que aquelles procedeixin d’un òrgan de jerarquia igual o superior al que va dictar la disposició general.", "Poden vulnerar el que estableix una disposició de caràcter general quan provenguin d’un òrgan de jerarquia superior al que va dictar la disposició general.", "No poden vulnerar el que estableix una disposició de caràcter general, llevat que aquelles procedeixin d’un òrgan de jerarquia igual o superior al que va dictar la disposició general.", "Poden vulnerar el que estableix una disposició de caràcter general quan procedeixin del mateix òrgan que dictà la disposició general."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 4, "Segons l’article 39.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, l’eficàcia d’un acte queda demorada:", "Quan així ho disposi l’òrgan competent.", "Quan així ho exigeixi el contingut de l’acte o estigui supeditada a la seva notificació, publicació o aprovació superior.", "Quan ho sol·liciten les persones interessades en el procediment.", "Quan l’acte sigui ferm."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 5, "Segons l’article 40.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, les notificacions han de contenir:", "Un extracte de la resolució, amb indicació de si posa fi o no a la via administrativa.", "L’expressió dels recursos que siguin procedents, si s’escau, en via administrativa i judicial, l’òrgan davant el qual s’hagin de presentar i el termini per interposar-los.", "Els mitjans de pagament que s’estableixin a favor dels administrats.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 6, "Segons l’article 42.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, quan la notificació es practica en el domicili de l’interessat i el primer intent de notificació resulta infructuós:", "S’ha de repetir l’intent per una sola vegada i en una hora diferent dins dels tres dies següents.", "S’ha de repetir l’intent dins de les quinze hores següents.", "S’ha de publicar l’acte de la forma prevista en l’article 44.", "S’ha de repetir l’intent dins de les tres hores següents."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 7, "Indicau quina de les afirmacions següents és correcta segons l’article 42.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, relatiu al segon intent de notificació administrativa en el domicili de l’interessat:", "El segon intent s’ha de fer sempre després de les quinze hores.", "El segon intent s’ha de fer sempre abans de les quinze hores.", "Cal deixar un marge de diferència de menys de dotze hores entre ambdós intents de notificació.", "Cal deixar en tot cas almenys un marge de diferència de tres hores entre tots dos intents de notificació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 8, "Segons l’article 43.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, quan la notificació per mitjans electrònics sigui de caràcter obligatori, o hagi estat escollida expressament per l’interessat, s’entén rebutjada quan:", "Hagin transcorregut deu dies naturals des de la posada a disposició de la notificació sense que s’accedeixi al seu contingut.", "Hagi transcorregut un mes des de la posada a disposició de la notificació sense que s’accedeixi al seu contingut.", "Hagin transcorregut deu dies hàbils des de la posada a disposició de la notificació sense que s’accedeixi al seu contingut.", "Hagin transcorregut cinc dies hàbils des de la posada a disposició de la notificació sense que s’accedeixi al seu contingut."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 9, "Indicau quina de les afirmacions següents és correcta segons l’article 45.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, relatiu a la publicació d’actes administratius:", "S’han de publicar al Diari Oficial de la Unió Europea els actes i comunicacions que, per disposició legal o reglamentària, s’hagin de publicar en el Butlletí Oficial de l’Estat.", "La publicació d’una convocatòria d’un procediment selectiu al tauler d’edictes substitueix la publicació al butlletí oficial corresponent.", "En els supòsits de publicacions d’actes que continguin elements comuns, es poden publicar de manera conjunta els aspectes coincidents, i només s’han d’especificar els aspectes individuals de cada acte.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 10, "Segons l’article 47.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, els actes que tenguin un contingut impossible són:", "Nuls de ple dret.", "Anul·lables.", "Anul·lables quan siguin dictats per l’òrgan competent i nuls quan siguin dictats per un òrgan manifestament incompetent.", "Nuls o anul·lables en funció de la jerarquia de l’òrgan que hagi dictat la disposició."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 11, "L’article 49.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, disposa que:", "La nul·litat o anul·labilitat d’un acte no implica la dels successius en el procediment que siguin independents del primer.", "La nul·litat o anul·labilitat d’un acte implica la dels successius en el procediment que siguin independents del primer.", "La nul·litat d’un acte no implica la dels successius en el procediment que siguin independents del primer.", "L’anul·labilitat d’un acte no implica la dels successius en el procediment que siguin independents del primer."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 12, "L’article 49.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, disposa que:", "La nul·litat o anul·labilitat en part de l’acte administratiu implica en tot cas la de les seves parts independents d’aquella.", "La nul·litat de l’acte administratiu no implica la de les seves parts independents d’aquella, llevat que la part viciada tingui tanta importància que sense aquesta l’acte administratiu no s’hauria dictat.", "La nul·litat o anul·labilitat en part de l’acte administratiu no implica la de les seves parts independents d’aquella, llevat que la part viciada tingui tanta importància que sense aquesta l’acte administratiu no s’hauria dictat.", "L’anul·labilitat de l’acte administratiu no implica la de les seves parts independents d’aquella, llevat que la part viciada tingui tanta importància que sense aquesta l’acte administratiu no s’hauria dictat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 13, "Segons l’article 55.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, l’objectiu del període d’informació o actuacions prèvies és:", "Conèixer les circumstàncies del cas concret, la conveniència o no d’iniciar el procediment i assegurar l’eficàcia de la resolució que es pugui dictar.", "Conèixer les circumstàncies del cas concret i la conveniència o no d’iniciar el procediment.", "Conèixer les circumstàncies del cas concret i la conveniència o no de dictar una resolució sancionadora.", "Conèixer les circumstàncies del cas concret, assegurar l’eficàcia de la resolució que es pugui dictar, i la conveniència o no de dictar una resolució sancionadora."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 14, "Segons l’article 56.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, les mesures provisionals han de ser confirmades, modificades o aixecades:", "En l’acord de finalització del procediment, que s’ha d’efectuar dins dels quinze dies següents a la seva adopció, el qual pot ser objecte del recurs que escaigui.", "En l’acord d’iniciació del procediment, que s’ha d’efectuar dins dels quinze dies següents a la seva adopció, contra el qual no és procedent cap recurs administratiu.", "En l’acord de finalització del procediment, que s’ha d’efectuar dins dels quinze dies següents a la seva adopció, contra el qual no és procedent cap recurs administratiu.", "En l’acord d’iniciació del procediment, que s’ha d’efectuar dins dels quinze dies següents a la seva adopció, el qual pot ser objecte del recurs que escaigui."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 15, "Indicau quina de les respostes següents és correcta segons l’article 56.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques:", "Les mesures provisionals no poden ser modificades a instància de part.", "Es prohibeix l’adopció de la mesura provisional de suspensió temporal d’activitats.", "Les mesures provisionals només s’extingeixen quan la resolució és ferma en via administrativa.", "Les mesures provisionals adoptades abans de la iniciació del procediment queden sense efecte quan l’acord d’iniciació no contengui un pronunciament exprés sobre aquestes mesures."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 16, "Segons l’article 57 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, quin recurs és procedent contra l’acord d’acumulació de procediments?", "Recurs de reposició.", "No és procedent cap recurs.", "Recurs administratiu o bé recurs contenciós administratiu.", "Recurs d’alçada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 17, "L’article 58 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, disposa que els procediments s’inicien:", "D’ofici per acord de l’òrgan competent, com a conseqüència d’una ordre superior, a petició raonada d’altres òrgans o per denúncia.", "D’ofici o a instància de part per acord de l’òrgan competent, per iniciativa pròpia o com a conseqüència d’una ordre superior, a petició raonada d’altres òrgans o per denúncia.", "D’ofici per acord de l’òrgan competent, per iniciativa pròpia o com a conseqüència d’una ordre superior, a petició raonada d’altres òrgans o per denúncia.", "D’ofici o a instància de part per acord de l’òrgan competent, per iniciativa pròpia o com a conseqüència d’una ordre d’altres òrgans, o per denúncia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 18, "Segons l’article 61.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, s’entén per petició raonada d’altres òrgans:", "La proposta d’iniciació del procediment formulada per qualsevol òrgan administratiu que no té competència per iniciar-lo i que ha tingut coneixement de les circumstàncies, conductes o fets objecte del procediment, ocasionalment o bé perquè té atribuïdes funcions d’inspecció, indagació o investigació.", "L’ordre emesa per un òrgan administratiu superior jeràrquic del competent per iniciar el procediment.", "L’acte pel qual qualsevol persona, en compliment o no d’una obligació legal, posa en coneixement d’un òrgan administratiu l’existència d’un fet determinat que pugui justificar la iniciació d’ofici d’un procediment administratiu.", "L’actuació derivada del coneixement directe o indirecte de les circumstàncies, conductes o fets objecte del procediment per part de l’òrgan que té atribuïda la competència d’iniciació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 19, "L’article 61.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, relatiu a l’inici del procediment per petició raonada d’altres òrgans, disposa que:", "La petició vincula l’òrgan competent per iniciar el procediment, si bé ha de comunicar a l’òrgan que l’hagi formulat els motius pels quals, si s’escau, la iniciació és procedent.", "La petició no vincula l’òrgan competent per iniciar el procediment, si bé ha de comunicar a l’òrgan que l’hagi formulat els motius pels quals, si s’escau, la iniciació no és procedent.", "La petició vincula l’òrgan competent per iniciar el procediment, si bé ha de comunicar a l’òrgan que l’hagi formulat els motius pels quals, si s’escau, la iniciació no és procedent.", "La petició no vincula l’òrgan competent per iniciar el procediment, si bé ha de comunicar a l’òrgan que l’hagi formulat els motius pels quals, si s’escau, la iniciació és procedent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 20, "Segons l’article 62.4 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, el denunciant que hagi participat en la comissió d’una infracció ha de quedar eximit de la sanció:", "Quan no hi hagi altres infractors i aporti elements de prova que permetin iniciar el procediment o comprovar la infracció, sempre que en el moment que s’aportin no es disposi d’elements suficients per ordenar-la i es repari el perjudici causat.", "Quan hi hagi altres infractors i el denunciant faciliti elements de prova que aportin un valor afegit significatiu.", "Quan hi hagi altres infractors i sigui el primer a aportar elements de prova que permetin iniciar el procediment o comprovar la infracció, sempre que en el moment que s’aportin no es disposi d’elements suficients per ordenar-la i es repari el perjudici causat.", "Quan no hi hagi altres infractors i el denunciant faciliti elements de prova que aportin un valor afegit significatiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 21, "Indicau quina de les afirmacions següents és correcta segons l’article 63.3 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques:", "Els procediments sancionadors s’inicien d’ofici o a instància de part i han d’establir la separació deguda entre la fase instructora i la sancionadora.", "No es poden iniciar nous procediments de caràcter sancionador per fets o conductes tipificades com a infraccions en la comissió dels quals l’infractor persisteixi de manera continuada, mentre no s’hagi dictat una primera resolució sancionadora, amb caràcter executiu.", "La qualificació jurídica definitiva de la infracció sempre ha de quedar fixada a la resolució d’inici.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 22, "Segons l’article 64.3 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, quan en el moment que es dicti l’acord d’iniciació d’un procediment sancionador no hi hagi elements suficients per a la qualificació inicial dels fets:", "La qualificació es pot dur a terme en una fase posterior mitjançant l’elaboració d’un plec de càrrecs, que s’ha de notificar als interessats.", "S’ha d’obrir una fase d’informació prèvia amb la finalitat de determinar els fets que motiven la instrucció del procediment.", "La qualificació es pot dur a terme en l’acord d’obertura del període de prova, que s’ha de notificar als interessats.", "S’ha d’arxivar el procediment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 23, "Indicau quina de les respostes següents és correcta segons l’article 65.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, que regula les especialitats en l’inici d’ofici dels procediments de responsabilitat patrimonial:", "És un requisit per iniciar el procediment de responsabilitat patrimonial que hagi prescrit el dret a la reclamació de l’interessat.", "S’ha d’arxivar el procediment quan els particulars presumptament lesionats no s’hi personin en el termini establert.", "L’acord d’iniciació del procediment s’ha de comunicar als interessats i se’ls ha de concedir un termini de quinze dies perquè presentin al·legacions.", "El procediment iniciat s’ha d’instruir encara que els particulars presumptament lesionats no s’hi personin en el termini establert."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 24, "Segons l’article 68.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, el termini d’esmena i millora de la sol·licitud:", "S’ha d’ampliar prudencialment, fins a cinc dies, sempre que no es tracti de procediments selectius o de concurrència competitiva.", "Es pot ampliar prudencialment, fins a cinc dies, sempre que no es tracti de procediments selectius o de concurrència competitiva.", "S’ha d’ampliar en cinc dies en els procediments selectius o de concurrència competitiva.", "Es pot ampliar prudencialment, fins a cinc dies, en els procediments selectius o de concurrència competitiva."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 25, "Indicau quina de les afirmacions següents és correcta segons l’article 69.3 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, que regula la declaració responsable i la comunicació:", "S’entén per declaració responsable aquell document mitjançant el qual els interessats posen en coneixement de l’Administració pública competent les seves dades identificadores o qualsevol altra dada rellevant per iniciar una activitat o exercir un dret.", "La comunicació s’ha de presentar dins d’un termini posterior a l’inici de l’activitat.", "Les declaracions responsables i les comunicacions permeten el reconeixement o l’exercici d’un dret o bé l’inici d’una activitat, des del dia de la seva presentació.", "S’ha d’exigir la presentació simultània de la declaració responsable i la comunicació llevat que la legislació sectorial ho prohibeixi."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 26, "Indicau quina de les afirmacions següents és correcta segons l’article 69.3 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques:", "Les declaracions responsables i les comunicacions permeten el reconeixement o l’exercici d’un dret o bé l’inici d’una activitat, des del dia de l’autorització.", "La declaració responsable es pot presentar dins d’un termini posterior a l’inici de l’activitat quan la legislació corresponent ho prevegi expressament.", "Com a regla general la comunicació s’ha de presentar després de l’inici de l’activitat.", "La comunicació es pot presentar dins d’un termini posterior a l’inici de l’activitat quan la legislació corresponent ho prevegi expressament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 27, "Segons l’article 70.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, forma part de l’expedient administratiu:", "La informació continguda en aplicacions, fitxers i bases de dades informàtiques.", "Les diligències encaminades a executar la resolució administrativa.", "Les notes, esborranys, opinions i resums.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 28, "D’acord amb el principi de simplificació administrativa que consagra l’article 72.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques:", "S’han d’acordar en un sol acte tots els tràmits que, per la seva naturalesa, admetin un impuls simultani i no sigui obligat el seu compliment successiu.", "Es poden acordar en un sol acte tots els tràmits que, per la seva naturalesa, admetin un impuls simultani i sigui obligat el seu compliment successiu.", "S’han d’acordar en un sol acte tots els tràmits que, per la seva naturalesa, admetin un impuls simultani i sigui obligat el seu compliment successiu.", "Es poden acordar en un sol acte tots els tràmits que, per la seva naturalesa, admetin un impuls simultani i no sigui obligat el seu compliment successiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 29, "Segons l’article 72.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, en sol·licitar els tràmits que hagin de complir altres òrgans:", "Es pot consignar en la comunicació cursada el termini legal establert a aquest efecte.", "S’ha de consignar en la comunicació cursada el termini legal establert a aquest efecte.", "S’ha de consignar en la comunicació cursada la suspensió del termini per dictar i notificar la resolució.", "Es pot consignar en la comunicació cursada la suspensió del termini per dictar i notificar la resolució."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 30, "Segons l’article 73.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, els tràmits que hagin d’executar els interessats:", "S’han de realitzar en el termini de deu dies a partir de l’endemà de la notificació de l’acte corresponent, excepte en el cas en què la norma corresponent fixi un termini diferent.", "S’han de realitzar en el termini de deu dies a partir de l’endemà de la notificació de l’acte corresponent.", "S’han de realitzar en el termini de quinze dies a partir de l’endemà de la notificació de l’acte corresponent, excepte en el cas en què la norma corresponent fixi un termini diferent.", "S’han de realitzar en el termini de quinze dies a partir de l’endemà de la notificació de l’acte corresponent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 31, "Segons l’article 73.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, en qualsevol moment del procediment, quan l’Administració consideri que algun dels actes dels interessats no reuneix els requisits necessaris:", "Ho ha de posar en coneixement del seu autor, i se li ha de concedir un termini no inferior a deu dies ni superior a quinze per executar-lo.", "S’ha de considerar que l’interessat desisteix de la seva petició, amb la resolució prèvia que ha de ser dictada en els termes que preveu l’article 21.", "Ho ha de posar en coneixement del seu autor, i se li ha de concedir un termini de deu dies per executar-lo.", "S’ha de considerar que l’interessat desisteix de la seva petició, amb la resolució prèvia que ha de ser dictada en el termini de deu dies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 32, "Segons l’article 75.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, els actes d’instrucció:", "S’han de dur a terme d’ofici o a instància de part.", "S’han de dur a terme d’ofici o a instància de part i a través de mitjans electrònics.", "S’han de dur a terme d’ofici i a través de mitjans electrònics.", "S’han de dur a terme d’ofici o a instància de part, en paper i a través de mitjans electrònics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 33, "Segons l’article 77.3 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, es poden rebutjar les proves proposades pels interessats:", "Quan l’òrgan instructor ho consideri oportú.", "Quan siguin manifestament improcedents o innecessàries.", "Quan hi hagi raons imperioses d’interès general.", "Quan siguin manifestament pertinents i necessàries."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 34, "Segons l’article 80.4 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, si l’informe ha de ser emès per una administració pública diferent de la que tramita el procediment amb vista a expressar el punt de vista corresponent a les seves competències respectives, i el termini transcorre sense que s’hagi emès:", "Han de prosseguir les actuacions.", "Es poden prosseguir les actuacions.", "No han de prosseguir les actuacions.", "S’ha de suspendre la instrucció del procediment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 35, "Segons l’article 81.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, en els procediments de responsabilitat patrimonial el termini per a l’emissió de l’informe del servei el funcionament del qual hagi ocasionat la presumpta lesió indemnitzable:", "No pot excedir els deu dies.", "No pot ser inferior a deu dies ni superior a quinze.", "No pot ser inferior a deu dies ni superior a trenta.", "No pot ser inferior a deu dies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 36, "Segons l’article 83.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, com es duu a terme el tràmit d’informació pública?", "S’ha de notificar als interessats i s’ha de publicar un anunci al diari oficial corresponent a fi que puguin presentar al·legacions en un termini no inferior a trenta dies.", "S’ha de publicar un anunci al diari oficial corresponent a fi que qualsevol persona física o jurídica pugui examinar l’expedient.", "S’ha de publicar un anunci al diari oficial corresponent a fi que els interessats puguin examinar l’expedient.", "S’ha de publicar un anunci al diari oficial corresponent a fi que qualsevol persona física o jurídica pugui examinar l’expedient en un termini no inferior a deu dies ni superior a quinze."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 37, "Segons l’article 86.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, els pactes i acords que subscriguin les administracions públiques:", "Requereixen sempre l’aprovació expressa del Consell de Ministres o l’òrgan equivalent de les comunitats autònomes.", "S’han de publicar al Butlletí Oficial de l’Estat o al diari oficial corresponent.", "Poden establir l’àmbit personal, funcional i territorial, i el termini de vigència.", "S’han de publicar o no segons la seva naturalesa i les persones a les quals estiguin destinats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 38, "Indicau quina de les afirmacions següents és correcta segons l’article 87 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, relatiu a la pràctica d’actuacions complementàries:", "Les actuacions complementàries són acordades per l’instructor del procediment.", "S’ha de concedir un termini no superior a quinze dies per formular al·legacions.", "Les actuacions complementàries s’han de practicar en un termini no superior a quinze dies.", "L’òrgan instructor pot suspendre el termini per resoldre el procediment fins que acabin les actuacions complementàries."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 39, "Segons l’article 87 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques:", "Abans de dictar la resolució, l’òrgan competent per resoldre ha de realitzar les actuacions complementàries indispensables per resoldre el procediment.", "Abans de dictar la resolució, l’òrgan instructor pot decidir, mitjançant un acord motivat, la realització de les actuacions complementàries indispensables per resoldre el procediment.", "Abans de dictar la resolució, l’òrgan competent per resoldre pot decidir, mitjançant un acord motivat, la realització de les actuacions complementàries indispensables per resoldre el procediment.", "Abans de dictar la resolució, l’òrgan instructor ha de realitzar les actuacions complementàries indispensables per resoldre el procediment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 40, "Indicau quina de les afirmacions següents és correcta segons l’article 88.5 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, relatiu al contingut de la resolució:", "L’acceptació d’informes o dictàmens no serveix de motivació a la resolució encara que s’incorporin al text d’aquesta resolució.", "La resolució del procediment es pot dictar electrònicament.", "Es pot acordar la inadmissió de les sol·licituds de reconeixement de drets no prevists en l’ordenament jurídic o manifestament que no tenen fonament.", "La resolució que posi fi al procediment només pot decidir sobre les qüestions plantejades pels interessats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 41, "Segons l’article 89.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, l’òrgan instructor ha de resoldre la finalització del procediment sancionador amb arxiu de les actuacions:", "Quan no figurin en el procediment ni siguin tinguts en compte en la resolució altres fets ni altres al·legacions i proves que les adduïdes per l’interessat.", "Quan la sanció tengui caràcter pecuniari i s’hagi reposat la situació alterada.", "Quan els fets provats no constitueixin, de manera manifesta, una infracció administrativa.", "Quan consideri que la infracció o la sanció revesteixen més gravetat que la determinada en la resolució d’inici."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 42, "Segons l’article 94.5 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, l’Administració pot limitar els efectes del desistiment o la renúncia a l’interessat:", "Quan es personin en el procediment tercers interessats i n’instin la continuació en el termini de deu dies.", "Quan la qüestió suscitada per la incoació del procediment comporta interès general o és convenient substanciar-la per definir-la i aclarir-la.", "Quan es produeixi la paralització del procediment per causa imputable a l’interessat.", "Quan raons d’interès públic o la falta de complexitat del procediment ho aconsellin."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 43, "L’article 95.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, disposa que:", "S’ha d’acordar la caducitat per la simple inactivitat de l’interessat en l’execució de tràmits, sempre que no siguin indispensables per dictar la resolució.", "No es pot acordar la caducitat per la simple inactivitat de l’interessat en l’execució de tràmits, sempre que no siguin indispensables per dictar la resolució.", "Es pot acordar la caducitat per la simple inactivitat de l’interessat en l’execució de tràmits, sempre que no siguin indispensables per dictar la resolució.", "No s’ha d’acordar la caducitat per la simple inactivitat de l’interessat en l’execució de tràmits, sempre que siguin indispensables per dictar la resolució."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 44, "Segons l’article 96.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, quan es pot acordar el procediment de tramitació simplificada?", "Quan així ho autoritzin les lleis, i en la forma i la quantia que aquestes lleis determinin.", "Quan raons d’interès públic o la falta de complexitat del procediment ho aconsellin.", "Quan no existeixi o no s’hagi pogut identificar la persona o persones responsables.", "Quan ho requereixi la naturalesa del procediment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 45, "Segons l’article 96.6 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, quin és el termini per resoldre el procediment de tramitació simplificada?", "Tres mesos, comptadors des del dia següent en què es notifiqui als interessats l’acord de tramitació simplificada del procediment.", "Tres mesos, comptadors des del dia següent en què es dicta la resolució d’inici del procediment.", "Trenta dies, a comptar del següent a aquell en què es notifiqui a l’interessat l’acord de tramitació simplificada del procediment.", "Trenta dies, a comptar des de la data en què es dicta la resolució d’inici del procediment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 46, "Segons l’article 100.3 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, quan les administracions públiques necessiten entrar en el domicili de l’afectat:", "Han d’obtenir sempre l’autorització judicial oportuna.", "N’han d’obtenir el consentiment o, si no, l’autorització judicial oportuna.", "N’han d’obtenir el consentiment i l’autorització judicial oportuna.", "Han d’instruir el procediment que correspongui d’acord amb el títol IV d’aquesta Llei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 47, "Segons l’article 102.4 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, l’exigència de les despeses de l’execució subsidiària:", "S’ha de liquidar de manera definitiva un cop executat l’acte, a través del procediment de constrenyiment.", "Es pot liquidar de manera provisional i es pot realitzar abans de l’execució, a reserva de la liquidació definitiva.", "S’ha de liquidar de manera provisional i es pot realitzar abans de l’execució, a reserva de la liquidació definitiva.", "S’ha de liquidar de manera definitiva un cop executat l’acte, amb l’autorització judicial prèvia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 48, "En quin dels supòsits següents es pot imposar la multa coercitiva segons la lletra a) de l’article 103.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques?", "Actes personalíssims en què no escaigui la compulsió directa sobre la persona de l’obligat.", "Quan en virtut d’un acte administratiu s’ha de satisfer una quantitat líquida.", "Actes l’execució dels quals no pot ser encarregada a una altra persona.", "Quan així ho exigeixi el contingut de l’acte o estigui supeditat a la seva notificació, publicació o aprovació superior."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 49, "Segons l’article 106 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, és necessari sol·licitar el dictamen del Consell d’Estat:", "En els processos de revisió d’actes nuls.", "En els processos de revisió de disposicions nul·les.", "En els processos de revisió d’actes nuls i disposicions nul·les.", "En els processos de revisió d’actes nuls, de disposicions nul·les i de declaració de lesivitat de disposicions anul·lables."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 50, "Segons l’article 106.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, quin caràcter té el dictamen del Consell d’Estat en els procediments de revisió d’actes nuls?", "Facultatiu i no vinculant.", "Preceptiu i vinculant.", "Preceptiu i no vinculant.", "Facultatiu i vinculant."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 51, "Segons l’article 106.5 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, quan es produeix la caducitat dels procediments de revisió de disposicions i actes nuls iniciats d’ofici?", "Pel transcurs del termini de sis mesos des del seu inici sense que s’hagi dictat una resolució.", "Pel transcurs del termini de tres mesos des del seu inici sense que s’hagi dictat una resolució.", "Pel transcurs del termini de sis mesos des que es dictà l’acte o disposició nul·la.", "Pel transcurs del termini de tres mesos des que es dictà  l’acte o disposició nul·la."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 52, "Segons l’article 107.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, la declaració de lesivitat afecta:", "Els actes favorables per als interessats que siguin anul·lables.", "Els actes desfavorables per als interessats que siguin anul·lables.", "Els actes favorables per als interessats que siguin nuls.", "Els actes desfavorables per als interessats que siguin nuls."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 53, "L’article 107.3 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, disposa:", "Que si, un cop transcorregut el termini de quatre anys des de la iniciació del procediment, no s’ha declarat la lesivitat, es produeix la caducitat del procediment.", "Que si, un cop transcorregut el termini de sis mesos des de la iniciació del procediment, no s’ha declarat la lesivitat, es produeix la caducitat del procediment.", "Que si, un cop transcorregut el termini de quatre anys des de la iniciació del procediment, no s’ha declarat la lesivitat, aquesta declaració es pot entendre desestimada per silenci administratiu.", "Que si, un cop transcorregut el termini de sis mesos des de la iniciació del procediment, no s’ha declarat la lesivitat, aquesta declaració es pot entendre desestimada per silenci administratiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 54, "Quin límit temporal estableix l’article 109.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, per rectificar els errors materials, de fet o aritmètics?", "No s’estableix cap límit.", "Quatre anys des que es va dictar l’acte administratiu.", "Un mes des que es va dictar l’acte administratiu.", "Sis mesos des que es va dictar l’acte administratiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 55, "Segons l’article 112.3 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques:", "Els recursos administratius contra una disposició general que es fonamenten únicament en la nul·litat d’aquesta disposició es poden interposar directament davant l’òrgan que va dictar la disposició esmentada.", "Els recursos contra un acte administratiu que es fonamenten únicament en la nul·litat d’alguna disposició administrativa de caràcter general es poden interposar directament davant l’òrgan que va dictar la disposició esmentada.", "Els recursos contra un acte administratiu que es fonamenten únicament en la nul·litat d’alguna disposició administrativa de caràcter general s’han d’interposar directament davant l’òrgan que va dictar la disposició esmentada.", "Els recursos administratius contra una disposició general que es fonamenten únicament en la nul·litat d’aquesta disposició s’han d’interposar directament davant l’òrgan que va dictar la disposició esmentada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 56, "Indicau quina de les afirmacions següents sobre els recursos administratius és correcta segons l’article 115.3 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques:", "Els vicis i els defectes que facin anul·lable un acte no poden ser al·legats pels qui els hagin causat.", "L’error o l’absència de la qualificació del recurs per part del recurrent és sempre una causa d’inadmissió.", "La falta de legitimació no és una causa d’inadmissió del recurs.", "Si ha transcorregut el termini per interposar el recurs, l’Administració ha de requerir l’interessat perquè esmeni el seu escrit."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 57, "Segons l’article 116 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, quina de les següents és una causa d’inadmissió dels recursos administratius?", "Tenir legitimació.", "Que l’acte sigui susceptible de recurs.", "Estar mancat el recurs manifestament de fonament.", "Que l’òrgan disposi de competència per resoldre el recurs."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 58, "Segons l’article 117.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, quan la impugnació es fonamenti en alguna de les causes de nul·litat de ple dret que preveu l’article 47.1 d’aquesta Llei, l’òrgan a qui competeix resoldre el recurs:", "Pot deixar sense efecte l’acte impugnat.", "Ha de suspendre l’execució de l’acte impugnat.", "Pot suspendre l’execució de l’acte impugnat.", "Ha de deixar sense efecte l’execució de l’acte impugnat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 59, "Segons l’article 119.3 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, la resolució d’un recurs administratiu:", "Requereix un tràmit d’audiència per un termini no inferior a deu dies ni superior a quinze quan s’hagi d’agreujar la situació del recurrent.", "Ha d’anar precedida sempre d’un tràmit d’audiència.", "Ha de ser congruent amb les peticions formulades pel recurrent, sense que en cap cas es pugui agreujar la seva situació inicial.", "Només ha de resoldre les qüestions de fons plantejades pels interessats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 60, "Indicau quina de les afirmacions següents és correcta segons l’article 120.2 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, relatiu a la suspensió del termini per resoldre un recurs administratiu fins que es dicti un pronunciament judicial:", "L’acord de suspensió es pot notificar als interessats.", "L’acord de suspensió s’ha de notificar als interessats, els quals el poden recórrer.", "L’acord de suspensió, contra el qual no s’hi pot interposar cap recurs, s’ha de notificar als interessats.", "L’acord de suspensió no s’ha de notificar als interessats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 61, "Indicau quina de les afirmacions següents és correcta segons l’article 121.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques:", "Els actes que no posin fi a la via administrativa poden ser recorreguts en alçada i en reposició.", "Es pot interposar el recurs de reposició i el recurs extraordinari de revisió contra els actes ferms en via administrativa.", "Els actes que posin fi a la via administrativa poden ser recorreguts en alçada.", "Els actes que no posin fi a la via administrativa poden ser recorreguts en alçada davant l’òrgan superior jeràrquic del que els va dictar."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 62, "Segons l’article 123.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, els actes administratius que posin fi a la via administrativa:", "Han de ser recorreguts en reposició davant el mateix òrgan que els hagi dictat com a requisit previ per a la impugnació davant l’ordre jurisdiccional contenciós administratiu.", "Poden ser recorreguts potestativament en reposició davant el mateix òrgan que els hagi dictat o ser impugnats directament davant l’ordre jurisdiccional contenciós administratiu.", "Han de ser recorreguts en alçada davant l’òrgan superior jeràrquic com a requisit previ per a la impugnació davant l’ordre jurisdiccional contenciós administratiu.", "Poden ser recorreguts potestativament en reposició davant l’òrgan superior jeràrquic o ser impugnats directament davant l’ordre jurisdiccional contenciós administratiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 63, "Segons l’article 125.1 de la Llei 39/2015, d’1 d'octubre, del procediment administratiu comú de les administracions públiques, contra quins actes es pot interposar el recurs extraordinari de revisió?", "Contra les disposicions generals, els actes definitius, els actes de tràmit qualificats i els actes ferms en via administrativa.", "Contra els actes definitius, els actes de tràmit qualificats i els actes ferms en via administrativa.", "Contra els actes definitius i els actes ferms en via administrativa.", "Contra els actes ferms en via administrativa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 64, "Segons l’article 42 de la Llei 3/2003, de 26 de març, de règim jurídic de l'administració de la Comunitat Autònoma de les Illes Balears, els actes dictats pel vicepresident adopten la forma de:", "Decret.", "Resolució.", "Acord.", "Ordre."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 65, "Segons l’article 42 de la Llei 3/2003, de 26 de març, de règim jurídic de l'administració de la Comunitat Autònoma de les Illes Balears, adopten la forma de decret:", "Els actes dictats pel president.", "Els actes dictats pel president i pel Govern.", "Els actes dictats pel president i per les comissions delegades.", "Els actes dictats pel president, pel Govern i per les comissions delegades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 66, "Segons l’article 48.1 de la Llei 3/2003, de 26 de març, de règim jurídic de l'administració de la Comunitat Autònoma de les Illes Balears, les actuacions que siguin d’interès per a la tramitació de l’expedient s’han de fer constar mitjançant:", "Una resolució.", "Un acord.", "Una diligència.", "Una ordre."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 67, "Segons l’article 50.1 de la Llei 3/2003, de 26 de març, de règim jurídic de l'Administració de la Comunitat Autònoma de les Illes Balears, els terminis màxims per dictar i notificar la resolució expressa en els procediments de competència de la comunitat autònoma:", "Són els que fixi la norma reguladora del procediment corresponent i no poden excedir de sis mesos.", "Són els que fixi la norma reguladora del procediment corresponent i no poden excedir de sis mesos, llevat que una llei n’estableixi un de més ampli o així es prevegi en la normativa comunitària europea.", "Són els que fixi la norma reguladora del procediment corresponent i no poden excedir de tres mesos.", "Són els que fixi la norma reguladora del procediment corresponent i no poden excedir de tres mesos, llevat que una llei n’estableixi un de més ampli o així es prevegi en la normativa comunitària europea."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 68, "Segons l’article 50.3. b) de la Llei 3/2003, de 26 de març, de règim jurídic de l'Administració de la Comunitat Autònoma de les Illes Balears, el termini màxim per dictar i notificar la resolució expressa en els procediments sancionadors abreujats respecte dels quals la comunitat autònoma disposa de competència normativa és:", "D’un any.", "De sis mesos.", "De tres mesos.", "D’un mes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 69, "Segons l’article 53.1.a de la Llei 3/2003, de 26 de març, de règim jurídic de l'Administració de la Comunitat Autònoma de les Illes Balears, exhaureixen la via administrativa:", "Els actes dictats pel president.", "Els actes dictats pel president i pel Consell de Govern.", "Els actes dictats pel president, pel Consell de Govern i pels òrgans directius de les conselleries.", "Els actes dictats pel president i pel Consell de Govern, llevat que una llei n’estableixi el contrari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 70, "Segons l’article 53.1. b) de la Llei 3/2003, de 26 de març, de règim jurídic de l'Administració de la Comunitat Autònoma de les Illes Balears, els acords de les comissions delegades del Govern:", "Exhaureixen la via administrativa.", "Exhaureixen la via administrativa, llevat que una llei n’estableixi el contrari.", "No exhaureixen la via administrativa.", "No exhaureixen la via administrativa, llevat que una llei n’estableixi el contrari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 71, "Indicau quina de les afirmacions següents és correcta segons l’article 54.1 de la Llei 3/2003, de 26 de març, de règim jurídic de l'Administració de la Comunitat Autònoma de les Illes Balears:", "La competència per resoldre els procediments de revisió d’actes nuls correspon sempre a l’òrgan que hagi dictat l’acte.", "La declaració de nul·litat requereix el dictamen previ i favorable del Consell Econòmic i Social de les Illes Balears.", "La competència per resoldre els procediments de revisió d’actes nuls correspon al Consell de Govern.", "Els procediments de revisió d’actes nuls s’inicien d’ofici per l’òrgan autor de l’acte, o a sol·licitud de la persona interessada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 72, "Segons l'article 54.2 de la Llei 3/2003, de 26 de març, de règim jurídic de l'Administració de la Comunitat Autònoma de les Illes Balears, en els procediments de revisió d’ofici de disposicions administratives:", "La competència per iniciar-los correspon a l’òrgan que les hagi aprovat i la resolució a l'òrgan superior jeràrquic.", "La competència per iniciar-los i resoldre’ls correspon al superior jeràrquic de l'òrgan que les hagi aprovat.", "La competència per iniciar-los i resoldre’ls correspon a l’òrgan que les hagi aprovat.", "La competència per iniciar-los correspon a l'òrgan superior jeràrquic i la resolució a l'òrgan que les hagi aprovat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 73, "D’acord amb l’article 55.1 de la Llei 3/2003, de 26 de març, de règim jurídic de l'Administració de la Comunitat Autònoma de les Illes Balears, quin òrgan és el competent per iniciar els procediments per declarar la lesivitat?", "L’òrgan autor de l’acte.", "El conseller competent per raó de la matèria, llevat que l’acte provengui d’una comissió delegada o del Consell de Govern, i en aquest cas correspon al Consell de Govern declarar-la.", "El conseller competent per raó de la matèria.", "L’òrgan autor de l’acte, llevat que l’acte provengui del president, i en aquest cas la declaració correspon al Consell de Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 74, "Segons l’article 56.1 de la Llei 3/2003, de 26 de març, de règim jurídic de l'Administració de la Comunitat Autònoma de les Illes Balears, quin és l’òrgan competent per revocar els actes de gravamen o desfavorables?", "El conseller competent per raó de la matèria.", "L’òrgan que hagi dictat l’acte o la disposició.", "El conseller competent per raó de la matèria, llevat que l’acte provengui d’una comissió delegada o del Consell de Govern, i en aquest cas correspon al Consell de Govern declarar-la.", "El superior jeràrquic de l’òrgan que hagi dictat l’acte o la disposició."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 75, "Segons l'article 56.3 de la Llei 3/2003, de 26 de març, de règim jurídic de l'Administració de la Comunitat Autònoma de les Illes Balears, les errates en el text publicat, respecte del text rebut, en el Butlletí Oficial de les Illes Balears:", "Poden ser corregides per l’òrgan encarregat del Butlletí, tot i que prèviament ho ha de comunicar al Consell de Govern.", "Poden ser corregides pel Consell de Govern, tot i que prèviament ho ha de comunicar a l’òrgan encarregat del butlletí.", "Poden ser corregides per l’òrgan encarregat del Butlletí, que ho ha de comunicar posteriorment a l’òrgan del qual hagi emanat l’acte o la disposició objecte de correcció.", "Poden ser corregides per l’òrgan encarregat del Butlletí, tot i que prèviament ho ha de comunicar a l’òrgan del qual hagi emanat l’acte o la disposició objecte de correcció."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 1, "La Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, té per objecte adaptar l’ordenament jurídic espanyol al:", "Reglament (UE) 2016/679 del Parlament Europeu i el Consell, de 27 d’abril de 2016, relatiu a la protecció de les persones físiques i jurídiques pel que fa al tractament de les dades personals i a la lliure circulació d’aquestes dades.", "Reglament (UE) 2016/679 del Parlament Europeu i el Consell, de 27 d’abril de 2016, relatiu a la protecció de les persones físiques pel que fa al tractament de les dades personals i a la lliure circulació d’aquestes dades.", "Reglament (UE) 2016/679 del Parlament Europeu i el Consell, de 27 d’abril de 2016, relatiu a la protecció de les persones físiques pel que fa al tractament de les seves dades personals i a la lliure circulació d’aquestes dades, i completar-ne les disposicions.", "Reglament (UE) 2016/679 del Parlament Europeu i el Consell, de 27 d’abril de 2016, relatiu a la protecció de les persones físiques i jurídiques pel que fa al tractament de les dades personals i a la lliure circulació d’aquestes dades, i completar-ne les disposicions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 2, "Quin dels tractaments de dades següents no és aplicable directament el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), perquè afecta activitats no compreses en l’àmbit d’aplicació del dret de la Unió Europea?", "Tractament de dades d’alumnes d’un centre educatiu.", "Tractaments fets en l’àmbit d’institucions penitenciàries.", "Tractament de dades per a fins comercials.", "Tractament de dades fet per empreses de telecomunicacions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 3, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, en relació amb els drets i llibertats consagrats a la Constitució i als tractats i convenis internacionals en què Espanya sigui part, qui ha de contribuir a garantir-ne l’aplicació?", "Els prestadors de serveis de la societat de la informació i els proveïdors de serveis d’Internet.", "Les persones que autoritzin el tractament de les seves dades personals.", "Exclusivament els proveïdors de serveis d’Internet.", "Exclusivament els prestadors de serveis de la societat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 4, "Indicau quin dels següents no és un dret digital reconegut a la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals:", "Dret a la intimitat davant l’ús de dispositius de videovigilància i enregistrament de sons a la llar.", "Dret a la intimitat davant la utilització de sistemes de geolocalització en l’àmbit laboral.", "Drets digitals en la negociació col·lectiva.", "Dret a l’oblit en cerques d’Internet."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 5, "El que disposen els títols de l’I al IX i els articles del 89 al 94 de la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, s’aplica a:", "Qualsevol tractament totalment automatitzat de dades personals, així com al tractament automatitzat de dades personals contingudes o destinades a ser incloses en un fitxer.", "Qualsevol tractament totalment o parcialment automatitzat de dades personals, així com al tractament no automatitzat de dades personals contingudes o destinades a ser incloses en un fitxer.", "Qualsevol tractament totalment automatitzat de dades personals, així com al tractament no automatitzat de dades personals contingudes o destinades a ser incloses en un fitxer.", "Qualsevol tractament totalment o parcialment automatitzat de dades personals, així com al tractament automatitzat de dades personals contingudes o destinades a ser incloses en un fitxer."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 6, "Indicau quina de les respostes següents no és un principi de la protecció de dades d’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals:", "Exactitud de les dades i, si és necessari, actualitzades.", "Deure de confidencialitat dels responsables i encarregats del tractament de dades, així com totes les persones que intervinguin en qualsevol fase.", "Tractament basat en el consentiment de l’afectat, i s’accepta que no hi hagi una declaració negativa.", "Consentiment dels menors d’edat, quan aquests siguin més grans de catorze anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 7, "Indicau quina de les respostes següents no és un principi de la protecció de dades d’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades):", "Minimització de dades.", "Limitació de la finalitat.", "Licitud, lleialtat i opacitat.", "Exactitud."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 8, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, quan la supressió derivi de l’exercici del dret d’oposició d’acord amb l’article 21.2 del Reglament (UE) 2016/ 679, el responsable:", "Pot conservar les dades identificatives de l’afectat necessàries per tal d’impedir tractaments futurs per a fins de màrqueting indirecte.", "No pot conservar les dades identificatives de l’afectat necessàries per tal d’impedir tractaments futurs per a fins de màrqueting indirecte.", "Pot conservar les dades identificatives de l’afectat necessàries per tal d’impedir tractaments futurs per a fins de màrqueting directe.", "No pot conservar les dades identificatives de l’afectat necessàries per tal d’impedir tractaments futurs per a fins de màrqueting directe."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 9, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), quan no s’hi ha d’aplicar el dret de supressió?", "Quan el tractament de dades personals afecti menors.", "Quan el tractament sigui necessari per exercir el dret a la llibertat d’expressió i d’informació.", "Quan les dades personals hagin estat tractades il·lícitament.", "Quan les dades personals ja no siguin necessàries en relació amb les finalitats per a les quals van ser recollides o tractades d’una altra manera."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 10, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, entre altres exigències, què implica el dret d’accés universal a Internet?", "Tothom té dret a accedir a Internet independentment de la seva condició personal, social, econòmica o geogràfica.", "Els proveïdors de serveis d’Internet han de proporcionar una oferta transparent de serveis sense discriminació per motius tècnics o econòmics.", "Es garanteix un accés universal, gratuït i no discriminatori per a tota la població.", "Tothom té dret a la llibertat d’expressió a Internet."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 11, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), l’encarregat del tractament pot recórrer a un altre encarregat:", "En cap cas.", "Sempre que ho comuniqui dins el següent mes al responsable, el qual té l’oportunitat d’autoritzar-lo o oposar-s’hi.", "Només si té l’autorització prèvia per escrit del responsable, i sempre que l’informi de qualsevol canvi previst en la incorporació o la substitució d’altres encarregats, de manera que doni al responsable l’oportunitat d’oposar-s’hi.", "Sempre que ho consideri oportú, atès que aquest reglament autoritza l’encarregat a disposar dels recursos que consideri millors per complir la seva funció d’acord amb la normativa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 12, "D’acord amb el títol V de la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, els responsables i encarregats del tractament han de designar un delegat de protecció de dades (senyalau la resposta incorrecta):", "Quan es tracti de distribuïdors i comercialitzadors d’energia elèctrica i els distribuïdors i comercialitzadors de gas natural.", "Quan es tracti d’empreses de serveis d’inversió, regulades per la legislació del mercat de valors.", "Quan es tracti de tribunals que actuïn en exercici de la seva funció judicial.", "Quan es tracti d’entitats asseguradores i reasseguradores."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 13, "D’acord amb el títol V de la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, els responsables i encarregats del tractament han de comunicar a l’Agència Espanyola de Protecció de Dades o, en el seu cas, a les autoritats autonòmiques de protecció de dades, les designacions, els nomenaments i els cessaments dels delegats de protecció de dades:", "En el termini de deu dies, tant en els supòsits en què estiguin obligades a designar-los com en el cas que sigui voluntària.", "En el termini de deu dies en els supòsits en què estiguin obligades a designar-los però no en el cas que sigui voluntària.", "En el termini de quinze dies, tant en els supòsits en què estiguin obligades a designar-los com en el cas que sigui voluntària.", "En el termini de quinze dies en els supòsits en què estiguin obligades a designar-los però no en el cas que sigui voluntària."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 14, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), el principi de minimització de dades en el tractament de dades suposa que les dades personals han de ser:", "Adequades, pertinents i limitades al que és necessari en relació amb els fins per als quals són tractades.", "Exactes i, si cal, actualitzades.", "Recollides amb fins determinats, explícits i legítims, i no seran tractades ulteriorment de manera incompatible amb aquests fins.", "Tractades de manera lícita, lleial i transparent en relació amb l’interessat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 15, "Indicau quina de les respostes següents no està inclosa entre les exigències que estableix la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, per garantir el dret d’accés universal a Internet:", "Tothom té dret a accedir a Internet independentment de la condició personal, social, econòmica o geogràfica.", "L’accés a Internet d’homes i dones ha de procurar la superació de la bretxa de gènere tant en l’àmbit personal com laboral.", "La garantia efectiva del dret d’accés a Internet ha d’atendre la realitat específica dels entorns rurals.", "Tothom té dret a la llibertat d’expressió a Internet."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 16, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), el dret a la portabilitat de les dades suposa que l’interessat té dret a rebre les dades personals que el concerneixin i que hagi facilitat a un responsable del tractament en un format estructurat, d’ús comú i lectura mecànica:", "Per suprimir-les o modificar-les sense que ho impedeixi el responsable a qui les hagi facilitades.", "I a transmetre-les a un altre responsable del tractament, la qual cosa pot impedir el responsable a qui les hagi facilitades.", "Per suprimir-les o modificar-les, la qual cosa pot impedir el responsable al qual les hagi facilitades.", "I a transmetre-les a un altre responsable del tractament sense que ho impedeixi el responsable al qual les hagi facilitades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 17, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, l’Agència Espanyola de Protecció de Dades té la condició de representant comú de les autoritats de protecció de dades del Regne de Espanya:", "Al Parlament Europeu.", "A la Comissió Europea.", "Al Comitè Europeu de Protecció de Dades.", "Al Consell Europeu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 18, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, què implica el dret a l’educació digital?", "Que l’accés a Internet ha de garantir condicions d’igualtat per a les persones que tenguin necessitats especials.", "Que es garanteix un accés universal, assequible, de qualitat i no discriminatori per a tota la població.", "Que el sistema educatiu ha de garantir la plena inserció de l’alumnat en la societat digital i l’aprenentatge d’un consum responsable i un ús crític i segur dels mitjans digitals.", "Que els usuaris tenen dret a la seguretat de les comunicacions que transmetin i rebin mitjançant Internet."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 19, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, el tractament de les dades dels menors de catorze anys, fonamentat en el consentiment:", "No és lícit en cap cas i té especial protecció.", "Només és lícit si consta el del titular de la pàtria potestat o tutela.", "És lícit en qualsevol cas.", "Només és lícit si consta el del titular de la pàtria potestat o tutela i el del responsable del tractament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 20, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, l’Agència Espanyola de Protecció de Dades ha de destinar el resultat positiu dels seus ingressos a:", "La caixa única de l’Administració de l’Estat.", "La dotació de les seves reserves per tal de garantir-ne la plena independència.", "La dotació de reserves per finançar les autoritats de control autonòmiques.", "El manteniment dels registres d’activitats de tractament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 21, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, els actes i les disposicions que dicti la presidència de l’Agència Espanyola de Protecció de Dades:", "No posen fi a la via administrativa, i són recurribles mitjançant un recurs d’alçada davant el Ministeri de Justícia.", "No posen fi a la via administrativa, i són recurribles mitjançant un recurs d’alçada davant el Ministeri d’Afers Econòmics i Transformació Digital.", "Posen fi a la via administrativa, i són recurribles, directament, davant la Sala Contenciosa Administrativa de l’Audiència Nacional.", "Posen fi a la via administrativa, i són recurribles, directament, davant la Sala Social de l’Audiència Nacional."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 22, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), quan el tractament de dades personals té per objecte el màrqueting directe:", "L’interessat té dret a oposar-se en tot moment al tractament de les dades personals que el concerneixin, inclosa l’elaboració de perfils.", "L’interessat té dret a oposar-se en tot moment al tractament de les dades personals que el concerneixin, excepte l’elaboració de perfils.", "L’autoritat de control té dret a oposar-se en tot moment al tractament de les dades personals que el concerneixin, inclosa l’elaboració de perfils.", "L’autoritat de control té dret a oposar-se en tot moment al tractament de les dades personals que el concerneixin, excepte l’elaboració de perfils."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 23, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, què implica el dret a la protecció dels menors a Internet?", "La utilització o difusió d’imatges o informació personal de menors a les xarxes socials i serveis de la societat de la informació equivalents que puguin implicar una intromissió il·legítima en els seus drets fonamentals determina la intervenció del Ministeri Fiscal.", "El sistema educatiu ha de garantir la plena inserció de l’alumnat en la societat digital i l’aprenentatge d’un consum responsable i un ús crític i segur dels mitjans digitals.", "S’ha de garantir un accés universal, assequible, de qualitat i no discriminatori per a tota la població, inclosos els menors.", "Els usuaris menors tenen dret a la seguretat de les comunicacions que transmetin i rebin a través d’Internet."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 24, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, l’Agència Espanyola de Protecció Dades ha d’elaborar i aprovar la relació de llocs de treball:", "En el marc dels criteris establerts pel Ministeri d’Hisenda.", "En el marc dels criteris establerts pel Ministeri de Presidència.", "En el marc dels criteris establerts pel Ministeri de Justícia.", "En el marc dels criteris establerts pel Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 25, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, les autoritats autonòmiques de protecció de dades personals poden exercir les funcions i potestats que estableixen els articles 57 i 58 del Reglament (UE) 2016/679, d’acord amb la normativa autonòmica, quan es refereixin a (senyalau la resposta incorrecta):", "Tractaments dels quals siguin responsables les entitats integrants del sector públic de la comunitat autònoma corresponent o de les entitats locals incloses en el seu àmbit territorial.", "Tractaments duits a terme per persones físiques o jurídiques per a l’exercici de les funcions públiques en matèries que siguin competència de l’Administració autonòmica o local corresponent.", "Tractaments duits a terme per persones físiques o jurídiques per a fins de màrqueting directe.", "Tractaments que estiguin expressament prevists, si s’escau, als estatuts d’autonomia respectius."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 26, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, el tractament de dades personals només es pot considerar fonamentat en el compliment d’una missió duita a terme en interès públic o en l’exercici de poders públics conferits al responsable, en els termes prevists a l’article 6.1.e) del Reglament (UE) 2016/679:", "Quan derivi d’una competència atribuïda per una norma de dret de la Unió Europea o una norma amb rang de llei.", "Quan derivi d’una competència atribuïda per una norma reglamentària de desplegament d’aquesta llei.", "Quan derivi d’una competència atribuïda per una norma de dret de la Unió Europea.", "Quan derivi d’una competència atribuïda per una norma amb rang de llei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 27, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, què implica el dret a l’actualització d’informacions en mitjans de comunicació digitals?", "Els responsables de xarxes socials i serveis equivalents han d’adoptar protocols adequats per possibilitar l’exercici del dret de rectificació davant dels usuaris que difonguin continguts que atemptin contra el dret a l’honor, la intimitat personal i familiar a Internet i el dret a comunicar o rebre lliurement informació veraç.", "Qualsevol persona té dret al fet que els motors de cerca a Internet eliminin de les llistes de resultats que s’obtenguin després d’una cerca efectuada a partir del seu nom els enllaços publicats que contenguin informació relativa a aquesta persona quan siguin inadequats, inexactes, no pertinents, no actualitzats o excessius.", "Qualsevol persona té dret a sol·licitar motivadament dels mitjans de comunicació digitals la inclusió d’un avís d’actualització prou visible al costa de les notícies que la concerneixin quan la informació continguda en la notícia original no reflecteixi la seva situació actual com a conseqüència de circumstàncies que s’hagin produït després de la publicació, i li causi un perjudici.", "Els usuaris tenen dret a la seguretat de les comunicacions que transmetin i rebin mitjançant Internet. Els proveïdors de serveis d’Internet han d’informar els usuaris dels seus drets."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 28, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), quina de les condicions següents no suposa la licitud del tractament de dades personals?", "Que el tractament sigui necessari per a l’execució d’un contracte en què l’interessat és part o per a l’aplicació a petició d’aquest de mesures precontractuals.", "Que el tractament sigui necessari per complir una obligació legal aplicable al particular.", "Que el tractament sigui necessari per protegir interessos vitals de l’interessat o d’una altra persona física.", "Que l’interessat hagi donat el consentiment per al tractament de les seves dades personals per a un o diversos fins específics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 29, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), quan l’interessat és objecte d’una decisió basada únicament en el tractament automatitzat i la decisió es basa en el consentiment explícit de l’interessat, aquest té com a mínim el dret a:", "Obtenir intervenció humana per part del responsable, a expressar el seu punt de vista i a impugnar la decisió.", "Sense obtenir intervenció humana per part del responsable, expressar el seu punt de vista i impugnar la decisió.", "Obtenir intervenció humana per part del responsable, expressar el seu punt de vista però no impugnar la decisió.", "Sense obtenir intervenció humana per part del responsable, expressar el seu punt de vista però no impugnar la decisió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 30, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, indicau quina de les respostes següents és una infracció molt greu:", "La resistència o l’obstrucció de l’exercici de la funció inspectora per l’autoritat de protecció de dades competent.", "El tractament de dades personals d’un menor d’edat sense obtenir-ne el consentiment, quan tengui capacitat per a això, o el del titular de la seva pàtria potestat o tutela, de conformitat amb l’article 8 del Reglament (UE) 2016/679.", "El trencament, com a conseqüència de la manca de la diligència deguda, de les mesures tècniques i organitzatives que s’hagin implantat d’acord amb el que exigeix l’article 32.1 del Reglament (UE) 2016/679.", "No cooperar amb les autoritats de control en l’exercici de les seves funcions en els supòsits no prevists en l’article 72 d’aquesta llei orgànica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 31, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), quan el tractament es basa en el consentiment de l’interessat:", "L’interessat té dret a retirar-ne el consentiment a partir d’un any des de la concessió.", "L’interessat té dret a retirar-ne el consentiment a partir dels dos anys des de la concessió.", "L’interessat té dret a retirar-ne el consentiment a partir dels sis mesos des de la concessió.", "L’interessat té dret a retirar el consentiment en qualsevol moment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 32, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, què implica el dret a la intimitat i l’ús de dispositius digitals en l’àmbit laboral?", "En cap cas s’admet la instal·lació de sistemes d’enregistrament de sons ni de videovigilància en llocs destinats al descans o l’esbargiment dels treballadors o dels empleats públics, com ara vestuaris, lavabos, menjadors i anàlegs.", "Els ocupadors poden tractar les dades obtingudes a través de sistemes de geolocalització per a l’exercici de les funcions de control dels treballadors o dels empleats públics previstes, respectivament, en l’article 20.3 de l’Estatut dels treballadors i en la legislació de funció pública, sempre que aquestes funcions s’exerceixin dins el seu marc legal i amb els límits inherents a aquest.", "L’ocupador pot accedir als continguts derivats de l’ús de mitjans digitals facilitats als treballadors als únics efectes de controlar el compliment de les obligacions laborals o estatutàries i de garantir la integritat dels dispositius esmentats.", "Els treballadors i els empleats públics tenen dret a la desconnexió digital a fi de garantir, fora del temps de treball legalment o convencionalment establert, el respecte del seu temps de descans, permisos i vacances, així com de la seva intimitat personal i familiar."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 33, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, indicau quina de les següents és una infracció greu:", "La reversió deliberada d’un procediment d’anonimització per tal de permetre la reidentificació dels afectats.", "L’incompliment del deure de l’encarregat del tractament de notificar al responsable del tractament les violacions de seguretat de què tengui coneixement.", "L’impediment o l’obstaculització o la no atenció reiterada de l’exercici dels drets que estableixen els articles 15 a 22 del Reglament (UE) 2016/679.", "L’incompliment de l’obligació de bloqueig de les dades que estableix l’article 32 d’aquesta llei orgànica quan sigui exigible."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 34, "D’acord amb l’article 7 del Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), en avaluar si el consentiment s’ha donat lliurement, s’ha de tenir en compte tant com sigui possible si:", "L’execució d’un contracte se supedita al consentiment al tractament de dades personals que no són necessàries per a l’execució del contracte esmentat.", "El particular interessat és més gran de 65 anys.", "L’execució d’un contracte es fa fora de la Unió Europea.", "El particular interessat és menor de 18 anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 35, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, què implica el dret a la intimitat davant l’ús de dispositius de videovigilància i d’enregistrament de sons al lloc de feina?", "Que els ocupadors poden tractar les imatges obtingudes a través de sistemes de càmeres o càmeres de vídeo per a l’exercici de les funcions de control dels treballadors o els empleats públics previstes, respectivament, en l’article 20.3 de l’Estatut dels Treballadors i en la legislació de funció pública, sempre que aquestes funcions s’exerceixin dins el seu marc legal i amb els límits inherents a aquest.", "Que es permet la instal·lació de sistemes de gravació de sons i de videovigilància en llocs destinats al descans o l’esbargiment dels treballadors o els empleats públics, com ara vestuaris, lavabos, menjadors i anàlegs.", "Que els ocupadors no estan obligats a informar els treballadors o els empleats públics i, si escau, els seus representants, sobre la mesura de tractar les imatges obtingudes a través de sistemes de càmeres o càmeres de vídeo per a l’exercici de les funcions de control dels treballadors o els empleats públics.", "Que s’ha de preservar el dret a la desconnexió digital en els supòsits de realització total o parcial del treball a distància així com al domicili de l’empleat vinculat a l’ús amb finalitats laborals d’eines tecnològiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 36, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, els responsables i encarregats, tenint en compte els elements enumerats en els articles 24 i 25 del Reglament (UE) 2016 /679, han de determinar les mesures tècniques i organitzatives apropiades que han d’aplicar per tal de garantir i acreditar que el tractament és conforme, entre d’altres:", "A aquesta llei orgànica i les seves normes de desenvolupament.", "A l’estat de la tècnica.", "Al contracte que reguli les obligacions de tots dos.", "A la legislació local."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 37, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, indicau quina de les següents és una infracció lleu:", "El tractament de dades personals sense dur a terme una valoració prèvia dels elements esmentats en l’article 28 d’aquesta llei orgànica.", "No disposar del registre d’activitats de tractament que estableix l’article 30 del Reglament (UE) 2016/679.", "La manca d’atenció per part del representant a la Unió del responsable o de l’encarregat del tractament de les sol·licituds que efectuïn l’autoritat de protecció de dades o els afectats.", "L’incompliment de l’obligació de notificació relativa a la rectificació o la supressió de dades personals o la limitació del tractament exigida per l’article 19 del Reglament (UE) 2016/679."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 38, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, què implica el dret a la intimitat davant l’ús de dispositius de videovigilància i d’enregistrament de sons al lloc de feina?", "Que els treballadors i els empleats públics tenen dret a la protecció de la seva intimitat en l’ús dels dispositius digitals posats a la seva disposició pel seu ocupador.", "Que es permet la instal·lació de sistemes d’enregistrament de sons i de videovigilància en llocs destinats al descans o l’esbargiment dels treballadors o els empleats públics, com ara vestuaris, lavabos, menjadors i anàlegs.", "Que els ocupadors poden tractar les dades obtingudes a través de sistemes de geolocalització per a l’exercici de les funcions de control dels treballadors o dels empleats públics.", "Que els ocupadors poden tractar les imatges obtingudes a través de sistemes de càmeres o càmeres de vídeo per a l’exercici de les funcions de control dels treballadors o els empleats públics previstes, respectivament, en l’article 20.3 de l’Estatut dels treballadors i en la legislació de funció pública, sempre que aquestes funcions s’exerceixin dins el seu marc legal i amb els límits inherents a aquest."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 39, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), el tractament de les dades personals d’un menor de 16 anys només es considera lícit:", "Si el consent el menor major de 14 anys.", "Si el consentiment el dona o l’autoritza el titular de la pàtria potestat o tutela del menor.", "Si el consent el menor major de 12 anys.", "No es pot fer tractament de dades personals de menors de 16 anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 40, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, interromp la prescripció de la infracció:", "La iniciació, fins i tot sense el coneixement de l’interessat, del procediment sancionador.", "La iniciació, amb coneixement de l’interessat, del procediment sancionador.", "La iniciació, amb coneixement de l’interessat, del procediment de cobrament executiu de la sanció.", "La iniciació, fins i tot sense el coneixement de l’interessat, del procediment de cobrament executiu de la sanció."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 41, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, una vegada interrompuda la prescripció de la infracció per la iniciació, amb coneixement de l’interessat, del procediment sancionador, s’ha de reiniciar el termini de prescripció:", "Si l’expedient sancionador està paralitzat durant més de nou mesos per causes no imputables al presumpte infractor.", "Si l’expedient sancionador està paralitzat durant més de tres mesos per causes no imputables al presumpte infractor.", "Si l’expedient sancionador està paralitzat durant més de sis mesos per causes no imputables al presumpte infractor.", "Si l’expedient sancionador està paralitzat durant més de nou mesos, sempre que ho sol·liciti l’interessat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 42, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, indicau la resposta incorrecta en relació amb el dret digital de protecció de dades dels menors a Internet:", "Els centres educatius han de garantir la protecció de l’interès superior del menor i els drets fonamentals.", "La publicació o difusió de dades personals del menor a través de serveis de la societat de la informació ha de comptar amb el consentiment del Ministeri Fiscal.", "Qualssevol persones físiques o jurídiques que desenvolupin activitats en què participin menors d’edat han de garantir la protecció de l’interès superior del menor i els drets fonamentals.", "Qualssevol persones físiques o jurídiques que desenvolupin activitats en què participin menors d’edat han de garantir especialment el dret a la protecció de dades personals en la publicació o difusió de les dades personals a través de serveis de la societat de la informació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 43, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, per a l’adopció de les mesures tècniques i organitzatives apropiades que han d’aplicar els responsables i encarregats del tractament s’han de tenir en compte, en particular, els riscs superiors que es poden produir (senyalau la resposta incorrecta):", "Quan el tractament impliqui una avaluació d’aspectes personals dels afectats per tal de crear o utilitzar perfils personals d’aquests.", "Quan es produeixi un tractament massiu que impliqui un gran nombre d’afectats.", "Quan les dades personals hagin estat objecte de transferència, amb caràcter habitual, als estats de la Unió respecte dels quals no s’hagi declarat un nivell adequat de protecció.", "Quan el tractament pugui generar situacions de discriminació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 44, "Quan les dades personals siguin obtingudes de l’afectat, el responsable del tractament pot donar compliment al deure d’informació que estableix l’article 13 del Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades):", "Facilitant a l’afectat la informació bàsica del tractament d’aquestes dades.", "Indicant a l’afectat una adreça electrònica o un altre mitjà que permeti accedir de manera senzilla i immediata a la informació bàsica.", "Indicant a l’afectat un correu postal que permeti accedir de manera immediata a la informació bàsica.", "Facilitant a l’afectat una adreça electrònica que permeti accedir en el futur a la informació bàsica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 45, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, indicau quina de les següents és una infracció lleu:", "No cooperar amb les autoritats de control en l’exercici de les seves funcions en els supòsits no prevists en l’article 72 d’aquesta llei orgànica.", "No disposar del registre d’activitats de tractament que estableix l’article 30 del Reglament (UE) 2016/679.", "No possibilitar la participació efectiva del delegat de protecció de dades en totes les qüestions relatives a la protecció de dades personals, no donar-li suport o interferir en l’exercici de les seves funcions.", "Incomplir l’obligació de suprimir les dades referides a una persona morta quan això sigui exigible d’acord amb l’article 3 d’aquesta llei orgànica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 46, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, quan les dades personals s’obtenguin de l’afectat, el responsable del tractament ha de facilitar a l’afectat la informació bàsica del tractament de aquestes dades, que ha de contenir:", "La identitat del responsable del tractament i del seu representant, si escau.", "La possibilitat d’exercir els principis de protecció de dades que estableixen els articles del 15 al 22 del Reglament (UE) 2016/679.", "Els resultats del tractament.", "Els mitjans de consentiment del tractament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 47, "Indicau quina de les respostes següents no està inclosa entre les exigències que estableix la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, per garantir el dret a l’oblit en cerques d’Internet:", "L’exercici del dret a l’oblit en cerques d’Internet impedeix l’accés a la informació publicada al lloc web mitjançant la utilització d’altres criteris de cerca diferents del nom de qui exerceixi el dret.", "El dret a l’oblit en cerques d’Internet subsistirà encara que sigui lícita la conservació de la informació publicada al lloc web al qual es dirigeixi l’enllaç i aquest no procedeixi a esborrar-lo prèviament o simultàniament.", "Qualsevol persona té dret que els motors de cerca a Internet eliminin de les llistes de resultats que s’obtenguin després d’una cerca efectuada a partir del seu nom quan les circumstàncies personals que invoqui l’afectat evidenciïn la prevalença dels seus drets sobre el manteniment dels enllaços pel servei de cerca a Internet.", "Qualsevol persona té dret que els motors de cerca a Internet eliminin de les llistes de resultats que s’obtenguin després d’una cerca efectuada a partir del seu nom els enllaços publicats que contenguin informació relativa a aquesta persona quan siguin no pertinents, entre altres motius."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 48, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, el registre d’activitats ha d’especificar, segons les seves finalitats:", "Els perfils duits a terme i les altres circumstàncies que estableix el Reglament esmentat.", "Les dades personals tractades i les altres circumstàncies que estableix el Reglament esmentat.", "Les persones les dades personals de les quals han estat tractades i les altres circumstàncies que estableix el Reglament esmentat.", "Les activitats de tractament duites a terme i les altres circumstàncies que estableix el Reglament esmentat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 49, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), cada autoritat de control ha de garantir que la imposició de les multes administratives d’acord amb aquest Reglament siguin en cada cas individual:", "Eficients, justes i dissuasives.", "Justes, dissuasives i correctives.", "Efectives, proporcionades i dissuasives.", "Eficients, proporcionades i correctives."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 50, "Quan el responsable o l’encarregat d’un tractament sigui l’administració d’una comunitat autònoma i cometi alguna de les infraccions a què fa referència la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, i la infracció sigui imputable a autoritats o directius i s’acrediti l’existència d’informes tècnics o recomanacions per al tractament que no s’hagin atès degudament:", "En la resolució en què s’imposi la sanció s’ha d’incloure una amonestació amb la denominació del càrrec responsable i se n’ha d’ordenar la publicació en el butlletí oficial autonòmic que correspongui.", "En la resolució en què s’imposi la sanció s’ha d’incloure la disposició del cessament del càrrec responsable i se n’ha d’ordenar la publicació en el butlletí oficial autonòmic que correspongui.", "En la resolució s’ha d’imposar la sanció directament al càrrec responsable i se n’ha d’ordenar la publicació en el butlletí oficial autonòmic que correspongui.", "En la resolució en què s’imposi la sanció s’ha d’incloure la disposició del cessament del càrrec responsable, però no s’ha de publicar per no vulnerar la mateixa llei orgànica de protecció de dades personals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 51, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, indicau la resposta incorrecta en relació amb les disposicions generals sobre l’exercici dels drets de les persones pel que fa al tractament de dades personals.", "Els mitjans han de ser fàcilment accessibles per a l’afectat.", "L’encarregat del tractament ha de facilitar un correu electrònic de contacte.", "El responsable del tractament està obligat a informar l’afectat sobre els mitjans a la seva disposició per exercir els drets que li corresponen.", "L’exercici del dret no pot ser denegat pel sol motiu d’optar l’afectat per un altre mitjà."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 52, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, indicau la resposta correcta en relació amb la prescripció de les sancions imposades en aplicació del Reglament (UE) 2016/679 i d’aquesta llei orgànica:", "Les sancions per un import comprès entre 40.001 i 300.000 euros prescriuen al cap de tres anys.", "Les sancions imposades per infraccions greus prescriuen en el termini de 2 anys.", "Les sancions per un import comprès entre 40.001 i 300.000 euros prescriuen a cap de dos anys.", "Les sancions imposades per infraccions greus prescriuen en el termini de tres anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 53, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, els responsables i encarregats del tractament de dades així com totes les persones que intervenguin en qualsevol fase d’aquest tractament estan subjectes:", "Al deure de custòdia.", "Al deure de confiança.", "Al deure de confidencialitat.", "Al deure de sigil."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 54, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, el responsable del tractament està obligat a bloquejar les dades:", "Quan dugui a terme actuacions de manteniment.", "Quan contracti un altre encarregat.", "Quan contracti un altre delegat de protecció de dades.", "Quan en dugui a terme la rectificació o la supressió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 55, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, el tractament de dades personals relatives a condemnes i infraccions penals només es pot dur a terme quan es trobi emparat:", "En una norma de dret de la Unió o en aquesta llei orgànica.", "En aquesta llei orgànica o en altres normes de rang legal.", "En aquesta llei orgànica.", "En una norma de dret de la Unió, en aquesta llei orgànica o en altres normes de rang legal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 56, "El dret a la transparència de la informació regulat en el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), estableix les formes en què pot ser facilitada la informació (indicau la incorrecta):", "Per escrit.", "Per mitjans electrònics.", "Verbalment, si l’interessat ho ha sol·licitat i s’identifica per un altre mitjà.", "Verbalment, si és el mitjà elegit per l’encarregat del tractament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 57, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, en relació amb el dret al testament digital (indicau la resposta correcta).", "Les persones legitimades a l’accés a continguts gestionats per prestadors de serveis de la societat de la informació sobre persones difuntes poden decidir en qualsevol cas sobre el manteniment o l’eliminació dels perfils personals d'aquestes persones difuntes en xarxes socials o serveis equivalents.", "La persona morta no pot prohibir l’accés, per part de persones vinculades al mort o hereus, a continguts gestionats per prestadors de serveis de la societat de la informació.", "En cas de persones mortes menors d’edat, les facultats d’accés a continguts gestionats per prestadors de serveis de la societat de la informació també les pot exercir el Ministeri Fiscal, que sempre ha d’actuar d’ofici.", "Les persones legitimades a l’accés a continguts gestionats per prestadors de serveis de la societat de la informació sobre persones mortes poden decidir sobre el manteniment o l’eliminació dels perfils personals de persones difuntes en xarxes socials o serveis equivalents, tret que el difunt hagi decidit sobre aquesta circumstància, cas en què cal atenir-se a les seves instruccions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 58, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), el tractament de les dades personals d’un menor:", "Es considera lícit quan tengui com a mínim 14 anys. Els estats membres poden establir per llei una edat inferior a aquests fins, sempre que aquesta no sigui inferior a 12 anys.", "Es considera lícit quan tengui com a mínim 16 anys. Els estats membres poden establir per llei una edat inferior a aquests fins, sempre que aquesta no sigui inferior a 12 anys.", "Es considera lícit quan tengui com a mínim 14 anys. Els estats membres poden establir per llei una edat inferior a aquests fins, sempre que aquesta no sigui inferior a 13 anys.", "Es considera lícit quan tengui com a mínim 16 anys. Els estats membres poden establir per llei una edat inferior a aquests fins, sempre que aquesta no sigui inferior a 13 anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 59, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, en decidir la imposició d’una multa administrativa i la quantia s’ha de tenir en compte (indicau la resposta incorrecta):", "L’existència d’un procés de fusió per absorció posterior a la comissió de la infracció, que no es pot imputar a l’entitat absorbent.", "L’afectació als drets de les persones vulnerables i d’edat avançada.", "La disposició, quan no sigui obligatori, d’un delegat de protecció de dades.", "La possibilitat que la conducta de l’afectat hagi pogut induir la comissió de la infracció."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 60, "D’acord amb el dret a la transparència de la informació regulat en el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), si el responsable del tractament no tramita la sol·licitud de l’interessat:", "L’ha d’informar sense dilació, i com a molt transcorreguts 15 dies de la recepció de la sol·licitud, de les raons per les quals no ha actuat i de la possibilitat de presentar una altra sol·licitud.", "L’ha d’informar sense dilació, i com a molt transcorreguts 15 dies de la recepció de la sol·licitud, de les raons per les quals no ha actuat i de la possibilitat de presentar una reclamació davant una autoritat de control i d’exercir accions judicials.", "L’ha d’informar sense dilació, i com a molt transcorregut un mes de la recepció de la sol·licitud, de les raons per les quals no ha actuat i de la possibilitat de presentar una altra sol·licitud.", "L’ha d’informar sense dilació, i com a molt transcorregut un mes de la recepció de la sol·licitud, de les raons per les quals no ha actuat i de la possibilitat de presentar una reclamació davant una autoritat de control i d’exercir accions judicials."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 61, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, la presidència i l’adjunt de l’Agència Espanyola de Protecció de Dades han de ser nomenats pel Consell de Ministres mitjançant:", "Un reial decret.", "Una llei ordinària", "Una ordre ministerial.", "Un acord."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 62, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, l’accés per part d’un encarregat de tractament a les dades personals que siguin necessàries per a la prestació d’un servei al responsable:", "No es considera una comunicació de dades en cap cas.", "No es considera una comunicació de dades sempre que es compleixi el que estableix el Reglament (UE) 2016/679, aquesta llei orgànica i les seves normes de desplegament.", "Es considera una comunicació de dades en qualsevol cas.", "Es considera una comunicació de dades sempre que es compleixi el que estableix el Reglament (UE) 2016/679, aquesta llei orgànica i les seves normes de desplegament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 63, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, la presidència de l’Agència Espanyola de Protecció de Dades ha d’estar assessorada per un Consell Consultiu compost pels membres següents (senyalau la resposta incorrecta):", "Un expert proposat per la Federació Espanyola de Municipis i Províncies.", "Dos experts proposats per les organitzacions empresarials.", "Dos experts proposats pel Consell de Consumidors i Usuaris.", "Un diputat, proposat pel Congrés dels Diputats"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 64, "D’acord amb el dret a la transparència de la informació regulat en el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), quan el responsable del tractament tengui dubtes raonables sobre la identitat de la persona física que presenta la sol·licitud d’accés a les dades personals:", "Pot cobrar per facilitar aquesta informació.", "Pot respondre aquesta sol·licitud en un termini més ampli.", "S’ha de comunicar amb l’afectat perquè hi consenti.", "Pot sol·licitar que es faciliti la informació addicional necessària per confirmar la identitat de l’interessat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 65, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), si un responsable o un encarregat del tractament incompleix de forma intencionada o negligent, per a les mateixes operacions de tractament o operacions vinculades, diverses disposicions d’aquest Reglament, la quantia total de la multa administrativa:", "No ha de ser superior a la quantia prevista per a les infraccions més greus.", "No ha de ser superior al doble de la quantia prevista per a totes les infraccions.", "Ha de ser la suma de les quanties previstes per a totes les infraccions.", "No ha de ser superior al triple de la quantia prevista per a totes les infraccions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 66, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, el dret d’accés s’entén atorgat si el responsable del tractament facilita a l’afectat un sistema d’accés remot, directe i segur a les dades personals:", "Que garanteixi, temporalment per un mínim de 6 mesos, l’accés a la seva totalitat.", "Que garanteixi, de manera permanent, l’accés a la seva totalitat.", "Que garanteixi, de manera temporal pel termini sol·licitat amb un mínim de 6 mesos, l’accés a la seva totalitat.", "Que garanteixi, de manera temporal, l’accés parcial a la informació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 67, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), en decidir la imposició d’una multa administrativa i la quantia en cada cas individual s’ha de tenir degudament en compte (indicau la resposta incorrecta):", "Qualsevol mesura presa pel responsable o l’encarregat del tractament per pal·liar els danys i els perjudicis patits pels interessats.", "La intencionalitat o negligència en la infracció.", "Qualsevol infracció anterior comesa pel responsable o l’encarregat del tractament.", "El grau de responsabilitat del delegat de protecció de dades del tractament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 68, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, el responsable del tractament ha de determinar si, quan finalitzi la prestació dels serveis de l’encarregat, les dades personals han de ser (indicau la resposta incorrecta):", "Destruïdes.", "Tornades al responsable.", "Lliurades a un nou encarregat.", "Tornades als interessats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 69, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, als efectes que estableix l’article 12.5 del Reglament (UE) 2016/679 es pot considerar repetitiu l’exercici del dret d’accés:", "Quan el dret d’accés sigui exercit més d’una vegada durant el termini de tres mesos, tret que hi hagi una causa legítima.", "Quan el dret d’accés sigui exercit més d’una vegada durant el termini de quatre mesos, tret que hi hagi una causa legítima.", "Quan el dret d’accés sigui exercit més d’una vegada durant el termini de sis mesos, tret que hi hagi causa legítima.", "Quan el dret d’accés sigui exercit més d’una vegada durant el termini d’un any, tret que hi hagi una causa legítima."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 70, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, en relació amb les polítiques d’impuls dels drets digitals:", "El Govern, mitjançant un decret del Consell de Govern, ha d’elaborar un pla d’accés a Internet.", "El Govern, en col·laboració amb les comunitats autònomes, ha d’elaborar un pla d’accés a Internet.", "El Consell Consultiu de l’Agència Espanyola de Protecció de Dades ha d’elaborar un pla d’accés a Internet.", "L’Agència Espanyola de Protecció de Dades, en col·laboració amb les autoritats autonòmiques de protecció de dades, ha d’elaborar un pla d’accés a Internet."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 71, "D’acord amb el Reglament (UE) 2016/679 del Parlament Europeu i del Consell, de 27 de abril de 2016 (Reglament general de protecció de dades), en decidir la imposició d’una multa administrativa i la quantia en cada cas individual s’ha de tenir degudament en compte (indicau la resposta incorrecta):", "La intencionalitat o la negligència en la infracció.", "Qualsevol mesura presa pel responsable o encarregat del tractament per pal·liar els danys i perjudicis patits pels interessats.", "Qualsevol mesura presa pel delegat de protecció de dades per pal·liar els danys i perjudicis patits pels interessats.", "L’adhesió a codis de conducta en virtut de l’article 40 o a mecanismes de certificació aprovats d’acord amb l’article 42."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 72, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, quan finalitzi la prestació dels serveis de l’encarregat, no escau la destrucció de les dades:", "Quan hi hagi una previsió legal que obligui a conservar-les.", "Quan la situació de la tecnologia no ho permeti.", "Quan hi ha una previsió que l’encarregat reutilitzi aquestes dades.", "Quan hi ha una previsió que el responsable de la protecció de les dades les reutilitzi."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 73, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, l’activitat d’investigació de l’Agència Espanyola de Protecció de Dades l’han de dur a terme:", "Els funcionaris de l’Agència Espanyola de Protecció de Dades o funcionaris aliens a aquesta habilitats expressament per la presidència.", "Exclusivament els funcionaris de l’Agència Espanyola de Protecció de Dades.", "Els funcionaris de l’Agència Espanyola de Protecció de Dades o funcionaris aliens a aquesta habilitats expressament pel Ministeri de Justícia.", "Exclusivament els funcionaris aliens habilitats expressament per la presidència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 74, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, estan obligats a proporcionar a l’Agència Espanyola de Protecció de Dades les dades, els informes, els antecedents i els justificants necessaris per dur a terme la seva activitat d‘investigació:", "Les administracions públiques, excloses les tributàries i de la Seguretat Social, i els particulars.", "Les administracions públiques, incloses les tributàries i de la Seguretat Social, i els particulars.", "Només els particulars.", "Només les administracions públiques, incloses les tributàries i de la Seguretat Social."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 75, "D’acord amb la Llei orgànica 3/2018, de 5 de desembre, de protecció de dades personals i garantia dels drets digitals, quan l’afectat triï un mitjà diferent del que se li ofereix que suposi un cost desproporcionat per exercir el dret d’accés:", "La sol·licitud s’ha de considerar considerada excessiva, per la qual cosa aquest afectat ha d’assumir l’excés de costos que la seva tria comporti.", "La sol·licitud ha de ser considerada excessiva, per la qual cosa aquest afectat ha d’assumir el 50 % de l’excés de costos que la seva tria comporti.", "La sol·licitud ha de ser considerada excessiva, per la qual cosa el responsable del tractament ha d’informar-lo dels mitjans disponibles per exercir el seu dret.", "La sol·licitud ha de ser considerada excessiva, per la qual cosa el responsable del tractament està facultat a no respondre-la."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 1, "Segons l’article 2 de l’Estatut d’autonomia de les Illes Balears, el territori de la comunitat autònoma de les Illes Balears està format:", "Per les illes de Mallorca, Menorca, Eivissa, Formentera i Cabrera.", "Per les illes de Mallorca, Menorca, Eivissa, Formentera i Cabrera i pel de les altres illes menors adjacents.", "Per les illes de Mallorca, Menorca, Eivissa i Formentera.", "Per les illes de Mallorca, Menorca, Eivissa i Formentera i pel de les altres illes menors adjacents."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 2, "Segons l’article 4 de l’Estatut d’autonomia de les Illes Balears, sobre la llengua pròpia de les Illes Balears:", "La llengua catalana, pròpia de les Illes Balears, tindrà, juntament amb la castellana, el caràcter d’idioma oficial.", "Tots tenen el dret de conèixer-la i d’usar-la, i ningú no podrà ser discriminat per causa de l’idioma.", "Les institucions de les Illes Balears garantiran l’ús normal i oficial dels dos idiomes.", "Les respostes a), b) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 3, "Segons l’article 6 de l’Estatut d’autonomia de les Illes Balears, el dia de les Illes Balears és:", "L’1 de març.", "El 2 de març.", "L’1 de maig.", "El 2 de maig."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 4, "Segons l’article 8 de l’Estatut d’autonomia de les Illes Balears, la comunitat autònoma articula la seva organització territorial:", "En consells insulars i ajuntaments.", "En illes.", "En govern balear, consells insulars i ajuntaments.", "En illes i municipis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 5, "Segons l’article 8 de l’Estatut d’autonomia de les Illes Balears, les institucions de govern:", "De les illes són els consells insulars.", "De les illes són els governs insulars, i les dels municipis, els ajuntaments.", "Dels municipis són els ajuntaments.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 6, "Segons l’article 22 de l’Estatut d’autonomia de les Illes Balears, les ajudes relatives al dret a l’accés a un habitatge digne es regulen:", "Mitjançant una llei.", "Mitjançant un decret.", "Mitjançant subvencions.", "Mitjançant una llei orgànica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 7, "Segons l’article 24 de l’Estatut d’autonomia de les Illes Balears, els poders públics de la comunitat autònoma han de reconèixer l’activitat turística:", "Com a element econòmic fonamental de les Illes balears.", "Com a element econòmic primordial de les Illes balears.", "Com a element econòmic estratègic de les Illes balears.", "Com a element econòmic important de les Illes balears."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 8, "Segons l’article 25 de l’Estatut d’autonomia de les Illes Balears, en relació amb la salut:", "Es garanteix un sistema sanitari universal de caràcter públic.", "Es garanteix un sistema sanitari públic de caràcter universal.", "Es garanteix un sistema sanitari universal de caràcter públic i privat.", "Es garanteix un sistema sanitari públic i privat de caràcter universal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 9, "Segons l’article 26 de l’Estatut d’autonomia de les Illes Balears, en relació amb l’educació:", "Es garantirà la gratuïtat de l’ensenyament en tots els nivells educatius.", "Es garantirà la gratuïtat de l’ensenyament en els nivells obligatoris.", "Es garantirà la gratuïtat de l’ensenyament en els nivells obligatoris i en els altres nivells que s’estableixin per llei.", "Es garantirà la gratuïtat de l’ensenyament en els nivells educatius que s’estableixin per llei."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 10, "Segons l’article 30 de l’Estatut d’autonomia de les Illes Balears, la Comunitat Autònoma té la competència exclusiva en matèria:", "De salut i sanitat.", "D’ordenació del sector pesquer.", "D’expropiació forçosa.", "De turisme."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 11, "Segons l’article 30 de l’Estatut d’autonomia de les Illes Balears, la Comunitat Autònoma té la competència exclusiva en matèria:", "De joventut.", "De contractes i Concessions administratives.", "De propietat industrial.", "De salvament marítim."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 12, "Segons l’article 30 de l’Estatut d’autonomia de les Illes Balears, la Comunitat Autònoma té la competència exclusiva en matèria:", "De protecció civil.", "D’activitats classificades.", "De fires internacionals.", "De polítiques de gènere."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 13, "Segons l’article 30 de l’Estatut d’autonomia de les Illes Balears, la Comunitat Autònoma té la competència exclusiva en matèria:", "De règim local.", "De fires Internacionals.", "D’arxius, biblioteques i museus que no siguin de titularitat estatal.", "De propietat intel·lectual."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 14, "Segons l’article 30 de l’Estatut d’autonomia de les Illes Balears, la Comunitat Autònoma té la competència exclusiva en matèria:", "D’ordenació del sector pesquer.", "De protecció de menors.", "De fires internacionals.", "De productes farmacèutics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 15, "Segons l’article 30 de l’Estatut d’autonomia de les Illes Balears, la Comunitat Autònoma té la competència exclusiva en matèria:", "De servei meteorològic de la comunitat autònoma.", "De legislació laboral.", "D’alteracions dels termes municipals i denominació oficial dels municipis i topònims.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 16, "Segons l’article 30 de l’Estatut d’autonomia de les Illes Balears, la Comunitat Autònoma té la competència exclusiva en matèria:", "D’estatut dels funcionaris de l’Administració de la Comunitat Autònoma.", "De mitjans de comunicació social.", "De pesca marítima a les aigües de les Illes Balears.", "D’activitats classificades."); 
