insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 73, "Segons l’article 93 de l’Estatut d’autonomia de les Illes Balears, l’òrgan jurisdiccional que culmina l’organització judicial de les Illes Balears dins el seu àmbit territorial és:", "El Tribunal Superior de Justícia de les Illes Balears.", "El Tribunal Suprem.", "L’Audiència provincial.", "El Tribunal Constitucional."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 74, "Segons l’article 139 de l’Estatut d’autonomia de les Illes Balears, a qui correspon la iniciativa de reforma de l’Estatut d’autonomia?", "Únicament al Parlament.", "Únicament al Govern de la Comunitat Autònoma.", "Únicament al Parlament i al Govern de la Comunitat Autònoma.", "Al Parlament, al Govern de la Comunitat Autònoma i a les Corts Generals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 75, "La Llei orgànica 1/2007, de 28 de febrer, de reforma de l’Estatut d’autonomia de les Illes Balears consta:", "D’una exposició de motius, un preàmbul, set títols i disposicions.", "D’una exposició de motius, un preàmbul, vuit títols i disposicions.", "D’una exposició de motius, un preàmbul, nou títols i disposicions.", "D’una exposició de motius, un preàmbul, deu títols i disposicions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 1, "La seu electrònica d’una administració pública és:", "L’adreça d’una administració disponible per a la ciutadania a través de xarxes de telecomunicacions.", "La xarxa de telecomunicacions de l’Administració que ofereix els serveis a tota la ciutadania.", "El conjunt agrupat de tots els procediments administratius inventariats i classificats per unitats orgàniques que pertanyen a una administració.", "El punt d’accés per a la ciutadania a les actuacions que pot realitzar amb l’Administració per mitjà d’una autenticació electrònica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 2, "Quines actuacions i tràmits s’efectuen mitjançant la seu electrònica d’una administració pública?", "Totes les actuacions i els tràmits referits a procediments o a serveis que requereixin la identificació de l'Administració pública i, si s’escau, la identificació o firma electrònica de les persones interessades.", "Totes les actuacions i els tràmits referits a procediments que requereixin la identificació de l'Administració pública o aquells serveis que requereixin un assentament de registre d’entrada dins l'Administració pública i, si s’escau, la identificació o firma electrònica de la ciutadania.", "Únicament aquelles actuacions i tràmits referits a procediments o a serveis que estiguin implantats sobre una plataforma de tramitació telemàtica. Aquelles actuacions o tràmits que no disposin de tramitació telemàtica, no tenen cabuda dins la seu electrònica.", "Totes les actuacions i tràmits referits a procediments o a serveis que requereixin un assentament de registre d’entrada dins l'Administració pública i, si s’escau, la identificació o firma electrònica de la ciutadania."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 3, "Pot correspondre la titularitat d’una seu electrònica a més d’un organisme públic?", "No, ja que sempre correspon a una administració pública.", "No, pot correspondre a un organisme públic, però no a més d’un.", "Sí, en l’àmbit de les seves competències.", "Sí, sempre que en sigui titular, a la vegada, l’administració pública de la qual depèn."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 4, "Senyalau la resposta incorrecta, en matèria de seu electrònica:", "L’establiment d’una seu electrònica comporta la responsabilitat del titular respecte de la integritat, la veracitat i l’actualització de la informació i els serveis als quals es pugui accedir a través de la seu.", "Les seus electròniques han de disposar de sistemes que permetin sempre establir comunicacions segures.", "Les seus electròniques han d’utilitzar, per identificar-se i garantir una comunicació segura amb aquestes seus, certificats reconeguts o qualificats d’autenticació de lloc web o un mitjà equivalent.", "La publicació a les seus electròniques d’informacions, serveis i transaccions ha de respectar els principis d’accessibilitat i ús d’acord amb les normes establertes sobre això, els estàndards oberts i, si s’escau, aquells altres que siguin d’ús generalitzat per part dels ciutadans."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 5, "Cada administració pública ha de determinar les condicions i els instruments de creació de les seus electròniques amb subjecció, entre d’altres, als principis de:", "Transparència, publicitat, responsabilitat, qualitat, seguretat, disponibilitat, accessibilitat, neutralitat i interoperabilitat.", "Transparència, publicitat, responsabilitat, eficàcia, seguretat, disponibilitat, accessibilitat, coordinació i interoperabilitat.", "Transparència, desconcentració, responsabilitat, eficàcia, seguretat, disponibilitat, accessibilitat, coordinació i interoperabilitat.", "Transparència, publicitat, responsabilitat, qualitat, seguretat, disponibilitat, accessibilitat, coordinació i interoperabilitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 6, "En matèria de funcionament del sector públic per mitjans electrònics, es poden crear seus electròniques paral·leles?", "No, aquest concepte no existeix.", "Sí, per raons tècniques i organitzatives; a més, un cop creades es poden suprimir.", "Sí, per raons tècniques i procedimentals; no obstant això, un cop creades no es poden suprimir.", "No, la seu electrònica és única."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 7, "El procés per tal de crear una seu electrònica associada és:", "La publicació de l’acte o la resolució de creació de la seu electrònica associada en el butlletí oficial que correspongui en funció de quina sigui l’administració pública titular de la seu.", "La publicació en el directori del punt d’accés general electrònic que correspongui.", "La seu electrònica associada no requereix cap acte o resolució de creació, ja que únicament es crea per raons tècniques i organitzatives.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 8, "No forma part dels elements obligatoris que han de constar en l’acte o resolució de creació d’una seu electrònica d’una administració pública:", "La identificació del titular de l’òrgan responsable de la seu electrònica.", "La identificació de l’òrgan o òrgans encarregats de la gestió i dels serveis posats a disposició en la seu.", "La identificació de la direcció de la seu electrònica de referència de la seu electrònica o seu electrònica associada que es creï.", "L’àmbit d’aplicació de la seu electrònica o seu electrònica associada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 9, "Quina de les següents normes tècniques d’interoperabilitat fa referència a la interconnexió amb la seu electrònica?", "Norma tècnica d’interoperabilitat del model de dades i condicions d’interoperabilitat dels registres de funcionaris habilitats.", "Norma tècnica d’interoperabilitat del model de dades i condicions d’interoperabilitat dels registres electrònics d’apoderaments.", "Norma tècnica d’interoperabilitat de les condicions d’ interconnexió amb les seus electròniques.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 10, "No forma part del contingut mínim que tota seu electrònica o seu electrònica associada ha de posar a disposició de les persones interessades:", "La identificació de l’acte o disposició de creació.", "L’accés a l’acte o disposició de creació.", "L’àmbit d’aplicació de la seu electrònica o seu electrònica associada.", "La identificació de l’adreça electrònica de referencia de la seu electrònica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 11, "Quant a aspectes temporals, quin dels següents elements és un contingut mínim del qual ha de disposar tota seu electrònica?", "La data oficial, així com el calendari de dies inhàbils a l’efecte de comprovar la validesa d’un registre.", "La data i l’hora oficials, i, si s’escau, el calendari de dies inhàbils a l’efecte de comprovar la validesa d’un registre", "El calendari de dies hàbils a l’efecte del còmput de terminis.", "La data i l’hora oficials, així com el calendari de dies inhàbils a l’efecte del còmput de terminis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 12, "Quina de les següents no forma part de la informació necessària que ha de publicar tota seu electrònica per a la seva correcta utilització?", "Mapa de la seu o informació equivalent.", "Especificació de l’estructura de navegació.", "Especificació de les diferents seccions disponibles.", "Mapa interactiu del menú."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 13, "El sistema de verificació dels certificats de la seu electrònica:", "És un contingut que la seu pot posar a disposició de les persones interessades.", "És un contingut mínim que tota seu electrònica o seu electrònica associada ha de posar a disposició de les persones interessades.", "És un servei que la seu pot posar a disposició de les persones interessades.", "És un servei mínim que tota seu electrònica o seu electrònica associada ha de posar a disposició de les persones interessades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 14, "La data i l’hora oficials, com un element mínim que ha de formar part de la seu electrònica, amb quin organisme s’ha de sincronitzar?", "Amb el Centre Espanyol de Predicció Metrològica.", "Amb el Registre de Control Metrològic.", "Amb el Reial Institut i Observatori de l’Armada.", "Amb el Ministeri de Ciència i Tecnologia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 15, "Qui és el responsable dels procediments que figurin a una seu electrònica associada a la qual s’hagi accedit a través d’un enllaç publicat a una seu electrònica?", "El titular de la seu electrònica que conté l’enllaç, en tot cas.", "El titular de la seu electrònica associada, en tot cas.", "El titular de la seu electrònica associada, sense perjudici de la deguda diligència del titular de la seu electrònica que conté l’enllaç respecte de la incorporació dels continguts en aquesta seu.", "Tant el titular de la seu electrònica que conté l’enllaç com el titular de la seu electrònica associada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 16, "Una seu electrònica pot contenir procediments o serveis la competència dels quals correspongui a un òrgan d’una altra administració?", "Sí, sempre que s’indiqui explícitament que el titular d’aquesta seu no es fa responsable de la integritat, veracitat i actualització del que faci referència a aquests procediments o serveis.", "No, una seu només pot publicar procediments o serveis la competència dels quals sigui d’un òrgan de la mateixa administració.", "Sí, tot i així, la responsabilitat de la integritat, veracitat i actualització del que faci referència a aquests procediments o serveis és del titular de la competència d’aquests procediments, sense perjudici de la deguda diligència del titular de la seu electrònica respecte de la incorporació dels continguts en aquesta seu.", "No, si els vol publicar ha de posar un enllaç o vincle a la seu propietària dels procediments o serveis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 17, "Si una administració pública opta per utilitzar un sistema de codi segur de verificació de documents en l’exercici d’actuacions automatitzades, aquest codi:", "Ha de permetre en tot cas la comprovació de la integritat del document a la seu electrònica o seu electrònica associada corresponent, i si s’escau, al portal del registre electrònic general, mitjançant un procediment de verificació directe i gratuït per a les persones interessades.", "Ha de permetre en tot cas la comprovació de la integritat del document a la seu electrònica o seu electrònica associada corresponent mitjançant un procediment de verificació directe i gratuït per a les persones interessades.", "Ha de permetre en tot cas la comprovació de la integritat del document a la seu electrònica o seu electrònica associada corresponent, i si s’escau, amb el sistema de custòdia documental, mitjançant un procediment de verificació indirecte i gratuït per a les persones interessades.", "Ha de permetre en tot cas la comprovació de la integritat del document a la seu electrònica o seu electrònica associada corresponent mitjançant un procediment de verificació indirecte i gratuït per a les persones interessades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 18, "Senyalau la resposta incorrecta respecte de la relació de segells electrònics utilitzats per cada administració pública:", "Aquesta relació ha d’incloure les característiques dels certificats electrònics.", "Aquesta relació ha de ser pública i accessible per mitjans electrònics.", "Aquesta relació s’ha de publicar a la seu electrònica o seu associada, i al portal d’internet corresponent.", "Aquesta relació ha d’incloure les característiques dels prestadors que els expedeixen."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 19, "El nivell de seguretat en la identificació electrònica exigit en els procediments i serveis que gestiona una entitat que pertany al sector públic:", "S’ha de definir i publicar a la seu electrònica.", "S’ha de determinar sobre la base de l’accessibilitat universal, d’acord amb l’Esquema Nacional de Seguretat i la normativa corresponent.", "S’ha de determinar sobre la base de l’anàlisi de riscs, d’acord amb l’Esquema Nacional d’Interoperabilitat i la normativa corresponent.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 20, "En una actuació administrativa automatitzada duta a terme mitjançant un sistema de signatura basat en un codi segur de verificació, com s’ha de garantir la interoperabilitat en les comunicacions de documents electrònics a altres òrgans, organismes o entitats?", "Amb la superposició d’un segell electrònic al codi segur de verificació.", "Amb un segell electrònic segur adjunt al document electrònic.", "Amb la superposició d’una firma electrònica al codi segur de verificació.", "Amb una firma electrònica del titular de l’òrgan competent que ha elaborat el document electrònic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 21, "En matèria de sistemes de firma electrònica del personal al servei de les administracions públiques, com han de ser els certificats electrònics d’empleat públic?", "Qualificats.", "Ajustats al que estableix l’Esquema Nacional de Seguretat.", "Ajustats a la legislació vigent en matèria d’identitat i firma electrònica.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 22, "Dins del conjunt de principis que el sector públic ha de respectar en les seves actuacions i relacions electròniques, què és el principi d’interoperabilitat?", "La capacitat dels sistemes d’informació i, per tant, dels procediments als quals aquests donen suport, de compartir dades i possibilitar l’intercanvi d’informació entre si.", "La capacitat dels sistemes d’informació i, per tant, dels procediments als quals aquests donen suport, de compartir informació i possibilitar l’intercanvi de dades entre si.", "La capacitat dels sistemes d’informació i, per tant, dels procediments als quals aquests donen suport, de compartir dades o possibilitar l’intercanvi d’informació entre si.", "La capacitat dels sistemes d’informació i, per tant, dels procediments als quals aquests donen suport, de compartir informació o possibilitar l’intercanvi de dades entre si."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 23, "Quin és l’òrgan tècnic de cooperació de les administracions públiques en matèria d’administració electrònica que assegura la compatibilitat i interoperabilitat del sistemes i aplicacions que empren les administracions públiques?", "El Comitè Sectorial d’Administració Electrònica.", "La Comissió Sectorial d’Administració Electrònica.", "La Conferència Sectorial d’Administració Electrònica.", "La Comissió Ministerial d’Administració Electrònica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 24, "Quina de les següents funcions no desenvolupa la Comissió Sectorial d’Administració Electrònica?", "Assegurar la compatibilitat dels sistemes emprats per les administracions públiques.", "Preparar plans i programes conjunts d’actuació per impulsar el desenvolupament de l'Administració electrònica a Espanya.", "Assegurar la interoperabilitat de les aplicacions emprades per les administracions públiques.", "Assegurar la interconnexió entre les administracions públiques per proporcionar informació administrativa clara, actualitzada i inequívoca."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 25, "Quin és l’òrgan competent per garantir la interoperabilitat en matèria de ciberseguretat i criptografia?", "Centre Criptogràfic Nacional, adscrit al Centre Nacional d’Intel·ligència.", "Centre Criptològic Nacional, adscrit al Centre Nacional d’Interoperabilitat.", "Centre Criptològic Nacional, adscrit al Centre Nacional d’Intel·ligència.", "Centre Criptogràfic Nacional, adscrit al Centre Nacional d’Interoperabilitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 26, "Quina de les següents opcions no es considera un principi específic de l’Esquema Nacional d’Interoperabilitat?", "L’enfocament de solucions multidimensionals.", "El caràcter multilateral de la interoperabilitat.", "La interoperabilitat com a element integrat amb la qualitat.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 27, "En l’àmbit de l’Administració electrònica i d’acord amb la norma tècnica de l’expedient electrònic, senyalau l’opció incorrecta sobre l’índex electrònic d’un expedient electrònic:", "L’índex electrònic ha de garantir la integritat de l’expedient electrònic.", "L’índex electrònic ha de permetre la recuperació de l’expedient electrònic, sempre que calgui.", "L’índex electrònic recull el conjunt de documents electrònics associats a l’expedient i es crea un cop l’expedient es tanca.", "L’índex electrònic és un dels components de l’expedient electrònic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 28, "En matèria d’interoperabilitat, com s’aprova una norma tècnica d’interoperabilitat?", "Mitjançant una resolució.", "Mitjançant una ordre ministerial.", "Mitjançant un reial decret.", "Mitjançant un acord del Consell de Ministres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 29, "Quina de les següents opcions no és una norma tècnica d’interoperabilitat?", "Catàleg d'estàndards.", "Política de signatura electrònica i de certificats de l’Administració.", "Relació de models de dades.", "Reutilització de dades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 30, "En l’àmbit de l’administració electrònica i d’acord amb la norma tècnica de digitalització de documents, quin és un dels requisits de la imatge electrònica?", "La imatge electrònica ha de respectar la geometria del document d’origen en mida, sens perjudici que pugui tenir proporcions diferents.", "La imatge electrònica no pot contenir caràcters o gràfics que no figurin al document d’origen.", "La resolució màxima de la imatge electrònica ha de ser de 200 píxels per polzada.", "La imatge electrònica ha d’aplicar els formats que s’estableixen per a fitxers d’imatge en la norma tècnica d’interoperabilitat del Catàleg de Formats Estàndards."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 31, "La xarxa SARA és la xarxa de comunicacions que s’estableix per tal de connectar i intercomunicar les administracions públiques espanyoles. On estan establertes les condicions perquè una administració pública pugui accedir-hi?", "A l’Esquema Nacional d’Interoperabilitat.", "A l’Esquema Nacional de Seguretat.", "A una norma tècnica d’interoperabilitat.", "A una guia d’aplicació d’una norma tècnica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 32, "Senyalau la resposta correcta en relació amb les normes tècniques d'interoperabilitat:", "El registre electrònic d'apoderaments està tractat en la mateixa norma tècnica d’interoperabilitat que tracta el registre electrònic general.", "Hi ha una norma tècnica d’interoperabilitat que tracta el registre electrònic d'apoderaments.", "Hi ha una norma tècnica d’interoperabilitat conjunta que tracta tant el registre electrònic d'apoderaments com el de funcionaris habilitats.", "No hi ha cap norma tècnica d’interoperabilitat que tracti el registre electrònic d'apoderaments."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 33, "D'acord amb el Reial decret 203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics, què no tracta la norma tècnica de model de dades per a l'intercanvi d'assentaments entre les entitats registrals?", "Els aspectes funcionals i tècnics per a l'intercanvi d'assentaments registrals.", "La gestió d'errors i excepcions.", "La gestió d'annexos.", "La digitalització."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 34, "D’acord amb la norma tècnica de document electrònic, quins són els components obligatoris d’un document electrònic?", "Contingut, firma electrònica i metadades del document electrònic.", "Contingut i metadades del document electrònic.", "Contingut, índex electrònic, firma electrònica i metadades del document electrònic.", "Contingut i segell electrònic de l’òrgan responsable del document."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 35, "D’acord amb el Reial decret 203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics, quina és la definició de sistema d'interconnexió de registres?", "La infraestructura bàsica que permet l'intercanvi d'assentaments electrònics de registre entre les administracions públiques.", "L'instrument que presta serveis d'interconnexió tècnica, organitzativa i jurídica entre sistemes d'informació per a un conjunt d'administracions públiques sota les condicions que aquestes administracions fixin.", "La infraestructura que permet la integració, com a servei o com a producte, tant de caràcter horitzontal com sectorial, entre les diferents plataformes registrals de simplificació administrativa.", "L'instrument que té per objecte definir la manera correcta d'intercanviar o emmagatzemar les dades d'un assentament registral i garantir-ne la seguretat, la conservació i la interoperabilitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 36, "D'acord amb la normativa del Reial decret 203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics, les aplicacions per al tractament del registre electrònic general, hauran de permetre interoperabilitat amb les eines de gestió d'expedients?", "Sí, en l'àmbit de l'Administració general de l'Estat.", "No, la llei no fa referència a aquesta d'interoperabilitat.", "Sí, en l'àmbit de totes les administracions públiques.", "d) No, la llei recomana aquesta interoperabilitat, però no la requereix."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 37, "De forma general, quina versió del protocol SCSP (Substitució de Certificats en Suport Paper) s’usa als serveis d’intercanvi de dades i documents entre administracions públiques?", "La versió 1.", "La versió 2.", "La versió 3.", "Les versions 2 o 3, d’acord amb les capacitats tècniques de l’agent cedent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 38, "En matèria dels intercanvis intermediats de dades entre administracions públiques, quin és l’agent que col·labora en les tasques d’auditoria quan és requerit per a això, i facilita al cedent la informació o els documents necessaris per al control de les consultes?", "El cedent", "L’emissor.", "El cessionari.", "El requirent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 39, "En matèria dels intercanvis intermediats de dades entre administracions públiques i referent a les autoritzacions d’accés als serveis, qui és l’agent que defineix la política d’auditoria i que fa auditories periòdiques sobre l’ús del sistema relatiu a les consultes de les seves dades?", "El cedent", "L’emissor.", "El cessionari.", "El requirent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 40, "En matèria dels intercanvis intermediats de dades entre administracions públiques, quin agent actua com a emissor a la vegada que com a cedent?", "Un cedent que facilita la cessió de les seves pròpies dades.", "Un emissor que facilita la cessió de les seves pròpies dades.", "Un cessionari que fa directament la consulta de les seves pròpies dades.", "Un requirent que fa directament la consulta de les seves pròpies dades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 41, "En matèria dels intercanvis intermediats de dades entre administracions públiques, quin agent ha de mantenir la traça de totes les peticions rebudes i les respostes generades?", "El cedent", "L’emissor.", "El cessionari.", "El requirent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 42, "Qui es pot adherir al conveni de col·laboració en matèria d’interoperabilitat telemàtica entre les administracions públiques de l’àmbit territorial de les Illes Balears?", "És un conveni tancat, sense possibilitat d’adherir-s’hi.", "Qualsevol administració pública de l’Estat espanyol.", "Els organismes públics i les entitats de dret públic vinculats o dependents de les administracions públiques, en tot cas.", "Totes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 43, "Qui no forma part de la Comissió de Seguiment del conveni de col·laboració en matèria d’interoperabilitat telemàtica entre les administracions públiques de l’àmbit territorial de les Illes Balears?", "El coordinador del Departament de Noves Tecnologies del Consell de Formentera.", "El director general de Modernització i Administració Digital de la Comunitat Autònoma de les Illes Balears.", "El cap de la Secció de Sistemes d’Informació i Seguretat del Consell d’Eivissa.", "Tots els anteriors càrrecs en formen part."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 44, "En matèria d’interoperabilitat telemàtica, què són els serveis propis?", "Són aquells que permeten als ens adscrits al conveni de col·laboració en matèria d’interoperabilitat telemàtica entre les administracions públiques de l’àmbit territorial de les Illes Balears, compartir i intercanviar informació mitjançant la Plataforma d'Interoperabilitat de les Illes Balears.", "Són aquells serveis que ofereix l’Administració general de l’Estat i que es poden consultar mitjançant la Plataforma d'Interoperabilitat de les Illes Balears.", "Són aquells serveis per a la consulta dels quals no cal accedir a la Plataforma d'Interoperabilitat de les Illes Balears, ja que són accessibles directament a través de la Intranet.", "Són aquells serveis de verificació i consulta de dades prestades per un òrgan de la mateixa Administració pública."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 45, "Com s’aprova la norma tècnica d’interoperabilitat de protocols d’intermediació de dades?", "Mitjançant la Resolució de 28 de juny de 2010 de la Secretaria d’Estat d’Administracions Públiques.", "Mitjançant el Reial decret 4/2010, de 8 de gener de 2010.", "Mitjançant la Resolució de 28 de juny de 2012 de la Secretaria d’Estat d’Administracions Públiques.", "Mitjançant el Reial decret 203/2010 de 30 de març de 2021."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 46, "Indicau la resposta incorrecta en relació amb l’aportació de documents per part de les persones interessades:", "L’Administració de la Comunitat Autònoma de les Illes Balears no ha d’exigir l’aportació de documents si aquests documents estan incorporats a la carpeta documental.", "Les administracions públiques no han d’exigir a la ciutadania la presentació de documentació si aquesta consta en el Catàleg de simplificació documental.", "Els interessats tenen dret a no aportar documents que ja estiguin en poder de l’Administració actuant.", "Les còpies que aportin els interessats en el procediment administratiu tenen eficàcia, exclusivament, en l’àmbit de l’activitat de les administracions públiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 47, "Indicau la resposta correcta en relació amb l’aportació de documents en un procediment administratiu:", "Els ciutadans han d’aportar les dades i els documents que exigeixen les administracions públiques d’acord amb el que disposa la normativa aplicable.", "Els interessats han d’aportar les dades i els documents que exigeixen les administracions públiques d’acord amb el que disposa la normativa aplicable.", "Els interessats han d’aportar les dades i els documents que exigeixen les administracions públiques.", "Els ciutadans han d’aportar les dades i els documents que exigeixen les administracions públiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 48, "En relació amb els documents que l’interessat no ha d’aportar a un procediment, com ha d’obtenir l’Administració actuant aquestes dades que estan en poder d’una altra administració?", "Mitjançant la consulta en les plataformes d’intermediació de dades o un altre sistema electrònic habilitat a l’efecte, per aquest ordre.", "Mitjançant els sistemes electrònics habilitats a l’efecte, la consulta a les plataformes d’intermediació de dades o les xarxes corporatives, indistintament.", "Mitjançant les xarxes corporatives, la consulta a les plataformes d’intermediació de dades o altres sistemes electrònics habilitats a l’efecte, per aquest ordre.", "Mitjançant la plataforma d’intermediació de dades i, quan no se’n tengui, la tramesa d’oficis amb el sistema VALIB."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 49, "Indicau la resposta correcta. En quins casos l’interessat no es pot oposar que l’Administració actuant obtengui les dades en poder d’una altra administració?", "Quan l’aportació del document s’exigeix en el marc de l’exercici de potestats sancionadores.", "Quan l’aportació del document s’exigeix en el marc de l’exercici de potestats tributàries.", "Quan l’aportació del document s’exigeix en el marc de l’exercici de potestats d’inspecció.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 50, "Indicau la resposta incorrecta:", "Les administracions públiques poden exigir la presentació de documents originals als interessats, en determinats casos.", "Les administracions públiques no poden exigir, en cap cas, la presentació de documents originals als interessats.", "Excepcionalment, la normativa reguladora del procediment pot establir l'exigència de presentar documents originals als interessats.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 51, "Si un ciutadà que té la condició d’interessat en un procediment no vol aportar un determinat document pel fet d’haver-lo presentat abans davant una altra administració:", "Ha d’indicar el dia i l’hora en què va presentar el document davant l’altra administració.", "Ha d’indicar quan, on i per què va presentar el document davant l’altra administració.", "Ha d’indicar en quin moment i davant quin òrgan administratiu va presentar el document.", "Ha d’indicar davant quin òrgan administratiu va presentar el document."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 52, "En relació amb el dret a no aportar documents a l’Administració pública:", "És un dret dels ciutadans que tenen reconeguda la condició d’interessats en el procediment.", "És un dret dels ciutadans, en general.", "És un dret de les persones interessades.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 53, "Es pot oposar un interessat a aportar determinada documentació en el procediment administratiu?", "No, els interessats han d’aportar al procediment les dades i els documents que exigeixen les administracions públiques d’acord amb el que estableix la normativa aplicable.", "Sí, en qualsevol cas.", "Hi ha casos en què l’interessat té dret a no aportar documents.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 54, "Si un interessat té dret a no aportar un determinat document en el procediment perquè aquest document està en poder d’una altra administració:", "L’administració actuant ha de consultar les dades per mitjans telemàtics, sempre que tengui el consentiment exprés de l’interessat.", "L’administració actuant ha de consultar les dades per mitjans telemàtics, sempre que tengui el consentiment tàcit de l’interessat.", "L’administració actuant ha de consultar les dades per mitjans telemàtics, encara que l’interessat s’hi oposi.", "L’administració actuant ha de consultar les dades per mitjans telemàtics, excepte que l’interessat s’hi oposi."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 55, "Quan l’administració actuant ha de recaptar un document en poder d’una altra administració presentat per l’interessat en un procediment anterior i no el pot aconseguir:", "L’interessat està obligat a presentar novament el document.", "Si l’interessat és una persona jurídica, pot requerir-la perquè presenti novament el document.", "Excepcionalment, pot requerir novament el document a l’interessat.", "No pot requerir novament el document a l’interessat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 56, "Indicau la resposta correcta. Amb caràcter general, el ciutadà està obligat a presentar els documents davant una administració quan:", "Hi hagi un procediment administratiu.", "S’oposi a la consulta de les dades per part de l’administració actuant.", "L’exigeixi una administració pública d’acord amb la normativa aplicable.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 57, "Excepcionalment, quan la rellevància del document en el procediment ho exigeixi o hi hagi dubtes derivats de la qualitat de la còpia:", "L’administració pública actuant no pot requerir l’interessat perquè aporti més documentació.", "L’administració pública actuant pot requerir l’interessat perquè exhibeixi el document original, per la qual cosa li ha de sol·licitar motivadament l’acarament de les còpies.", "L’Administració pública actuant pot requerir l’interessat perquè presenti novament una còpia del document.", "L’administració pública actuant pot requerir l’interessat perquè comparegui davant les oficines públiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 58, "Quan pot l’òrgan instructor d’un procediment requerir a l’interessat perquè aporti un document original?", "Excepcionalment, quan la còpia aportada per l’interessat és de molt mala qualitat i en té dubtes sobre el contingut.", "Amb caràcter general, quan es tracta d’un document clau per resoldre el procediment.", "Quan l’interessat hagi aportat la documentació en paper i aquesta documentació no està digitalitzada.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 59, "Indicau la resposta correcta en relació amb l’aportació de documents per part dels interessats:", "Els documents que aportin els interessats al procediment administratiu, tant originals com còpies, tenen eficàcia en l’àmbit de l’activitat de les administracions públiques.", "Les còpies que aportin els interessats al procediment administratiu tenen eficàcia exclusivament en l’àmbit de l’activitat de les administracions públiques.", "Els documents que aportin els interessats al procediment administratiu tenen eficàcia exclusivament en l’àmbit de l’activitat de les administracions públiques.", "Les còpies que aportin els ciutadans tenen eficàcia davant qualsevol administració pública."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 60, "Assenyalau la resposta correcta en relació amb el Catàleg de simplificació documental:", "El Catàleg conté documents dels interessats l’aportació dels quals no és obligatòria en el procediment administratiu.", "El Catàleg contribueix a fer efectiu el dret de les persones interessades a no aportar documentació elaborada per les administracions públiques.", "Els documents inclosos en el Catàleg són susceptibles de ser consultats a través de plataformes interoperables.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 61, "En quin any es va crear el Catàleg de simplificació documental?", "El 2013.", "El 2011.", "El 2015.", "El 2017."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 62, "En el moment d’entrar en vigor el Catàleg de simplificació documental, respecte de quins documents es va suprimir l’obligació de presentar-los?", "Obligacions tributàries davant la hisenda autonòmica.", "Dades de residència.", "Dades d’identitat.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 63, "En matèria d’actuació i funcionament del sector públic per mitjans electrònics, una seu electrònica és:", "La direcció electrònica disponible per a la ciutadania a través de xarxes de telecomunicacions, la titularitat de la qual correspon a una administració pública, o bé a un o diversos organismes públics o entitats de dret públic en l’exercici de les seves competències.", "El punt d’accés electrònic que permet l’accés a través d’internet a la informació publicada, la titularitat de la qual correspon a una administració pública, o bé a un o diversos organismes públics o entitats de dret públic en l’exercici de les seves competències.", "La direcció electrònica disponible per a la ciutadania que agrupa un conjunt ordenat de documents i actuacions relatius a la resolució administrativa, així com les diligències encaminades a executar-la.", "El punt d’accés electrònic que engloba un escenari de comunicacions delimitat, controlat i protegit en el qual els participants es relacionen mitjançant mitjans electrònics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 64, "En matèria de funcionament del sector públic per mitjans electrònics, es poden crear seus electròniques associades?", "Sí, per raons tècniques i organitzaves es pot crear una seu associada a la seu electrònica. La seu electrònica associada tindrà consideració de seu electrònica durant el període de temps que la seu electrònica principal estigui inaccessible.", "Sí, per raons tècniques i organitzaves es poden crear una o diverses seus electròniques associades a la seu electrònica. Les seus electròniques associades tindran consideració de seu electrònica a tots els efectes.", "Sí, per raons tècniques i de seguretat es pot crear una seu associada a la seu electrònica. La seu electrònica associada tindrà consideració de seu electrònica durant el període de temps que la seu electrònica principal estigui inaccessible.", "Sí, per raons tècniques i de seguretat es poden crear una o diverses seus electròniques associades a la seu electrònica. Les seus electròniques associades tindran consideració de seu electrònica a tots els efectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 65, "On està allotjada la direcció electrònica habilitada única (DEHú) a què es refereix l’article 43 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques?", "A la seu electrònica de cada administració pública.", "A la seu electrònica del Punt d’Accés General electrònic de l’Administració General de l’Estat.", "A la seu electrònica de cada administració pública. i a totes les seves seus electròniques associades.", "A la seu electrònica de l’Administració General de l’Estat i a totes les seves seus electròniques associades."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 66, "Cal posar l’acte o la disposició de creació d’una seu electrònica d’una administració pública a disposició de les persones interessades?", "Sí, tant la seva identificació com el seu accés directe, ja que formen part del contingut mínim de què tota seu electrònica ha de disposar.", "Sí, tant la seva identificació com el seu enllaç a la seva publicació en el butlletí oficial corresponent, ja que formen part del contingut mínim de què tota seu electrònica ha de disposar.", "Sí, tant la seva identificació com el seu accés, ja sigui directe o amb el seu enllaç a la seva publicació en el butlletí oficial corresponent, ja que formen part del contingut mínim de què tota seu electrònica ha de disposar.", "Sí, amb el seu directe o amb el seu enllaç a la seva publicació en el butlletí oficial corresponent. No obstant, la identificació de l’acte o la disposició no forma part del contingut mínim de què tota seu electrònica ha de disposar."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 67, "Es pot adherir una entitat de dret públic vinculat o dependent a la seu electrònica titularitat d’una altra administració pública?", "No, només es podria adherir si la seu és titularitat de la mateixa administració pública.", "No, primer cal que es constitueixi com a seu electrònica associada.", "Sí, de forma voluntària i mitjançant la formalització de l’instrument d’adhesió corresponent, i en tot cas, constituint-se com a seu electrònica associada.", "Sí, de forma voluntària i mitjançant la formalització de l’instrument d’adhesió corresponent, sense que es constitueixi com a seu electrònica associada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 68, "En matèria d’interoperabilitat, què és la superposició d’un segell electrònic al codi segur de verificació, en les comunicacions de documents electrònics a altres òrgans?", "És un mecanisme de validació automàtica de l’origen i la integritat dels documents electrònics en els termes que estableix la Norma tècnica d’interoperabilitat d’expedient electrònic, usat en les actuacions administratives automatitzades.", "És un mecanisme de validació manual de l’origen i la integritat dels documents electrònics en els termes que estableix la Norma tècnica d’interoperabilitat d’expedient electrònic, usat en les actuacions administratives manuals.", "És un mecanisme de verificació automàtica de l’origen i la integritat dels documents electrònics en els termes que estableix la Norma tècnica d’interoperabilitat de document electrònic, usat en les actuacions administratives automatitzades.", "És un mecanisme de verificació manual de l’origen i la integritat dels documents electrònics en els termes que estableix la Norma tècnica d’interoperabilitat de document electrònic, usat en les actuacions administratives manuals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 69, "Quina relació té el Centre Criptològic Nacional amb la interoperabilitat a les administracions públiques?", "No té cap relació. El Centre Criptològic Nacional vetla per la seguretat de les xarxes i sistemes d’informació, sense tenir en compte la interoperabilitat.", "El Centre Criptològic Nacional ha de garantir la interoperabilitat en matèria de ciberseguretat i criptografia.", "El Centre Criptològic Nacional ha d’assegurar la compatibilitat dels sistemes i les aplicacions criptogràfiques emprades per les administracions públiques.", "No té cap relació. El Centre Criptològic Nacional vela per a la defensa nacional en l’àmbit militar."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 70, "Senyalau la resposta correcta:", "L’Esquema Nacional d’Interoperabilitat el regula el Reial decret 4/2010, de 8 de gener, i no s’ha vist afectat per cap norma posterior.", "L’Esquema Nacional d’Interoperabilitat l’estableix la Llei 11/2007, de 22 de juny, d’accés electrònic dels ciutadans als serveis públics.", "L’Esquema Nacional de Seguretat es remet a l’Esquema Nacional d’Interoperabilitat per a les qüestions en matèria d’interoperabilitat que vagin més enllà dels aspectes necessaris per garantir la seguretat.", "L’Esquema Nacional d’Interoperabilitat el modifica la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 71, "Senyalau la resposta correcta en relació amb els principis específics de l’Esquema Nacional d’Interoperabilitat:", "La interoperabilitat ha d’estar present al llarg de tot el cicle de vida dels serveis i els sistemes, excepte en la seva concepció.", "La cadena d’interoperabilitat es manifesta en el desplegament dels sistemes i els serveis, entre d’altres.", "L’accés a la informació al llarg del temps no és un principi que hagi de garantir aquest esquema.", "S’ha d’afavorir l’aproximació multilateral a la interoperabilitat de manera que es puguin obtenir els avantatges derivats de l’aplicació d’arquitectures integrades i centralitzades, entre d’altres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 72, "Quin és el procediment vigent per aprovar i publicar una norma tècnica d’interoperabilitat?", "El Ministeri de la Presidència, a proposta del Comitè Sectorial d’Administració Electrònica, aprova la norma tècnica d’interoperabilitat i la publica mitjançant resolució de la Secretaria d’Estat per a la Funció Pública.", "El Ministeri d’Assumptes Econòmics i Transformació Digital, a proposta de la Comissió Sectorial d’Administració Electrònica, aprova la norma tècnica d’interoperabilitat i la publica mitjançant resolució de la Secretaria d’Estat de Digitalització i Intel·ligència Artificial.", "El Ministeri de la Presidència, a proposta de la Comissió Sectorial d’Administració Electrònica, aprova la norma tècnica d’interoperabilitat i la publica mitjançant resolució de la Secretaria d’Estat per a la Funció Pública.", "El Ministeri d’Assumptes Econòmics i Transformació Digital, a proposta del Comitè Sectorial d’Administració Electrònica, aprova la norma tècnica d’interoperabilitat i la publica mitjançant resolució de la Secretaria d’Estat de Digitalització i Intel·ligència Artificial."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 1, "El Tribunal de Justícia de la Unió Europea n’establirà el reglament de procediment, el qual requereix l’aprovació:", "Del Consell.", "Del Parlament Europeu.", "Del Consell Europeu.", "De la Comissió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 2, "D’acord amb l’article 288 del Tractat de Funcionament de la Unió Europea, quina norma té un abast general, és obligatòria en tots els elements i directament aplicable a cada estat membre?", "La directiva.", "El dictamen.", "El reglament.", "La decisió quan designi destinataris."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 3, "Un membre de la Comissió Europea ha de presentar la dimissió si li ho demana:", "El president del Parlament Europeu.", "El president del Consell Europeu.", "El president de la Comissió Europea.", "El president del Consell."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 4, "En quina data es va signar el Tractat de Roma?", "2 de setembre de 1951.", "25 de març de 1957.", "8 d’abril del 1964.", "1 de juliol de 1987"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 5, "Respecte de la Unió Europea, és incorrecte afirmar el següent:", "Els reglaments tenen un abast general. Són obligatoris en tots els seus elements i directament aplicables a cada estat membre.", "Les directives obliguen l’estat membre destinatari quant al resultat que s’hagi d’aconseguir, i deixen, però, a les autoritats nacionals l’elecció de la forma i dels mitjans.", "Les recomanacions són vinculants.", "Els dictàmens no són vinculants."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 6, "El Tractat de la Unió Europea es va signar a Maastricht:", "El 15 d’abril de 1988.", "El 7 de setembre de 1990.", "El 15 d’octubre de 1960.", "El 7 de febrer de 1992."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 7, "És correcte afirmar que els reglaments de la Unió Europea:", "Són no vinculants.", "Són dret comunitari primari.", "Són dret derivat.", "Són recomanacions i dictàmens"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 8, "És correcte afirmar que les directives de la Unió Europea:", "Tenen un abast general. Són obligatòries en tots els seus elements i directament aplicables a cada estat membre.", "Obliguen l’estat membre destinatari quant al resultat que s’hagi d’aconseguir, i deixen, però, a les autoritats nacionals l’elecció de la forma i dels mitjans.", "No són vinculants.", "Són dret comunitari primari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 9, "El Tractat de París que crea la Comunitat Europea del Carbó i l’Acer va entrar en vigor:", "El 16 d’abril de 1948.", "El 18 d’abril de 1961.", "El 23 de juliol de 1952.", "El 2 de juny de 1960."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 10, "El Consell Europeu està format:", "Únicament pels caps d’estat o de govern dels estats membres de la Unió Europea.", "Pels caps d’estat o de govern dels estats membres de la Unió Europea i pel president del Parlament Europeu.", "Pels caps d’estat o de govern dels estats membres de la Unió Europea, pel president del Consell Europeu i pel president del Parlament Europeu.", "Pels caps d’estat o de govern dels estats membres de la Unió Europea, pel president del Consell Europeu i pel president de la Comissió Europea."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 11, "Quin organisme de la Unió Europea elabora l’avantprojecte del pressupost?", "El Defensor del Poble Europeu.", "El Consell Europeu.", "La Comissió Europea.", "El Parlament Europeu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 12, "En quin tractat apareix per primer cop la possibilitat que un estat membre pugui abandonar la Unió Europea?", "En el Tractat de Lisboa.", "En el Tractat d’Amsterdam.", "En el Tractat de Niça.", "En el Tractat de Roma."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 13, "On es va signar la darrera reforma del Tractat de la Unió Europea?", "A Amsterdam.", "No hi ha hagut cap reforma del Tractat de la Unió Europea.", "A Niça.", "A Lisboa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 14, "El 18 d’abril del 1951 es va signar a París el Tractat Constitutiu de la Unió Europea del Carbó i de l’Acer, quins països van signar aquest tractat?", "Alemanya occidental, Bèlgica, França, Itàlia, Luxemburg i els Països Baixos.", "Alemanya occidental, Bèlgica, França, Itàlia, Gran Bretanya i els Països Baixos.", "Alemanya occidental, França, Gran Bretanya, Itàlia, Luxemburg i Països Baixos.", "Alemanya occidental, Dinamarca, França, Itàlia, Luxemburg i Països Baixos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 15, "Els reglaments europeus es caracteritzen:", "Pel caràcter no obligatori, l’abast individual i l’aplicabilitat directa.", "Pel caràcter obligatori, l’abast individual i l’aplicació directa.", "Pel caràcter vinculant, l’abast general i la no aplicabilitat directa.", "Pel caràcter obligatori, l’abast general i l’aplicació directa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 16, "En relació amb la Unió Europea, les recomanacions i els dictàmens:", "No són vinculants i van dirigits tant a estats membres com a persones físiques o jurídiques.", "Són vinculants i van dirigits tant a estats membres com a persones físiques o jurídiques.", "Són vinculants i van dirigits a tots els estats membres.", "No són vinculants i només van dirigits a persones físiques o jurídiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 17, "Una de les següents no és una funció de la Comissió Europea:", "Executar el pressupost i gestionar els programes.", "Vetllar per l'aplicació dels tractats de la UE.", "La potestat legislativa.", "La iniciativa legislativa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 18, "Senyalau la resposta correcta. El Parlament Europeu:", "Només té funcions de consulta.", "Només és un òrgan de control.", "Es tria per sufragi universal directe.", "És l’òrgan encarregat d’executar el pressupost."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 19, "La Mesa del Parlament Europeu està composta:", "Pel president, dotze vicepresidents i els qüestors.", "Pel president, deu vicepresidents i els qüestors.", "Pel president, dos vicepresidents i els qüestors.", "Pel president, catorze vicepresidents i els qüestors."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 20, "Els drets, les llibertats i els principis reconeguts a la Unió Europea estan enunciats en:", "El Tractat de Tallinn.", "El Reglament Europeu de la Ciutadania Europea.", "La Constitució Europea.", "La Carta dels Drets Fonamentals de la Unió Europea."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 21, "El Tribunal de Justícia de la Unió Europea es va crear mitjançant:", "El Tractat de la CECA.", "El Tractat de Niça.", "El Tractat d’Amsterdam.", "El Tractat de Lisboa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 22, "Senyalau la resposta correcta respecte de les relacions internacionals de la Unió Europea amb tercers països:", "El Consell negocia els tractats internacionals i la Comissió els aprova.", "La Comissió negocia els tractats internacionals i el Parlament Europeu els sanciona.", "La Comissió negocia els tractats internacionals i el Consell els aprova.", "Un nombre indeterminat de diputats europeus negocia els tractats internacionals i la Comissió els aprova."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 23, "D’acord amb el que preveu el Tractat de la Unió Europea, senyaleu la resposta correcta en relació amb les institucions de la Unió:", "El Consell Europeu tria el president de la Comissió.", "El Consell està compost per un representant de cada estat membre, de rang ministerial.", "El Parlament Europeu està compost per representants dels ciutadans de la Unió. El seu nombre no ha d’excedir 850, més el president.", "El mandat de la Comissió és de quatre anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 24, "Pel que fa al procediment de revisió ordinari establert en el Tractat de la Unió Europea per modificar els tractats (senyalau la resposta correcta):", "El Govern de qualsevol estat membre, el Parlament Europeu o la Comissió poden presentar al Consell projectes de revisió.", "Té per finalitat revisar la totalitat o part de les disposicions relatives a les polítiques i les accions internes de la Unió.", "Té per finalitat només augmentar competències atribuïdes a la Unió en els tractats.", "El Govern de qualsevol estat membre pot presentar al Parlament projectes de revisió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 25, "La delimitació de les competències de la Unió Europea es regeix:", "Pel principi d’atribució.", "Pels principis de subsidiarietat i proporcionalitat.", "Pel principi de jerarquia.", "Pel principi d’eficàcia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 26, "Els actes legislatius de la Unió Europea podran adoptar-se únicament a proposta:", "De la Comissió Europea.", "Del Consell Europeu i la Comissió Europea.", "Del Consell d’Europa.", "Del Consell de la Unió Europea."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 27, "El procés d’integració europea va començar:", "Amb la creació de la CECA i l’EURATOM.", "Amb la creació de la Comunitat Econòmica Europea (CEE), el 1960.", "Amb els Tractats de Roma de 1957.", "Amb la creació de la CECA, el 1951."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 28, "El mandat dels membres de la Comissió s’estableix per un període de:", "Cinc anys.", "Sis anys.", "Quatre anys.", "Tres anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 29, "Executar el pressupost i gestionar els programes és una funció que correspon:", "Al Parlament Europeu.", "A la Comissió.", "Al Consell i al Parlament Europeu.", "Al Consell Europeu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 30, "La institució de la Unió Europea que està composta per un ministre de cada país de la Unió Europea és:", "La Comissió Europea.", "El Comitè de les Regions.", "El Parlament Europeu.", "El Consell."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 31, "Quins estats van signar el Tractat de Roma?", "Alemanya, Bèlgica, França, Itàlia, Luxemburg i els Països Baixos.", "Alemanya, el Regne Unit, Bèlgica, França, Itàlia i Luxemburg.", "Alemanya, Àustria, Bèlgica, França, Luxemburg i els Països Baixos.", "Alemanya, Bèlgica, França, Dinamarca, Luxemburg i els Països Baixos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 32, "Pel que fa al Consell Europeu:", "També rep la denominació de Consell d’Europa, però no és el mateix òrgan que el Consell de la Unió Europea.", "Representa els governs dels estats membres a través de representants de rang ministerial per adoptar legislació i coordinar polítiques.", "Està integrat pels caps d’estat o de govern dels estats membres de la Unió Europea, i s’encarrega de determinar-ne la direcció i les prioritats polítiques generals.", "Cada estat membre n’exerceix la presidència en torns de sis mesos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 33, "A partir de quin tractat s’estableix la Unió Econòmica i Monetària a la Unió Europea?", "El Tractat de Roma.", "El Tractat de la Unió Europea.", "El Tractat d’Amsterdam.", "El Tractat de París."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 34, "Quin òrgan té el dret a la iniciativa legislativa a la Unió Europea?", "Els països membres.", "El Comitè de les Regions.", "El president del Parlament.", "La Comissió Europea."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 35, "De les afirmacions següents relatives a la Comissió Europea, senyaleu la correcta:", "La Comissió està integrada per 27 membres.", "Espanya té designats tres comissaris.", "La Comissió és un òrgan col·legiat i està integrada per 27 membres.", "La Comissió representa els interessos dels estats membres de la Unió Europea."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 36, "D’acord amb l’article 17.2 del Tractat de la Unió Europea, els actes legislatius de la Unió:", "S’adopten per majoria qualificada de tres cinquenes parts del Parlament Europeu.", "Només poden adoptar-se a proposta de la Comissió, excepte quan els tractats disposin una altra cosa", "Únicament es poden adoptar a proposta de la Comissió o d’un dels països membres.", "S’adopten a proposta del Consell per majoria qualificada de tres cinquenes parts."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 37, "D’acord amb el que estableix l’article 48.2 del Tractat de la Unió Europea, poden presentar projectes de revisió dels tractats al Consell:", "El ministre d’assumptes exteriors de qualsevol estat membre.", "El president de qualsevol estat membre.", "El consell de ministres de qualsevol estat membre.", "El govern de qualsevol estat membre, el Parlament Europeu o la Comissió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 38, "A quin òrgan ha de presentar una sol·licitud d’adhesió un país que sol·liciti ingressar a la Unió Europea?", "Al Consell Europeu.", "Al Parlament Europeu.", "Al Consell.", "A la Comissió Europea."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 39, "En quin tractat es va crear la ciutadania europea?", "En el d’Amsterdam.", "En el de la constitució de la CECA.", "En el de Niça.", "En el de Maastricht."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 40, "Segons el Tractat de la Unió Europea, el president del Consell Europeu és elegit:", "Pel Consell Europeu, per majoria qualificada per a un mandat de dos anys i mig, que es pot renovar una sola vegada.", "Pel Parlament Europeu per majoria qualificada.", "Pel Parlament Europeu per majoria simple, que es pot renovar una sola vegada.", "Cap de les respostes anteriors no és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 41, "De conformitat amb el Tractat de la Funcionament de la Unió Europea, senyalau quin dels actes següents no té caràcter vinculant:", "El reglament", "La directiva", "La decisió", "El dictamen"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 42, "De conformitat amb el Tractat de la Unió Europea, senyalau l’opció correcta respecte de les sessions o reunions del Consell:", "Han de ser públiques quan deliberi i voti sobre un projecte d’acte legislatiu.", "No han de ser públiques en cap cas.", "Han de ser públiques a excepció d’aquelles en què es deliberi sobre un projecte d’acte legislatiu.", "Cap de les respostes anteriors no és correcta."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 43, "Quina és la durada del mandat del president del Tribunal General del Tribunal de Justícia de la Unió Europea?", "Un any, renovable.", "Dos anys, renovables.", "Tres anys, renovables.", "Quatre anys, renovables."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 44, "Una de les funcions del Parlament Europeu és:", "Definir les prioritats polítiques generals.", "Vetlar per la coherència exterior de la Unió Europea.", "Exercir funcions de control polític i consultives.", "Adoptar iniciatives de la programació anual i pluriennal de la Unió Europea per assolir acords institucionals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 45, "Quants d’estats membres té actualment la Unió Europea?", "50.", "37.", "27.", "20."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 46, "Indicau l’òrgan del Parlament Europeu que és responsable dels assumptes administratius i econòmics que afecten directament els diputats i les seves condicions de treball:", "Els qüestors.", "La Conferència de Presidents.", "La taula.", "La Secretaria General."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 47, "Els actes legislatius de la Unió Europea podran adoptar-se únicament a proposta:", "De la Comissió Europea.", "Del Consell Europeu i la Comissió Europea.", "Del Consell d’Europa.", "Del Consell de la Unió Europea."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 48, "D’acord amb el Tractat de la Unió Europea, la Unió Europea substituirà i succeirà a:", "L’OTAN.", "La CECA.", "La Comunitat Econòmica Europea.", "A cap de les anteriors."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 49, "Com s’agrupen els diputats al Parlament Europeu?", "Per països.", "Per ideologies polítiques.", "Per regions.", "Per l’idioma."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 50, "Com són elegits els diputats del Parlament Europeu?", "sufragi universal directe, lliure i secret.", "Per sufragi universal indirecte dels països membres.", "Per sufragi universal dels diputats del congrés.", "Per sufragi universal directe dels funcionaris dels països membres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 51, "El Parlament Europeu està compost per representants dels ciutadans de la Unió, amb un nombre màxim de:", "705 més el president.", "705, inclòs el president.", "649 diputats.", "Representants en una proporció igual a cada estat membre."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 52, "Quina afirmació és veritable?", "La Comissió Europea decideix sobre totes les noves lleis i les actuacions de la Unió Europea.", "La Comissió Europea proposa nova legislació, mentre que el Consell de la Unió Europea i el Parlament Europeu prenen la decisió final sobre tota la legislació de la Unió Europea.", "El Consell Europeu, compost pels presidents i primers ministres dels països de la Unió Europea, adopta la legislació de la Unió Europea.", "La Comissió Europea decideix unilateralment la normativa de la Unió Europea."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 53, "Senyalau l’afirmació correcta en relació amb els comissaris de la Unió Europea:", "Els comissaris representen els punts de vista dels països respectius.", "Per ser comissari cal ser primer funcionari al propi país.", "Els comissaris són proposats pels seus governs nacionals i han de ser aprovats pel Parlament Europeu.", "Els comissaris són escollits d'entre els ministres dels governs nacionals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 54, "Els membres del Comitè Econòmic i Social i del Comitè de les Regions assisteixen:", "Al Consell Europeu i al Consell.", "Al Parlament, al Consell Europeu i a la Comissió.", "A la Comissió i al Consell.", "Al Parlament, al Consell i a la Comissió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 55, "La renovació parcial dels jutges i advocats generals del Tribunal de Justícia té lloc:", "Cada dos anys.", "Cada sis anys.", "Cada tres anys.", "Cada quatre anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 56, "Els diputats al Parlament Europeu són elegits per a un mandat:", "De quatre anys.", "De cinc anys.", "De set anys.", "De sis anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 57, "El Consell Europeu es reuneix:", "Dues vegades per semestre.", "Una vegada per trimestre.", "Tres vegades per semestre.", "Dues vegades per any."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 58, "Segons el Tractat de la Unió Europea, quin dels càrrecs següents no forma part del Consell Europeu?", "L’Alt Representant de la Unió per a Assumptes Exteriors i Política de Seguretat.", "El cap d’estat o de govern d’un estat membre.", "El president de la Comissió.", "El president del Consell Europeu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 59, "La Presidència del Consell, a excepció de la formació d’Afers Exteriors, l’exerceix cada estat membre durant un període:", "D’un any.", "De sis mesos.", "De divuit mesos.", "De nou mesos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 60, "Garantir el respecte del dret en la interpretació i l’aplicació dels tractats és funció:", "Del Tribunal de Justícia de la Unió Europea.", "Del Defensor del Poble Europeu.", "Del Tribunal de Justícia i el Tribunal General.", "Dels tribunals de justícia de cada estat membre."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 61, "El Parlament Europeu pot constituir una comissió temporal de recerca a petició:", "D’una desena part dels diputats.", "D’una quarta part dels diputats.", "D’una quarta part dels grups polítics.", "D’una cinquena part dels diputats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 62, "La preparació dels treballs del Consell correspon:", "A la Secretaria General del Consell.", "Al president del Consell.", "A la Taula del Consell.", "Al comitè compost pels representants permanents dels governs dels estats membres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 63, "Per disposició del Tractat de Funcionament de la Unió Europea, el cessament d’un membre de la Comissió Europea, en cas d’haver deixat de reunir les condicions necessàries per exercir les seves funcions, pot ser declarat:", "Per la Comissió, mitjançant un acord adoptat per majoria absoluta dels seus membres.", "Pel Tribunal de Justícia de la Unió Europea, a proposta del Consell exclusivament.", "A instància del Consell o de la Comissió, pel Tribunal de Justícia.", "Pel Consell Europeu, a proposta de la Comissió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 64, "L’òrgan de la Unió Europea que representa els estats membres és:", "El Parlament Europeu.", "La Comissió.", "El Consell.", "El Tribunal de Justícia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 65, "Qui presideix el Consell d’Afers Estrangers?", "L’Alt Representant de la Unió per a Afers Exteriors i Política de Seguretat.", "El president de la Comissió.", "El president del Consell a proposta del Parlament.", "El president del Parlament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 66, "El Tribunal de Justícia de la Unió Europea té la seu a:", "Estrasburg.", "París.", "Brussel·les.", "Luxemburg."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 67, "El Defensor del Poble Europeu ha de presentar al Parlament Europeu un informe sobre el resultat de les seves investigacions:", "Anualment.", "Semestralment.", "Trianualment.", "Al final del seu mandat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 68, "Qui tria el Defensor del Poble Europeu?", "El Parlament Europeu.", "La Comissió.", "El Consell.", "El Parlament a proposta del Consell Europeu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 69, "La moció de censura de la Comissió ha de ser aprovada:", "Per majoria d’un terç dels vots emesos que representin, alhora, la majoria dels diputats que componen el Parlament Europeu", "Per majoria de dos terços dels vots emesos que representin, alhora, la majoria dels diputats que componen el Parlament Europeu", "Per majoria de tres cinquens dels vots emesos que representin, alhora, la majoria dels diputats que componen el Parlament Europeu", "Per majoria d’un cinquè dels vots emesos que representin, alhora, la majoria dels diputats que componen el Parlament Europeu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 70, "Quants d’escons corresponen a Espanya al Parlament Europeu actualment?", "54.", "59.", "60.", "65."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 71, "Actualment, la Comissió Europea està composta per:", "28 comissaris.", "27 comissaris.", "26 comissaris.", "25 comissaris."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 72, "Com s’anomena el principi que implica que, en cas de conflicte i en certes condicions, les normes que no tenen atribuïda una aplicabilitat directa poden ser invocades pels particulars davant els tribunals nacionals?", "Principi de supremacia del dret comunitari.", "Principi d’efecte directe.", "Principi de legalitat.", "Cap dels anteriors."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 73, "Quin dels següents actes normatius de la Unió Europea és obligatori en tots els seus elements:", "La decisió.", "La recomanació.", "El dictamen.", "L’acte."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 74, "El Tribunal de Justícia Europeu està compost:", "Per 15 jutges de reconegut prestigi.", "Per un jutge per cada estat membre.", "Per dos jutges per cada estat membre.", "Per 12 jutges."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 75, "Indicau quina de les següents no és una de les competències exclusives de la Unió Europea:", "La unió duanera.", "El mercat interior.", "L’establiment de les normes sobre competències necessàries per al funcionament del mercat interior.", "La política monetària dels estats membres la moneda dels quals és l’euro."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 1, "En matèria d’actuació i funcionament del sector públic per mitjans electrònics, senyalau la resposta incorrecta amb relació al concepte de registre electrònic:", "Les administracions públiques han de disposar de registres electrònics per rebre i trametre sol·licituds, escrits i comunicacions, que han de ser plenament interoperables de manera que se’n garanteixi la compatibilitat informàtica i la interconnexió en els termes que preveuen l’article 16 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, i l’article 60 del Reial decret  203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics.", "Cada administració ha de disposar d’un registre electrònic central en el qual ha de fer l’assentament de qualsevol document que es presenti o es rebi a qualsevol òrgan administratiu, organisme públic o entitat de dret públic vinculat o dependent.", "Els organismes públics i entitats de drets públic vinculats o dependents de cada administració poden disposar del seu propi registre electrònic plenament interoperable i interconnectat amb el registre electrònic general de l’administració a la qual estiguin vinculats o de la qual depenguin.", "Els registres electrònics han d’admetre documents electrònics normalitzats corresponents als serveis, procediments i tràmits que s’especifiquin de conformitat amb el que disposi la norma de creació del registre, emplenats d’acord amb formats preestablerts."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 2, "En matèria de registre electrònic, el Registre Electrònic General és:", "Un registre electrònic de què disposarà cada administració pública i en el qual s’ha de fer l’assentament de qualsevol document que es presenti o es rebi a qualsevol òrgan administratiu d’aquesta administració. Aquells organismes públics o entitats de dret públic vinculat o dependent d’aquesta administració han de disposar del seu propi registre electrònic, plenament interoperable i interconnectat amb el registre electrònic general de l’administració de la qual depenen.", "Un registre electrònic de què disposarà cada administració pública i en el qual s’ha de fer l’assentament de qualsevol document que es presenti o es rebi a qualsevol òrgan administratiu d’aquesta administració, així com també a qualsevol organisme públic o entitat de dret públic vinculat o dependent.", "Un registre electrònic de què disposarà cada administració pública i en el qual s’ha de fer l’assentament de qualsevol document que es presenti o es rebi a qualsevol òrgan administratiu d’aquesta administració. Aquells organismes públics o entitats de dret públic vinculat o dependent d’aquesta administració, poden disposar del seu propi registre electrònic, totalment independent del registre electrònic general de l’administració de la qual depenen.", "Un registre electrònic de què disposarà cada administració pública i en el qual s’ha de fer l’assentament de qualsevol document que es presenti o es rebi a qualsevol òrgan administratiu d’aquesta administració, així com també a qualsevol organisme públic o entitat de dret privat vinculat o dependent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 3, "Si un organisme públic o entitat de dret públic opta per disposar del seu propi registre electrònic, aquest registre ha de ser:", "Plenament interoperable i interconnectat amb el Registre Electrònic General de l’Administració General de l’Estat.", "Plenament interoperable, exportable en format de dades obertes i interconnectat amb el Registre Electrònic General de l’Administració General de l’Estat.", "Plenament interoperable i interconnectat amb el registre electrònic general de l’administració a la qual estigui vinculat o de la qual depengui.", "Plenament interoperable, exportable en format de dades obertes i interconnectat amb el registre electrònic general de l’administració a la qual estigui vinculat o de la qual depengui."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 4, "En matèria d’actuació i funcionament del sector públic per mitjans electrònics, quins documents han d’admetre els registres electrònics?", "Documents electrònics interoperables corresponents als serveis, procediments i tràmits que s’especifiquin de conformitat amb el que disposi la norma de creació del registre, emplenats d’acord amb formats oberts.", "Documents electrònics normalitzats corresponents als serveis, procediments i tràmits que s’especifiquin de conformitat amb el que disposi la norma de creació del registre, emplenats d’acord amb formats oberts.", "Documents electrònics digitalitzats corresponents als serveis, procediments i tràmits que s’especifiquin de conformitat amb el que disposi la norma de creació del registre, emplenats d’acord amb formats preestablerts.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 5, "Si un interessat presenta en el Registre Electrònic General del Govern de les Illes Balears un document, el règim especial del qual estableixi una altra forma de presentació, s’ha de tenir per presentat?", "No, tal com estableixen l’article 16.9 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, i l’article 37.4 del Reial decret 203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics.", "Sí, tal com estableixen l’article 16.8 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, i l’article 37.4 del Reial decret  203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics.", "Sí, tal com estableix l’article 37.4 del Reial decret 203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics, que deroga l’article 16.9 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques.", "No, tal com estableix l’article 37.4 del Reial decret 203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 6, "D’acord amb l’article 37.4 del Reial decret  203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics, no es consideren presentats en el registre els documents i la informació el règim especial dels quals estableixi una altra forma de presentació. En aquests supòsits:", "L’òrgan executiu competent per a la tramitació del procediment ha de notificar aquesta circumstància a l’interessat i l’ha d’informar dels requeriments exigits per la legislació específica aplicable.", "L’òrgan administratiu competent per a la tramitació del procediment ha de notificar aquesta circumstància a l’interessat i l’ha d’informar dels requisits exigits per la legislació específica aplicable.", "L’òrgan executiu competent per a la tramitació del procediment ha de comunicar aquesta circumstància a l’interessat i l’ha d’informar dels requeriments exigits per la legislació específica aplicable.", "L’òrgan administratiu competent per a la tramitació del procediment ha de comunicar aquesta circumstància a l’interessat i l’ha d’informar dels requisits exigits per la legislació específica aplicable."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 7, "Què significa que els registres de totes i cada una de les administracions públiques han de ser plenament interoperables?", "Que se n’han de garantir la compatibilitat informàtica i la interconnexió.", "Que se n’ha de garantir la transmissió telemàtica dels assentaments registrals.", "Que han de garantir la transmissió telemàtica dels documents que es presentin a qualsevol dels registres.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 8, "D’acord amb l’article 38 del Reial decret  203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics, la presentació per mitjà del servei electrònic per a la presentació de sol·licituds, escrits i comunicacions que no disposin de models normalitzats de presentació, independentment de les administracions públiques o organismes públics o entitats de dret públic vinculats o dependents a les quals vagin dirigits:", "No genera cap anotació al Registre Electrònic General de l’Administració General de l’Estat. Aquest servei electrònic és una passarel·la d’interconnexió amb el Registre Electrònic General de l’administració o organisme al qual va dirigit l’assentament, registre al qual es genera l’anotació.", "Genera una anotació al Registre Electrònic General de l’Administració General de l’Estat.", "Aquest servei electrònic ha de ser accessible des de la seu electrònica del PAGe de l’Administració general de l’Estat.", "Les respostes b) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 9, "D’acord amb la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, quin àmbit del sector públic ha de disposar d’un registre electrònic d’apoderaments?", "L’àmbit estatal.", "L’àmbit autonòmic.", "L’àmbit local.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 10, "Els assentaments que s’efectuïn als registres electrònics generals i particulars d’apoderaments han de tenir un contingut mínim d’informació. Senyalau quina de les opcions següents no forma part d’aquest contingut mínim obligatori:", "Nom i cognoms o la denominació o raó social, document nacional d’identitat, número d’identificació fiscal o document equivalent de l’apoderat.", "Tipus de poder.", "Arxiu notarial.", "Període de temps pel qual s’atorga el poder."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 11, "D’acord amb l’article 6.3 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, una de les dades obligatòries que han de contenir els assentaments que es facin en els registres electrònics generals i particulars d’apoderaments és:", "Data de caducitat del poder.", "Identificació del funcionari habilitat que registra l’assentament.", "Data d’inscripció.", "Nombre de dies naturals pels quals s’atorga el poder."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 12, "Quina és l’actuació correcta cas que es detecti un codi maliciós susceptible d’afectar la integritat o la seguretat del sistema en documents que ja s’hagin registrats?", "S’ha d’anul·lar l’assentament registral i s’ha de comunicar aquesta circumstància a l’interessat perquè pugui fer l’esmena.", "No existeix la possibilitat de registrar un codi maliciós, ja que el registre electrònic general compleix amb l’Esquema Nacional de Seguretat, i no permet la recepció de documents que no segueixin formats preestablerts per la norma tècnica d’interoperabilitat corresponent.", "S’ha d’anul·lar l’assentament registral i s’ha de notificar aquesta circumstància a l’interessat perquè pugui fer l’esmena.", "Se n’ha de requerir l’esmena a l’interessat que els hagi aportat, d’acord amb el que preveu l’article 14.3 del Reial decret  203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 13, "D’acord amb l’article 32 del Reial decret  203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics, la representació es pot acreditar mitjançant qualsevol mitjà vàlid en dret que deixi constància fidedigna de la seva existència, entre d’altres:", "Mitjançant l’apoderament efectuat per compareixença electrònica a les oficines d’assistència en matèria de registre o compareixença personal en la corresponent seu electrònica o seu electrònica associada.", "Mitjançant l’acreditació de la seva inscripció en el registre electrònic d’apoderaments de l’administració pública competent o en els seus registres particulars d’apoderaments.", "Mitjançant un certificat electrònic de representant.", "Mitjançant un document privat la matriu del qual consti en un arxiu notarial o una inscripció practicada en un registre mercantil."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 14, "Quin reglament regula el Registre Electrònic General de l’Administració General de l’Estat?", "L’Ordre PCM/1382/2021, de 9 de desembre.", "El Reial decret 113/2003, de 5 de novembre.", "El Reial decret 203/2021, de 30 de març, pel qual s’aprova el Reglament d’actuació i funcionament del sector públic per mitjans electrònics.", "No existeix cap normativa que el reguli."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 15, "Els registres electrònics de totes i cadascuna de les administracions públiques:", "Han de ser plenament interoperables, de manera que se’n garanteixi la compatibilitat informàtica i la interconnexió, així com la transmissió telemàtica dels assentaments registrals i dels documents que es presentin en qualsevol dels registres.", "Han d’estar plenament interconnectats, de manera que se’n garanteixi la compatibilitat informàtica i la intermediació, així com la transmissió telemàtica dels assentaments registrals i dels documents que es presentin en qualsevol dels registres.", "Han de ser plenament interoperables, de manera que se’n garanteixi la compatibilitat informàtica i la interconnexió, així com la transmissió telemàtica dels assentaments registrals i dels documents que es presentin en un registre de l’administració o organisme al qual es dirigeixin.", "Han d’estar plenament interconnectats, de manera que se’n garanteixi la compatibilitat informàtica i la intermediació, així com la transmissió telemàtica dels assentaments registrals i dels documents que es presentin en un registre de l’administració o organisme al qual es dirigeixin."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 16, "El dret a comunicar-se amb les administracions públiques a través d’un punt d’accés general electrònic de l’Administració és propi de:", "Els qui de conformitat amb l’article 3 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, tenen capacitat jurídica davant les administracions públiques.", "Els qui de conformitat amb l’article 3 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, tenen capacitat d’obrar davant les administracions públiques.", "Els qui de conformitat amb l’article 3 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, tenen capacitat jurídica i capacitat d’obrar davant les administracions públiques.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 17, "El dret a ser assistit en l’ús de mitjans electrònics amb les seves relacions amb les administracions públiques és titularitat de:", "Les persones físiques, en general.", "Les persones físiques majors d’edat.", "Els ciutadans i les ciutadanes amb capacitat jurídica.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 18, "Quin d’aquests subjectes està obligat a rebre per mitjans electrònics les notificacions generades per l’Agència Tributària de les Illes Balears en l’exercici de les seves funcions?", "Les persones jurídiques.", "Els registradors de la propietat, quan s’han de relacionar amb l’administració en l’exercici de la seva activitat professional.", "Les comunitats de béns.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 19, "Les notificacions que la Conselleria d’Agricultura, Pesca i Alimentació ha de practicar en el marc d’un procediment administratiu a una comunitat de béns, s’han de fer per mitjans electrònics?", "Vertader.", "Només si l’interessat ho sol·licita.", "Fals.", "Vertader, atès que una comunitat de béns té personalitat jurídica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 20, "Poden les persones físiques escollir en tot moment si es comuniquen amb les administracions públiques per exercir els seus drets i obligacions a través de mitjans electrònics?", "Sí, excepte en determinats casos.", "Sí, sempre.", "No sempre.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 21, "Està obligat un notari a relacionar-se electrònicament amb les administracions públiques?", "Sí, sempre.", "Només si ha de fer tràmits en l’exercici de la seva activitat professional.", "Sí, sempre que estigui col·legiat.", "No."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 22, "Quan una persona física no obligada a relacionar-se electrònicament amb les administracions públiques comunica el seu dret a relacionar-se per mitjans electrònics, els efectes de la comunicació es produeixen:", "A partir del dia següent en què l’òrgan competent per tramitar el procediment tengui constància de la comunicació.", "A partir del cinquè dia hàbil següent en què l’òrgan competent per tramitar el procediment tengui constància de la comunicació.", "A partir del tercer dia hàbil següent en què l’òrgan competent per tramitar el procediment tengui constància de la comunicació.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 23, "En el cas que una persona jurídica hagi de rebre una notificació d’un procediment que ha d’iniciar d’ofici l’Administració pública i aquesta no té les dades de contacte electròniques per fer l’avís de la posada a disposició, com ha d’efectuar-se la notificació?", "En paper.", "Per mitjans electrònics, posant la notificació a disposició de la seu electrònica.", "Per mitjans electrònics, posant la notificació a disposició de la carpeta ciutadana.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 24, "En tot cas, estan obligats a relacionar-se a través de mitjans electrònics amb les administracions públiques per fer qualsevol tràmit d’un procediment administratiu els subjectes següents:", "Els qui representen un interessat que no estigui obligat a relacionar-se electrònicament amb l’Administració.", "Les comunitats de propietaris.", "Els empleats de les administracions públiques per fer tràmits i actuacions personals.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 25, "D’acord amb l’article 14 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques:", "Les administracions públiques poden establir l’obligació de relacionar-se amb elles a través de mitjans electrònics per a determinats procediments i per a determinats col·lectius de persones físiques que, per raó de la seva capacitat econòmica, tècnica, dedicació professional o altres motius quedi acreditat que tenen accés i disponibilitat dels mitjans electrònics necessaris.", "Les administracions públiques poden establir reglamentàriament l’obligació de relacionar-se amb elles a través de mitjans electrònics per a determinats col·lectius de persones físiques que, per raó de la seva capacitat econòmica, tècnica i dedicació professional quedi acreditat que tenen accés i disponibilitat dels mitjans electrònics necessaris.", "Les administracions públiques poden establir reglamentàriament l’obligació de relacionar-se amb elles a través de mitjans electrònics per a determinats procediments i per a determinats col·lectius de persones físiques que, per raó de la seva capacitat econòmica, tècnica, dedicació professional o altres motius quedi acreditat que tenen accés i disponibilitat dels mitjans electrònics necessaris.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 26, "En quina d’aquestes activitats professionals és obligatori relacionar-se electrònicament amb les administracions públiques en l’exercici de les seves funcions?", "Medicina.", "Farmàcia.", "Notaria.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 27, "Les persones físiques estan obligades a relacionar-se electrònicament amb les administracions públiques?", "No, en general.", "En determinats casos sí.", "Alguns col·lectius sí que ho estan.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 28, "Indicau la resposta correcta:", "Les persones interessades que es relacionen amb les administracions públiques a través de mitjans electrònics tenen dret a consultar en el Punt d’Accés General electrònic l’estat de la tramitació dels procediments.", "Les persones interessades que es relacionen amb les administracions públiques a través de mitjans electrònics tenen dret a consultar en el Punt d’Accés General electrònic l’òrgan competent per instruir el procediment.", "Les persones interessades que es relacionen amb les administracions públiques a través de mitjans electrònics tenen dret a consultar en el Punt d’Accés General electrònic els actes de tràmit que s’han dictat en el procediment.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 29, "Quina d'aquesta informació té dret a consultar en el Punt d'Accès General electrònic la persona interessada que es relaciona electrònicament amb les administracions públiques?", "La identificació de les autoritats i el personal al servei de les administracions públiques sota la responsabilitat dels quals es tramita el procediment administratiu.", "Els actes de tràmit dictats en el procediment.", "Els requisits jurídics o tècnics que les disposicions vigents imposin als projectes, les actuacions o les sol·licituds que es proposin realitzar.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 30, "En quin cas l’Administració pot obligar les persones físiques a relacionar-s’hi per mitjans electrònics?", "En els procediments de concessió de subvencions, per a determinats col·lectius, quan estigui previst en un reglament.", "Quan ho estableixi per llei per a determinats col·lectius de persones físiques.", "Quan ho estableixi per reglament per a determinats col·lectius de persones físiques i procediments", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 31, "Quin d’aquests principis generals no regeix en les actuacions i el funcionament del sector públic per mitjans electrònics?", "El principi de facilitat d’ús.", "El principi de personalització.", "El principi de planificació.", "El principi de proactivitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 32, "En relació amb l’actuació i el funcionament del sector públic per mitjans electrònics, s’entén pel principi de personalització i proactivitat:", "La capacitat de les administracions públiques per proporcionar serveis preemplenats i d’anticipar-se a les possibles necessitats dels usuaris finals del servei, partint del coneixement adquirit per aquests usuaris.", "La capacitat per dissenyar els serveis electrònics centrant-se en les persones usuàries.", "No existeix aquest principi general.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 33, "Estan obligades les comunitats autònomes a donar el servei d’informació telefònica 012?", "Sí.", "No.", "Només en el cas dels ajuntaments.", "No, es tracta d’un servei que ha d’oferir l’Administració general de l’Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 34, "Quina d’aquestes administracions públiques no està obligada a oferir el servei d’informació telefònica 012?", "No hi ha cap administració pública obligada a donar aquest servei.", "Les comunitats autònomes.", "Els ajuntaments.", "L’Administració general de l’Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 35, "Quin òrgan directiu de l’Administració de la Comunitat Autònoma de les Illes Balears exerceix les funcions en matèria d’atenció a la ciutadania?", "La Direcció General de Participació, Transparència i Voluntariat.", "L’Oficina d’Atenció en Matèria de Registre.", "La Direcció General de Qualitat i Serveis.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 36, "En relació amb l’atenció a la ciutadania, indicau la resposta correcta:", "L’atenció i informació ciutadana és una competència que exerceix la Conselleria de Presidència.", "L’atenció i informació ciutadana és una competència que exerceix la Direcció General de Qualitat dels Serveis.", "L’atenció i informació ciutadana és una competència que exerceix la Conselleria de Salut i Consum.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 37, "Indicau la resposta correcta en relació amb l’assistència en l’ús de mitjans electrònics:", "Les administracions públiques han de garantir que els interessats es puguin relacionar amb l’Administració a través de mitjans electrònics, per a la qual cosa posaran a la seva disposició els canals d’accés que siguin necessaris.", "Les administracions públiques han de garantir que els ciutadans es puguin relacionar amb l’Administració a través de mitjans electrònics, per a la qual cosa posaran a la seva disposició els canals d’accés que siguin necessaris.", "Les administracions públiques han de garantir que les persones físiques es puguin relacionar amb l’Administració a través de mitjans electrònics, per a la qual cosa posaran a la seva disposició els canals d’accés que siguin necessaris.", "Les administracions públiques han de garantir que les persones jurídiques es puguin relacionar amb l’Administració a través de mitjans electrònics, per a la qual cosa posaran a la seva disposició els canals d’accés que siguin necessaris."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 38, "A qui han d’assistir en l’ús de mitjans electrònics les administracions públiques?", "A la ciutadania.", "Als interessats, en determinats casos.", "A les persones físiques.", "A les persones jurídiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 39, "Indicau la resposta correcta. Si un ciutadà es presenta a una oficina d’assistència en matèria de registre per presentar una sol·licitud en una convocatòria de subvencions:", "Serà atès en l’ús de mitjans electrònics, depenent del funcionari.", "Serà assistit en l’ús de mitjans electrònics, especialment en el cas d’una empresa que no té els mitjans electrònics adequats.", "Serà assistit en l’ús de mitjans electrònics, excepte quan l’interessat sigui una persona jurídica, entre d'altres.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 40, "Si una persona presenta una sol·licitud en una convocatòria d’ajudes davant una oficina d’assistència en matèria de registre de l’Administració autonòmica i no disposa de firma electrònica:", "L’oficina d’assistència en matèria de registre no és un canal d’atenció a la ciutadania si el procediment està publicat a la Seu Electrònica.", "La firma electrònica la podrà fer qualsevol funcionari, sempre que l’interessat no sigui una societat anònima.", "Les administracions públiques han de garantir que els interessats es puguin relacionar amb l’Administració a través de mitjans electrònics.", "Les respostes b) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 41, "Indicau la resposta correcta en relació amb el punt d’accés general electrònic (PAGe):", "El PAGe ha de disposar, com a mínim, d’una seu electrònica, a través de la qual es podrà accedir a determinats serveis.", "El PAGe ha de facilitar l’accés als serveis, els tràmits i la informació dels òrgans, organismes públics i entitats vinculats o dependents de l’administració pública corresponent.", "La Seu Electrònica ha de disposar d’un punt d’accés general electrònic (PAGe), a través del qual es podran accedir als serveis i tràmits.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 42, "En relació amb els canals d’atenció a la ciutadania, indicau la resposta correcta:", "Un canal és una estructura o  mitjà de difusió dels continguts i els serveis, i s’hi inclou el canal telefònic i l’electrònic, així com d’altres que hi hagi en l’actualitat.", "Un canal és una estructura o  mitjà de difusió dels continguts i el procediment, i s’hi inclou el canal presencial i l’electrònic, així com d’altres que hi hagi en l’actualitat o pugui haver-hi en el futur (dispositius mòbils, etc.).", "Un canal és una estructura o mitjà de difusió dels continguts i els serveis, i s’hi inclou el canal presencial, el telefònic i l’electrònic, així com d’altres que hi hagi en l’actualitat.", "Un canal és una estructura o mitjà de difusió dels continguts i els serveis, i s’hi inclou el canal presencial, el telefònic i l’electrònic, així com d’altres que hi hagi en l’actualitat o pugui haver-hi en el futur (dispositius mòbils, etc.)."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 43, "En quin tipus de canal s’ha de posar a disposició dels interessats la informació subjecta a les obligacions de transparència segons la Llei 19/2013, de 9 de desembre, de transparència, accés a la informació pública i bon govern?", "A través dels canals electrònics, en particular a la pàgina web.", "A la carpeta ciutadana.", "A través dels canals electrònics, en particular a la seu electrònica o pàgina web.", "A través dels canals electrònics, en particular la seu electrònica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 44, "Indicau la resposta correcta en relació amb l’atenció a la ciutadania per mitjans electrònics:", "Les administracions públiques han d’assistir en l’ús de mitjans electrònics els interessats d’un procediment administratiu si no disposen dels mitjans electrònics necessaris.", "Les administracions públiques han d’assistir en l’ús de mitjans electrònics la ciutadania quan així ho sol·liciti.", "Les administracions públiques han d’assistir en l’ús de mitjans electrònics determinats interessats d’un procediment administratiu.", "Les administracions públiques han d’assistir en l’ús de mitjans electrònics tots els interessats d’un procediment administratiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 45, "L’Administració pública ha d’assistir en l’ús de mitjans electrònics una persona jurídica que té la condició d’interessada en el procediment?", "Sí, atès que és una obligació de les administracions públiques.", "Només si no disposa dels mitjans electrònics necessaris.", "No.", "En determinats casos, com per exemple en allò referent a la identificació i la firma electrònica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 46, "Quina fita marca la transformació de les oficines de registre en oficines d’assistència en matèria de registre?", "L’entrada en vigor de les previsions de registre electrònic d’apoderaments, registre electrònic, registre d’empleats públics habilitats, punt d’accés general electrònic de l’Administració i arxiu únic electrònic.", "El 2 d’abril de 2002.", "L’entrada en vigor de la Llei 40/2015, d’1 d’octubre, de règim jurídic del sector públic.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 47, "Quan un ciutadà compareix davant una oficina d’assistència en matèria de registre (OAMR) per presentar una sol·licitud d’una convocatòria de subvencions:", "L’empleat públic ha de digitalitzar el document.", "L’OAMR no ha de digitalitzar el document si la normativa aplicable exigeix que es presenti el document en un suport específic no susceptible de digitalització.", "No es consideren presentats els documents el règim especial dels quals estableixi una altra forma de presentar els documents.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 48, "Quin òrgan superior de l’Administració de la Comunitat Autònoma de les Illes Balears té les funcions d’ordenació i coordinació de les oficines d’assistència en matèria de registre (OAMR)?", "La Conselleria de Presidència, Funció Pública i Igualtat.", "La Direcció General de Modernització i Administració Digital.", "La conselleria competent en matèria d’administració digital.", "La Direcció General de Qualitat dels Serveis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 49, "Segons la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques, quines funcions noves en matèria d’administració electrònica han passat a assumir les oficines de registre?", "L’anotació electrònica dels assentaments d’entrada i sortida.", "L’acarament i l’expedició de còpies compulsades de documents originals.", "La digitalització de documents presentats en paper.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 50, "En relació amb les funcions de les oficines d’assistència en matèria de registre (OAMR), què s’ha de fer si, un cop digitalitzat un document, no pot ser retornat a l’interessat?", "S’ha de conservar durant tres mesos.", "S’ha de trametre a l’interessat a través del NOTIB.", "S’ha de conservar durant sis mesos.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 51, "Quan un document es presenta davant una oficina d’assistència en matèria de registre:", "S’ha de fer el corresponent assentament de tot document que sigui presentat. També s’ha d’anotar la sortida dels documents oficials dirigits a altres òrgans o particulars.", "S’ha de fer el corresponent assentament de tot document que sigui presentat. També es pot anotar la sortida dels documents oficials dirigits a altres òrgans o particulars.", "S’ha de fer el corresponent assentament de tot document que sigui presentat. També s’ha d’anotar la sortida dels documents oficials dirigits a particulars.", "No s’ha de fer cap assentament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 52, "Quina d’aquestes funcions no està assignada a les oficines d’assistència en matèria de registre segons el Reial decret 203/2021?", "L’anotació, si escau, dels assentaments de sortida dels documents.", "L’anotació dels documents en el registre electrònic.", "La pràctica de notificacions mitjançant l’aplicació NOTIB.", "La identificació o firma electrònica de l’interessat, excepte en el cas de persones jurídiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 53, "Indicau la resposta correcta. Els documents en suport no electrònic presentats a través de les oficines d’assistència en matèria de registres:", "S’han de digitalitzar i se n’han de tornar els documents originals.", "S’han de digitalitzar i s’han d’incorporar en l’expedient administratiu electrònic.", "S’han de digitalitzar i custodiar si en aquell moment no és possible tornar el document original.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 54, "Què ha de fer una oficina d’assistència en matèria de registres si ha de trametre un document a una altra administració i la mida d’aquest document excedeix la capacitat que permet  el sistema d’interconnexió de registres (SIR)?", "La tramesa es pot substituir per la posada a disposició dels documents, prèviament dipositats en un repositori d’intercanvi de fitxers.", "El document s’ha d’arxivar dins un dispositiu intern de memòria USB  (pen drive) i trametre a través d’un ordenança.", "La tramesa s’ha de substituir per la posada a disposició dels documents, prèviament dipositats en un repositori d’intercanvi de fitxers.", "Totes les respostes incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 55, "Entre les funcions de les noves oficines d’assistència en matèria de registre (OAMR),  hi ha la de recepcionar la documentació presentada per una persona jurídica?", "No, perquè les persones jurídiques no poden presentar documents en paper.", "Sí.", "No, les seves funcions són les que preveu l’article 16 de la Llei 39/2015, d’1 d’octubre.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 56, "Si davant una oficina d’assistència en matèria de registre (OAMR) algun dels subjectes obligats a relacionar-se electrònicament amb l’Administració presenta la sol·licitud presencialment:", "L’OAMR no li ha de permetre presentar documentació en paper.", "L’OAMR li ha de registrar la documentació, però se’ l’ha de requerir perquè esmeni la documentació.", "L’OAMR té com a funció expressa assistir els interessats en general.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 57, "Quina d’aquestes funcions és de les oficines d’assistència en matèria de registre (OAMR)?", "La digitalització dels documents presentats de manera presencial.", "L’assistència en la identificació i firma electrònica als interessats en general.", "La pràctica de notificacions als interessats que compareixen espontàniament en una OAMR i així ho sol·liciten.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 58, "Senyalau la resposta correcta. Les administracions públiques han d’assistir en l’ús de mitjans electrònics els interessats no inclosos en els apartats 2 i 3 de l’article 14 de la Llei 39/2015:", "Quan així ho sol·licitin, especialment en allò referent a firma electrònica.", "Quan així ho sol·licitin, especialment en allò referent a obtenir còpies autèntiques.", "Quan així ho sol·licitin, especialment en allò referent a digitalització de documents.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 59, "Entre les funcions de les oficines d’assistència en matèria de registre (OAMR) hi ha la de practicar notificacions electròniques a les persones interessades?", "En determinats casos, sí.", "No.", "Sí, amb caràcter general.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 60, "Un cop digitalitzat un document presentat per un interessat, què ha de fer l’oficina d’assistència en matèria de registre (OAMR)?", "Tornar una còpia autèntica a l’interessat.", "Tornar el document a l’interessat.", "Arxivar el document presentat.", "Destruir el document presentat, en cas que sigui en paper."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 61, "La pràctica de notificacions electròniques és una funció de les oficines d’assistència en matèria de registres que es preveu en la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques?", "Sí.", "Sempre que disposin dels mitjans electrònics per practicar-les.", "No.", "En determinats casos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 62, "Si després de registrar una queixa o un suggeriment es conclou que va referit a una altra administració o entitat pública de l’Estat espanyol:", "La direcció general competent en matèria de qualitat dels serveis l’ha de remetre a l’entitat objecte de la queixa i ho ha de comunicar a la persona interessada.", "La unitat administrativa corresponent l’ha de remetre a l’entitat objecte de la queixa i ho ha de comunicar a la persona interessada.", "La unitat administrativa corresponent ha d’inadmetre la queixa o el suggeriment i ho ha de comunicar a la persona interessada.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 63, "Quins d’aquests aspectes no regula l’Ordre de la consellera d’Administracions Públiques d’1 d’agost de 2014 per la qual es desplega el Decret 82/2009, de 13 de novembre, pel qual es regula la gestió de queixes i suggeriments sobre el funcionament dels serveis públics de l’Administració de la Comunitat Autònoma de les Illes Balears:", "El model del full de queixes i suggeriments.", "La forma i els mitjans de presentació de les queixes i els suggeriments.", "La tramitació de les queixes i els suggeriments mitjançant l’aplicació d’ús general QSSI.", "La informació sobre el dret i els sistemes de queixes i suggeriments."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 64, "Senyalau la resposta incorrecta. L’Ordre de la consellera d’Administracions Públiques d’1 d’agost de 2014 per la qual es desplega el Decret 82/2009, de 13 de novembre, pel qual es regula la gestió de queixes i suggeriments sobre el funcionament dels serveis públics de l’Administració de la Comunitat Autònoma de les Illes Balears s’aplica als serveis que presten:", "Els consorcis en què participa la Comunitat Autònoma de les Illes Balears.", "Les persones jurídiques adjudicatàries de contractes de serveis públics.", "El sector públic instrumental de la Comunitat Autònoma de les Illes Balears.", "Els ajuntaments."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 65, "En el cas que la resposta a una queixa o un suggeriment presentats per un ciutadà no sigui satisfactòria, aquest ciutadà pot:", "Interposar un recurs d’alçada.", "Interposar una reclamació en via administrativa.", "Adreçar-se a la Inspecció General de Qualitat, Organització i Serveis.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 66, "El termini de què disposa l’Administració de la Comunitat Autònoma de les Illes Balears per resoldre una queixa o un suggeriment és de:", "Quinze dies hàbils en el cas de les queixes; no hi ha termini en el cas dels suggeriments.", "Quinze dies hàbils.", "Quinze dies naturals.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 67, "És aplicable el Decret 82/2009, de 13 de novembre, pel qual es regula la gestió de queixes i suggeriments sobre el funcionament dels serveis públics de l’Administració de la Comunitat Autònoma de les Illes Balears a les persones jurídiques privades?", "No.", "Sí, en determinats casos.", "Sí.", "Només pel que fa a les queixes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 68, "Segons l’article 2 del Decret 82/2009, de 13 de novembre, pel qual es regula la gestió de queixes i suggeriments sobre el funcionament dels serveis públics de l’Administració de la Comunitat Autònoma de les Illes Balears una queixa és:", "Una manifestació o una declaració efectuada per una persona física per fer constar la disconformitat amb la prestació d’un servei públic.", "Una manifestació o una declaració efectuada per una persona física o jurídica per fer constar la disconformitat amb la prestació d’un servei públic o privat.", "Una manifestació o una declaració efectuada pels ciutadans i les ciutadanes per fer constar la disconformitat amb la prestació d’un servei públic.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 69, "Qui és l’òrgan competent per resoldre una queixa o un suggeriment adreçats a l’Hospital Mateu Orfila?", "La Gerència de l’IB-Salut.", "La Direcció de l’Hospital.", "La direcció general competent en matèria de salut.", "El Departament de Benestar Social del Consell Insular de Menorca."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 70, "Quin és l’òrgan competent per resoldre una queixa o un suggeriment segons el Decret 82/2009, de 13 de novembre, pel qual es regula la gestió de queixes i suggeriments sobre el funcionament dels serveis públics de l’Administració de la Comunitat Autònoma de les Illes Balears?", "L’òrgan superior competent per raó de la matèria, a excepció dels que facin referència a la prestació de serveis sanitaris i assistencials.", "La direcció general competent en matèria de qualitat dels serveis.", "La direcció dels centres sanitaris, educatius, sociosanitaris i assistencials en el cas que la queixa o el suggeriment facin referència a la prestació de serveis d’aquests centres.", "Totes les respostes són incorrectes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 72, "Senyalau la resposta correcta segons indica el Decret 82/2009, de 13 de novembre, pel qual es regula la gestió de les queixes i els suggeriments sobre el funcionament dels serveis públics de l'Administració de la Comunitat Autònoma de les Illes Balears:", "Si un cop transcorregut el termini de quinze dies la persona interessada no ha obtingut una resposta, pot adreçar-se a la Inspecció General de Qualitat, Organització i Serveis, perquè, com a òrgan inspector, dugui a terme les actuacions necessàries per conèixer els motius que hagin pogut ocasionar la falta de contestació i adoptar les mesures pertinents.", "Si un cop transcorregut el termini de quinze dies naturals la persona interessada no ha obtingut una resposta, pot adreçar-se a la Inspecció General de Qualitat, Organització i Serveis, perquè, com a òrgan inspector, dugui a terme les actuacions necessàries per conèixer els motius que hagin pogut ocasionar la falta de contestació i adoptar les mesures pertinents.", "Si un cop transcorregut el termini de quinze dies hàbils la persona interessada no ha obtingut una resposta, pot adreçar-se a la Inspecció General de Qualitat, Organització i Serveis, perquè, com a òrgan inspector, dugui a terme les actuacions necessàries per conèixer els motius que hagin pogut ocasionar la falta de contestació i adoptar les mesures pertinents.", "Si un cop transcorregut el termini d’un mes la persona interessada no ha obtingut una resposta, pot adreçar-se a la Inspecció General de Qualitat, Organització i Serveis, perquè, com a òrgan inspector, dugui a terme les actuacions necessàries per conèixer els motius que hagin pogut ocasionar la falta de contestació i adoptar les mesures pertinents."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 73, "Senyalau la resposta correcta en relació amb les queixes i els suggeriments relatius a serveis públics de l’Administració de la Comunitat Autònoma:", "La presentació d’una queixa no impedeix l’exercici del dret genèric de petició que reconeix l’article 29 de la Constitució.", "La formulació d’una queixa té la qualificació de recurs administratiu si compleix els requisits de l’article 115 de la Llei 39/2015, d’1 d’octubre, del procediment administratiu comú de les administracions públiques.", "La Llei orgànica 4/2001, de 12 de novembre, reguladora del dret de petició s’aplica subsidiàriament en defecte de previsió del Decret 82/2009, de 13 de novembre, pel qual es regula la gestió de queixes i suggeriments sobre el funcionament dels serveis públics de l’Administració de la Comunitat Autònoma de les Illes Balears.", "La formulació d’una queixa o d’un suggeriment en exercici del dret de petició es tramita de conformitat amb la Llei orgànica 4/2001, de 12 de novembre, reguladora del dret de petició."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 74, "En relació amb les queixes i els suggeriments, els òrgans o ens que utilitzen una aplicació diferent de la d'ús general (QSSI) han de trametre a la direcció general competent en matèria d'atenció i informació ciutadana la informació següent:", "Temps màxim de resposta.", "Nombre de suggeriments que s’han presentat.", "Matèria o motiu de la queixa o del suggeriment.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 75, "Indicau la resposta correcta en relació amb les queixes i els suggeriments:", "A cada conselleria s’han de constituir equips de millora encarregats d’analitzar totes les queixes i els suggeriments.", "A cada conselleria i ens del sector públic instrumental s’han de constituir equips de millora encarregats d’analitzar totes les queixes i els suggeriments.", "Els equips de millora s’han de constituir en el si dels òrgans i ens als quals els és d’aplicació el Decret 82/2009, de 13 de novembre, pel qual es regula la gestió de queixes i suggeriments sobre el funcionament dels serveis públics de l’Administració de la Comunitat Autònoma de les Illes Balears.", "A cada conselleria i ens del sector públic instrumental s’han de constituir equips de millora o unitats administratives especialitzades encarregats d’analitzar totes les queixes i els suggeriments."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 1, "Els consells insulars han d’adequar el seu funcionament a:", "El que disposen el títol VI de la Llei 4/2022, de 28 de juny, de consells insulars, i el reglament orgŕnic respectiu.", "El que disposen el títol V de la Llei 4/2022, de 28 de juny, de consells insulars, i el reglament orgŕnic respectiu.", "El que disposen l’Estatut d’autonomia, el títol V de la Llei 4/2022, de 28 de juny, de consells insulars, i el reglament orgŕnic respectiu.", "El que disposen l’Estatut d’autonomia, el títol VI de la Llei 4/2022, de 28 de juny, de consells insulars, i el reglament orgŕnic respectiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 2, "El catalŕ és la llengua:", "D’ús normal i preferent en l’Administració insular i en les entitats que en depenen.", "D’ús normal i exclusiu en l’Administració insular i en les entitats que en depenen.", "D’ús normal i general en l’Administració insular i en les entitats que en depenen.", "D’ús formal i habitual en l’Administració insular i en les entitats que en depenen."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 3, "Segons estableix la Llei 4/2022, de 28 de juny, de consells insulars:", "Els consells insulars han d’adoptar mesures per a la normalització de la llengua catalana en qualsevol ŕmbit i han de vetlar per la qualitat del llenguatge administratiu.", "Els consells insulars han d’adoptar mesures per a la normalització de la llengua catalana en qualsevol ŕmbit i han de vetlar per l’estandardització del llenguatge administratiu.", "Els consells insulars han d’adoptar mesures per a la normalització de la llengua catalana en l’ŕmbit de les seves competčncies i han de vetlar per la qualitat del llenguatge administratiu.", "Els consells insulars han d’adoptar mesures per a la normalització de la llengua catalana en l’ŕmbit de les seves competčncies i han de vetlar per l’estandardització del llenguatge administratiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 4, "Els consellers executius no electes del Consell Insular:", "Poden intervenir en les sessions del Ple i les comissions, amb veu i sense vot, en assumptes relacionats amb el departament respectiu.", "Poden intervenir en les sessions del Ple i les comissions, amb veu i vot, en assumptes relacionats amb el departament respectiu.", "Poden intervenir en les sessions del Ple i les comissions, amb veu i sense vot, en assumptes relacionats amb les competčncies insulars.", "Poden intervenir en les sessions del Ple i les comissions, amb veu i vot, en assumptes relacionats amb les competčncies insulars."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 5, "En les sessions del Consell Executiu es poden adoptar acords sobre altres assumptes que no figurin en l’ordre del dia:", "Per decisió de la presidčncia, en qualsevol cas.", "Per raons d’urgčncia, sempre que aquesta sigui acordada per la majoria absoluta dels membres del Consell Executiu.", "Per raons d’urgčncia, sempre que aquesta sigui acordada per la majoria simple dels membres del Consell Executiu", "Per raons d’oportunitat, sempre que aquesta sigui acordada per la majoria absoluta dels membres del Consell Executiu"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 6, "El Ple del Consell Insular exerceix el control i la fiscalització de l’actuació del president i del Consell Insular, entre d’altres, pels mitjans següents:", "Moció de censura, qüestió de confiança, comissions informatives.", "Moció de confiança, comissions d’investigació, preguntes.", "Moció de censura, comissions informatives, preguntes.", "Moció de censura, qüestió de confiança, comissions d’investigació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 7, "La qüestió de confiança la pot plantejar al Ple del Consell Insular:", "El president sobre el seu programa en conjunt, sobre una declaració de política especial o sobre l’aprovació de qualsevol assumpte de transcendčncia general.", "El president sobre el seu programa en conjunt, sobre una declaració de política general o sobre l’aprovació de qualsevol assumpte de transcendčncia especial.", "Qualsevol grup polític sobre el seu programa en conjunt, sobre una declaració de política general o sobre l’aprovació de qualsevol assumpte de transcendčncia especial.", "El president o qualsevol grup polític sobre el seu programa en conjunt, sobre una declaració de política general o sobre l’aprovació de qualsevol assumpte de transcendčncia especial."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 8, "Els debats sobre l’actuació de política general que ha de dur a terme el Ple del Consell Insular són:", "Un mínim de dos debats anuals.", "Un mínim d’un debat en cada mandat corporatiu.", "Un mínim de dos debats en cada mandat corporatiu.", "Un mínim d’un debat anual."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 9, "El Ple pot acordar de celebrar una sessió extraordinŕria que tengui per objecte debatre la gestió del Consell Executiu en ŕrees determinades:", "A proposta del president o a sol·licitud d’almenys una quarta part dels seus membres.", "A proposta del president o a sol·licitud d’almenys una tercera part dels seus membres.", "A proposta del president o a sol·licitud d’almenys dos grups polítics que representin una tercera part dels seus membres.", "A proposta del president o a sol·licitud d’almenys dos grups polítics que representin una quarta part dels seus membres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 10, "Les interpel·lacions:", "Han de versar sobre l’actuació del president, del Consell Executiu o d’algun departament en qüestions de política general.", "Han de versar sobre l’actuació del Ple, del president, del Consell Executiu o d’algun departament en qüestions de política general.", "Han de versar sobre l’actuació del president, del Consell Executiu o d’algun departament en qüestions de política insular.", "Han de versar sobre l’actuació del ple, del president, del Consell Executiu o d’algun departament en qüestions de política insular."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 11, "Les preguntes:", "Tenen una resposta oral o una resposta escrita.", "Tenen una resposta oral i una resposta escrita.", "Tenen una resposta únicament oral.", "Tenen una resposta únicament escrita."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 12, "El Ple pot acordar la creació de comissions d’investigació sobre l’actuació dels ňrgans de govern insulars o dels seus membres en un assumpte o una matčria determinats:", "A proposta d’un grup polític que representi almenys la tercera part dels seus membres.", "A proposta d’un grup polític que representin almenys la quarta part dels seus membres.", "A proposta de dos grups polítics que representin almenys la quarta part dels seus membres.", "A proposta de dos grups polítics que representin almenys la tercera part dels seus membres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 13, "Les compareixences del president o dels membres del Consell Executiu davant el Ple o davant una comissió:", "Es poden dur a terme a petició únicament del president, perň també si ho sol·liciten almenys dos grups polítics o el nombre de membres del Ple que fixi el reglament orgŕnic.", "Es poden dur a terme a petició del president o dels membres del Consell Executiu, com també si ho sol·liciten almenys dos grups polítics o el nombre de membres del Ple que fixi el reglament orgŕnic.", "Es poden dur a terme a petició del president, com també si ho sol·licita un grup polític o el nombre de membres del Ple que fixi el reglament orgŕnic.", "Es poden dur a terme a petició del president o dels membres del Consell Executiu, així com si ho sol·licita un grup polític o el nombre de membres del Ple que fixi el reglament orgŕnic"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 14, "Els actes dictats pel president adopten la forma de:", "Resolucions de la presidčncia.", "Bans de la presidčncia.", "Reglaments de la presidčncia.", "Decrets de la presidčncia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 15, "Contra els actes dictats pel Consell Executiu es pot interposar:", "Un recurs d’alçada davant el Ple.", "Un recurs d’alçada davant la Comissió de Govern.", "Un recurs d’alçada davant la Presidčncia.", "No hi cap recurs d’alçada contra els actes dictats pel Consell Executiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 16, "Són competents per resoldre els procediments de revisió d’ofici de disposicions i actes:", "El Ple i el president.", "El Ple i el Consell Executiu.", "El Ple i la Comissió de Govern.", "El Consell Executiu i el president."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 17, "La resolució dels procediments de revisió d’ofici en matčria tributŕria correspon:", "Al Ple.", "Als serveis d’intervenció.", "Al Consell Executiu.", "Al president."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 18, "L’exercici de la potestat sancionadora correspon:", "Als ňrgans insulars determinats legalment o reglamentŕriament per raó de la matčria o, si no n’hi ha, al president.", "Als ňrgans insulars determinats legalment o reglamentŕriament per raó de la matčria o, si no n’hi ha, al Consell Executiu.", "Als ňrgans insulars determinats legalment o reglamentŕriament per raó de la matčria o, si no n’hi ha, al conseller executiu competent.", "Als ňrgans insulars determinats legalment o reglamentŕriament per raó de la matčria o, si no n’hi ha, al Ple."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 19, "La potestat reglamentŕria dels consells insulars s’exerceix mitjançant les disposicions aprovades:", "Pel Ple.", "Pel Govern.", "Pel Parlament.", "Pel Consell Executiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 20, "Les disposicions generals del Ple responen a la tipologia següent:", "Reglament orgŕnic,  reglament ordinari , ordenança fiscal i altres reglaments.", "Reglament orgŕnic, reglament executiu, ordenança fiscal i reglaments organitzatius.", "Reglament organitzatiu, reglament executiu, ordenança fiscal i altres reglaments.", "Reglament orgŕnic, reglament executiu, ordenança fiscal i altres reglaments."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 21, "Els pressupostos generals i els instruments de planificació general i sectorial i d’ordenació territorial i urbanística tenen rang de:", "Disposició especial.", "Disposició reglamentŕria.", "Disposició legal.", "Disposició especialitzada."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 22, "La potestat reglamentŕria en les matčries de l’article 70 de l’Estatut d’autonomia correspon:", "Als consells insulars i al Govern.", "Als consells insulars i, supletňriament, al Govern.", "Als consells insulars, sense possibilitat d’intervenció del Govern.", "Als consells insulars, sens perjudici de la facultat del Govern d’establir els principis generals en la matčria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 23, "En l’exercici de la potestat reglamentŕria, els consells insulars han d’actuar d’acord amb els principis de:", "Oportunitat, eficŕcia, proporcionalitat, seguretat jurídica, transparčncia i eficičncia.", "Necessitat, eficŕcia, proporcionalitat, seguretat jurídica, transparčncia i eficičncia.", "Necessitat, oportunitat, eficŕcia, proporcionalitat, seguretat jurídica, transparčncia i eficičncia.", "Necessitat, eficŕcia, progressivitat, seguretat jurídica, transparčncia i eficičncia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 24, "Les relacions entre els reglaments de cada consell insular es regeixen pels principis de:", "Competició i especialitat.", "Competčncia i transparčncia.", "Competició  i transparčncia.", "Competčncia i especialitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 25, "Perquč els reglaments entrin en vigor i produeixin efectes jurídics:", "Se n’ha de publicar l’acord en el Butlletí Oficial de les Illes Balears.", "S’han de publicar íntegrament en el Butlletí Oficial de l’Estat.", "Se n’ha de publicar l’acord en el Butlletí Oficial de l’Estat.", "S’han de publicar íntegrament en el Butlletí Oficial de les Illes Balears."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 26, "La consulta pública prčvia a l’inici del procediment d’elaboració de disposicions reglamentŕries i en els supňsits que preveu la normativa bŕsica estatal no és preceptiva quan es tracti d’iniciatives:", "De reglaments tčcnics i d’organització.", "De reglaments orgŕnics.", "De reglaments executius.", "De reglaments de desplegament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 27, "L’elaboració dels reglaments executius és iniciada:", "Per acord plenari.", "Pel president.", "Per acord del Consell Executiu.", "Pel conseller executiu competent per raó de la matčria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 28, "El projecte de reglament executiu ha de ser adoptat per:", "El Consell Executiu.", "El conseller executiu competent per raó de la matčria.", "El president.", "El Ple."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 29, "El termini dels trŕmits d’audičncia, de consultes i d’informació pública per a l’aprovació de reglaments executius ha de ser adequat a la naturalesa de la disposició i, en tot cas:", "No inferior a quaranta dies.", "No inferior a trenta dies.", "No inferior a vint dies.", "No inferior a deu dies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 30, "Les mesures provisionals adequades i necessŕries per assegurar l’eficŕcia de la regulació que es pretengui establir amb un reglament executiu, poden ser adoptades per:", "El Consell Executiu.", "El conseller executiu competent per raó de la matčria.", "El president.", "El Ple."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 31, "La proposta prčvia del reglament executiu que se sotmeti a aprovació definitiva ha d’anar acompanyada de:", "La darrera versió del projecte, la memňria d’anŕlisi d’impacte normatiu i el dictamen del Consell Consultiu.", "La darrera versió del projecte, la memňria d’anŕlisi d’impacte de gčnere i el dictamen del Consell Consultiu.", "La darrera versió del projecte, la memňria d’anŕlisi d’impacte normatiu i el dictamen del Govern.", "La darrera versió del projecte, la memňria d’anŕlisi d’impacte de gčnere  i el dictamen del Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 32, "Per a l’elaboració del reglament orgŕnic s’han de seguir, en qualsevol cas, els trŕmits següents:", "Informació pública per un termini no inferior a un mes, informe sobre al·legacions, informe dels serveis jurídics, dictamen del Consell Consultiu i aprovació definitiva pel Ple.", "Aprovació inicial pel Ple, informació pública per un termini no inferior a 45 dies, informe sobre al·legacions, informe dels serveis jurídics, dictamen del Consell Consultiu i aprovació definitiva pel Ple.", "Aprovació inicial pel Ple, informació pública per un termini no inferior a un mes, informe sobre al·legacions, informe dels serveis jurídics i aprovació definitiva pel Ple.", "Aprovació inicial pel Ple, informació pública per un termini no inferior a un mes, informe sobre al·legacions, informe dels serveis jurídics, dictamen del Consell Consultiu i aprovació definitiva pel Ple."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 33, "Quin ňrgan dels consells insulars exerceix la iniciativa legislativa prevista en l'Estatut d'autonomia?", "El Consell Executiu.", "El Ple", "La Presidčncia", "La Junta de Portaveus"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 34, "Els consells insulars poden representar protocol·lŕriament el Govern de la comunitat autňnoma en un acte oficial que tengui lloc a l'illa?", "Sí, per mitjŕ de qualsevol conseller executiu.", "Sí, per mitjŕ de la seva presidčncia.", "No, ha de representar-lo el president del Govern.", "No, ha de representar-lo qualsevol dels membres del Govern."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 35, "Les polítiques de gčnere, la conciliació de la vida familiar i laboral, i la dona són matčries de competčncia dels consells insulars?", "No, són competčncia del Govern de les Illes Balears.", "Sí, són competčncies prňpies dels consells insulars.", "Sí, són competčncies delegades dels consells insulars.", "No, són competčncies de l'Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 36, "Quina potestat té el Govern de les Illes Balears respecte de les competčncies prňpies dels consells insulars?", "La potestat de coordinar l'actuació dels consells insulars en l'exercici de les competčncies.", "La potestat reglamentŕria.", "La funció executiva i de gestió.", "La potestat d'adoptar polítiques prňpies en cada sector de l'acció pública."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 37, "Les proposicions de llei dels consells insulars s’han d’aprovar:", "Per majoria simple dels membres assistents al Ple.", "Per majoria absoluta del Ple.", "Per majoria simple del Consell Executiu.", "Per majoria simple del nombre de membres del Ple."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 38, "En relació amb els plans insulars de cooperació, indicau la resposta incorrecta:", "És un instrument per contribuir al finançament de les inversions de carŕcter prioritari que proposin les entitats locals.", "Té carŕcter anual.", "Té carŕcter pluriennal.", "El Govern de la comunitat autňnoma ha de col·laborar en la dotació econňmica dels plans."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 39, "D'acord amb l'art 112 de la Llei 4/2022 de consells insulars, quina facultat es reserva el Govern de la comunitat autňnoma respecte de les competčncies delegades als consells insulars?", "Dictar instruccions tčcniques de carŕcter particular.", "Instruir els expedients sancionadors dels serveis objecte de la delegació.", "Designar assessors.", "Nomenar personal tčcnic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 40, "Les propostes de delegació de competčncies municipals en els consells insulars s'han de sotmetre a informació pública per un termini mínim de:", "Un mes.", "Quinze dies.", "Dos mesos.", "Tres mesos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 41, "En cas d'incompliment del decret de delegació per part d'un consell insular, el Govern de la comunitat autňnoma podrŕ adoptar la mesura següent:", "Suspensió parcial o total de la delegació per un període no superior a sis mesos.", "Suspensió parcial o total de la delegació per un període no superior a un mes.", "Suspensió parcial o total de la delegació per un període no superior a tres mesos.", "Suspensió parcial o total de la delegació per un període no superior a un any."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 42, "La delegació de competčncies als consells insulars s'ha d'acordar mitjançant:", "Un decret aprovat en el Consell de Govern.", "Un acord de Ple dels consells insulars adoptat per majoria simple.", "Una llei del Govern de la comunitat autňnoma.", "Un reglament del consell insular corresponent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 43, "Quan un instrument de planificació de la comunitat autňnoma afecta ŕmbits materials en quč els consells insulars tenguin competčncies, aquests han de disposar de la informació adequada i han de ser oďts en un termini:", "D’un mes.", "De quinze dies.", "De tres mesos.", "Adequat i suficient"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 44, "Qui ha de resoldre els recursos administratius contra els actes de l’Administració de la comunitat autňnoma dictats abans de la transferčncia de la competčncia als consells insulars, presentats posteriorment a aquesta?", "Els ňrgans competents dels consells insulars.", "Els ňrgans competents de l’Administració de la Comunitat Autňnoma.", "El Tribunal Administratiu Central de Recursos.", "Poden resoldre els recursos tant els ňrgans competents dels consells insulars com els ňrgans competents de l’Administració de la Comunitat Autňnoma."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 45, "En relació amb els consorcis, indicau la resposta correcta:", "Les entitats instrumentals dels consells insulars no poden constituir consorcis amb altres administracions públiques.", "Es poden constituir quan la cooperació no es por dur a terme mitjançant un conveni.", "Els consells insulars no poden constituir consorcis amb entitats privades.", "Les entitats instrumentals dels consells insulars no poden constituir consorcis amb entitats públiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 46, "Els consells insulars coordinen o assumeixen la prestació dels serveis municipals als municipis amb una població:", "Inferior a 25.000 habitants.", "Inferior a 30.000 habitants.", "Inferior a 15.000 habitants.", "Inferior a 20.000 habitants."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 47, "Els ens instrumentals dels consells insulars poden subscriure convenis amb ciutadans particulars?", "Els ens instrumentals dels consells insulars no poden subscriure cap tipus de convenis.", "Els ens instrumentals dels consells insulars no poden subscriure convenis amb subjectes de dret privat.", "Sí, si implica cessió de la titularitat de la competčncia.", "Sí, d’acord amb la legislació bŕsica de l’ Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 48, "Quins són els ňrgans superiors d’administració dels consells insulars?", "Directors insulars", "El/la president/a", "Els consellers executius", "Totes les respostes anteriors són correctes"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 49, "La sessió pública constitutiva del Ple dels consells insulars se celebra:", "En el període comprčs entre els dies vint-i-dos i quaranta-cinc des de la data de les  eleccions.", "En el període comprčs entre els dies vint-i-u i quaranta-sis des de la data de les  eleccions.", "En el període comprčs entre els dies vint i quaranta-cinc des de la data de les  eleccions.", "En el període comprčs entre els dies vint-i-u i quaranta-cinc des de la data de les  eleccions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 50, "Quina de les funcions següents no correspon a les comissions del Ple?", "En el cas de la Comissió Especial de Comptes, les que preveu la legislació d'hisendes locals.", "El seguiment de la gestió del president, del Consell Executiu i dels seus membres, sens perjudici del control que correspon al Ple.", "L'informe o la consulta dels assumptes que hagin de ser sotmesos a la decisió del Ple.", "L'exercici de les competčncies assignades en el reglament orgŕnic i de les competčncies delegades pel Ple d'acord amb la Llei de consells insulars."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 51, "Quines d’aquestes atribucions no requereixen el vot favorable de la majoria absoluta del nombre legal de membres del Ple dels consells insulars?", "Exercir la iniciativa legislativa d'acord amb l'Estatut d'autonomia.", "Crear, modificar i suprimir els serveis públics de competčncia del Consell Insular, determinar-ne les formes de gestió i aprovar la prestació de serveis públics i d'activitats econňmiques en rčgim de monopoli d'acord amb la legislació sobre la competčncia.", "Alterar la qualificació jurídica dels béns de domini públic i autoritzar la cessió gratuďta de béns immobles a altres entitats públiques o privades", "Aprovar la creació i la supressió de municipis, com també l'alteració de termes municipals."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 52, "Per quina d’aquestes causes no cessa el president del Consell Insular?", "La pčrdua de la condició de membre del Consell Insular.", "Quan la incapacitat  física o psíquica és apreciada motivadament per dues cinquenes parts dels membres del Ple, i aprovada per majoria simple.", "L'acabament del mandat d'acord amb la legislació electoral.", "La renúncia comunicada per escrit al Ple."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 53, "Quina d’aquestes afirmacions es incorrecta?", "El Consell Executiu és l'ňrgan de govern al capdavant de l'Administració insular.", "El Consell Executiu estŕ integrat pel president, el vicepresident o vicepresidents i els consellers executius que tenen la condició d’electes.", "El Consell Executiu  respon políticament davant el Ple de la seva gestió de forma solidŕria.", "El president assigna la secretaria del Consell Executiu a un dels seus membres o al secretari general del Consell Insular. Si ho fa en un dels membres, aquest podrŕ comptar amb l'assistčncia d'un funcionari del grup A."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 54, "Els consells insulars emparen els drets dels ciutadans, mitjançant:", "Els instruments i procediments adequats per rebre la informació institucional i administrativa per a l’exercici dels seus dret i participació en l’organització de l’Administració insular.", "L’assistčncia a les sessions del Ple fent ús de les facultats determinades pel reglament orgŕnic.", "Les consultes en els procediments de planificació sectorial i d’elaboració normativa.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 55, "Els ens del sector públic instrumental dels consells insulars es regeixen per:", "Per a l’elaboració i aprovació dels pressuposts, dels comptes anuals, tresoreria i fiscalització, per la legislació d’hisendes locals.", "El patrimoni, per la legislació de patrimoni, si escau.", "Pel reglament orgŕnic del consell insular corresponent.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 56, "La Llei de consells insulars preveu que les notificacions, citacions i altres comunicacions judicials, perquč s'entenguin fetes amb validesa, s'han de practicar:", "En la seu dels serveis jurídics dels consells insulars.", "De conformitat amb el rčgim electrňnic de comunicacions vigent.", "En la persona d’un dels seus lletrats o advocats.", "Totes les respostes anteriors són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 57, "Les retribucions de les persones titulars dels ňrgans directius es fixen i seran públiques quan:", "El Decret de Presidčncia fixi les retribucions dels ňrgans directius.", "Segons el previst en la Llei 19/2013, de 9 de desembre, de transparčncia, accés a la informació pública i bon govern.", "La normativa pressupostŕria fixi les retribucions dels ňrgans directius.", "Les respostes b) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 58, "Els membres dels consells insulars tenen el dret i el deure de:", "Gaudir dels drets, els honors i les distincions propis del cŕrrec.", "Assistir a les sessions del Ple.", "Percebre les retribucions i indemnitzacions que determini el Ple.", "El deure de fer la declaració d’activitats i béns només els consellers electes, perň no la resta de membres."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 59, "El Consell Executiu, com a ňrgan de govern dels consells insulars, quina d’aquestes atribucions pot exercir?", "Aprovar la plantilla de personal.", "Aprovar el pla insular de cooperació.", "Resoldre els conflictes d'atribucions que es puguin plantejar entre els consellers executius.", "Recončixer les obligacions derivades de responsabilitat patrimonial en els casos previstos en el reglament orgŕnic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 60, "Quina d’aquestes atribucions correspon als directors insulars?", "Tenir cura de l'execució del pressupost.", "Donar assistčncia tčcnica i administrativa al conseller executiu.", "Dur a terme la gestió dels serveis comuns i del personal del seu departament.", "Vetlar per la utilització racional i eficient dels mitjans materials al seu cŕrrec."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 61, "Quines de les entitats que formen el sector públic instrumental dels consells insulars tenen personalitat pública?", "Entitats públiques empresarials.", "Societats mercantils públiques.", "Consorcis insulars.", "Fundacions del sector públic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 62, "En els termes establerts en el reglament orgŕnic dels consells insulars, l'assessorament jurídic als ňrgans de l'Administració insular no correspon:", "Als lletrats integrants dels serveis jurídics dels consells insulars.", "Als funcionaris amb habilitació nacional.", "Als lletrats o advocats del Govern de les Illes Balears.", "Als advocats integrants dels serveis jurídics dels consells insulars."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 63, "Quina d’aquestes afirmacions, en relació amb els ňrgans directius, és incorrecta?", "Els ňrgans directius s'integren en l'estructura dels departaments d'acord amb el que disposi el decret de la presidčncia corresponent.", "Els titulars dels ňrgans directius són nomenats i separats pel Consell Executiu.", "Els titulars dels ňrgans de direcció exerceixen el seu cŕrrec en rčgim de dedicació exclusiva.", "Quan es produeixi el nomenament dels nous membres del Consell Executiu, els titulars dels ňrgans directius han de continuar en el cŕrrec fins que no se'n disposi expressament el cessament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 64, "Per quina d’aquestes causes el president ha de continuar en l’exercici del cŕrrec fins que el successor n’hagi pres possessió?", "La denegació de la qüestió de confiança.", "La declaració d'incompatibilitat adoptada pel Ple.", "L'acabament del mandat d'acord amb la legislació electoral.", "Les respostes a) i c) són correctes"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 65, "La condició de vicepresident es perd per, a més de pel cessament:", "Per la pčrdua de la condició de membre del Consell Insular.", "Per la renúncia expressa comunicada per escrit.", "Per la incapacitat física o psíquica permanent que l'impossibiliti per exercir el cŕrrec.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 1, "Segons la Llei 7/85, de 2 d'abril, Reguladora de les bases de rčgim local, el personal al servei de les Entitats locals estarŕ integrat per:", "Funcionaris de carrera, contractats en rčgim de dret laboral i personal eventual que exerceix llocs de confiança o assessorament especial.", "Funcionaris de carrera, funcionaris interins i contractats en rčgim de dret laboral.", "Funcionaris de carrera, funcionaris interins i personal eventual.", "Funcionaris de carrera, funcionaris interins, personal eventual i personal directiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 2, "Segons la Llei 20/2006, municipal i de rčgim local de les Illes Balears, tenen la consideració de personal al servei de les entitats locals de les Illes Balears:", "El personal funcionari de carrera, funcionari interí, personal eventual i personal directiu.", "El personal funcionari de carrera, funcionari interí, personal laboral fix i personal eventual.", "El personal funcionari, el personal eventual i el personal laboral al servei de les entitats locals.", "El personal funcionari de carrera, funcionari interí, personal laboral fix, el personal eventual i el personal directiu"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 3, "Quin personal al servei de les entitats locals es regeix per la Llei 3/2007 de 27 de març, de Funció pública de la Comunitat autňnoma de les Illes Balears, en les matčries no reservades a la legislació bŕsica?", "El personal funcionari, personal laboral i el personal eventual", "El personal funcionari  i el personal laboral", "Únicament el personal funcionari", "El personal funcionari i el personal eventual"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 4, "En virtut de quina competčncia exclusiva de l'Estat, es dicta l'Estatut bŕsic de l'empleat públic?", "De l'article 149.1ş.7a de la Constitució Espanyola", "De l' article 149.1r.13č de la Constitució Espanyola", "De l' article 149.1r.18č de la Constitució Espanyola", "De la regulació de les condicions econňmiques bŕsiques que garanteixen la igualtat de tots els espanyols en l' exercici dels drets."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 5, "La Llei 3/2007 de 27 de març, de Funció pública de la Comunitat autňnoma de les Illes Balears serŕ aplicable als funcionaris de les entitats locals:", "De manera supletňria,", "En tot cas, atčs que és una norma amb rang de Llei", "En les matčries no reservada a la legislació bŕsica estatal.", "En cap cas resulta d' aplicació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 6, "Segons el sistema de fonts de la funció pública local, serŕ d' aplicació directa:", "El Text refós de l'Estatut bŕsic de l'empleat públic, la legislació bŕsica estatal i la Llei 20/2006, municipal i de rčgim local de les Illes Balears", "La llei de funció pública de la CAIB i la seva normativa de desenvolupament.", "La normativa de desenvolupament estatal.", "El TREBEP i la Llei de funció pública de la CAIB."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 7, "Segons el Text refós de l' Estatut bŕsic de l' empleat públic, els empleats públics es classifiquen en:", "Funcionaris de carrera i funcionaris interins.", "Funcionaris de carrera, funcionaris interins i personal laboral", "Funcionaris de carrera, funcionaris interins, personal laboral i personal eventual.", "Funcionaris de carrera, funcionaris interins, personal laboral i personal eventual i personal directiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 8, "Són funcionaris de carrera qui:", "En virtut de nomenament legal estan vinculats a una Administració Pública per una relació estatutŕria regulada pel Dret Administratiu per a l' acompliment de serveis professionals de carŕcter permanent.", "En virtut de nomenament legal estan vinculats a una Administració Pública per una relació laboral regulada pel Dret Administratiu per a l' acompliment de serveis professionals de carŕcter permanent.", "En virtut de nomenament legal estan vinculats a una Administració Pública per una relació estatutŕria regulada pel Dret laboral per a l' acompliment de serveis professionals de carŕcter permanent.", "En virtut de nomenament legal estan vinculats a una Administració Pública per una relació estatutŕria regulada pel Dret Administratiu per a l' acompliment de serveis professionals de carŕcter variable."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 9, "El nomenament d' un funcionari interí:", "No podrŕ tenir una durada superior a 3 anys.", "Tindrŕ lloc sempre que hi hagi una vacant.", "Tindrŕ lloc sempre que hi hagi un excés o acumulació de tasques.", "S' haurŕ de justificar sempre per raons de necessitat i urgčncia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 10, "Segons el Text refós de l' Estatut bŕsic de l' empleat públic el personal laboral és aquell que:", "En virtut de contracte de treball formalitzat tant per escrit com verbalment, presta servei retribuďt per les Administracions Públiques.", "En virtut de contracte de treball fix formalitzat per escrit, presta servei retribuďt per les Administracions Públiques", "En virtut de contracte de treball formalitzat per escrit, en qualsevol de les modalitats de contractació previstes en la legislació laboral, presta servei retribuďt per les Administracions Públiques.", "En virtut de contracte de treball formalitzat per escrit, en qualsevol de les modalitats previstes en el Text refós de l' Estatut bŕsic de l' empleat públic, presta servei retribuďt per les Administracions Públiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 11, "Segons la Llei 3/2007 de 27 de març, de Funció pública de la Comunitat autňnoma de les Illes Balears, quines funcions podria dur a terme el personal laboral?", "Funcions atribuďdes a un funcionari de carrera.", "Funcions atribuďdes a un funcionari de carrera, excepte les que impliquin exercici de l' autoritat.", "Les funcions previstes en el conveni col.lectiu que li sigui d' aplicació", "Les funcions dels llocs corresponents a les ŕrees de manteniment i conservació d' edificis, equips i d' instal.lacions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 12, "El nomenament interí per a l' execució de programes de carŕcter temporal tindrŕ una durada de:", "3 anys.", "9 mesos dins d' un període de 18 mesos.", "3 anys ampliables per 12 mesos més.", "Fins que finalitzi l' execució del programa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 13, "El nomenament interí per excés o acumulació de tasques tindrŕ una durada de:", "9 mesos dins d' un període de 18 mesos.", "3 mesos dins d' un període de 9 mesos.", "12 mesos prorrogables per 6 mesos més.", "Pel temps estrictament necessari"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 14, "El nomenament interí per substitució transitňria dels titulars tindrŕ una durada de:", "Fins que s' incorpori el titular del lloc.", "3 anys com a mŕxim.", "9 mesos dins d' un període de 18 mesos.", "Pel temps estrictament necessari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 15, "El nomenament interí per cobrir llocs vacants tindrŕ una durada mŕxima de 3 anys, excepte:", "Que el procés selectiu quedi desert, cas en el qual podrŕ continuar ocupant el lloc.", "Podrŕ romandre fins a la resolució de la convocatňria amb dret a compensació econňmica, sempre que s' hagi publicat la convocatňria dins dels tres anys.", "Podrŕ romandre fins a la resolució de la convocatňria sense dret a compensació econňmica, sempre que s' hagi publicat la convocatňria dins dels tres anys.", "En cap cas podrŕ superar el termini de 3 anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 16, "És personal eventual:", "En virtut de nomenament i amb carŕcter permanent, només realitza funcions expressament qualificades com de confiança especial.", "En virtut de nomenament i amb carŕcter no permanent, només realitza funcions expressament qualificades com de confiança especial.", "En virtut de nomenament, previ procés de provisió per concurs, i carŕcter no permanent, només realitza funcions expressament qualificades com de confiança especial.", "En virtut de nomenament i carŕcter no permanent, realitza entre d' altres, funcions qualificades com de confiança especial."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 17, "Per designar el personal directiu:", "S' atendrŕ a principis d' igualtat, mčrit i capacitat i a criteris d' idoneďtat.", "Tant el seu nomenament com el seu cessament seran lliures.", "Hauran de tenir la condició de funcionari de carrera del subgrup A1", "Es durŕ a terme mitjançant procediments que garanteixin la publicitat i la concurrčncia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 18, "En quin d'aquests supňsits, la finalització del nomenament interí origina el dret a compensació econňmica?", "Per supressió o amortització del lloc assignat per raons organitzatives.", "Per haver transcorregut més de 3 anys en els casos d' execució de programes de carŕcter temporal.", "Pel transcurs de 3 anys sense que s' hagi procedit a publicar la convocatňria en aquest termini.", "Pel transcurs de 3 anys sense que s' hagi cobert el lloc per un funcionari de carrera."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 19, "Quina de les següents subescales no pertany a l'escala de l'Administració general?", "Tčcnica", "Subalterna", "Serveis especials", "De gestió"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 20, "El personal funcionari amb habilitació de carŕcter nacional, es regeix per:", "El TREBEP", "La llei 20/2006 municipal i de rčgim local de les Illes Balears.", "La llei 7/85 de bases de rčgim local", "Per la seva normativa específica."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 21, "L' oferta d' ocupació pública és:", "El conjunt de llocs de treball vacants la cobertura dels quals resulti necessŕria, amb dotació pressupostŕria", "El conjunt de llocs de treball que van deixant vacants les jubilacions produďdes l' exercici anterior.", "El conjunt de places vacants de personal funcionari i de personal laboral la cobertura dels quals és necessŕria, amb dotació pressupostŕria.", "El conjunt de places vacants de personal funcionari la cobertura del qual és necessŕria, amb dotació pressupostŕria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 22, "Indiqui la correcta:", "L'oferta pública s'ha de publicar al BOIB", "L' oferta pública d' ocupació ha d' indicar la titulació requerida per al seu accés.", "Serŕ objecte de l' oferta pública tots els llocs vacants la cobertura dels quals sigui necessŕria.", "El Govern de les Illes Balears podrŕ acordar l'execució conjunta de les ofertes públiques d'ocupació de diverses entitats locals, a sol·licitud d'aquestes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 23, "Quin termini té l'Administració pública per executar l'oferta pública d'ocupació?", "1 any improrrogable.", "3 anys improrrogables.", "3 anys prorrogables per un més.", "1 any prorrogable per un més."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 24, "En quin cas la condició de personal eventual podrŕ constituir mčrit per a l' accés a la funció pública?", "Només podrŕ ser mčrit per a la promoció interna.", "Només podrŕ ser mčrit per a l' accés al subgrup A1", "En cap cas", "Sempre, per considerar-se temps de servei prestat a l' Administració."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 25, "Les necessitats reals de recursos humans es concreten en:", "La relació de llocs de treball", "En els plans d' ordenació", "En l' oferta pública d' ocupació", "A la plantilla pressupostŕria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 26, "Segons la Llei de bases del rčgim local, les plantilles hauran de respondre als principis següents:", "Principis d' igualtat, capacitat i mčrit", "Principis d' igualtat, capacitat, mčrit i publicitat.", "Principi d' eficičncia, economia i sostenibilitat financera.", "Principi de racionalitat, economia i eficičncia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 27, "Segons la Llei de bases de rčgim local, les corporacions locals formaran públicament la seva oferta pública d' ocupació ajustant-se als criteris establerts en:", "La mesa general de negociació", "Acord plenari.", "Acord de Junta de Govern.", "A l' aprovat per l' Estat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 28, "Quin d'aquests conceptes retributius no té la consideració de retribució bŕsica?", "Sou", "Triennis", "Serveis extraordinaris", "Pagues extraordinŕries"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 29, "El complement específic estŕ destinat a retribuir:", "L' especial dificultat tčcnica, dedicació, incompatibilitat, responsabilitat, perillositat o penositat.", "L' especial rendiment, activitat extraordinŕria i l' interčs i iniciativa amb quč el funcionari exerceix el seu treball.", "L' especialització, responsabilitat, competčncia i comandament.", "La progressió assolida pel funcionari dins del sistema de carrera administrativa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 30, "Segons el TREBEP, la carrera horitzontal és::", "El conjunt ordenat d' oportunitats d' ascens i expectatives de progrés professional conforme als principis d' igualtat, mčrit i capacitat.", "Consisteix en la progressió de graus, categories, graons o altres conceptes anŕlegs, sense necessitat de canviar de llocs.", "El conjunt ordenat d' oportunitats d' ascens en l' estructura de llocs de treball.", "El conjunt ordenat d' oportunitats d' ascens des d' un cos o escala d' un subgrup o grup de classificació professional en el supňsit que no tingui subgrup, a un altre de superior."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 31, "En la carrera horitzontal s'ha de valorar:", "La trajectňria i actuació professional, la qualitat dels treballs realitzats, els coneixements adquirits i el resultat de l' avaluació de l' acompliment", "Només l' avaluació de l' acompliment", "La conducta professional i el rendiment o assoliment de resultat.", "La trajectňria i actuació professional i el resultat de l' avaluació de l' acompliment"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 32, "L' avaluació de l' acompliment atendrŕ criteris de:", "Transparčncia, objectivitat, imparcialitat i no discriminació.", "Privacitat, subjectivitat, imparcialitat i no discriminació.", "Publicitat, igualtat, mčrit i capacitat.", "Privacitat, subjectivitat, mčrit i capacitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 33, "La carrera professional és una retribució de carŕcter:", "Bŕsica", "Complementŕria", "Extraordinŕria,", "Indemnitzadora."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 34, "D'acord amb el TREBEP, quin d'aquests principis no regeix en l'actuació dels empleats públics?", "Objectivitat", "Accessibilitat", "Exemplaritat", "Publicitat"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 35, "Per mort, accident o malaltia greu d' un oncle que viu en diferent localitat, la persona empleada pública li correspon un permís de:", "5 dies", "4 dies", "3 dies", "2 dies"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 36, "Quina d'aquestes matčries no són objecte de negociació segons el TREBEP?", "La determinació i aplicació de les retribucions complementŕries.", "Els plans de previsió social complementŕria", "Les propostes sobre drets sindicals i de participació", "L' increment de les retribucions de personal."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 37, "Pot una persona estrangera d'un país que no pertanyi a la UE participar en un procés selectiu d'una corporació local?", "No, es requereix que tingui nacionalitat espanyola.", "Sí, es pot presentar en igualtat de condicions.", "Sí que es pot presentar, amb excepció de l' accés a les places que impliquin participació directa en els poders públics.", "Sí, si el seu cňnjuge té nacionalitat espanyola o té nacionalitat d' un altre Estat membre."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 38, "Quina de les següents situacions no és una situació recollida en el títol VI del TREBEP?", "Serveis especials.", "Serveis en altres administracions.", "Jubilació parcial.", "Suspensió de funcions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 39, "Si una persona funcionŕria de carrera d'una altra administració és designada personal eventual en un Ajuntament, en quina situació administrativa serŕ declarada en la seva Administració d'origen?)", "Servei en altres administracions", "Serveis especials.", "Excedčncia voluntŕria per interčs particular", "Excedčncia voluntŕria per prestació de serveis en el sector públic."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 40, "L' excedčncia voluntŕria per interčs particular:", "Es pot concedir per un període mínim de 2 anys.", "Es pot concedir per un període mínim de 5 anys.", "Es pot concedir per un període mínim de 2 anys.", "Es pot concedir per un període mŕxim de 5 anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 41, "Si una persona funcionŕria de carrera, obté una plaça per concurs oposició en una altra Administració, en quina situació serŕ declarada en la seva Administració d' origen:", "Excedčncia voluntŕria per prestació de serveis en el sector públic.", "Servei en altres administracions", "Servei especials", "Suspensió de funcions."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 42, "Mitjançant quin instrument jurídic es podran regular altres situacions administratives per als funcionaris de carrera, segons el TREBEP:", "Mitjançant Acord dels ňrgans de govern de les Administracions Públiques.", "Mitjançant Decret acordat en el Consell de Ministres", "Mitjançant reglament de desenvolupament.", "Mitjançant lleis de funció pública."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 43, "En quina situació administrativa es computa el temps a efectes d' ascensos, reconeixement de triennis, promoció interna i drets en el rčgim de la seguretat social, que els sigui d' aplicació:", "Servei en altres administracions", "Servei especials perň sense el cňmput de temps per a ascensos.", "Serveis especials.", "Excedčncia per cura de familiars."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 44, "Si una persona funcionŕria de carrera obté un lloc de treball en una altra Administració per concurs de mčrit, en quina situació quedaria respecte a la seva Administració d' origen:", "Servei en altres administracions", "Excedčncia voluntŕria per prestació de serveis en el sector públic", "Serveis especials", "Suspensió de funcions"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 45, "El TREBEP regula expressament, com a situació administrativa, i sens perjudici d' altres situacions que s' estableixin en les corresponents lleis de funció pública:", "L'Expectativa de destinació", "L'Excedčncia forçosa", "La suspensió de funcions.", "L'Excedčncia voluntŕria"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 46, "En les excedčncia per raó de violčncia de gčnere, es tindrŕ dret a percebre les retribucions íntegres durant:", "Els 6 primers mesos.", "Els 2 primers mesos.", "Els 3 primers mesos.", "El primer any."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 47, "En les excedčncia per raó de violčncia de gčnere, tindran dret a la reserva del lloc de treball que desenvolupaven durant:", "Els 2 primers mesos.", "Els 3 primers mesos.", "Els 6 primers mesos", "Durant el primer any."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 48, "La suspensió ferma per sanció disciplinŕria no podrŕ excedir de:", "6 mesos.", "6 anys", "12 mesos.", "3 mesos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 49, "Segons la Llei 20/2006, Municipal i de Rčgim local , es podran proveir mitjançant lliure designació els llocs de:", "Caps de departament.", "Caps de servei.", "Caps de secció.", "Xofer."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 50, "El rčgim disciplinari del personal laboral es regirŕ:", "Pel que disposi la legislació laboral, en allň no previst en el TREBEP.", "Pel que disposi el TREBEP.", "Pel que disposi el conveni col·lectiu que sigui d' aplicació.", "Pel que disposi el reglament disciplinari a la CAIB."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 51, "El període mŕxim de durada de la situació de declaració d' expectativa de destinació és:", "2 anys", "1 any.", "6 mesos.", "3 mesos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 52, "El reingrés en el servei actiu del personal funcionari que no té reserva de lloc de treball s' efectua:", "Per adscripció provisional", "Per declaració d' expectativa de destinació", "Per comissió de serveis", "A través de la participació en les convocatňries de provisió."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 53, "El reingrés es durŕ a terme respectant el següent ordre de prelació de situació de procedčncia:", "Expectativa de destinació, excedčncia forçosa, suspensió de funcions i excedčncia voluntŕria.", "Excedčncia voluntŕria, expectativa de destinació, excedčncia forçosa i suspensió de funcions.", "Expectativa de destinació, excedčncia forçosa, excedčncia voluntŕria i suspensió de funcions", "Expectativa de destinació, excedčncia voluntŕria, excedčncia forçosa i suspensió de funcions"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 54, "Quan un lloc de treball quedi vacant de forma temporal i definitiva, pot ocupar-se en comissió de serveis:", "Pel personal funcionari de carrera o funcionari interí del mateix cos", "Pel personal funcionari de carrera que pertanyi al mateix subgrup i compleixi els requisits del lloc.", "Pel personal funcionari de carrera del mateix cos, escala o especialitat que compleixi els requisits del lloc.", "Pel personal de la lletra c), i si no ho hagués podrŕ ser personal funcionari interí que compleixi els mateixos requisits."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 55, "La durada de la comissió de serveis és:", "Pel temps estrictament necessari.", "Per un any", "Fins que torna el titular del lloc.", "No podrŕ autoritzar-se la prňrroga de les comissions de serveis en llocs vacants més enllŕ d' 1 any."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 56, "En quins supňsits podrŕ efectuar-se un nomenament per millora d' ocupació en un lloc singularitzat:", "Quan resulti dues vegades desert en un procés de provisió per concurs obert i permanent específic.", "Quan resulti dues vegades desert en una convocatňria de comissió de serveis", "Quan no sigui possible la seva cobertura mitjançant nomenament interí", "Quan hagi  funcionari de carrera de subgrup immediatament inferior disponible pel seu nomenament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 57, "El rčgim d' incompatibilitats de l' empleat públic local estŕ regulat en:", "El TREBEP.", "A la llei 20/2006, de municipal i de rčgim local de les Illes Balears", "A la Llei 7/85, de 2 d'abril, Reguladora de les bases de rčgim local.", "En la llei 53/1984, de 26 de desembre d'Incompatibilitats del personal al servei de les Administracions públiques."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 58, "El personal al servei de les corporacions locals podrŕ exercir un segon lloc o activitat en el sector públic:", "En cap cas.", "En els supňsits previstos per a funcionaris docents i sanitaris.", "Si així ho determina el Ple de la Corporació", "Per raons d' interčs públic que així ho determini la Junta de Govern"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 59, "Serŕ requisit per autoritzar un funcionari del grup A la compatibilitat d' activitats públiques, que la quantitat total percebuda per ambdues prestacions", "No superi la remuneració per al cŕrrec de Director/a General ni superi la retribució de l'activitat principal incrementada en un 45%", "No superi la remuneració per al cŕrrec de Director/a General ni superi la retribució de l'activitat principal incrementada en un 40%", "No superi la remuneració per al cŕrrec de Director/a General ni superi la retribució de l'activitat principal incrementada en un 35%", "No superi la remuneració per al cŕrrec de Director/a General ni superi la retribució de l'activitat principal incrementada en un 30%"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 60, "L' autorització o denegació de compatibilitat pública per a un segon lloc o activitat en el sector públic del personal funcionari d' una corporació local correspon:", "Al Ple", "Junta de Govern", "A l' Alcalde", "Al Regidor de l' Ŕrea competent."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 61, "El incompliment injustificat de l' horari de treball constitueix falta greu si:", "Si acumulat suposa un mínim de 5 hores dins del mes natural.", "Si acumulat suposa un mínim de 10 hores dins d' un mes natural.", "Si acumulat suposa un mínim de 8 hores dins d' un mes natural.", "Si acumulat suposa un mínim de 3 hores dins d' un mes natural."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 62, "Quin d' aquests principis no regeix en la potestat disciplinŕria:", "Principi de retroactivitat", "Principi de culpabilitat", "Principi de presumpció d' innocčncia", "Principi de celeritat"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 63, "L' incompliment de les normes d' incompatibilitat constitueix:", "Falta greu", "Falta molt greu, quan doni lloc a una situació d' incompatibilitat", "Falta lleu, si s' ha comunicat la incompatibilitat abans de l' inici del corresponent procediment disciplinari.", "Falta molt greu"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 64, "La separació del servei és una sanció que es podrŕ imposar per:", "Falta greus", "Falta molt greus", "Falta lleus", "No constitueix una sanció, ja que és una situació administrativa."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 65, "Les infraccions greus prescriuen a:", "Els 2 anys", "Els 3 anys", "Els 4 anys", "A l' any"); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 66, "El termini de prescripció de les sancions disciplinŕries imposades són:", "3 anys per a les molt greus, 2 anys per a les greus i 6 mesos per a les lleus.", "3 anys per a les molt greus, 2 anys per a les greus i 1 any per a les lleus.", "3 anys per a les molt greus, 1 any per a les greus i 6 mesos per a les lleus.", "4 anys per a les molt greus, 3 anys per a les greus i 1 any per a les lleus."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 67, "El termini de prescripció de les faltes començarŕ a comptar-se des de:", "La notificació de l' inici del procediment disciplinari.", "Des que l' ňrgan competent per iniciar el procediment té coneixement de la comissió de la falta.", "Des que es comet la falta.", "Des de l' aprovació de l' acord d' iniciació del procediment."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 68, "El termini de prescripció de les sancions comença a comptar-se des de::", "La fermesa de la resolució.", "La notificació de la resolució sancionadora.", "L' aprovació de la resolució sancionadora.", "El transcurs d' 1 mes des de la resolució sancionadora."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 69, "Quin d'aquests principis no regeix en el procediment en un procediment disciplinari?", "Principi de celeritat.", "Principi d' eficŕcia.", "Principi d' economia processal.", "Principi de retroactivitat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 70, "La suspensió provisional com a mesura cautelar en un procediment disciplinari no podrŕ tenir una durada superior a:", "6 mesos.", "6 mesos, llevat del cas de paralització del procediment imputable a l' interessat.", "3 mesos.", "2 mesos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 71, "El funcionari suspens provisional tindrŕ dret a percebre:", "El 75% de les retribucions bŕsiques i, si s' escau, les prestacions per fill a cŕrrec.", "El 100% de les retribucions bŕsiques i, si s' escau, les prestacions per fill a cŕrrec.", "Les retribucions íntegres i, si s' escau, les prestacions per fill a cŕrrec.", "El sou base i, s'escau, les prestacions per fill a cŕrrec."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 72, "La incoació d'un expedient disciplinari al personal de l'Administració Local  correspon a:", "Al president/a  de la Corporación o el ňrgan a qui delegui.", "A la Junta de Govern o l'ňrgan a qui delegui.", "Al Ple de la Corporació", "Al Regidor/a competent  por raó de la matčria."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 1, "D'acord amb l'article 116.3 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, els plecs de clàusules administratives i de prescripcions tècniques seran substituïts pel document descriptiu:", "En cas que el procediment elegit per adjudicar el contracte sigui el procediment obert simplificat.", "En cas que el procediment elegit per adjudicar el contracte sigui el de negociat sense publicitat.", "En cas que el procediment elegit per adjudicar el contracte sigui el de negociació amb publicitat.", "En cas que el procediment elegit per adjudicar el contracte sigui el de diàleg competitiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 2, "D'acord amb l'article 3.1 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, es considera que no formen part del sector públic les entitats següents:", "L'Administració General de l'Estat, les administracions de les comunitats autònomes, les ciutats autònomes de Ceuta i Melilla i les entitats que integren l'Administració local.", "Les entitats gestores i els serveis comuns de la Seguretat Social.", "Els organismes autònoms, les universitats públiques i les autoritats administratives independents.", "Els consorcis sense personalitat jurídica pròpia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 3, "Són competència de l'ordre jurisdiccional contenciós administratiu les qüestions següents:", "Les relatives a la preparació, adjudicació, efectes, modificació i extinció dels contractes administratius.", "Les que se suscitin en relació amb la preparació i l'adjudicació dels contractes privats de les administracions públiques.", "Les relatives a la preparació i l'adjudicació dels contractes d'entitats del sector públic que no tenguin el caràcter de poders adjudicadors.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 4, "Els contractes menors, d’acord amb l’article 29.8 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l’ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24/UE, de 26 de febrer de 2014:", "No poden tenir una durada superior a dos anys.", "No poden tenir una durada superior a un any.", "No poden tenir una durada superior a un any, però poden ser objecte de pròrroga per un any més.", "No poden tenir una durada superior a sis mesos, prorrogables per sis mesos més."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 5, "Es consideren contractes menors, d’acord amb l’article 118 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l’ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24/UE, de 26 de febrer de 2014:", "Els de valor estimat inferior a 15.000 euros quan es tracti de subministraments.", "Els de valor estimat inferior a 45.000 euros quan es tracti d’obres.", "Els de valor estimat inferior a 50.000 euros quan es tracti d’obres.", "Els de valor estimat inferior a 20.000 euros quan es tracti de serveis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 6, "Els contractes administratius es qualifiquen en:", "Contractes d’obres, serveis i gestió de serveis públics.", "Contractes d’obres, serveis, subministraments, concessió d'obres i concessió de serveis.", "Contractes de serveis, subministraments i concessió d'obres.", "Contractes d’obres, serveis, concessió d'obres i concessió de serveis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 7, "Tenen caràcter privat, d'acord amb l'article 25 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24/UE, de 26 de febrer de 2014, els contractes següents:", "Els contractes de serveis que tenguin per objecte serveis financers amb número de referència CPV de 66100000-1 a 66720000-3.", "Els que tenguin per objecte la creació i interpretació artística i literària i els d'espectacles amb número de referència CPV de 79995000-5 a 79995200-7, i de 92000000-1 a 92700000-8, excepte 92230000-2, 92 -6.", "Aquells l'objecte dels quals sigui la subscripció a revistes, publicacions periòdiques i bases de dades.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 8, "D'acord amb l'article 25.2 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, els contractes administratius es regeixen:", "Quant a la preparació, adjudicació, efectes, modificació i extinció, per aquesta Llei i les seves disposicions de desenvolupament; supletòriament s'aplicaran la resta de normes de dret administratiu i, si no, les normes de dret privat.", "Quant a la preparació, adjudicació, efectes i modificació per la Llei de contractes i les disposicions de desenvolupament; i quant a la seva extinció per les normes de dret privat.", "Quant a la preparació i adjudicació, per aquesta Llei i les disposicions de desenvolupament; supletòriament s'aplicaran la resta de normes de dret administratiu i, quant als seus efectes, modificació i extinció per les normes de dret privat.", "Quant a la preparació, adjudicació, efectes, modificació i extinció, per aquesta Llei i les seves disposicions de desenvolupament, i supletòriament s'aplicaran les normes de dret privat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 9, "D'acord amb l'article 27 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, les qüestions relatives a la preparació i adjudicació dels contractes privats de les administracions públiques, són competència de:", "L’ordenament jurisdiccional civil.", "L’ordenament jurisdiccional penal.", "L’ordenament jurisdiccional laboral.", "L'ordenament jurisdiccional contenciós administratiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 10, "El contracte de manteniment d'un centre públic educatiu és un contracte:", "D’obres.", "De serveis.", "De subministraments.", "De gestió de serveis públics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 11, "D'acord amb l'article 34 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, en els contractes del sector públic poden incloure's qualssevol pactes, clàusules i condicions, sempre que:", "No siguin contraris a l'interès públic, a l'ordenament jurídic i als principis de bona administració.", "No siguin contraris a la moral i al principi d’igualtat.", "No siguin contraris al principi de proporcionalitat i d’igualtat.", "No siguin contraris al principi de lleialtat institucional."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 12, "D'acord amb l'article 19 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, no es consideren subjectes a regulació harmonitzada, sigui quin sigui el seu valor estimat, els contractes següents:", "Els que tenguin com a objecte l'adquisició, el desenvolupament, la producció o la coproducció de programes destinats a serveis de comunicació audiovisual o serveis de comunicació radiofònica.", "Els inclosos dins l'àmbit definit per l'article 346 del Tractat de Funcionament de la Unió Europea que concloguin al sector de la immigració.", "Aquells que tenguin per objecte els serveis de certificació i autenticació de documents que hagin de ser prestats per un notari públic.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 13, "Senyalau la resposta incorrecta. D'acord amb l'article 152.4 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/ UE i 2014/24/UE, de 26 de febrer de 2014:", "El desistiment del procediment haurà d'estar fonamentat en una infracció no esmenable de les normes de preparació del contracte o de les reguladores del procediment d'adjudicació.", "S'haurà de justificar en l'expedient la concurrència de la causa del desistiment.", "El desistiment no impedirà la iniciació immediata d’un procediment de licitació.", "El desistiment impedirà la iniciació immediata d’un procediment de licitació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 14, "Indicau quin dels següents no és un procediment d'adjudicació dels contractes administratius:", "Diàleg competitiu.", "Associació per a la innovació.", "Procediment amb negociació.", "Associació per a la investigació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 15, "D'acord amb l'article 96 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, la inscripció en el Registre Oficial de Licitadors i Empreses Classificades del Sector Públic acredita enfront de tots els òrgans de contractació del sector públic, segons el que s’hi reflecteixi i llevat que hi hagi una prova en contra :", "La solvència econòmica i financera i tècnica o professional i la classificació.", "Les condicions d’aptitud de l’empresari quant a la seva personalitat i capacitat d’obrar, representació, habilitació professional o empresarial.", "La concurrència o no concurrència de les prohibicions de contractar.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 16, "En el procediment obert simplificat que preveu l'article 159.6 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24/UE, de 26 de febrer de 2014:", "Només s'eximeixen els licitadors de l'acreditació de la solvència econòmica.", "S'eximeixen els licitadors de l'acreditació de la solvència econòmica i financera i tècnica o professional.", "L'oferta es lliura en tres sobres o fitxers electrònics.", "Es requereix la constitució d’una garantia definitiva."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 17, "D'acord amb l'article 26 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, tenen la consideració de contractes privats:", "Els que subscriguin les administracions públiques que tinguin per objecte serveis financers amb número de referència CPV de 66100000-1 a 66720000-3.", "Els subscrits per entitats del sector públic que tot i ser poder adjudicador reuneixin la condició d’administracions públiques.", "Els subscrits per entitats del sector públic que no reuneixin la condició de poder adjudicador.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 18, "D'acord amb l'article 72 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, els òrgans de contractació aprecien directament les prohibicions de contractar de les persones en les quals concorri alguna de les circumstàncies següents:", "Haver estat condemnades mitjançant una sentència ferma per delictes de terrorisme.", "Haver estat sancionades amb caràcter ferm per una infracció greu en matèria professional que posi en dubte la seva integritat, de disciplina de mercat o de falsejament de la competència.", "Haver sol·licitat la declaració de concurs voluntari.", "Haver incorregut en falsedat en facilitar qualsevol altra informació relativa a la capacitat i solvència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 19, "D'acord amb l'article 36.4 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, llevat que les clàusules indiquin una altra cosa, els contractes del sector públic s'entenen subscrits:", "Al lloc on es trobi la seu de l'òrgan de contractació.", "Al lloc on es trobi la seu del contractista.", "Al lloc on es dugui a terme l'execució del contracte.", "Al lloc on es recepcioni el contracte."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 20, "Senyalau la resposta incorrecta. D'acord amb l'article 11 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/ UE i 2014/24/UE, de 26 de febrer de 2014, queden exclosos de l'àmbit d'aplicació de la Llei:", "Els contractes relatius a serveis d’arbitratge i conciliació.", "Els contractes que tenguin per objecte serveis relacionats amb campanyes polítiques.", "Els contractes regulats en la legislació laboral.", "Els contractes de serveis de neteja."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 21, "D'acord amb l'article 198.4 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, l'Administració té l'obligació d'abonar el preu:", "Dins dels trenta dies següents a la data d’aprovació de les certificacions d’obra o dels documents que acreditin la conformitat amb el que disposa el contracte dels béns lliurats o serveis prestats.", "Dins dels quaranta dies següents a la data d'aprovació de les certificacions d'obra o dels documents que acreditin la conformitat amb el que disposa el contracte dels béns lliurats o serveis prestats.", "Dins dels seixanta dies següents a la data d'aprovació de les certificacions d'obra o dels documents que acreditin la conformitat amb el que disposa el contracte dels béns lliurats o serveis prestats.", "Dins dels quinze dies següents a la data d'aprovació de les certificacions d'obra o dels documents que acreditin la conformitat amb el que disposa el contracte dels béns lliurats o serveis prestats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 22, "D'acord amb l'article 65 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, només poden contractar amb el sector públic:", "Les persones naturals o jurídiques, espanyoles o estrangeres, que tenguin plena capacitat d'obrar.", "Les persones naturals o jurídiques, espanyoles o estrangeres, que no estiguin sotmeses a alguna prohibició per contractar.", "Les persones naturals o jurídiques, espanyoles o estrangeres, que acreditin la seva solvència econòmica i financera i tècnica o professional o, en els casos en què així ho exigeixi aquesta Llei, es trobin degudament classificades.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 23, "La construcció d'una presa és un contracte administratiu:", "De serveis.", "De subministraments.", "D’obres.", "De concessió de serveis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 24, "Senyalau la resposta correcta, quan en vèncer un contracte no s'hagi formalitzat el nou contracte que garanteixi la continuïtat de la prestació que ha de dur a terme el contractista com a conseqüència d'incidències resultants d'esdeveniments imprevisibles per a l'òrgan de contractació produïdes en el procediment d'adjudicació i hi hagi raons d'interès públic per no interrompre la prestació:", "Es podrà prorrogar el contracte originari fins que comenci l’execució del nou contracte i en tot cas per un període màxim de dotze mesos, sense modificar la resta de condicions del contracte, sempre que l’anunci de licitació del nou contracte s’hagi publicat amb una antelació mínima de tres mesos respecte de la data de finalització del contracte originari.", "Es podrà prorrogar el contracte originari fins que comenci l’execució del nou contracte i en tot cas per un període màxim de nou mesos, sense modificar la resta de condicions del contracte, sempre que l’anunci de licitació del nou contracte s’hagi publicat amb una antelació mínima de tres mesos respecte de la data de finalització del contracte originari.", "Es podrà prorrogar el contracte originari fins que comenci l’execució del nou contracte i en tot cas per un període màxim de dotze mesos, sense modificar la resta de condicions del contracte, encara que l’anunci de licitació del nou contracte no s’hagi publicat.", "Es podrà prorrogar el contracte originari fins que comenci l’execució del nou contracte i en tot cas per un període màxim de nou mesos, sense modificar la resta de condicions del contracte, sempre que l’anunci de licitació del nou contracte s’hagi publicat amb una antelació mínima de sis mesos respecte de la data de finalització del contracte originari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 25, "D'acord amb l'article 32.2 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, per a la condició de mitjà propi personificat de l'entitat destinatària de l'encàrrec respecte del poder adjudicador concret que fa l'encàrrec, entre d’altres, quin requisit s’ha de complir?", "S'haurà de reconèixer expressament en els seus estatuts o actes de creació.", "Serà necessària la conformitat o l’autorització expressa del poder adjudicador respecte del que sigui mitjà propi.", "Serà necessària la verificació per l'entitat pública de què depengui l'ens que hagi de ser mitjà propi de què disposa de mitjans personals i materials apropiats per a la realització dels encàrrecs de conformitat amb el seu objecte social.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 26, "D'acord amb l'article 99 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014:", "L’objecte dels contractes haurà de ser indeterminat.", "Es pot fraccionar un contracte amb la finalitat de disminuir-ne la quantia.", "S'ha de preveure sempre la realització independent de cadascuna de les parts mitjançant la divisió en lots.", "No es pot fraccionar un contracte amb la finalitat de disminuir-ne la quantia i eludir així els requisits de publicitat o els relatius al procediment d'adjudicació que corresponguin."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 27, "D'acord amb l'article 27 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, les qüestions relatives a la preparació i adjudicació dels contractes d'entitats del sector públic que no tenguin el caràcter de poders adjudicadors, són competència:", "De l’ordenament jurisdiccional civil.", "De l’ordenament jurisdiccional penal.", "De l’ordenament jurisdiccional laboral.", "De l'ordenament jurisdiccional contenciós administratiu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 28, "D'acord amb l'article 63.3 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, en el cas de la informació relativa als contractes, haurà de publicar-se al perfil del contractant:", "La memòria justificativa del contracte, l'informe d'insuficiència de mitjans en el cas de contractes de serveis, la justificació del procediment utilitzat per a l’adjudicació quan es faci servir un procediment diferent de l'obert o del restringit.", "L'objecte detallat del contracte, la durada, el pressupost base de licitació i l'import d'adjudicació, inclòs l'impost sobre el valor afegit.", "El plec de clàusules administratives particulars i el de prescripcions tècniques que hagin de regir el contracte o documents equivalents, si escau, i el document d’aprovació de l’expedient.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 29, "D'acord amb l'article 103.5 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, excepte en els contractes de subministrament d'energia, quan escaigui, la revisió periòdica i predeterminada de preus en els contractes del sector públic tendrà lloc:", "Quan el contracte s'hagi executat, almenys, en el 20 per cent del seu import i hagin transcorregut dos anys des de la formalització. No obstant això, la condició relativa al percentatge d'execució del contracte no serà exigible als contractes de concessió de serveis.", "En tot cas, quan el contracte s'hagi executat, almenys, en el 25 per cent de l’import i hagin transcorregut dos anys des de la formalització.", "Quan el contracte s'hagi executat, almenys, en el 30 per cent de l’import i hagin transcorregut dos anys des de la formalització. No obstant això, la condició relativa al percentatge d'execució del contracte no serà exigible als contractes de concessió de serveis.", "En tot cas, quan el contracte s'hagi executat, almenys, en el 15 per cent de l’import i hagin transcorregut dos anys des de la formalització."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 30, "D'acord amb l'article 107 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, en casos especials, l'òrgan de contractació podrà establir en el plec de clàusules administratives particulars que, a més de la garantia a què es refereix l'apartat anterior, es presti una garantia complementària:", "De fins a un 5 per 100 del preu final ofert pel licitador que va presentar la millor oferta, exclòs l'impost sobre el valor afegit, i la garantia total pot assolir un 10 per 100 del preu.", "De fins a un 3 per 100 del preu final ofert pel licitador que va presentar la millor oferta, exclòs l'impost sobre el valor afegit,  i la garantia total pot assolir un 8 per 100 del preu.", "De fins a un 5 per 100 del preu final ofert pel licitador que va presentar la millor oferta, exclòs l'impost sobre el valor afegit, i la garantia total pot assolir un 8 per 100 del preu.", "De fins a un 3 per 100 del preu final ofert pel licitador que va presentar la millor oferta, exclòs l'impost sobre el valor afegit, i la garantia total pot assolir un 10 per 100 del preu."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 31, "D'acord amb l'article 29.4 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, com a regla general, els contractes de subministraments i de serveis de prestació successiva tenen un termini màxim de durada de:", "Cinc anys, amb les possibles pròrrogues incloses.", "Cinc anys més pròrroga de cinc anys més.", "Tres anys amb les possibles pròrrogues incloses.", "Tres anys més pròrroga de fins a tres anys més."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 32, "D'acord amb l'article 111.2 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, l'acord de devolució de la garantia constituïda:", "S'ha d'adoptar i notificar a l'interessat en el termini de tres mesos des de la finalització del termini de garantia.", "S'ha d'adoptar i notificar a l'interessat en el termini de sis mesos des de la finalització del termini de garantia.", "S'ha d'adoptar i notificar a l'interessat en el termini de dos mesos des de la finalització del termini de garantia.", "S'ha d'adoptar i notificar a l’interessat en el termini d'un mes des de la finalització del termini de garantia."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 33, "D'acord amb l'article 116 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, en l'expedient de contractació s'haurà de justificar:", "L’elecció del procediment de licitació.", "Els criteris de solvència tècnica o professional i econòmica i financera, i els criteris que es tenen en consideració per adjudicar el contracte, però no la classificació que s'exigeixi als participants.", "El pressupost de licitació del contracte sense incloure el valor estimat del contracte.", "L’informe de suficiència de mitjans."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 34, "Quan l'Administració hagi de contractar de manera immediata a causa d'esdeveniments catastròfics, de situacions que suposin un perill greu o de necessitats que afectin la defensa nacional, s’està davant d'una tramitació:", "D'emergència.", "D'excepció.", "D’urgència.", "De risc."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 35, "D'acord amb l'article 122 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, els plecs de clàusules administratives particulars han d’incloure:", "Els criteris de solvència i d’adjudicació del contracte.", "Les consideracions socials, laborals i ambientals que s’estableixin com a criteris de solvència, d’adjudicació o com a condicions especials d’execució.", "Els pactes i les condicions definidors dels drets i les obligacions de les parts del contracte.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 36, "Els expedients de contractació administrativa poden ser de tramitació:", "Ordinària i urgent.", "Ordinària i per emergència.", "Ordinària.", "Ordinària, per urgència i per emergència."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 37, "Si un licitador subscriu una proposta en unió temporal amb d’altres i, a més, subscriu una proposta de manera individual o figura en més d’una unió temporal, la infracció d’aquestes normes:", "Donarà lloc a l'admissió només d'una de les propostes que hagi subscrit.", "Donarà lloc a la no admissió de totes les propostes que hagi subscrit.", "Donarà lloc a l'admissió de la proposta que esculli el licitador d'entre totes les presentades.", "Donarà lloc a l'admissió de la primera proposta que el licitador hagi presentat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 38, "D'acord amb l'article 140 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, en relació amb la presentació de la documentació acreditativa del compliment dels requisits previs:", "Les proposicions al procediment obert hauran d'anar acompanyades d'una declaració responsable que s’ha d’ajustar al formulari de document europeu únic de contractació.", "En els casos en què l'empresari recorri a la solvència i mitjans d'altres empreses de conformitat amb l'article 75 de la Llei, cadascuna també ha de presentar una declaració responsable.", "En tots els supòsits en què en el procediment s'exigeixi la constitució de garantia provisional, cal aportar el document acreditatiu d'haver-la constituït.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 39, "D'acord amb l'article 145.3 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, l'aplicació de més d'un criteri d'adjudicació és procedent, en tot cas, a l'adjudicació dels contractes següents:", "Quan l’òrgan de contractació consideri que la definició de la prestació no és susceptible de ser millorada per altres solucions tècniques.", "Aquells que no requereixin l'ús de tecnologia especialment avançada o l'execució dels quals sigui particularment complexa.", "Contractes de concessió d'obres i de concessió de serveis.", "Contractes de serveis amb prestacions indefinides tècnicament."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 40, "L'avaluació de les ofertes d'acord amb els criteris quantificables mitjançant la mera aplicació de fórmules:", "En tot cas, es farà prèviament a la d’aquells altres criteris en què no concorri aquesta circumstància.", "En tot cas es farà després d’efectuar prèviament la d’aquells altres criteris en què no concorri aquesta circumstància, de la qual cosa s’ha de deixar constància documental.", "Podrà fer-se prèviament a la d’aquells altres criteris en què no concorri aquesta circumstància.", "Podrà fer-se prèviament o amb posterioritat a la d’aquells altres criteris en què no concorri aquesta circumstància a elecció de l’òrgan de contractació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 41, "Senyalau la resposta correcta, d'acord amb l'article 153.3 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/ UE i 2014/24/UE, de 26 de febrer de 2014, si el contracte és susceptible d’un recurs especial en matèria de contractació conforme a l'article 44:", "La formalització no es pot efectuar abans que transcorrin deu dies hàbils des que es remeti la notificació de l'adjudicació als licitadors i candidats. Les comunitats autònomes poden incrementar aquest termini, sense que excedeixi els dos mesos.", "La formalització no es pot efectuar abans que transcorrin deu dies hàbils des que es remeti la notificació de l'adjudicació als licitadors i candidats. Les comunitats autònomes poden incrementar aquest termini, sense que excedeixi un mes.", "La formalització no es pot efectuar abans que transcorrin quinze dies hàbils des que es remeti la notificació de l'adjudicació als licitadors i candidats. Les comunitats autònomes poden incrementar aquest termini, sense que excedeixi un mes.", "La formalització no es pot fer abans que transcorrin quinze dies hàbils des que es remeti la notificació de l'adjudicació als licitadors i candidats. Les comunitats autònomes només poden incrementar aquest termini en deu dies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 42, "La tramitació del procediment obert simplificat s’ha d’ajustar a les especialitats següents:", "L'oferta s’ha de presentar en dos o tres sobres o arxius electrònics en els supòsits en què en el procediment es prevegin criteris d'adjudicació la quantificació dels quals depengui d'un judici de valor. En cas contrari, l'oferta s’ha de presentar en dos sobres o fitxers electrònics.", "L'oferta s’ha de presentar en un únic sobre o fitxer electrònic en tot cas.", "L'oferta s’ha de presentar en un únic sobre o arxiu electrònic en els supòsits en què en el procediment no es prevegin criteris d'adjudicació la quantificació dels quals depengui d'un judici de valor. En cas contrari, l'oferta s’ha de presentar en dos sobres o fitxers electrònics.", "L'oferta s’ha de presentar en dos sobres o fitxers electrònics en tot cas."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 43, "Quan l'òrgan de contractació procedeixi a la divisió en lots de l'objecte del contracte, aquest pot introduir les limitacions següents, amb la justificació deguda en l'expedient:", "Pot limitar el nombre de lots per als quals un mateix candidat o licitador pot presentar una oferta.", "Pot limitar el nombre de lots per als quals un mateix candidat o licitador pot presentar una oferta, però no pot limitar el nombre de lots que es poden adjudicar a cada licitador.", "Pot limitar el nombre de lots que es poden adjudicar a cada licitador.", "Les respostes a) i c) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 44, "Senyalau la resposta incorrecta. En els contractes d'obres de valor estimat inferior a 80.000 euros, i en contractes de subministraments i de serveis de valor estimat inferior a 60.000 euros, excepte els que tenguin per objecte prestacions de caràcter intel·lectual als quals no és d’aplicació l'apartat 6 de l'article 159 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/ 24/UE, de 26 de febrer de 2014, el procediment obert simplificat pot seguir la tramitació següent:", "El termini per presentar proposicions no pot ser inferior a deu dies hàbils, comptadors des de l'endemà de la publicació de l'anunci de licitació al perfil de contractant. No obstant això, quan es tracti de compres corrents de béns disponibles en el mercat el termini és de cinc dies hàbils.", "S'eximeix els licitadors de l'acreditació de la solvència econòmica i financera i tècnica o professional.", "L'oferta s’ha de lliurar en un únic sobre o arxiu electrònic i s’ha d’avaluar, en tot cas, d'acord amb criteris d'adjudicació quantificables mitjançant la mera aplicació de fórmules establertes en els plecs.", "Es requereix la constitució de garantia definitiva, i la formalització del contracte es pot efectuar mitjançant la signatura d'acceptació el contractista de la resolució d'adjudicació."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 45, "D'acord amb l'article 80 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, els acords relatius a la classificació de les empreses els han d’adoptar les comissions classificadores de la Junta Consultiva de Contractació Pública de l'Estat:", "Amb eficàcia general davant de tots els òrgans de contractació.", "Amb eficàcia limitada al territori seu de l’òrgan de contractació.", "Amb eficàcia limitada al procediment de licitació en qüestió.", "Amb eficàcia limitada a sis mesos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 46, "Quan en la tramitació d'un procediment negociat sense publicitat únicament hi participi un candidat, la mesa de contractació, o sinó, l'òrgan de contractació:", "Ha de negociar amb el candidat en tot cas.", "Pot negociar amb el candidat.", "No ha de negociar amb el candidat.", "Ha de negociar amb el candidat sempre que sigui possible."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 47, "Senyalau la resposta incorrecta. D'acord amb l'article 180 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/ UE i 2014/24/UE, de 26 de febrer de 2014, el procediment de contractació d'associació per a la innovació:", "S’estructura en fases successives seguint la seqüència de les etapes del procés de recerca i innovació, que pot incloure la fabricació dels productes, la prestació dels serveis o la realització de les obres.", "S'estructura en fases independentment que siguin successives d'acord amb una sèrie d'etapes del procés de recerca i innovació, que pot incloure la fabricació dels productes, la prestació dels serveis o la realització de les obres.", "L'associació per a la innovació ha de fixar uns objectius intermedis que haurien d'assolir els socis i ha de proveir el pagament de la retribució en terminis adequats.", "En cap cas, la resolució de l'associació per a la innovació o la reducció del nombre de candidats participants dóna lloc a indemnització, sens perjudici de la contraprestació que, en les condicions que s’estableixen en el plec, correspongui pels treballs realitzats."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 48, "D'acord amb l'article 190 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, l'òrgan de contractació no té les prerrogatives següents:", "Interpretar els contractes administratius i resoldre els dubtes que n'ofereixi el compliment.", "Modificar els contractes administratius per raons d’interès públic.", "Declarar la responsabilitat imputable al contractista arran de l’execució del contracte.", "Inspeccionar les instal·lacions, les oficines i altres emplaçaments en què el contractista desenvolupi les seves activitats, encara que no siguin determinants per al desenvolupament de les prestacions objecte del contracte."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 49, "D'acord amb l'article 191.3 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, és preceptiu el dictamen del Consell Consultiu en l’àmbit de la Comunitat Autònoma de les Illes Balears:", "En cas que l'òrgan de contractació exerceixi la prerrogativa d'interpretar el contracte.", "En cas que l'òrgan de contractació exerceixi la prerrogativa d'anul·lar el contracte.", "En el cas que l'òrgan de contractació exerceixi la prerrogativa de resoldre el contracte, quan el contractista formuli oposició.", "En el cas de les modificacions dels contractes quan no estiguin previstes en el plec de clàusules administratives particulars i la seva quantia, aïllada o conjuntament, sigui superior a un 40 per cent del preu inicial del contracte, IVA exclòs, i el seu preu sigui igual o superior a 8.000.000 d’euros."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 50, "D'acord amb l'article 204 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, els contractes de les administracions públiques es poden modificar durant la seva vigència quan en els plecs de clàusules administratives particulars s'hagi advertit expressament d'aquesta possibilitat:", "Fins a un màxim del vint per cent del preu inicial.", "Fins a un màxim del deu per cent del preu inicial.", "Fins a un màxim del quinze per cent del preu inicial.", "Fins a un màxim del trenta per cent del preu inicial."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 51, "Als contractes s’ha de fixar un termini de garantia que ha de comptar des de:", "La data de recepció o conformitat del contracte.", "La data de formalització del contracte.", "La data d’aprovació del contracte.", "La data de pagament del contracte."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 52, "No són causa de resolució del contracte:", "La pròrroga del contracte.", "La declaració de concurs o la declaració d’insolvència en qualsevol altre procediment.", "L’acord mutu entre l’Administració i el contractista.", "L'incompliment de l'obligació principal del contracte."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 53, "Senyalau la resposta incorrecta:", "Els subcontractistes queden obligats només davant del contractista principal, que que assumeix, per tant, la responsabilitat total de l’execució del contracte davant l’Administració, d’acord estrictament amb els plecs de clàusules administratives particulars o document  descriptiu, i amb els termes del contracte.", "Si així es preveu en els plecs, els licitadors hauran d'indicar a l'oferta la part del contracte que tenguin previst subcontractar, amb esment de l'import, i el nom o el perfil empresarial, definit per referència a les condicions de solvència professional o tècnica, dels subcontractistes als quals s'encomanarà la realització.", "En tot cas, el contractista haurà de comunicar per escrit, després de l'adjudicació del contracte i, com a molt tard, quan se n’iniciï l'execució, a l'òrgan de contractació la intenció de subscriure els subcontractes, amb esment de la part de la prestació que es pretén subcontractar i la identitat, dades de contacte i representant o representants legals del subcontractista, i amb justificació suficient de l'aptitud per a executar-la.", "El subcontractista haurà de notificar per escrit a l'òrgan de contractació qualsevol modificació que pateixi."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 54, "D'acord amb l'article 68 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, respecte de les empreses no comunitàries:", "Addicionalment, el plec de clàusules administratives particulars pot exigir a les empreses no comunitàries que resultin adjudicatàries de contractes d'obres que obrin una sucursal a Espanya, amb designació d'apoderats o representants per a les operacions.", "Addicionalment, el plec de clàusules administratives particulars pot exigir a les empreses no comunitàries que resultin adjudicatàries de contractes d'obres que estiguin inscrites al Registre Mercantil.", "Addicionalment, el plec de clàusules administratives particulars pot exigir a les empreses no comunitàries que resultin adjudicatàries de contractes d'obres que tributin a Espanya.", "Les respostes a) i b) són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 55, "D'acord amb l'article 219.2 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, la durada d’un acord marc:", "No pot excedir de cinc anys.", "No pot excedir de tres anys.", "No pot excedir de sis anys.", "No pot excedir de quatre anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 56, "Senyalau la resposta incorrecta. D'acord amb l'article 232 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/ UE i 2014/24/UE, de 26 de febrer de 2014, a l’efecte d'elaboració dels projectes es classifiquen les obres, segons l’objecte i la naturalesa, en els grups següents:", "Obres de primer establiment, reforma, restauració, rehabilitació o gran reparació.", "Obres de reparació simple.", "Obres de conservació i manteniment.", "Obres de desgast."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 57, "D'acord amb l'article 82 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, la classificació de les empreses:", "Té una vigència indefinida en tot cas.", "Té una vigència indefinida mentre l'empresari mantengui les condicions i les circumstàncies en què es va basar la concessió.", "Té una vigència anual.", "Té una vigència de tres anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 58, "L'execució del contracte d'obres comença:", "Amb la formalització del contracte.", "Amb l'acta de comprovació del replanteig.", "Amb la supervisió del projecte.", "Amb l’aprovació del contracte."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 59, "Els contractes administratius es qualifiquen en:", "Serveis, obres, subministraments, concessió d'obres i concessió de serveis.", "Subministraments i obres.", "Serveis, obres i subministraments.", "Obres i serveis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 60, "D'acord amb l'article 284 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, l’Administració pot gestionar indirectament, mitjançant un contracte de concessió de serveis, els serveis de la seva titularitat o competència sempre que siguin susceptibles d’explotació econòmica per particulars. En cap cas poden prestar-se mitjançant concessió de serveis els que impliquin:", "Efectes econòmics.", "Exercici de l’autoritat inherent als poders públics.", "Risc operacional.", "Risc i ventura."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 61, "Senyalau la resposta incorrecta. D'acord amb l'article 16 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/ UE i 2014/24/UE, de 26 de febrer de 2014, són contractes de subministrament:", "Els que tenen per objecte l'adquisició, l'arrendament financer, o l'arrendament, amb opció de compra o sense, de productes o béns mobles.", "Els contractes relatius a propietats incorporals o valors negociables.", "Els que tenguin per objecte l’adquisició d’energia primària o energia transformada.", "Aquells en què l'empresari s'obliga a lliurar una pluralitat de béns de forma successiva i per preu unitari."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 62, "D'acord amb l'article 302 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, quan raons tècniques o econòmiques degudament justificades en l’expedient ho aconsellin, podrà establir-se en el plec de clàusules administratives particulars que el pagament del preu total dels béns a subministrar consisteixi part en diners i part en el lliurament d'altres béns de la mateixa classe, sense que, en cap cas, l'import d'aquests:", "Pugui superar el 50 per cent del preu total.", "Pugui superar el 20 per cent del preu total.", "Pugui superar el 30 per cent del preu total.", "Pugui superar el 40 per cent del preu total."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 63, "Una entitat contractant pot instrumentar la contractació de personal a través del contracte de serveis:", "Només mitjançant un contracte menor.", "En cap cas.", "Només en determinats casos sempre que l'òrgan de contractació ho autoritzi.", "Quan hi concorrin circumstàncies sobrevingudes i imprevistes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 64, "D'acord amb l'article 131 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, l'adjudicació es farà, ordinàriament:", "Utilitzant una pluralitat de criteris d’adjudicació basats en el principi de millor relació qualitat-preu, i utilitzant el procediment obert o el procediment restringit.", "Utilitzant un únic criteri d’adjudicació basat en el preu i utilitzant el procediment restringit.", "Utilitzant un únic criteri d’adjudicació basat en el preu i utilitzant el procediment obert.", "Utilitzant una pluralitat de criteris d’adjudicació basats en el principi de millor relació qualitat-preu, i utilitzant el procediment negociat."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 65, "La redacció d'un projecte d'obres és un contracte de:", "Subministrament.", "Concessió obres.", "Obres.", "Serveis."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 66, "D'acord amb l'article 69.1 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, poden contractar amb el sector públic les unions d'empresaris que es constitueixin temporalment a aquest efecte, sense que sigui necessari formalitzar-les en escriptura pública:", "Fins que s'hagi efectuat l'adjudicació del contracte a favor seu.", "Fins que s'hagi publicat la formalització del contracte a la plataforma de contractació corresponent.", "Fins que no s'hagi efectuat l'aprovació de l'expedient.", "Fins que no s'hagi publicat la licitació del contracte."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 68, "D'acord amb l'article 156.6 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, en el procediment obert en el cas dels contractes de les administracions públiques que no estiguin subjectes a regulació harmonitzada:", "El termini de presentació de proposicions no ha de ser inferior a quinze dies, comptats des de l'endemà de la publicació de l'anunci de licitació del contracte al perfil del contractant. En els contractes d'obres i de concessió d'obres i concessió de serveis, el termini ha de ser, com a mínim, de vint-i-sis dies.", "El termini de presentació de proposicions no ha de ser inferior a vint dies, comptadors des de l'endemà de la publicació de l'anunci de licitació del contracte en el perfil del contractant. En els contractes d'obres i de concessió d'obres i concessió de serveis, el termini ha de ser, com a mínim, de trenta dies.", "En tot cas el termini de presentació de proposicions no ha de ser inferior a vint dies, comptadors des de l'endemà de la publicació de l'anunci de licitació del contracte al perfil del contractant.", "El termini de presentació de proposicions no ha de ser inferior a quinze dies, comptats des de l'endemà de la publicació de l'anunci de licitació del contracte al perfil del contractant. Als contractes d'obres i de concessió d'obres i concessió de serveis, el termini ha de ser, com a mínim, de trenta dies."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 69, "L'Oficina Independent de Regulació i Supervisió de la Contractació ha d’elaborar un informe de supervisió que ha de remetre a la Junta Consultiva de Contractació Pública de l'Estat, que s'integrarà en l'informe nacional que s’ha d’enviar a la Comissió Europea:", "Cada tres anys.", "Cada dos anys.", "Cada cinc anys.", "Cada quatre anys."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 70, "D'acord amb l'article 198.5 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, el contractista podrà procedir, si s’escau, a la suspensió del compliment del contracte:", "Si la demora en el pagament és superior a cinc mesos.", "Si la demora en el pagament és superior a quatre mesos.", "Si la demora en el pagament és superior a tres mesos.", "Si la demora en el pagament és superior a sis mesos."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 71, "Senyalau la resposta incorrecta. Amb relació al Registre de contractes del sector públic, que constitueix el sistema oficial central d'informació sobre la contractació pública a Espanya:", "Els poders adjudicadors han de comunicar al Registre de contractes del sector públic, per a la seva inscripció, les dades bàsiques dels contractes adjudicats per ells, entre les quals ha de figurar la identitat de l'adjudicatari, i l'import d'adjudicació d’aquests, juntament amb el desglossament corresponent de l'impost sobre el valor afegit.", "Els poders adjudicadors han de comunicar al Registre de contractes del sector públic, per a la seva inscripció, les dades bàsiques dels contractes adjudicats per ells, entre les quals ha de figurar la identitat de l'adjudicatari, l'objecte i l'import d'adjudicació d’aquests sense el desglossament de l’impost sobre el valor afegit.", "Els poders adjudicadors han de comunicar, si escau, les modificacions, pròrrogues, variacions de terminis o de preu, import final i extinció dels contractes.", "Les comunicacions de dades de contractes al Registre de contractes del sector públic s'han d’efectuar per mitjans electrònics, informàtics o telemàtics."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 72, "D'acord amb l'article 101 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, en el càlcul del valor estimat dels contractes d'obres, subministraments i serveis s’ha de tenir en compte:", "L'import total, sense incloure l'impost sobre el valor afegit.", "La totalitat de les modificacions a l'alça previstes.", "Qualsevol forma d'opció eventual i les pròrrogues eventuals del contracte.", "Totes les respostes són correctes."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 73, "Els òrgans de contractació de les administracions locals, així com els de les seves entitats vinculades o dependents:", "Poden optar bé per allotjar la publicació dels seus perfils de contractant al servei d'informació que a aquest efecte estableixi la comunitat autònoma del seu àmbit territorial, o bé per allotjar-los a la Plataforma de Contractació del Sector Públic.", "Hauran d'allotjar de manera exclusiva la publicació dels seus perfils de contractant en el servei d'informació que a aquest efecte estableixi la comunitat autònoma del seu àmbit territorial.", "Poden optar de forma excloent bé per allotjar la publicació dels seus perfils de contractant al servei d'informació que a aquest efecte estableixi la comunitat autònoma del seu àmbit territorial, o bé per allotjar-los a la Plataforma de Contractació del Sector Públic.", "Hauran d'allotjar, de manera excloent i exclusiva, la publicació dels seus perfils de contractant en el servei d'informació que a aquest efecte estableixi la comunitat autònoma del seu àmbit territorial."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 74, "Senyalau la resposta incorrecta. D'acord amb la disposició addicional quarantena primera de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/ 23/UE i 2014/24/UE, de 26 de febrer de 2014, es reconeix la naturalesa de prestacions de caràcter intel·lectual als serveis:", "D’arquitectura.", "De consultoria i urbanisme.", "D’enginyeria.", "De recerca."); 
insert into questionbkp (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 75, "D'acord amb l'article 36.1 de la Llei 9/2017, de 8 de novembre, de contractes del sector públic, per la qual es transposen a l'ordenament jurídic espanyol les directives del Parlament Europeu i del Consell 2014/23/UE i 2014/24 /UE, de 26 de febrer de 2014, els contractes que subscriguin els poders adjudicadors, llevat dels contractes menors i dels contractes basats en un acord marc i els contractes específics en el marc d'un sistema dinàmic d'adquisició als quals es refereix a l'apartat 3 d'aquest article 36, es perfeccionen:", "Amb l’adjudicació.", "Amb la formalització.", "Amb la publicació.", "Amb l’aprovació."); 
